// Phase 83.3 — Lifecycle-aware case progression. The "Resolve this case"
// card and Quick actions list now mirror the actual stage tracker so the
// operator sees only what's left to do, not what's already done. The
// goal is "completed visit" — get the homeowner what they asked for.
// =============================================================================
// Phase 83.5 — Case archetype classification.
// =============================================================================
// Not every case is "find a vendor." The cockpit's progression + suggested
// actions used to be one-size-fits-all, which led to:
//   • Vague requests ("Help me with this") routing to vendor sourcing
//   • Pre-vendored tasks ("Schedule with Handyman Express") suggesting we
//     pick from 5 candidates
//   • Internal tasks ("Find the Use & Care Guide") starting a vendor pipeline
//
// `detectConciergeArchetype` reads the request context, message text, and
// dossier to slot the case into one of 6 archetypes. Each archetype gets
// its own Resolve plan, Quick actions, and stage tracker semantics.
//
// Archetypes:
//   clarify              — vague / unclear request; need a follow-up question
//   coordinate_vendor    — vendor named in context, just schedule
//   internal_task        — info gathering (manuals, docs, lookups), no vendor
//   find_vendor          — full sourcing pipeline (the original default)
//   quote                — competitive quote gathering
//   general              — Q&A; reply-and-resolve

const CHEZ_VAGUE_PHRASES = [
  "help me",
  "not sure",
  "don't know",
  "i don't know",
  "what should",
  "what to do",
  "where this came from",
  "where this task came from",
  "anything you can do",
  "please help",
  "can you help",
];

function detectConciergeArchetype(req, dossier, messages) {
  // Phase 83.5 — Manual override wins. Tom can flip the archetype via
  // the "Reclassify this case" quick action when the auto-classifier
  // gets it wrong.
  const override = state.chezArchetypeOverride && state.chezArchetypeOverride[req.id];
  if (override) {
    const ctxOverride = (req.context && typeof req.context === "object") ? req.context : {};
    const namedOverride = ctxOverride.vendor_name || ctxOverride.contractor_name || ctxOverride.contractor;
    return { id: override, vendor_name: namedOverride ? String(namedOverride) : undefined };
  }

  const ctx = (req.context && typeof req.context === "object") ? req.context : {};
  const summary = (req.summary || "").toLowerCase();
  const firstMessage = (messages || []).find((m) => m.role === "user")?.content || "";
  const firstText = String(firstMessage).toLowerCase();
  const combined = `${summary} ${firstText}`;
  const category = req.category || "general";

  // Pre-vendored: a vendor name lives in the request context (set by iOS
  // when the homeowner delegated a task that already had a contractor).
  // Also matches when the message body explicitly names a known household
  // vendor.
  const namedVendor = ctx.vendor_name || ctx.contractor_name || ctx.contractor;
  if (namedVendor) {
    return { id: "coordinate_vendor", vendor_name: String(namedVendor) };
  }
  // Heuristic: message text mentions one of the homeowner's vendors by
  // company name.
  if (dossier?.contractors?.length) {
    for (const c of dossier.contractors) {
      const name = String(c.company_name || "").toLowerCase();
      if (name.length > 3 && combined.includes(name)) {
        return { id: "coordinate_vendor", vendor_name: c.company_name, vendor_id: c.id };
      }
    }
  }

  // Internal info task: docs, manuals, guides, lookups — Chez does these
  // ourselves rather than calling a vendor.
  const internalSignals = [
    "use & care guide", "use and care guide", "user manual", "owner's manual",
    "find the manual", "find the guide", "document", "warranty document",
    "registration", "serial number", "model number lookup",
  ];
  if (internalSignals.some((s) => combined.includes(s))) {
    return { id: "internal_task" };
  }

  // Quote-specific framing in the request category.
  if (category === "get_quote") {
    return { id: "quote" };
  }

  // General questions — short reply works.
  if (category === "general") {
    return { id: "general" };
  }

  // Vague request: signals like "help me with this", "not sure", short
  // body without specifics. Triggers when the body is short AND uses a
  // vague phrase. Long bodies with clear specifics fall through to the
  // category-default.
  const isShort = firstText.trim().split(/\s+/).length < 25;
  const looksVague = CHEZ_VAGUE_PHRASES.some((p) => combined.includes(p));
  if (isShort && looksVague) {
    return { id: "clarify" };
  }

  // Default by category.
  if (category === "find_vendor" || category === "find_handyman") {
    return { id: "find_vendor" };
  }
  if (category === "schedule_visit") {
    return { id: "coordinate_vendor", vendor_name: namedVendor };
  }
  if (category === "coordinate_task") {
    // Coordinate task without a named vendor → most cases need vendor
    // sourcing; the few that don't usually have an internal-task signal
    // (caught above).
    return { id: "find_vendor" };
  }

  return { id: "general" };
}

function computeConciergeCaseProgression(req, dossier) {
  const cached = state.chezAnalysisByRequest && state.chezAnalysisByRequest[req.id];
  const candidates = cached ? [
    ...((cached.existing_vendors || []).map((v) => ({ ...v, _source: "existing" }))),
    ...((cached.places_candidates || []).map((v) => ({ ...v, _source: "places" }))),
  ].map((v) => ({ ...v, _fit: computeChezVendorFit(v) }))
    .sort((a, b) => b._fit - a._fit) : [];
  const callState = (state.chezVendorCallsByRequest && state.chezVendorCallsByRequest[req.id]) || {};
  const callsLogged = Object.values(callState).filter((s) => s && s.outcome).length;
  const recommendedCount = Object.values(callState).filter((s) => s && s.recommended).length;
  const messages = state.chezMessages[req.id] || [];
  const vendorProposals = messages.filter((m) => m.proposal && m.proposal.kind === "vendor");
  const dateProposals = messages.filter((m) => m.proposal && m.proposal.kind === "date_slot");
  const proposalsSent = vendorProposals.length > 0;
  const anyApproved = vendorProposals.some((m) => m.proposal.status === "approved");
  const datesProposed = dateProposals.length > 0;
  const visits = (state.chezVisitsByRequest || {})[req.id] || [];
  const livingVisits = visits.filter((v) => v.state !== "cancelled");
  const visitScheduled = livingVisits.some((v) => v.state === "scheduled");
  const visitComplete = livingVisits.length > 0 && livingVisits.every((v) => v.state === "completed");
  const isResolved = req.status === "resolved";
  // Whether we sent a clarifying question and got an answer.
  // Detected by: any concierge message older than the most recent user
  // message implies the homeowner replied to our outreach.
  const adminMessages = messages.filter((m) => m.role === "concierge");
  const userMessages = messages.filter((m) => m.role === "user");
  const adminAsked = adminMessages.length > 0;
  const homeownerReplied = userMessages.length > 1 ||
    (userMessages.length === 1 && adminMessages.length > 0 && new Date(userMessages[0].created_at).getTime() > new Date(adminMessages[0].created_at).getTime());
  // Find the first vendor that's been called but not recommended yet —
  // that's the natural "next call to log" candidate.
  const nextUncalledIdx = candidates.findIndex((v) => {
    const cd = callState[vendorCandidateKey(v)];
    return !cd || !cd.outcome;
  });
  const topVendor = candidates[0];

  return {
    candidates,
    topVendor,
    callsLogged,
    recommendedCount,
    proposalsSent,
    anyApproved,
    datesProposed,
    visits,
    livingVisits,
    visitScheduled,
    visitComplete,
    isResolved,
    nextUncalledIdx,
    hasResearch: !!cached && (candidates.length > 0),
    sentCount: vendorProposals.length,
    approvedCount: vendorProposals.filter((m) => m.proposal.status === "approved").length,
    adminAsked,
    homeownerReplied,
    adminMessageCount: adminMessages.length,
    userMessageCount: userMessages.length,
  };
}

function renderConciergeAlfredActionsHtml(req, dossier) {
  const messages = state.chezMessages[req.id] || [];
  const archetype = detectConciergeArchetype(req, dossier, messages);
  const p = computeConciergeCaseProgression(req, dossier);

  // Phase 83.5 — Branch the plan + quick actions by case archetype. Each
  // case type has a different "shape" of work and shouldn't be forced
  // through the find_vendor pipeline.
  let plan;
  if (p.isResolved) {
    plan = {
      headline: `Case resolved. <span class="cockpit-muted">Reopen if the homeowner needs more help.</span>`,
      ctaLabel: "Reopen",
      ctaAction: "reopen",
      steps: [],
      quickActions: [
        { label: "Reopen this case", sub: "If the homeowner has follow-up questions", action: "reopen" },
      ],
      tone: "resolved",
    };
  } else if (archetype.id === "clarify") {
    plan = buildClarifyPlan(req, dossier, p);
  } else if (archetype.id === "coordinate_vendor") {
    plan = buildCoordinateVendorPlan(req, dossier, p, archetype);
  } else if (archetype.id === "internal_task") {
    plan = buildInternalTaskPlan(req, dossier, p);
  } else if (archetype.id === "quote") {
    plan = buildQuotePlan(req, dossier, p);
  } else if (archetype.id === "general") {
    plan = buildGeneralPlan(req, dossier, p);
  } else {
    plan = buildFindVendorPlan(req, dossier, p);
  }

  // Always-available utilities at the bottom of the quick-actions list.
  plan.quickActions = plan.quickActions.concat([
    { label: "Mark waiting on customer", sub: "Pause SLA until they reply", action: "waiting" },
    { label: "Snooze this case", sub: "Resurface later — tracked as a system note", action: "snooze" },
    { label: "Reclassify this case", sub: "Wrong archetype? Pick the right workflow", action: "reclassify-case" },
  ]);

  // Memory provenance: how many vendors Chez has sourced for this
  // homeowner historically. Pulled from the dossier's contractors with
  // chez_recommended_at set.
  const chezSourced = (dossier?.contractors || []).filter((c) => c.chez_recommended_at);
  const memoryNote = chezSourced.length
    ? `${chezSourced.length} vendor${chezSourced.length === 1 ? "" : "s"} sourced by Chez for this household — saved to their profile.`
    : "First case for this household — picks here become their permanent vendors.";

  const sourcesUsed = [
    "request thread",
    "homeowner profile",
    `${dossier?.home_systems?.length || 0} systems`,
    `${dossier?.contractors?.length || 0} vendors`,
    `${dossier?.routines?.length || 0} routines`,
    p.candidates.length ? `${p.candidates.length} vendor candidates` : null,
    p.visits.length ? `${p.visits.length} visit${p.visits.length === 1 ? "" : "s"} on the calendar` : null,
  ].filter(Boolean).join(" · ");

  const archetypeLabel = {
    clarify: "Clarification needed",
    coordinate_vendor: "Coordinate visit · vendor named",
    internal_task: "Internal task · Chez does this",
    find_vendor: "Source vendors",
    quote: "Get a quote",
    general: "General help",
  }[archetype.id] || "Resolve this case";

  return `
    <div class="cockpit-resolve ${plan.tone === "resolved" ? "is-resolved" : plan.tone === "complete" ? "is-complete" : ""} cockpit-resolve--${escapeHtml(archetype.id)}">
      <div class="cockpit-resolve__head">
        <span class="cockpit-spark cockpit-spark--sm">✦</span>
        <span class="cockpit-resolve__eyebrow">${escapeHtml(archetypeLabel)}</span>
      </div>
      <div class="cockpit-resolve__headline">${plan.headline}</div>
      ${plan.steps && plan.steps.length > 0 ? `
        <div class="cockpit-resolve__steps">
          ${plan.steps.slice(0, 4).map((s, i) => `
            <div class="cockpit-resolve__step ${s.done ? "is-done" : ""}">
              <span class="cockpit-resolve__step-num">${s.done ? "✓" : (i + 1)}</span>
              <span class="cockpit-resolve__step-text">${escapeHtml(s.label)}</span>
            </div>
          `).join("")}
        </div>
      ` : ""}
      ${plan.ctaLabel ? `
        <button type="button" class="cockpit-btn cockpit-btn--primary cockpit-btn--full" data-cockpit-action="${escapeHtml(plan.ctaAction)}">
          <span class="cockpit-spark cockpit-spark--sm" style="color:#fff;">✦</span>${plan.ctaLabel}
        </button>
      ` : ""}
    </div>

    <div class="cockpit-eyebrow cockpit-eyebrow--space">Quick actions</div>
    <div class="cockpit-actions">
      ${plan.quickActions.map((a) => renderConciergeActionRow(a.label, a.sub, a.action)).join("")}
    </div>

    <div class="cockpit-context-box">
      <div class="cockpit-context-box__eyebrow">Memory · what Chez remembers</div>
      <div class="cockpit-context-box__body">${escapeHtml(memoryNote)}</div>
    </div>

    <div class="cockpit-context-box">
      <div class="cockpit-context-box__eyebrow">Context I'm using</div>
      <div class="cockpit-context-box__body">${escapeHtml(sourcesUsed || "loading…")}</div>
    </div>
  `;
}

// =============================================================================
// Phase 83.5 — Plan builders per archetype.
// =============================================================================

// CLARIFY — vague request, need to ask the homeowner what they actually need.
function buildClarifyPlan(req, dossier, p) {
  const dossierObj = dossier || {};
  const homeownerFirst = dossierObj.users?.[0]?.full_name?.split(" ")[0]
    || dossierObj.family_members?.[0]?.first_name
    || "the homeowner";

  // Branch on whether we've already sent a clarifying question.
  if (!p.adminAsked) {
    return {
      headline: `Vague request — start with a clarifying question. <span class="cockpit-muted">We don't know what kind of help they need yet.</span>`,
      ctaLabel: "Draft clarifying question",
      ctaAction: "draft-clarifier",
      steps: [
        { label: "Ask what kind of help they need", done: false },
        { label: "Wait for their reply", done: false },
        { label: "Re-classify into the right workflow", done: false },
        { label: "Resolve once they have what they need", done: false },
      ],
      quickActions: [
        { label: "Draft clarifying question", sub: `Pre-fills the composer with a tone-aware prompt for ${escapeHtml(homeownerFirst)}`, action: "draft-clarifier" },
        { label: "Reclassify this case", sub: "If you already know what they need, pick the right workflow", action: "reclassify-case" },
        { label: "Mark resolved", sub: "If this turned out to be a non-issue", action: "resolved" },
      ],
    };
  }
  if (p.adminAsked && !p.homeownerReplied) {
    return {
      headline: `Asked the homeowner what they need. <span class="cockpit-muted">Waiting on their reply — pause the SLA timer.</span>`,
      ctaLabel: "Mark waiting on customer",
      ctaAction: "waiting",
      steps: [
        { label: "Asked what they need", done: true },
        { label: "Wait for reply", done: false },
        { label: "Re-classify based on their answer", done: false },
        { label: "Resolve", done: false },
      ],
      quickActions: [
        { label: "Mark waiting on customer", sub: "Pause SLA until they reply", action: "waiting" },
        { label: "Send a follow-up nudge", sub: "If they haven't replied", action: "draft-from-brief" },
      ],
    };
  }
  // Got a reply — operator should re-read it and reclassify.
  return {
    headline: `Homeowner replied. <span class="cockpit-muted">Read their answer and reclassify so the cockpit can route the right workflow.</span>`,
    ctaLabel: "Reclassify this case",
    ctaAction: "reclassify-case",
    steps: [
      { label: "Asked what they need", done: true },
      { label: "Got their reply", done: true },
      { label: "Re-classify into the right workflow", done: false },
      { label: "Resolve once they have what they need", done: false },
    ],
    quickActions: [
      { label: "Reclassify this case", sub: "Pick the right archetype for what they actually asked", action: "reclassify-case" },
      { label: "Reply directly", sub: "Compose a normal reply if it's a simple Q&A", action: "draft-from-brief" },
    ],
  };
}

// COORDINATE_VENDOR — vendor is named in context. Skip research, go to dates.
function buildCoordinateVendorPlan(req, dossier, p, archetype) {
  const vendorName = archetype.vendor_name || "the named vendor";
  const visit = p.livingVisits[0];
  const visitState = visit?.state;

  if (p.visitComplete) {
    return {
      headline: `${escapeHtml(vendorName)}'s visit is done. <span class="cockpit-muted">Mark resolved so this drops off your queue.</span>`,
      ctaLabel: "Mark resolved",
      ctaAction: "resolved",
      tone: "complete",
      steps: [
        { label: `Called ${vendorName}`, done: true },
        { label: "Sent dates to homeowner", done: true },
        { label: "Visit booked", done: true },
        { label: "Visit complete", done: true },
      ],
      quickActions: [
        { label: "Mark resolved", sub: "Drops this off your queue", action: "resolved" },
        { label: "Re-open the visit card", sub: "If you need to add notes or update the outcome", action: "scroll-to-visits" },
      ],
    };
  }
  if (p.visitScheduled) {
    const when = visit?.scheduled_for ? formatSlotDisplay(visit.scheduled_for) : "the booked date";
    return {
      headline: `${escapeHtml(vendorName)} is booked for <strong>${escapeHtml(when)}</strong>. <span class="cockpit-muted">Mark completed once the visit is done.</span>`,
      ctaLabel: "Mark visit completed",
      ctaAction: "scroll-to-visits",
      steps: [
        { label: `Confirmed with ${vendorName}`, done: true },
        { label: "Date locked", done: true },
        { label: "After the visit, mark it completed", done: false },
        { label: "Mark case resolved", done: false },
      ],
      quickActions: [
        { label: "Open the visit card", sub: "Update outcome / mark completed", action: "scroll-to-visits" },
        { label: "Reschedule", sub: "If the homeowner needs a different date", action: "scroll-to-visits" },
      ],
    };
  }
  if (p.anyApproved) {
    return {
      headline: `Homeowner picked their date with ${escapeHtml(vendorName)}. <span class="cockpit-muted">Confirm the slot with the vendor and mark scheduled.</span>`,
      ctaLabel: "Open visit card to confirm",
      ctaAction: "scroll-to-visits",
      steps: [
        { label: `Called ${vendorName} for available dates`, done: true },
        { label: "Sent dates to homeowner", done: true },
        { label: `Lock the date with ${vendorName}`, done: false },
        { label: "Mark scheduled", done: false },
      ],
      quickActions: [
        { label: "Open visit card", sub: "Confirm the date and mark scheduled", action: "scroll-to-visits" },
        { label: `Call ${vendorName}`, sub: "Lock the homeowner's pick", action: "scroll-to-visits" },
      ],
    };
  }
  if (p.datesProposed) {
    return {
      headline: `Sent dates to homeowner. <span class="cockpit-muted">Waiting on them to pick — auto-confirms the visit when they approve.</span>`,
      ctaLabel: "Send a check-in",
      ctaAction: "send-checkin-reminder",
      steps: [
        { label: `Called ${vendorName} for dates`, done: true },
        { label: "Sent dates to homeowner", done: true },
        { label: "Wait for them to pick", done: false },
        { label: "Visit auto-confirms on approval", done: false },
      ],
      quickActions: [
        { label: "Send a warm check-in", sub: "Pre-fills the composer with a nudge", action: "send-checkin-reminder" },
        { label: "Mark waiting on customer", sub: "Pause SLA until they reply", action: "waiting" },
      ],
    };
  }
  // Day 0: vendor named, no outreach yet.
  return {
    headline: `Vendor's named: <strong>${escapeHtml(vendorName)}</strong>. <span class="cockpit-muted">Call them for available dates, then offer those to the homeowner.</span>`,
    ctaLabel: visit ? "Send dates to homeowner" : "Open proposal builder",
    ctaAction: visit ? "scroll-to-visits" : "open-proposal-builder",
    steps: [
      { label: `Call ${vendorName} for 2-3 available dates`, done: false },
      { label: "Send those dates to the homeowner", done: false },
      { label: "Wait for them to pick", done: false },
      { label: "Mark scheduled, then completed after the visit", done: false },
    ],
    quickActions: [
      { label: "Open proposal builder · dates", sub: "Send 2-3 dates to homeowner", action: "open-proposal-builder" },
      { label: "Draft a status update", sub: "Tell the homeowner you're calling the vendor", action: "draft-from-brief" },
    ],
  };
}

// INTERNAL_TASK — Chez does the work itself (manual lookups, doc fetches, etc.)
function buildInternalTaskPlan(req, dossier, p) {
  const isResolved = p.isResolved;
  if (isResolved) {
    return {
      headline: `Internal task done. <span class="cockpit-muted">Asset delivered to the homeowner.</span>`,
      ctaLabel: "Reopen",
      ctaAction: "reopen",
      tone: "resolved",
      steps: [
        { label: "Sourced the asset", done: true },
        { label: "Saved to homeowner's documents", done: true },
        { label: "Replied with the link", done: true },
      ],
      quickActions: [],
    };
  }
  return {
    headline: `Internal task — Chez does this directly. <span class="cockpit-muted">No vendor needed. Find the asset, save to their docs, reply with the link.</span>`,
    ctaLabel: "Search equipment manuals",
    ctaAction: "search-equipment-manuals",
    steps: [
      { label: "Search the equipment-manuals catalog", done: false },
      { label: "Try the manufacturer's website if not in catalog", done: false },
      { label: "Save to homeowner's documents", done: false },
      { label: "Reply with the link + mark resolved", done: false },
    ],
    quickActions: [
      { label: "Search equipment manuals", sub: "Open the lookup-manual catalog", action: "search-equipment-manuals" },
      { label: "Open the homeowner's vault", sub: "Check existing documents first", action: "open-vault" },
      { label: "Compose a reply with attachment", sub: "When you've got the asset", action: "draft-from-brief" },
      { label: "Mark resolved", sub: "Once the homeowner has the asset", action: "resolved" },
    ],
  };
}

// FIND_VENDOR — original full sourcing pipeline.
function buildFindVendorPlan(req, dossier, p) {
  const allSteps = [
    {
      label: p.hasResearch
        ? `Researched ${p.candidates.length} vendor${p.candidates.length === 1 ? "" : "s"}`
        : "Run vendor research to pull candidates",
      done: p.hasResearch,
    },
    {
      label: p.callsLogged === 0
        ? `Call vendors and log notes`
        : p.callsLogged < Math.min(3, p.candidates.length)
        ? `Log ${Math.min(3, p.candidates.length) - p.callsLogged} more call${Math.min(3, p.candidates.length) - p.callsLogged === 1 ? "" : "s"}`
        : `Logged ${p.callsLogged} calls`,
      done: p.callsLogged >= Math.min(3, Math.max(1, p.candidates.length)),
    },
    {
      label: p.recommendedCount === 0
        ? "Mark the strongest as Recommended"
        : `${p.recommendedCount} marked Recommended`,
      done: p.recommendedCount > 0,
    },
    {
      label: !p.proposalsSent
        ? `Send proposal${p.recommendedCount > 1 ? "s" : ""}`
        : `Sent ${p.sentCount} proposal${p.sentCount === 1 ? "" : "s"}`,
      done: p.proposalsSent,
    },
    {
      label: !p.anyApproved ? "Wait for homeowner to pick" : `Picked ${p.livingVisits[0]?.vendor_name || "a vendor"}`,
      done: p.anyApproved,
    },
    {
      label: !p.visitScheduled && !p.visitComplete
        ? `Send dates to homeowner${p.livingVisits[0]?.vendor_name ? ` (with ${p.livingVisits[0].vendor_name})` : ""}`
        : "Visit booked",
      done: p.visitScheduled || p.visitComplete,
    },
    { label: !p.visitComplete ? "After the visit, mark it completed" : "Visit completed", done: p.visitComplete },
    { label: !p.isResolved ? "Mark case resolved" : "Case resolved", done: p.isResolved },
  ];

  let headline = "";
  let ctaLabel = "";
  let ctaAction = "";

  if (p.visitComplete) {
    headline = `Visit completed. <span class="cockpit-muted">Wrap up — mark resolved.</span>`;
    ctaLabel = "Mark resolved"; ctaAction = "resolved";
  } else if (p.visitScheduled) {
    const when = p.livingVisits.find((v) => v.state === "scheduled")?.scheduled_for;
    const whenLabel = when ? formatSlotDisplay(when) : "the booked date";
    headline = `Visit scheduled for ${escapeHtml(whenLabel)}. <span class="cockpit-muted">Mark completed once the visit is done.</span>`;
    ctaLabel = "Open visit card"; ctaAction = "scroll-to-visits";
  } else if (p.anyApproved) {
    const vendor = p.livingVisits[0]?.vendor_name || "the vendor";
    headline = `Homeowner picked ${escapeHtml(vendor)}. <span class="cockpit-muted">Send 2-3 dates so they can pick a slot.</span>`;
    ctaLabel = "Send dates to homeowner"; ctaAction = "scroll-to-visits";
  } else if (p.proposalsSent) {
    headline = `${p.sentCount} proposal${p.sentCount === 1 ? "" : "s"} out. <span class="cockpit-muted">Waiting on homeowner — send a check-in if it stalls.</span>`;
    ctaLabel = "Send a check-in"; ctaAction = "send-checkin-reminder";
  } else if (p.recommendedCount > 0) {
    headline = `${p.recommendedCount} vendor${p.recommendedCount === 1 ? " is" : "s are"} ready to send. <span class="cockpit-muted">One click drafts the proposal.</span>`;
    ctaLabel = "Open proposal builder"; ctaAction = "alfred-resolve-with-proposal";
  } else if (p.callsLogged > 0) {
    headline = `${p.callsLogged} call${p.callsLogged === 1 ? "" : "s"} logged. <span class="cockpit-muted">Mark the strongest as Recommended.</span>`;
    ctaLabel = "Open #" + ((p.nextUncalledIdx >= 0 ? p.nextUncalledIdx : 0) + 1) + "'s form"; ctaAction = "alfred-resolve-open-top";
  } else if (p.candidates.length > 0) {
    const v = p.topVendor;
    const vname = v?.company_name || v?.name || "top match";
    headline = `${p.candidates.length} candidates ready. <span class="cockpit-muted">Call ${escapeHtml(vname)} first — best fit.</span>`;
    ctaLabel = `Open ${escapeForHtml(vname.split(" ")[0])}'s call form`; ctaAction = "alfred-resolve-open-top";
  } else {
    headline = `Source vendors end-to-end. <span class="cockpit-muted">Pull candidates, log calls, propose, track the visit.</span>`;
    ctaLabel = "Run vendor research"; ctaAction = "rerun-analysis";
  }

  const quickActions = [];
  if (!p.hasResearch) quickActions.push({ label: "Run vendor research", sub: "Pull existing-network + local Places candidates", action: "rerun-analysis" });
  if (p.candidates.length > 0 && p.callsLogged < p.candidates.length) quickActions.push({ label: "Open next vendor's call form", sub: "Log outcome + cost", action: "alfred-resolve-open-top" });
  if (p.recommendedCount > 0 && !p.proposalsSent) quickActions.push({ label: "Send recommended vendors", sub: `Drafts ${p.recommendedCount} proposal card${p.recommendedCount === 1 ? "" : "s"}`, action: "alfred-resolve-with-proposal" });
  if (p.proposalsSent && !p.anyApproved) quickActions.push({ label: "Send a warm check-in", sub: "Pre-fills the composer", action: "send-checkin-reminder" });
  if (p.anyApproved && !p.visitScheduled) quickActions.push({ label: "Send dates to homeowner", sub: "Open the visit card · date_slot proposal", action: "scroll-to-visits" });
  if (p.visitScheduled && !p.visitComplete) quickActions.push({ label: "Mark visit completed", sub: "Stamp the outcome", action: "scroll-to-visits" });
  if (p.visitComplete && !p.isResolved) quickActions.push({ label: "Mark case resolved", sub: "Drops this off your queue", action: "resolved" });
  if (p.hasResearch) quickActions.push({ label: "Re-run AI analysis", sub: "Refresh brief + candidates", action: "rerun-analysis" });

  return { headline, ctaLabel, ctaAction, steps: allSteps, quickActions };
}

// QUOTE — competitive quote gathering. Lighter than full vendor sourcing.
function buildQuotePlan(req, dossier, p) {
  return {
    headline: `Quote request. <span class="cockpit-muted">Gather 2-3 quotes, compose a comparison summary, send it to the homeowner.</span>`,
    ctaLabel: p.hasResearch ? "Open call form for #1" : "Run vendor research",
    ctaAction: p.hasResearch ? "alfred-resolve-open-top" : "rerun-analysis",
    steps: [
      { label: "Source 2-3 quote candidates", done: p.hasResearch },
      { label: `Call each, log estimates (${p.callsLogged}/${Math.min(3, p.candidates.length || 3)})`, done: p.callsLogged >= 2 },
      { label: "Compose comparison summary + send", done: p.proposalsSent },
      { label: "Wait for homeowner pick · resolve", done: p.isResolved },
    ],
    quickActions: [
      { label: p.hasResearch ? "Open next vendor's call form" : "Run vendor research", sub: "Get 2-3 estimates", action: p.hasResearch ? "alfred-resolve-open-top" : "rerun-analysis" },
      { label: "Compose comparison summary", sub: "Pre-fills the composer with a quote breakdown", action: "draft-from-brief" },
      { label: "Open proposal builder · cost tab", sub: "Send the comparison as structured cost cards", action: "open-proposal-builder" },
    ],
  };
}

// GENERAL — Q&A. Reply and resolve.
function buildGeneralPlan(req, dossier, p) {
  if (p.adminAsked && !p.homeownerReplied) {
    return {
      headline: `Replied. <span class="cockpit-muted">Waiting on a follow-up — mark waiting on customer if you want to pause SLA.</span>`,
      ctaLabel: "Mark waiting on customer",
      ctaAction: "waiting",
      steps: [
        { label: "Replied to homeowner", done: true },
        { label: "Wait for any follow-up", done: false },
        { label: "Mark resolved when done", done: false },
      ],
      quickActions: [
        { label: "Mark waiting on customer", sub: "Pause SLA until they reply", action: "waiting" },
        { label: "Mark resolved", sub: "If no follow-up needed", action: "resolved" },
      ],
    };
  }
  return {
    headline: `General question. <span class="cockpit-muted">Compose a reply, mark resolved.</span>`,
    ctaLabel: "Draft a reply",
    ctaAction: "draft-from-brief",
    steps: [
      { label: "Compose a reply", done: false },
      { label: "Mark resolved", done: false },
    ],
    quickActions: [
      { label: "Draft a reply", sub: "Pre-fills the composer with tone QA", action: "draft-from-brief" },
      { label: "Mark resolved", sub: "If you've answered the question", action: "resolved" },
    ],
  };
}

// Inline-safe HTML escape variant (the global `escapeHtml` returns a
// string; this is a pass-through so the template-literal wrapper reads
// uniformly when interpolating already-escaped pieces).
function escapeForHtml(s) { return escapeHtml(String(s ?? "")); }

function renderConciergeActionRow(label, sub, action) {
  return `
    <button type="button" class="cockpit-action" data-cockpit-action="${escapeHtml(action)}">
      <span class="cockpit-action__icon"><span class="cockpit-spark cockpit-spark--sm">✦</span></span>
      <div class="cockpit-action__main">
        <div class="cockpit-action__label">${escapeHtml(label)}</div>
        <div class="cockpit-action__sub">${escapeHtml(sub)}</div>
      </div>
      <span class="cockpit-action__arrow">→</span>
    </button>
  `;
}

function renderConciergeAlfredChatHtml(req, dossier) {
  state.concierge.alfred.chat[req.id] = state.concierge.alfred.chat[req.id] || [{
    from: "alfred",
    text: `I read this case and the homeowner's full profile. ${dossier?.profile?.about_us ? "Their standing instructions are loaded too. " : ""}Ask me anything about precedent, vendors on file, or how to frame the next reply.`,
  }];
  const chat = state.concierge.alfred.chat[req.id];

  const suggestedPrompts = [
    "What's the cheapest path to resolve this?",
    `Show me ${dossier ? primaryHomeownerLabel(dossier).split(" ").slice(-1)[0] + "'s" : "the homeowner's"} last 3 vendor decisions`,
    "Is there a similar past case I should study?",
    "What questions am I forgetting to ask the vendor?",
  ];

  return `
    <div class="cockpit-chat">
      ${chat.map((m) => m.from === "alfred" ? `
        <div class="cockpit-chat__msg cockpit-chat__msg--alfred">
          <div class="cockpit-chat__avatar"><span class="cockpit-spark cockpit-spark--sm" style="color:#fff;">✦</span></div>
          <div class="cockpit-chat__bubble">${escapeHtml(m.text)}</div>
        </div>
      ` : `
        <div class="cockpit-chat__msg cockpit-chat__msg--user">
          <div class="cockpit-chat__bubble cockpit-chat__bubble--user">${escapeHtml(m.text)}</div>
        </div>
      `).join("")}
      ${chat[chat.length - 1]?._loading ? `<div class="cockpit-chat__typing">Alfred is reading the case…</div>` : ""}
    </div>
    <div class="cockpit-chat__prompts">
      ${suggestedPrompts.map((p) => `
        <button type="button" class="cockpit-chat__prompt" data-cockpit-action="alfred-prompt" data-prompt="${escapeHtml(p)}">${escapeHtml(p)}</button>
      `).join("")}
    </div>
  `;
}

function renderConciergeAlfredSimilarHtml(req, dossier) {
  // Use past_requests as similar-case precedent. Filtered to exclude the
  // current case and only show resolved or replied-to cases (gives the
  // operator a reference for what's worked before).
  const past = (dossier?.past_requests || []).filter((r) => r.id !== req.id).slice(0, 4);
  if (past.length === 0) {
    return `<p class="cockpit-muted cockpit-alfred__empty">No prior cases for this homeowner. They're new to Chez.</p>`;
  }

  const patternCard = past.length >= 2
    ? `
      <div class="cockpit-pattern">
        <div class="cockpit-pattern__head">
          <span class="cockpit-spark cockpit-spark--sm">✦</span>
          <span class="cockpit-pattern__eyebrow">Pattern</span>
        </div>
        <div class="cockpit-pattern__body">
          ${past.length} prior cases for this homeowner${past.filter((p) => p.status === "resolved").length === past.length ? " — all resolved" : ""}.
          ${past.filter((p) => p.category === req.category).length > 0
            ? `${past.filter((p) => p.category === req.category).length} were also <b>${escapeHtml(CHEZ_CATEGORY_LABELS[req.category] || req.category)}</b> requests.`
            : "Different category from this one — fewer precedents to lean on."}
        </div>
      </div>
    `
    : "";

  return `
    <div class="cockpit-similar">
      ${past.map((c) => `
        <button type="button" class="cockpit-similar__card" data-cockpit-action="open-past-case" data-past-id="${escapeHtml(c.id)}">
          <div class="cockpit-similar__head">
            <span class="cockpit-similar__id">${escapeHtml(c.id.slice(0, 8))}</span>
            <span class="cockpit-muted">${escapeHtml(c.created_at ? formatDateOnly(c.created_at) : "")}</span>
          </div>
          <div class="cockpit-similar__title">${escapeHtml(c.summary || "—")}</div>
          <div class="cockpit-similar__sub">${escapeHtml(CHEZ_CATEGORY_LABELS[c.category] || "request")}</div>
          <div class="cockpit-similar__outcome">→ ${escapeHtml(CHEZ_STATUS_LABELS[c.status] || c.status)}</div>
        </button>
      `).join("")}
    </div>
    ${patternCard}
  `;
}

// =============================================================================
// COCKPIT — handler attachment. Single delegation entry point that wires every
// interactive element after each render. Idempotent — every render replaces
// the cockpit DOM, so listeners only ever bind to the freshly-rendered nodes.
// =============================================================================

// ============================================================================
// Phase 86B — CRM hygiene helpers
// ============================================================================
// Fetches snippets + tag definitions lazily on first cockpit render.
// Idempotent — once loaded, subsequent calls no-op. Re-renders the cockpit
// when data arrives so the slash picker + tag chips pick up the fresh data.
// ============================================================================

async function ensureCrmReferenceData() {
  const stale = (loadedAt) => Date.now() - loadedAt > 5 * 60_000; // 5 minutes
  const promises = [];
  if (state.crm.snippets.length === 0 || stale(state.crm.snippetsLoadedAt)) {
    promises.push(
      callChezConcierge({ action: "list_snippets" })
        .then((r) => {
          state.crm.snippets = r.snippets ?? [];
          state.crm.snippetsLoadedAt = Date.now();
        })
        .catch((e) => console.warn("[crm] snippets load failed", e))
    );
  }
  if (state.crm.tagDefinitions.length === 0 || stale(state.crm.tagDefinitionsLoadedAt)) {
    promises.push(
      callChezConcierge({ action: "list_tag_definitions" })
        .then((r) => {
          state.crm.tagDefinitions = r.tags ?? [];
          state.crm.tagDefinitionsLoadedAt = Date.now();
        })
        .catch((e) => console.warn("[crm] tag defs load failed", e))
    );
  }
  // Phase 86E.2 — batch-load every applied tag across the queue so the
  // queue rail can filter by tag without a per-row fetch. RLS gates by
  // admin allowlist; the response is small (one row per tag-application).
  if (Object.keys(state.crm.allTagsByRequest).length === 0 || stale(state.crm.allTagsLoadedAt)) {
    promises.push(
      supabase.from("chez_request_tags")
        .select("request_id, tag_definition_id")
        .then(({ data, error }) => {
          if (error) throw error;
          const map = {};
          for (const row of (data || [])) {
            (map[row.request_id] = map[row.request_id] || []).push(row.tag_definition_id);
          }
          state.crm.allTagsByRequest = map;
          state.crm.allTagsLoadedAt = Date.now();
        })
        .catch((e) => console.warn("[crm] tag bulk load failed", e))
    );
  }
  if (promises.length > 0) {
    await Promise.allSettled(promises);
    // Re-render with the freshly-loaded data, but only if we're still on
    // the cockpit (operator may have navigated away during the fetch).
    if (state.view === "chez") renderConciergeCockpit();
  }
}

// Load applied tags for a single case. Fire-and-forget; the case header
// re-renders on the next cockpit pass once data arrives.
async function loadAppliedTagsForCase(requestId) {
  if (!requestId) return;
  try {
    const { data, error } = await supabase
      .from("chez_request_tags")
      .select("tag_definition_id, applied_at")
      .eq("request_id", requestId);
    if (error) throw error;
    // Join client-side against the tagDefinitions cache so the case
    // header has slug + label + color without an extra round-trip.
    const defsById = new Map(state.crm.tagDefinitions.map((d) => [d.id, d]));
    state.crm.appliedTagsByRequest[requestId] = (data ?? []).map((row) => {
      const def = defsById.get(row.tag_definition_id);
      return def ? { ...def, applied_at: row.applied_at } : null;
    }).filter(Boolean);
  } catch (e) {
    console.warn("[crm] applied tags load failed", e);
    state.crm.appliedTagsByRequest[requestId] = [];
  }
}

// Token substitution for snippet bodies. Tokens are inline placeholders the
// operator can use in snippet copy — the slash picker resolves them at
// insert-time. Unknown tokens get left in place so the operator sees
// what's missing and can edit before sending.
function applySnippetTokens(body, ctx) {
  if (!body) return "";
  return body
    .replace(/\{homeowner_first_name\}/g, ctx.homeownerFirstName || "{homeowner_first_name}")
    .replace(/\{homeowner_name\}/g, ctx.homeownerName || "{homeowner_name}")
    .replace(/\{address_street\}/g, ctx.addressStreet || "{address_street}")
    .replace(/\{vendor_name\}/g, ctx.vendorName || "{vendor_name}")
    .replace(/\{visit_date\}/g, ctx.visitDate || "{visit_date}")
    .replace(/\{question\}/g, ctx.question || "{question}");
}

// Slash picker — searchable dropdown of snippets, opens when the operator
// types "/" at the start of a line or right after whitespace. Filters by
// the chars typed after "/". Click or Enter inserts. Esc closes.
function openSlashPicker(input, activeReq) {
  state.crm.slashOpen = true;
  state.crm.slashQuery = "";
  state.crm.slashCursor = 0;
  state.crm.slashTargetRequestId = activeReq?.id || null;
  renderSlashPicker(input, activeReq);
}

function closeSlashPicker() {
  state.crm.slashOpen = false;
  state.crm.slashQuery = "";
  state.crm.slashCursor = 0;
  document.querySelector("[data-slash-picker]")?.remove();
}

function renderSlashPicker(input, activeReq) {
  // Position the picker right below the textarea.
  const rect = input.getBoundingClientRect();
  let picker = document.querySelector("[data-slash-picker]");
  if (!picker) {
    picker = document.createElement("div");
    picker.className = "cockpit-slash-picker";
    picker.dataset.slashPicker = "true";
    document.body.appendChild(picker);
  }
  picker.style.position = "fixed";
  picker.style.left = `${rect.left}px`;
  picker.style.top = `${rect.bottom + 6}px`;
  picker.style.width = `${rect.width}px`;
  picker.style.zIndex = "9999";

  const q = (state.crm.slashQuery || "").toLowerCase();
  const matches = state.crm.snippets.filter((s) => {
    if (!q) return true;
    return (
      (s.slug || "").includes(q) ||
      (s.label || "").toLowerCase().includes(q) ||
      (s.category || "").toLowerCase().includes(q)
    );
  }).slice(0, 8);

  if (matches.length === 0) {
    picker.innerHTML = `
      <div class="cockpit-slash-picker__empty">
        No snippets match "${escapeHtml(q)}". <span class="cockpit-muted">Esc to close, or keep typing.</span>
      </div>
    `;
    return;
  }

  state.crm.slashCursor = Math.min(state.crm.slashCursor, matches.length - 1);
  picker.innerHTML = matches.map((s, i) => `
    <button type="button"
      class="cockpit-slash-picker__row ${i === state.crm.slashCursor ? "is-active" : ""}"
      data-slash-snippet="${escapeHtml(s.id)}">
      <div class="cockpit-slash-picker__row-left">
        <strong>/${escapeHtml(s.slug)}</strong>
        <span class="cockpit-muted">${escapeHtml(s.label)}</span>
      </div>
      <span class="cockpit-slash-picker__preview">${escapeHtml((s.body || "").slice(0, 80))}${(s.body || "").length > 80 ? "…" : ""}</span>
    </button>
  `).join("");

  picker.querySelectorAll("[data-slash-snippet]").forEach((row) => {
    row.addEventListener("mousedown", (e) => {
      // mousedown (not click) so it fires before the textarea blur.
      e.preventDefault();
      const snippet = state.crm.snippets.find((s) => s.id === row.dataset.slashSnippet);
      if (snippet) insertSnippetIntoComposer(input, snippet, activeReq);
    });
  });
}

function insertSnippetIntoComposer(input, snippet, activeReq) {
  const ctx = buildSnippetTokenContext(activeReq);
  const resolved = applySnippetTokens(snippet.body, ctx);
  // Replace the "/abc" trigger range with the resolved body.
  const value = input.value || "";
  const caret = input.selectionStart ?? value.length;
  // Find the slash-trigger that opened the picker (last "/" before caret).
  const before = value.slice(0, caret);
  const slashIdx = before.lastIndexOf("/");
  const trigger = slashIdx >= 0 ? value.slice(slashIdx, caret) : "";
  // Replace it inline.
  const newValue = (slashIdx >= 0 ? value.slice(0, slashIdx) : value) + resolved + value.slice(caret);
  input.value = newValue;
  input.dispatchEvent(new Event("input", { bubbles: true })); // re-run critique
  // Move caret to end of inserted snippet.
  const newCaret = (slashIdx >= 0 ? slashIdx : caret) + resolved.length;
  input.setSelectionRange(newCaret, newCaret);
  input.focus();
  closeSlashPicker();
  // Bump use_count + last_used_at (fire-and-forget).
  callChezConcierge({ action: "record_snippet_use", snippet_id: snippet.id }).catch(() => {});
  // Reflect locally so the picker sort updates on next open.
  snippet.use_count = (snippet.use_count || 0) + 1;
  snippet.last_used_at = new Date().toISOString();
}

function buildSnippetTokenContext(activeReq) {
  if (!activeReq) return {};
  const ctx = activeReq.context || {};
  const homeownerName = ctx.homeowner_name || ctx.user_name || "";
  const homeownerFirstName = homeownerName ? homeownerName.split(/\s+/)[0] : "";
  return {
    homeownerFirstName,
    homeownerName,
    addressStreet: ctx.address_street || ctx.property_street || "",
    vendorName: ctx.vendor_name || ctx.contractor_name || "",
    visitDate: ctx.visit_date || "",
    question: "",
  };
}

// ----------------------------------------------------------------------------
// Tag chip strip — renders in the case header below the existing chips.
// ----------------------------------------------------------------------------
// Phase 86E.2 — queue rail tag chip strip. Renders below the All/Mine/
// Urgent tabs. Each chip is a tag definition; clicking toggles the
// active filter (state.concierge.queueTagFilter). Only renders chips
// that have at least one applied case — keeps the strip tight when the
// taxonomy hasn't been used yet.
function renderQueueTagChipsHtml() {
  const defs = state.crm.tagDefinitions || [];
  if (defs.length === 0) return ""; // not loaded yet, or empty taxonomy
  const tagsInUse = new Set();
  for (const list of Object.values(state.crm.allTagsByRequest || {})) {
    for (const id of list) tagsInUse.add(id);
  }
  const visible = defs.filter((d) => tagsInUse.has(d.id));
  if (visible.length === 0) return "";
  const active = state.concierge.queueTagFilter;
  const chips = visible.map((d) => `
    <button type="button"
      class="cockpit-queue-tag cockpit-tag-chip cockpit-tag-chip--${escapeHtml(d.color || "muted")} ${active === d.slug ? "is-active" : ""}"
      data-queue-tag-filter="${escapeHtml(d.slug)}">
      ${escapeHtml(d.label)}
    </button>
  `).join("");
  const clear = active
    ? `<button type="button" class="cockpit-queue-tag cockpit-queue-tag--clear" data-queue-tag-filter="__clear">Clear</button>`
    : "";
  return `
    <div class="cockpit-queue__tags">
      ${chips}
      ${clear}
    </div>
  `;
}

function renderTagChipsHtml(activeReq) {
  if (!activeReq) return "";
  // Trigger load if we haven't yet.
  if (!state.crm.appliedTagsByRequest[activeReq.id]) {
    loadAppliedTagsForCase(activeReq.id).then(() => {
      if (state.view === "chez") renderConciergeCockpit();
    });
    return "";
  }
  const applied = state.crm.appliedTagsByRequest[activeReq.id] || [];
  const chips = applied.map((t) => `
    <button type="button" class="cockpit-tag-chip cockpit-tag-chip--${escapeHtml(t.color || "muted")}" data-tag-remove="${escapeHtml(t.slug)}" title="Click to remove">
      ${escapeHtml(t.label)} <span class="cockpit-tag-chip__x">×</span>
    </button>
  `).join("");
  return `
    <div class="cockpit-tags" data-cockpit-tags>
      ${chips}
      <button type="button" class="cockpit-tag-chip cockpit-tag-chip--add" data-tag-picker-open>+ Tag</button>
    </div>
  `;
}

function openTagPicker(anchor, activeReq) {
  if (!activeReq) return;
  const rect = anchor.getBoundingClientRect();
  let picker = document.querySelector("[data-tag-picker]");
  if (!picker) {
    picker = document.createElement("div");
    picker.className = "cockpit-tag-picker";
    picker.dataset.tagPicker = "true";
    document.body.appendChild(picker);
  }
  picker.style.position = "fixed";
  picker.style.left = `${rect.left}px`;
  picker.style.top = `${rect.bottom + 6}px`;
  picker.style.zIndex = "9999";
  const applied = new Set((state.crm.appliedTagsByRequest[activeReq.id] || []).map((t) => t.slug));
  picker.innerHTML = `
    <div class="cockpit-tag-picker__head">Apply a tag</div>
    ${state.crm.tagDefinitions.map((d) => `
      <button type="button" class="cockpit-tag-picker__row" data-tag-apply="${escapeHtml(d.slug)}">
        <span class="cockpit-tag-chip cockpit-tag-chip--${escapeHtml(d.color)}">${escapeHtml(d.label)}</span>
        ${applied.has(d.slug) ? `<span class="cockpit-muted">applied</span>` : ""}
      </button>
    `).join("")}
  `;
  picker.querySelectorAll("[data-tag-apply]").forEach((row) => {
    row.addEventListener("mousedown", async (e) => {
      e.preventDefault();
      const slug = row.dataset.tagApply;
      if (applied.has(slug)) return; // already applied
      await callChezConcierge({ action: "apply_tag", request_id: activeReq.id, tag_slug: slug });
      delete state.crm.appliedTagsByRequest[activeReq.id]; // force reload
      closeTagPicker();
      await loadAppliedTagsForCase(activeReq.id);
      renderConciergeCockpit();
    });
  });
  // Click-outside to close.
  setTimeout(() => {
    const handler = (ev) => {
      if (!picker.contains(ev.target)) {
        closeTagPicker();
        document.removeEventListener("mousedown", handler);
      }
    };
    document.addEventListener("mousedown", handler);
  }, 0);
}
function closeTagPicker() {
  document.querySelector("[data-tag-picker]")?.remove();
}

async function removeTagFromCase(activeReq, slug) {
  if (!activeReq || !slug) return;
  await callChezConcierge({ action: "remove_tag", request_id: activeReq.id, tag_slug: slug });
  delete state.crm.appliedTagsByRequest[activeReq.id];
  await loadAppliedTagsForCase(activeReq.id);
  renderConciergeCockpit();
}

function attachConciergeCockpitHandlers(activeReq, filteredCases) {
  const host = el.conciergeHost;
  if (!host) return;

  // ---- Top bar -----------------------------------------------------------

  const searchInput = host.querySelector("[data-cockpit-search]");
  if (searchInput) {
    searchInput.addEventListener("input", (e) => {
      state.concierge.searchQuery = e.target.value;
      renderConciergeCockpit();
      // Restore focus after re-render so typing isn't interrupted.
      const fresh = host.querySelector("[data-cockpit-search]");
      if (fresh) {
        fresh.focus();
        fresh.setSelectionRange(fresh.value.length, fresh.value.length);
      }
    });
    searchInput.addEventListener("keydown", (e) => {
      if (e.key === "Escape") {
        state.concierge.searchQuery = "";
        renderConciergeCockpit();
      }
    });
  }

  host.querySelector("[data-cockpit-toggle-vendor]")?.addEventListener("click", () => {
    state.concierge.ui.vendorOpen = !state.concierge.ui.vendorOpen;
    persistConciergeUI();
    renderConciergeCockpit();
  });

  host.querySelector("[data-cockpit-toggle-ai]")?.addEventListener("click", () => {
    state.concierge.ui.aiOpen = !state.concierge.ui.aiOpen;
    persistConciergeUI();
    renderConciergeCockpit();
  });

  host.querySelector("[data-cockpit-refresh]")?.addEventListener("click", async () => {
    try { await loadAdminData(); } catch (e) { console.warn("[concierge] refresh failed", e); }
    renderConciergeCockpit();
  });

  // ---- Queue rail --------------------------------------------------------

  host.querySelectorAll("[data-cockpit-queue-filter]").forEach((btn) => {
    btn.addEventListener("click", () => {
      state.concierge.queueFilter = btn.dataset.cockpitQueueFilter;
      renderConciergeCockpit();
    });
  });

  // Phase 86E.2 — queue tag chip toggles. Clicking an active chip clears
  // it (so the strip doubles as a toggle); clicking another swaps the
  // filter. "Clear" button explicitly resets to null.
  host.querySelectorAll("[data-queue-tag-filter]").forEach((chip) => {
    chip.addEventListener("click", () => {
      const slug = chip.dataset.queueTagFilter;
      if (slug === "__clear") {
        state.concierge.queueTagFilter = null;
      } else if (state.concierge.queueTagFilter === slug) {
        state.concierge.queueTagFilter = null;
      } else {
        state.concierge.queueTagFilter = slug;
      }
      renderConciergeCockpit();
    });
  });

  host.querySelectorAll("[data-cockpit-case-id]").forEach((btn) => {
    btn.addEventListener("click", async () => {
      const id = btn.dataset.cockpitCaseId;
      const req = (state.chezRequests || []).find((r) => r.id === id);
      if (!req) return;
      state.selectedChezRequest = req;
      // Reset the per-case Alfred sidebar tab to the actions view so the
      // copilot starts fresh for each case.
      state.concierge.alfred.tab = "actions";
      // Phase 83.1 — Master-detail nav. Selecting a case morphs the queue
      // rail into the chat panel so the operator works in the active
      // conversation, not against a list of one highlighted item.
      state.concierge.queueMode = "case";
      // Pre-load thread before render so the chat panel doesn't flash empty.
      await loadChezMessages(id);
      renderConciergeCockpit();
    });
  });

  host.querySelector("[data-cockpit-tip-case]")?.addEventListener("click", async (e) => {
    const id = e.currentTarget.dataset.cockpitTipCase;
    const req = (state.chezRequests || []).find((r) => r.id === id);
    if (!req) return;
    state.selectedChezRequest = req;
    state.concierge.queueMode = "case";
    await loadChezMessages(id);
    renderConciergeCockpit();
  });

  if (!activeReq) return;

  // ---- Homeowner panel — dossier chip drilldowns -----------------------

  host.querySelectorAll("[data-cockpit-dossier-entity]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const entity = btn.dataset.cockpitDossierEntity;
      const id = btn.dataset.cockpitDossierId;
      openDossierDrawer(activeReq.household_id, entity, id);
    });
  });

  // Phase 83.5 — Family member clicks open a person-scoped drawer
  // (related cases, assigned tasks, role + access).
  host.querySelectorAll("[data-cockpit-family-id]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const id = btn.dataset.cockpitFamilyId;
      const kind = btn.dataset.cockpitFamilyKind || "family_member";
      openFamilyMemberDrawer(activeReq.household_id, kind, id);
    });
  });

  // Phase 83.5 — Stage tracker clicks scroll to the relevant section.
  host.querySelectorAll("[data-cockpit-stage]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const stage = btn.dataset.cockpitStage;
      scrollWorkspaceToStage(stage);
    });
  });

  // ---- AI brief tabs -----------------------------------------------------

  host.querySelectorAll("[data-cockpit-brief-tab]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const tab = btn.dataset.cockpitBriefTab;
      state.concierge.briefTab = state.concierge.briefTab || {};
      state.concierge.briefTab[activeReq.id] = tab;
      renderConciergeCockpit();
    });
  });

  // ---- Alfred sidebar tabs ----------------------------------------------

  host.querySelectorAll("[data-cockpit-alfred-tab]").forEach((btn) => {
    btn.addEventListener("click", () => {
      state.concierge.alfred.tab = btn.dataset.cockpitAlfredTab;
      renderConciergeCockpit();
    });
  });

  // ---- Alfred composer ---------------------------------------------------

  const alfredInput = host.querySelector("[data-cockpit-alfred-input]");
  if (alfredInput) {
    alfredInput.addEventListener("input", (e) => {
      state.concierge.alfred.input = state.concierge.alfred.input || {};
      state.concierge.alfred.input[activeReq.id] = e.target.value;
    });
    alfredInput.addEventListener("keydown", async (e) => {
      if (e.key === "Enter" && !e.shiftKey) {
        e.preventDefault();
        await sendConciergeAlfredMessage(activeReq);
      }
    });
  }

  // ---- Composer (reply form) ---------------------------------------------

  const composerInput = host.querySelector("[data-cockpit-reply-input]");
  if (composerInput) {
    // Phase 86B — slash composer detection.
    // Watches for "/" at start-of-line or after whitespace; opens the
    // snippet picker. Picker filters by the chars typed after "/".
    // Keyboard: ArrowUp/Down move cursor, Enter selects, Esc closes.
    composerInput.addEventListener("keydown", (ev) => {
      if (!state.crm.slashOpen) return;
      if (ev.key === "Escape") { ev.preventDefault(); closeSlashPicker(); return; }
      if (ev.key === "ArrowDown") { ev.preventDefault(); state.crm.slashCursor++; renderSlashPicker(composerInput, activeReq); return; }
      if (ev.key === "ArrowUp")   { ev.preventDefault(); state.crm.slashCursor = Math.max(0, state.crm.slashCursor - 1); renderSlashPicker(composerInput, activeReq); return; }
      if (ev.key === "Enter") {
        ev.preventDefault();
        const q = (state.crm.slashQuery || "").toLowerCase();
        const matches = state.crm.snippets.filter((s) =>
          !q ||
          (s.slug || "").includes(q) ||
          (s.label || "").toLowerCase().includes(q) ||
          (s.category || "").toLowerCase().includes(q)
        );
        const snippet = matches[state.crm.slashCursor];
        if (snippet) insertSnippetIntoComposer(composerInput, snippet, activeReq);
      }
    });

    composerInput.addEventListener("input", (e) => {
      state.concierge.composer = state.concierge.composer || {};
      const slot = state.concierge.composer[activeReq.id] = state.concierge.composer[activeReq.id] || { tone: "warm" };
      slot.draft = e.target.value;

      // Slash trigger detection: look at the character right before the caret.
      // A "/" at start-of-line or right after whitespace opens the picker.
      const caret = e.target.selectionStart ?? slot.draft.length;
      const before = slot.draft.slice(0, caret);
      const slashIdx = before.lastIndexOf("/");
      const shouldOpen = slashIdx >= 0 &&
        (slashIdx === 0 || /\s/.test(before[slashIdx - 1])) &&
        !before.slice(slashIdx).includes(" ") && // closed once they type a space
        !before.slice(slashIdx).includes("\n");
      if (shouldOpen) {
        state.crm.slashQuery = before.slice(slashIdx + 1);
        if (!state.crm.slashOpen) openSlashPicker(composerInput, activeReq);
        else renderSlashPicker(composerInput, activeReq);
      } else if (state.crm.slashOpen) {
        closeSlashPicker();
      }

      // Re-compute critique on debounce — but DON'T re-render the whole
      // cockpit on every keystroke (would lose focus). Update the critique
      // node in place.
      const critique = slot.draft ? assessConciergeReplyTone(slot.draft, slot.tone) : null;
      slot.critique = critique;
      const critiqueNode = host.querySelector(".cockpit-critique");
      const composerNode = host.querySelector(".cockpit-composer");
      if (critique) {
        if (critiqueNode) {
          critiqueNode.querySelector("span:nth-of-type(2)").innerHTML = `<b>Alfred:</b> ${escapeHtml(critique)}`;
        } else if (composerNode) {
          // Inject a critique row.
          const after = composerInput;
          const div = document.createElement("div");
          div.className = "cockpit-critique";
          div.innerHTML = `
            <span class="cockpit-spark cockpit-spark--sm">✦</span>
            <span><b>Alfred:</b> ${escapeHtml(critique)}</span>
            <span class="cockpit-critique__tone">Tone: ${escapeHtml(slot.tone)}</span>
          `;
          after.parentNode.insertBefore(div, after.nextSibling);
        }
      } else if (critiqueNode) {
        critiqueNode.remove();
      }
    });
  }

  // Phase 86B — tag chip interactions.
  host.querySelector("[data-tag-picker-open]")?.addEventListener("click", (ev) => {
    ev.stopPropagation();
    openTagPicker(ev.currentTarget, activeReq);
  });
  host.querySelectorAll("[data-tag-remove]").forEach((chip) => {
    chip.addEventListener("click", async (ev) => {
      ev.stopPropagation();
      const slug = chip.dataset.tagRemove;
      await removeTagFromCase(activeReq, slug);
    });
  });

  host.querySelectorAll("[data-cockpit-tone]").forEach((btn) => {
    btn.addEventListener("click", () => {
      state.concierge.composer = state.concierge.composer || {};
      const slot = state.concierge.composer[activeReq.id] = state.concierge.composer[activeReq.id] || { draft: "" };
      slot.tone = btn.dataset.cockpitTone;
      renderConciergeCockpit();
    });
  });

  // ---- Reply form submit + send variants ---------------------------------

  const replyForm = host.querySelector("[data-cockpit-reply-form]");
  if (replyForm) {
    replyForm.addEventListener("submit", async (e) => {
      e.preventDefault();
      // Default submit = "Send · waiting on customer"
      await submitConciergeReply(activeReq, replyForm, "waiting_customer");
    });
  }

  // ---- Cockpit-wide [data-cockpit-action] delegation --------------------

  host.querySelectorAll("[data-cockpit-action]").forEach((btn) => {
    btn.addEventListener("click", async (e) => {
      const action = btn.dataset.cockpitAction;
      if (!action) return;
      e.stopPropagation();
      await handleConciergeAction(action, activeReq, btn);
    });
  });

  // Phase 86C — vendor card outbound buttons (Email + Counter).
  host.querySelectorAll("[data-vendor-email]").forEach((btn) => {
    btn.addEventListener("click", (e) => {
      e.stopPropagation();
      const email = btn.dataset.vendorEmail;
      const name = btn.dataset.vendorNameAttr || "";
      if (!email) return;
      openVendorEmailComposer(activeReq, { name, email });
    });
  });
  host.querySelectorAll("[data-vendor-counter]").forEach((btn) => {
    btn.addEventListener("click", (e) => {
      e.stopPropagation();
      const name = btn.dataset.vendorNameAttr || "";
      const email = btn.dataset.vendorEmail || "";
      const cost = btn.dataset.vendorCost || "";
      openVendorCounterComposer(activeReq, { name, email, currentCostLabel: cost });
    });
  });

  // ---- Vendor sheet — reuse legacy handlers --------------------------
  // The vendor cards use the same data attributes (`[data-vendor-key]`,
  // `[data-vendor-field]`, etc.) the legacy attachChezPanelHandlers wires,
  // but scoped to the cockpit host. Run that handler attachment now so
  // every vendor row, slot input, recommend toggle, and ✨ Summarize button
  // wires up against the live state cache.
  attachConciergeVendorHandlers(host, activeReq);

  // ---- Visit cards — same pattern ---------------------------------------
  attachConciergeVisitHandlers(host, activeReq);
}

// Persist Alfred on/off + density to localStorage so the operator's choice
// survives reload.
function persistConciergeUI() {
  try {
    localStorage.setItem("chez-cockpit-ui-v1", JSON.stringify(state.concierge.ui));
  } catch (e) { /* localStorage unavailable */ }
}
function restoreConciergeUI() {
  try {
    const raw = localStorage.getItem("chez-cockpit-ui-v1");
    if (raw) {
      const parsed = JSON.parse(raw);
      state.concierge.ui = { ...state.concierge.ui, ...parsed };
    }
  } catch (e) { /* ignore */ }
}

// Available cockpit width = 100vw - 260 (admin nav). 4-pane mode (queue +
// homeowner + workspace + Alfred) needs ~1640px viewport to leave the
// workspace ≥400px wide. Below that, Alfred coexists awkwardly. We:
//   1) on first load, auto-collapse Alfred at <1640px (sane default)
//   2) when the user explicitly toggles Alfred on at narrow widths,
//      render it as an absolute-positioned overlay instead of a column
//      so the workspace stays usable underneath.
function isConciergeNarrow() {
  // 1100 = drop homeowner threshold; 1640 = drop Alfred threshold.
  // Detect using window.innerWidth so it tracks live resizes.
  return (window.innerWidth || 1280) < 1640;
}
function applyConciergeNarrowDefaults() {
  // First-load only — once the user has touched the toggle (persisted
  // value exists), respect their choice.
  let persisted = null;
  try { persisted = localStorage.getItem("chez-cockpit-ui-v1"); } catch (e) {}
  if (!persisted && isConciergeNarrow()) {
    state.concierge.ui.aiOpen = false;
  }
}
// Fire once at boot (after restoreConciergeUI sets persisted values).
applyConciergeNarrowDefaults();

// Re-render the cockpit when the viewport crosses the narrow/wide breakpoint
// so Alfred swaps between column and overlay mode cleanly. Debounced so a
// continuous drag-resize doesn't thrash innerHTML 60 times a second.
let __conciergeResizeTimer = null;
let __conciergeLastNarrow = isConciergeNarrow();
window.addEventListener("resize", () => {
  if (state.view !== "chez") return;
  if (__conciergeResizeTimer) clearTimeout(__conciergeResizeTimer);
  __conciergeResizeTimer = setTimeout(() => {
    const narrowNow = isConciergeNarrow();
    if (narrowNow !== __conciergeLastNarrow) {
      __conciergeLastNarrow = narrowNow;
      renderConciergeCockpit();
    }
  }, 180);
});

// =============================================================================
// COCKPIT — primary action dispatcher. Every button that mutates state goes
// through here. Each branch wires to a real Edge Function action or a local
// state mutation that ultimately re-renders.
// =============================================================================

async function handleConciergeAction(action, req, btn) {
  switch (action) {
    case "new-case":
      // Phase 84 — operator-initiated case. A small modal: pick household,
      // pick category, summary, optional initial message. Fires the
      // admin_submit Edge Function action which creates a chez_requests
      // row attributed to the homeowner's user_id but flagged
      // admin_initiated so the iOS thread shows "Chez started this case
      // for you."
      await openConciergeNewCaseModal();
      return;

    case "back-to-queue":
      // Phase 83.1 — Flip the queue rail back from chat-panel mode to the
      // case list. The selected case stays in state so the workspace
      // doesn't lose its data; only the rail's render mode changes.
      state.concierge.queueMode = "list";
      renderConciergeCockpit();
      return;

    case "reassign":
      // Single-agent for v1. The button is rendered enabled with a tooltip
      // explaining the constraint, so clicking it lands a non-blocking
      // toast rather than freezing the tab with a native alert.
      showAdminToast("Single-agent setup. Reassignment unlocks when additional Chez operators come online.", { kind: "info" });
      return;

    case "snooze":
      await snoozeConciergeCase(req);
      return;

    case "resolved": {
      // CRITICAL — destructive customer-visible action. The transition writes
      // a permanent "Chez marked this resolved" system message to the
      // homeowner thread and pushes via iOS. Always confirm.
      const ok = await openConfirmModal({
        title: "Mark case as resolved?",
        body: "The homeowner will see a permanent system message in their Chez thread (\"Chez marked this resolved\"). If you Reopen later, the resolved message stays on the thread — it isn't undoable.",
        confirmLabel: "Mark resolved",
      });
      if (!ok) return;
      await performChezTransition(req, "resolved");
      return;
    }
    case "waiting": {
      // CRITICAL — destructive customer-visible action. The transition writes
      // a permanent "Chez is waiting on your answer" system message. Confirm
      // before firing.
      if (req.status === "waiting_customer") {
        showAdminToast("Case is already waiting on the customer.", { kind: "info" });
        return;
      }
      const ok = await openConfirmModal({
        title: "Mark case waiting on customer?",
        body: "The homeowner will see a permanent system message in their Chez thread (\"Chez is waiting on your answer\") and the SLA clock pauses. The message stays on the thread even if you mark open again.",
        confirmLabel: "Mark waiting",
      });
      if (!ok) return;
      await performChezTransition(req, "waiting_customer");
      return;
    }
    case "reopen": {
      // Destructive customer-visible action. Writes "Chez reopened this
      // request" to the thread.
      const ok = await openConfirmModal({
        title: "Reopen this case?",
        body: "The homeowner will see a permanent system message in their Chez thread (\"Chez reopened this request\"). The SLA clock restarts.",
        confirmLabel: "Reopen",
      });
      if (!ok) return;
      await performChezTransition(req, "open");
      return;
    }

    case "rerun-analysis":
      runChezAnalysis(req.id, true);
      renderConciergeCockpit();
      return;

    case "expand-vendor":
    case "collapse-vendor": {
      const card = btn.closest("[data-vendor-key]");
      if (!card) return;
      const key = card.getAttribute("data-vendor-key");
      state.chezExpandedVendorKeys = state.chezExpandedVendorKeys || {};
      state.chezExpandedVendorKeys[req.id] = state.chezExpandedVendorKeys[req.id] || {};
      state.chezExpandedVendorKeys[req.id][key] = action === "expand-vendor";
      renderConciergeCockpit();
      return;
    }

    case "add-vendor-manual":
      // Open the proposal builder with a single empty vendor row so the
      // operator can add a candidate by hand.
      startProposalFlow(req);
      return;

    case "find-more-vendors": {
      // Inline prompt for category — the proposal builder has the full
      // search flow (with location pre-fill from the dossier).
      const dossier = (state.chezDossiersByHousehold || {})[req.household_id];
      const property = dossier?.properties?.[0];
      const town = property?.city || "";
      const stateCode = property?.state || "";
      const cached = state.chezAnalysisByRequest?.[req.id];
      const inferred = cached?.analysis?.inferred_category || "";
      const category = window.prompt(`Search local vendors near ${town || "the homeowner"}, ${stateCode || ""}. Category?`, inferred || (req.category === "find_handyman" ? "handyman" : ""));
      if (!category || !category.trim()) return;
      try {
        btn.disabled = true;
        const orig = btn.textContent;
        btn.textContent = "Searching…";
        const session = (await supabase.auth.getSession()).data.session;
        const resp = await fetch(`${SUPABASE_URL}/functions/v1/find-local-vendors`, {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            "apikey": SUPABASE_ANON_KEY,
            "Authorization": `Bearer ${session?.access_token || SUPABASE_ANON_KEY}`,
          },
          body: JSON.stringify({ town, state: stateCode, category: category.trim() }),
        });
        if (resp.ok) {
          const data = await resp.json();
          const newPlaces = (data.vendors || []).map((v) => ({ ...v, _source: "places" }));
          // Merge into the analysis cache so the vendor sheet picks them up.
          state.chezAnalysisByRequest[req.id] = state.chezAnalysisByRequest[req.id] || { analysis: {}, existing_vendors: [], places_candidates: [] };
          const existing = new Set((state.chezAnalysisByRequest[req.id].places_candidates || []).map((v) => v.name));
          const merged = (state.chezAnalysisByRequest[req.id].places_candidates || []).concat(newPlaces.filter((v) => !existing.has(v.name)));
          state.chezAnalysisByRequest[req.id].places_candidates = merged;
        }
        btn.disabled = false;
        btn.textContent = orig;
        renderConciergeCockpit();
      } catch (err) {
        btn.disabled = false;
        alert(`Vendor search failed: ${err.message || err}`);
      }
      return;
    }

    case "package-send":
      await packageAndSendRecommendedVendors(req);
      return;

    case "open-proposal-builder":
      startProposalFlow(req);
      return;

    case "assign-handyman":
      await assignHandymanToAssessmentFlow(req, btn);
      return;

    case "scroll-to-visits": {
      // Jump the workspace to the active visits panel and pulse the first
      // active card so the operator's eye lands on what they need to do.
      const host = el.conciergeHost;
      const target = host?.querySelector(".admin-chez__visits .admin-chez__visit-card") || host?.querySelector(".admin-chez__visits");
      if (target) {
        target.scrollIntoView({ behavior: "smooth", block: "center" });
        target.classList.add("is-pulsing");
        setTimeout(() => target.classList.remove("is-pulsing"), 1500);
      }
      return;
    }

    case "send-checkin-reminder": {
      // Pre-fill the composer with a soft check-in nudge so the operator
      // can send "haven't heard back, want to push?" with one click.
      const dossier = (state.chezDossiersByHousehold || {})[req.household_id];
      const first = dossier ? primaryHomeownerLabel(dossier).split(" ")[0] : "there";
      const tone = state.concierge.composer?.[req.id]?.tone || "warm";
      const drafts = {
        warm: `Hi ${first} — just making sure my proposal landed. Happy to walk through any of the options on the phone if it'd help. No rush; let me know whenever you're ready.`,
        direct: `${first} — quick check on the proposal I sent. Any of the options work, or want me to dig further?`,
        formal: `Hello ${first}, following up on the proposal sent earlier. Please let me know which option you'd like to pursue, or if any modifications would be helpful.`,
      };
      state.concierge.composer = state.concierge.composer || {};
      state.concierge.composer[req.id] = { draft: drafts[tone] || drafts.warm, tone, critique: assessConciergeReplyTone(drafts[tone] || drafts.warm, tone) };
      // Focus the composer input on the next paint.
      renderConciergeCockpit();
      requestAnimationFrame(() => {
        el.conciergeHost?.querySelector("[data-cockpit-reply-input]")?.focus();
      });
      return;
    }

    case "draft-clarifier": {
      // Phase 83.5 — Clarify-archetype CTA. Pre-fills the composer with a
      // tone-aware question that gets the homeowner to tell us what kind
      // of help they actually want, so we can route to the right workflow.
      const dossier = (state.chezDossiersByHousehold || {})[req.household_id];
      const first = dossier ? primaryHomeownerLabel(dossier).split(" ")[0] : "there";
      const tone = state.concierge.composer?.[req.id]?.tone || "warm";
      const drafts = {
        warm: `Hey ${first} — got your note, happy to help! Quick clarifier so I get this right: are you looking for someone to come out and do this for you, advice on how to handle it yourself, or just a vendor recommendation? Also, is there a specific system / area in the house this is about?`,
        direct: `${first} — to route this properly: do you want a vendor to handle it, advice on doing it yourself, or just a recommendation? And which system / area of the house?`,
        formal: `Hello ${first}, to ensure we route your request to the right resource, could you let us know whether you'd like a vendor to perform the work, advice for handling it yourself, or simply a recommendation? Additionally, please specify which system or area of the home this concerns.`,
      };
      state.concierge.composer = state.concierge.composer || {};
      state.concierge.composer[req.id] = { draft: drafts[tone] || drafts.warm, tone, critique: assessConciergeReplyTone(drafts[tone] || drafts.warm, tone) };
      renderConciergeCockpit();
      requestAnimationFrame(() => {
        el.conciergeHost?.querySelector("[data-cockpit-reply-input]")?.focus();
      });
      return;
    }

    case "reclassify-case": {
      // Phase 83.5 — Manual archetype override. Lets the operator pick
      // the right workflow when the auto-classifier got it wrong (or when
      // a clarify case has now been answered and needs to flip).
      // Phase 85.5: replaced window.prompt() with an in-app radio modal so
      // the cockpit no longer freezes the browser tab to ask for input.
      const currentOverride = (state.chezArchetypeOverride || {})[req.id] || null;
      const picked = await openReclassifyModal(currentOverride);
      if (!picked) return;
      // Stash the override on the request's context (in-memory only for
      // v1 — survives a re-render but not a page reload). Future: persist
      // to chez_requests.archetype_override.
      state.chezArchetypeOverride = state.chezArchetypeOverride || {};
      state.chezArchetypeOverride[req.id] = picked;
      renderConciergeCockpit();
      return;
    }

    case "search-equipment-manuals": {
      // Phase 83.5 — Internal task helper. Opens a side prompt for a model
      // number, then fires the existing lookup-manual edge function.
      // Fallback: open the catalog browser tab.
      const model = window.prompt("Equipment model number to search? (e.g. AOSCG502W2)", "");
      if (!model || !model.trim()) return;
      try {
        const session = (await supabase.auth.getSession()).data.session;
        const resp = await fetch(`${SUPABASE_URL}/functions/v1/lookup-manual`, {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            "apikey": SUPABASE_ANON_KEY,
            "Authorization": `Bearer ${session?.access_token || SUPABASE_ANON_KEY}`,
          },
          body: JSON.stringify({ model_number: model.trim() }),
        });
        if (resp.ok) {
          const data = await resp.json();
          const manualUrl = data?.manual_url || data?.url || null;
          if (manualUrl) {
            // Pre-fill the composer with a reply that includes the manual
            // link so Tom can click Send.
            const dossier = (state.chezDossiersByHousehold || {})[req.household_id];
            const first = dossier ? primaryHomeownerLabel(dossier).split(" ")[0] : "there";
            const tone = state.concierge.composer?.[req.id]?.tone || "warm";
            const draft = `Hey ${first} — found the Use & Care Guide for your ${model.trim()}. Here's the link:\n\n${manualUrl}\n\nLet me know if you need anything else.`;
            state.concierge.composer = state.concierge.composer || {};
            state.concierge.composer[req.id] = { draft, tone, critique: assessConciergeReplyTone(draft, tone) };
            renderConciergeCockpit();
            return;
          }
          alert("No manual found in the catalog. Try the manufacturer's website or the homeowner's documents vault.");
        } else {
          alert(`Search failed (${resp.status}). Try the manufacturer's website directly.`);
        }
      } catch (err) {
        console.warn("[concierge] manual search failed", err);
        alert(`Search failed: ${err.message || err}`);
      }
      return;
    }

    case "open-vault": {
      // Open the homeowner's documents vault in a new tab. For v1 this is
      // a discoverability nudge — the admin doesn't have an in-cockpit
      // doc browser yet, but tom@getchez.com has admin RLS bypass via
      // service role so they can inspect the household's docs from the
      // Supabase dashboard.
      const householdId = req.household_id;
      const dashboardUrl = `https://supabase.com/dashboard/project/jsucwnkntdrxhysojgri/editor/documents?filter=household_id%3Deq%3A${householdId}`;
      window.open(dashboardUrl, "_blank");
      return;
    }

    case "alfred-resolve-with-proposal":
      // One-click: open the proposal builder pre-loaded with the
      // recommended vendors (the underlying packageAndSendRecommendedVendors
      // is the action proper — but it goes straight to send, no preview).
      // For "with my approval", show a confirm first.
      if (confirm("Send all recommended vendors to the homeowner? They'll get Approve/Counter/Decline cards in their thread.")) {
        await packageAndSendRecommendedVendors(req);
      }
      return;

    case "alfred-resolve-open-top": {
      // Expand the top-fit vendor's call form so the operator can start
      // logging the call.
      const cached = state.chezAnalysisByRequest?.[req.id];
      if (!cached) return;
      const candidates = [
        ...((cached.existing_vendors || []).map((v) => ({ ...v, _source: "existing" }))),
        ...((cached.places_candidates || []).map((v) => ({ ...v, _source: "places" }))),
      ].map((v) => ({ ...v, _fit: computeChezVendorFit(v) }))
        .sort((a, b) => b._fit - a._fit);
      if (candidates.length === 0) return;
      const top = candidates[0];
      const key = vendorCandidateKey(top);
      state.chezExpandedVendorKeys = state.chezExpandedVendorKeys || {};
      state.chezExpandedVendorKeys[req.id] = state.chezExpandedVendorKeys[req.id] || {};
      state.chezExpandedVendorKeys[req.id][key] = true;
      // Make sure vendor sheet is open so the form is visible.
      state.concierge.ui.vendorOpen = true;
      persistConciergeUI();
      renderConciergeCockpit();
      // Scroll the workspace down to the vendor row.
      requestAnimationFrame(() => {
        const card = el.conciergeHost?.querySelector(`[data-vendor-key="${key}"]`);
        card?.scrollIntoView({ behavior: "smooth", block: "center" });
      });
      return;
    }

    case "summarize-thread":
      await summarizeConciergeThread(req, btn);
      return;

    case "draft-from-brief":
      await draftConciergeReplyFromBrief(req);
      return;

    case "save-draft": {
      // Local state already tracks the draft as the user types; this just
      // confirms with a transient feedback line so the operator knows it
      // was captured.
      const fb = el.conciergeHost?.querySelector("[data-cockpit-feedback]");
      if (fb) {
        fb.textContent = "Draft saved locally — survives within this session.";
        setTimeout(() => { if (fb) fb.textContent = ""; }, 2400);
      }
      return;
    }

    case "send-keep-open": {
      const form = el.conciergeHost?.querySelector("[data-cockpit-reply-form]");
      if (form) await submitConciergeReply(req, form, null);
      return;
    }

    case "focus-composer": {
      const input = el.conciergeHost?.querySelector("[data-cockpit-reply-input]");
      input?.focus();
      input?.scrollIntoView({ behavior: "smooth", block: "center" });
      return;
    }

    case "alfred-prompt": {
      // Click a suggested-prompt button → set the Alfred input to that
      // prompt and immediately send it (saves the operator a click).
      const prompt = btn.dataset.prompt;
      if (!prompt) return;
      state.concierge.alfred.input = state.concierge.alfred.input || {};
      state.concierge.alfred.input[req.id] = prompt;
      await sendConciergeAlfredMessage(req);
      return;
    }

    case "alfred-send":
      await sendConciergeAlfredMessage(req);
      return;

    case "open-past-case": {
      const id = btn.dataset.pastId;
      const past = (state.chezRequests || []).find((r) => r.id === id);
      if (past) {
        state.selectedChezRequest = past;
        state.concierge.alfred.tab = "actions";
        await loadChezMessages(id);
        renderConciergeCockpit();
      } else {
        alert("That past case isn't loaded — refresh and try again.");
      }
      return;
    }

    case "open-profile":
      openHouseholdProfileDrawer(req.household_id);
      return;

    // ---- Visit-card actions (legacy handler ports) ------------------
    case "adopt-slot": {
      // Phase 83.2 — Adopting a vendor-offered slot populates the canonical
      // `scheduled_for` datetime when the slot has a parseable ISO; falls
      // back to the freeform `scheduled_window` note when it doesn't.
      const card = btn.closest("[data-visit-id]");
      if (!card) return;
      const slotIso = btn.dataset.slotIso || "";
      const slotText = btn.dataset.slotText || "";
      if (slotIso) {
        const dtInput = card.querySelector("[data-visit-field='scheduled_for']");
        if (dtInput) {
          dtInput.value = slotIso;
          dtInput.dispatchEvent(new Event("change", { bubbles: true }));
        }
      } else {
        const noteInput = card.querySelector("[data-visit-field='scheduled_window']");
        if (noteInput) {
          noteInput.value = slotText;
          noteInput.dispatchEvent(new Event("change", { bubbles: true }));
        }
      }
      return;
    }
    case "propose-alternate-dates": {
      // Phase 83.4 — Send the homeowner 2-3 confirmed dates after they've
      // approved a vendor. The homeowner picks one, the Edge Function
      // auto-flips the visit to scheduled with their chosen datetime.
      // Pre-fills the proposal builder's message with the vendor's name
      // so the operator doesn't retype context.
      const card = btn.closest("[data-visit-id]");
      const visitId = card?.getAttribute("data-visit-id");
      const visit = (state.chezVisitsByRequest?.[req.id] || []).find((v) => v.id === visitId);
      const vendorName = visit?.vendor_name || "the vendor";
      startProposalFlow(req);
      requestAnimationFrame(() => {
        const modal = document.querySelector("[data-chez-proposal-modal]");
        if (!modal) return;
        // Switch to date_slot tab.
        modal.querySelector("[data-proposal-tab='date']")?.click();
        // Pre-fill the message body with a homeowner-facing template that
        // names the vendor. The operator can edit before sending.
        const messageInput = modal.querySelector("textarea[name='content']");
        if (messageInput && !messageInput.value) {
          messageInput.value = `${vendorName} can do any of these dates. Tap Approve on whichever fits — we'll lock it in with them.`;
        }
      });
      return;
    }
    case "visit-mark-scheduled":
      await visitMarkAction(req, btn, "scheduled");
      return;
    case "visit-mark-completed":
      await visitMarkAction(req, btn, "completed");
      return;
    case "visit-cancel":
      await visitMarkAction(req, btn, "cancelled");
      return;
    case "visit-save-notes":
      await visitSaveAction(req, btn);
      return;
    case "mark-resolved-from-visits":
      await performChezTransition(req, "resolved");
      return;
    case "expand-analysis":
      state.chezAnalysisExpandedByRequest = state.chezAnalysisExpandedByRequest || {};
      state.chezAnalysisExpandedByRequest[req.id] = true;
      renderConciergeCockpit();
      return;

    default:
      console.warn("[concierge] unhandled action:", action);
  }
}

// Phase 84 — Operator-initiated case ("+ New case" in cockpit topbar).
// Small modal: pick household + category + summary + optional message.
// Fires admin_submit which creates a chez_requests row flagged
// admin_initiated; the iOS thread surfaces "Chez started this for you".
async function openConciergeNewCaseModal() {
  // Tear down any existing modal.
  document.querySelector("[data-chez-newcase-modal]")?.remove();

  // Build the household picker from the unique households across the
  // current chezRequests + dossier cache. For households we've never
  // touched, we'd need a separate fetch; for v1 we use what we have.
  const seenHouseholds = new Map();
  for (const r of (state.chezRequests || [])) {
    if (r.household_id && !seenHouseholds.has(r.household_id)) {
      // Find a friendly name from the dossier cache if loaded.
      const dossier = (state.chezDossiersByHousehold || {})[r.household_id];
      const name = dossier ? primaryHomeownerLabel(dossier) : `Household ${r.household_id.slice(0, 8)}`;
      seenHouseholds.set(r.household_id, name);
    }
  }
  const households = Array.from(seenHouseholds.entries())
    .map(([id, name]) => ({ id, name }))
    .sort((a, b) => a.name.localeCompare(b.name));

  const categoryOptions = [
    { value: "find_vendor", label: "🔍 Find a vendor" },
    { value: "get_quote", label: "💰 Get a quote" },
    { value: "schedule_visit", label: "📅 Schedule a visit" },
    { value: "coordinate_task", label: "✅ Coordinate a task" },
    { value: "find_handyman", label: "🛠️ Find a handyman" },
    { value: "general", label: "💬 General help" },
  ];

  const modal = document.createElement("div");
  modal.className = "admin-modal";
  modal.setAttribute("data-chez-newcase-modal", "");
  modal.innerHTML = `
    <div class="admin-modal__backdrop" data-modal-close></div>
    <div class="admin-modal__panel" style="max-width: 540px;">
      <header class="admin-modal__head">
        <div>
          <h2>Start a new case</h2>
          <p class="admin-muted">For when a homeowner reaches you outside the app — phone, email, text. The case lands in the homeowner's iOS Chez thread flagged "Chez started this for you."</p>
        </div>
        <button type="button" class="admin-modal__close" data-modal-close aria-label="Close">×</button>
      </header>
      <div class="admin-modal__body">
        <label>
          <span>Household</span>
          <select name="household">
            ${households.length === 0
              ? `<option value="">— No households loaded yet — refresh the queue —</option>`
              : `<option value="">Pick a household</option>` + households.map((h) => `<option value="${escapeHtml(h.id)}">${escapeHtml(h.name)}</option>`).join("")}
          </select>
        </label>
        <label>
          <span>Category</span>
          <select name="category">
            ${categoryOptions.map((c) => `<option value="${escapeHtml(c.value)}">${escapeHtml(c.label)}</option>`).join("")}
          </select>
        </label>
        <label>
          <span>One-line summary</span>
          <input type="text" name="summary" placeholder="e.g. Margaret called about a roof leak — needs a roofer this week" />
        </label>
        <label>
          <span>Initial message to homeowner (optional)</span>
          <textarea name="initial_message" rows="3" placeholder="Hi Margaret — I'm starting a case to track the roofer hunt we just talked about. I'll have 2-3 options to you by Friday."></textarea>
        </label>
      </div>
      <footer class="admin-modal__foot">
        <button type="button" class="admin-button admin-button--ghost" data-modal-close>Cancel</button>
        <button type="button" class="admin-button admin-button--primary" data-newcase-submit>Create case</button>
      </footer>
    </div>
  `;
  document.body.appendChild(modal);
  modal.querySelectorAll("[data-modal-close]").forEach((b) => b.addEventListener("click", () => modal.remove()));

  modal.querySelector("[data-newcase-submit]").addEventListener("click", async (e) => {
    const btn = e.currentTarget;
    const householdId = modal.querySelector("select[name='household']").value;
    const category = modal.querySelector("select[name='category']").value;
    const summary = modal.querySelector("input[name='summary']").value.trim();
    const initialMessage = modal.querySelector("textarea[name='initial_message']").value.trim();
    if (!householdId) { alert("Pick a household."); return; }
    if (!summary) { alert("Add a one-line summary."); return; }
    btn.disabled = true; btn.textContent = "Creating…";
    try {
      const result = await callChezConcierge({
        action: "admin_submit",
        household_id: householdId,
        category,
        summary,
        context: { _admin_initiated: true },
        initial_message: initialMessage || undefined,
      });
      modal.remove();
      // Reload the queue + jump straight into the new case.
      await loadAdminData();
      const newId = (result?.request?.id) ?? null;
      if (newId) {
        const fresh = (state.chezRequests || []).find((r) => r.id === newId);
        if (fresh) {
          state.selectedChezRequest = fresh;
          state.concierge.queueMode = "case";
          await loadChezMessages(newId);
        }
      }
      renderConciergeCockpit();
    } catch (err) {
      console.warn("[admin] new case failed", err);
      alert(`Couldn't create case: ${err.message || err}`);
      btn.disabled = false; btn.textContent = "Create case";
    }
  });
}

// =============================================================================
// Phase 85.5 — Confirm / Snooze / Reclassify modals + lightweight toast
// =============================================================================
//
// Replaces the native `window.prompt()` and `window.alert()` calls scattered
// across the cockpit (Snooze, Reclassify, Reassign) with in-app modals that
// match the Households workbench pattern. Also adds an `openConfirmModal`
// helper used to guard the destructive case actions (Mark resolved / Reopen /
// Mark waiting on customer / Revoke Chez ownership) that previously fired
// instantly with no undo step.
//
// Why: the audit found that the same operator action (Snooze, Mark complete,
// Reclassify) had two completely different UX flows depending on surface.
// The workbench used polished modals; the cockpit used native dialogs that
// blocked the browser tab. Standardizing on the workbench pattern eliminates
// the asymmetry.

// Returns Promise<boolean> — true on confirm, false on cancel.
// `danger: true` styles the confirm button red; default is salmon primary.
function openConfirmModal({ title, body, confirmLabel = "Confirm", cancelLabel = "Cancel", danger = false } = {}) {
  return new Promise((resolve) => {
    const overlay = document.createElement("div");
    overlay.className = "admin-modal-overlay";
    overlay.innerHTML = `
      <div class="admin-modal admin-modal--sm" role="dialog" aria-modal="true">
        <header class="admin-modal__head">
          <h2>${escapeHtml(title || "Confirm")}</h2>
          <button type="button" class="admin-modal__close" aria-label="Close" data-confirm-cancel>&times;</button>
        </header>
        <div class="admin-modal__body">
          ${typeof body === "string" ? `<p class="admin-modal__intro">${escapeHtml(body)}</p>` : ""}
        </div>
        <div class="admin-modal__buttons" style="padding: 0 16px 16px;">
          <button type="button" class="admin-pill" data-confirm-cancel>${escapeHtml(cancelLabel)}</button>
          <button type="button" class="admin-pill ${danger ? "admin-pill--danger" : "admin-pill--action"}" data-confirm-ok>${escapeHtml(confirmLabel)}</button>
        </div>
      </div>
    `;
    document.body.appendChild(overlay);
    const cleanup = (result) => {
      document.removeEventListener("keydown", onKey);
      overlay.remove();
      resolve(result);
    };
    const onKey = (e) => {
      if (e.key === "Escape") { e.preventDefault(); cleanup(false); }
      else if (e.key === "Enter") { e.preventDefault(); cleanup(true); }
    };
    document.addEventListener("keydown", onKey);
    overlay.querySelectorAll("[data-confirm-cancel]").forEach((b) => b.addEventListener("click", () => cleanup(false)));
    overlay.querySelector("[data-confirm-ok]").addEventListener("click", () => cleanup(true));
    overlay.addEventListener("click", (e) => { if (e.target === overlay) cleanup(false); });
    // Autofocus the primary button so Enter commits immediately.
    requestAnimationFrame(() => overlay.querySelector("[data-confirm-ok]")?.focus());
  });
}

// Small non-blocking toast for status messages that don't need a modal.
// Replaces `alert()` for informational / non-actionable feedback. The toast
// auto-dismisses after `ms` milliseconds (default 3.5s) or on click.
function showAdminToast(message, { kind = "info", ms = 3500 } = {}) {
  let host = document.querySelector(".admin-toast-host");
  if (!host) {
    host = document.createElement("div");
    host.className = "admin-toast-host";
    document.body.appendChild(host);
  }
  const toast = document.createElement("div");
  toast.className = `admin-toast admin-toast--${kind}`;
  toast.textContent = message;
  host.appendChild(toast);
  // Trigger CSS transition.
  requestAnimationFrame(() => toast.classList.add("is-visible"));
  const dismiss = () => {
    toast.classList.remove("is-visible");
    setTimeout(() => toast.remove(), 200);
  };
  toast.addEventListener("click", dismiss);
  setTimeout(dismiss, ms);
}

// Snooze: in-app modal with quick-select pill row (4h / 24h / 48h / 72h) +
// a custom hours stepper. Writes a system-only audit message + transitions
// status to waiting_customer so the case stops counting against SLA. The
// next time the homeowner replies (or the operator manually reopens), it
// surfaces again.
async function snoozeConciergeCase(req) {
  const hours = await openSnoozeModal();
  if (!hours) return;
  const n = Number(hours);
  if (!Number.isFinite(n) || n < 1 || n > 72) {
    showAdminToast("Snooze duration must be between 1 and 72 hours.", { kind: "error" });
    return;
  }
  const until = new Date(Date.now() + n * 3600 * 1000);
  const note = `Snoozed by Chez until ${until.toLocaleString(undefined, { weekday: "short", month: "short", day: "numeric", hour: "numeric", minute: "2-digit" })}.`;
  try {
    // 1. Log the snooze as a thread system message via the reply path
    //    (acknowledgement_required false; the homeowner doesn't see it
    //    flagged as actionable).
    await callChezConcierge({
      action: "transition_status",
      request_id: req.id,
      to_status: "waiting_customer",
      note,
    });
    await loadChezMessages(req.id);
    await loadAdminData();
    renderConciergeCockpit();
  } catch (err) {
    showAdminToast(`Snooze failed: ${err.message || err}`, { kind: "error" });
  }
}

// In-app modal replacing `window.prompt("Snooze for how many hours? (1-72)")`.
// Returns a Promise<string|null> — the picked hours, or null on cancel.
function openSnoozeModal() {
  return new Promise((resolve) => {
    const overlay = document.createElement("div");
    overlay.className = "admin-modal-overlay";
    const presets = [
      { label: "4 hours",  value: 4 },
      { label: "Today",    value: 8 },
      { label: "Tomorrow", value: 24 },
      { label: "2 days",   value: 48 },
      { label: "3 days",   value: 72 },
    ];
    overlay.innerHTML = `
      <div class="admin-modal admin-modal--sm" role="dialog" aria-modal="true">
        <header class="admin-modal__head">
          <h2>Snooze case</h2>
          <button type="button" class="admin-modal__close" aria-label="Close" data-snooze-cancel>&times;</button>
        </header>
        <div class="admin-modal__body">
          <p class="admin-modal__intro">Pause the SLA clock. The case resurfaces when the homeowner replies or the timer ends.</p>
          <div class="admin-modal__quickpills">
            ${presets.map((p) => `
              <button type="button" class="admin-quickpill" data-snooze-pill data-snooze-value="${p.value}">${escapeHtml(p.label)}</button>
            `).join("")}
          </div>
          <label class="admin-modal__field" style="margin-top: 12px;">
            <span>Or custom hours (1-72)</span>
            <input type="number" min="1" max="72" step="1" value="24" data-snooze-custom class="admin-input" />
          </label>
        </div>
        <div class="admin-modal__buttons" style="padding: 0 16px 16px;">
          <button type="button" class="admin-pill" data-snooze-cancel>Cancel</button>
          <button type="button" class="admin-pill admin-pill--action" data-snooze-ok>Snooze</button>
        </div>
      </div>
    `;
    document.body.appendChild(overlay);
    const customInput = overlay.querySelector("[data-snooze-custom]");
    overlay.querySelectorAll("[data-snooze-pill]").forEach((pill) => {
      pill.addEventListener("click", () => {
        overlay.querySelectorAll("[data-snooze-pill]").forEach((b) => b.classList.remove("is-active"));
        pill.classList.add("is-active");
        customInput.value = pill.dataset.snoozeValue;
      });
    });
    const cleanup = (result) => {
      document.removeEventListener("keydown", onKey);
      overlay.remove();
      resolve(result);
    };
    const onKey = (e) => {
      if (e.key === "Escape") { e.preventDefault(); cleanup(null); }
      else if (e.key === "Enter") { e.preventDefault(); cleanup(customInput.value); }
    };
    document.addEventListener("keydown", onKey);
    overlay.querySelectorAll("[data-snooze-cancel]").forEach((b) => b.addEventListener("click", () => cleanup(null)));
    overlay.querySelector("[data-snooze-ok]").addEventListener("click", () => cleanup(customInput.value));
    overlay.addEventListener("click", (e) => { if (e.target === overlay) cleanup(null); });
    requestAnimationFrame(() => customInput.focus());
  });
}

// In-app modal replacing the `window.prompt(type 1-6)` reclassify picker.
// Returns a Promise<string|null> — the picked archetype slug, or null.
function openReclassifyModal(currentArchetype = null) {
  return new Promise((resolve) => {
    const choices = [
      { value: "clarify",            label: "Clarify",            sub: "Ask the homeowner first — what they need isn't clear yet" },
      { value: "coordinate_vendor",  label: "Coordinate visit",   sub: "Vendor is named — schedule the visit and confirm details" },
      { value: "internal_task",      label: "Internal task",      sub: "Chez handles this directly — no homeowner action needed" },
      { value: "find_vendor",        label: "Source vendors",     sub: "Full pipeline — find, vet, propose vendor candidates" },
      { value: "quote",              label: "Get a quote",        sub: "Competitive bidding — multiple vendors quote the same work" },
      { value: "general",            label: "General",            sub: "One-off question — reply and resolve" },
    ];
    const overlay = document.createElement("div");
    overlay.className = "admin-modal-overlay";
    overlay.innerHTML = `
      <div class="admin-modal admin-modal--sm" role="dialog" aria-modal="true">
        <header class="admin-modal__head">
          <h2>Reclassify this case</h2>
          <button type="button" class="admin-modal__close" aria-label="Close" data-reclassify-cancel>&times;</button>
        </header>
        <div class="admin-modal__body">
          <p class="admin-modal__intro">Pick the workflow that matches what the homeowner is actually asking for. The cockpit reroutes the case accordingly.</p>
          <div class="admin-modal__radios">
            ${choices.map((c) => `
              <label class="admin-modal__radio">
                <input type="radio" name="archetype" value="${escapeHtml(c.value)}" ${c.value === currentArchetype ? "checked" : ""} />
                <div>
                  <strong>${escapeHtml(c.label)}</strong>
                  <span class="admin-muted">${escapeHtml(c.sub)}</span>
                </div>
              </label>
            `).join("")}
          </div>
        </div>
        <div class="admin-modal__buttons" style="padding: 0 16px 16px;">
          <button type="button" class="admin-pill" data-reclassify-cancel>Cancel</button>
          <button type="button" class="admin-pill admin-pill--action" data-reclassify-ok>Reclassify</button>
        </div>
      </div>
    `;
    document.body.appendChild(overlay);
    const cleanup = (result) => {
      document.removeEventListener("keydown", onKey);
      overlay.remove();
      resolve(result);
    };
    const onKey = (e) => { if (e.key === "Escape") { e.preventDefault(); cleanup(null); } };
    document.addEventListener("keydown", onKey);
    overlay.querySelectorAll("[data-reclassify-cancel]").forEach((b) => b.addEventListener("click", () => cleanup(null)));
    overlay.querySelector("[data-reclassify-ok]").addEventListener("click", () => {
      const picked = overlay.querySelector("input[name='archetype']:checked");
      cleanup(picked ? picked.value : null);
    });
    overlay.addEventListener("click", (e) => { if (e.target === overlay) cleanup(null); });
  });
}

// Submit the reply form. `toStatus` controls what the case transitions to:
// "waiting_customer" for the primary submit, null for "Send · keep open".
async function submitConciergeReply(req, form, toStatus) {
  const content = (form.elements.content?.value || "").trim();
  if (!content) {
    alert("Type a reply first.");
    return;
  }
  const ack = form.elements.acknowledgement_required?.checked || false;
  const feedback = el.conciergeHost?.querySelector("[data-cockpit-feedback]");
  const submitBtn = form.querySelector("button[type='submit']");
  if (submitBtn) {
    submitBtn.disabled = true;
    submitBtn.textContent = "Sending…";
  }
  try {
    await callChezConcierge({
      action: "reply",
      request_id: req.id,
      content,
      acknowledgement_required: ack,
      to_status: toStatus,
    });
    // Clear the local draft cache so the next render shows an empty composer.
    if (state.concierge.composer && state.concierge.composer[req.id]) {
      state.concierge.composer[req.id] = { draft: "", tone: state.concierge.composer[req.id].tone || "warm" };
    }
    if (feedback) feedback.textContent = "Sent.";
    await loadAdminData();
    await loadChezMessages(req.id);
    renderConciergeCockpit();
  } catch (err) {
    console.warn("[concierge] reply failed", err);
    if (feedback) feedback.textContent = `Failed: ${err.message || err}`;
    if (submitBtn) {
      submitBtn.disabled = false;
      submitBtn.textContent = "Send · waiting on customer";
    }
  }
}

// "Draft from brief" — populates the composer with a tone-aware template
// that pulls in the cached AI brief summary so the operator gets a sane
// starting point.
async function draftConciergeReplyFromBrief(req) {
  const cached = state.chezAnalysisByRequest && state.chezAnalysisByRequest[req.id];
  const dossier = (state.chezDossiersByHousehold || {})[req.household_id];
  const homeownerFirst = dossier
    ? primaryHomeownerLabel(dossier).split(" ")[0]
    : "there";
  const tone = state.concierge.composer?.[req.id]?.tone || "warm";
  const summary = cached?.analysis?.summary || "Working on it.";
  const approach = cached?.analysis?.recommended_approach || "";
  // Compose a body that (1) acknowledges the homeowner, (2) notes what we
  // know from the brief, (3) commits to a next step + timeframe.
  const body = approach
    ? `Quick update on ${escapeForDraft(req.summary || "your request")} — ${escapeForDraft(approach.split(".")[0])}.`
    : `Quick update on ${escapeForDraft(req.summary || "your request")} — ${escapeForDraft(summary.split(".")[0])}.`;
  const next = "I'll have an update or proposal ready for you in the next 24 hours.";
  const greetings = {
    warm: `Hi ${homeownerFirst} — ${body} ${next} Let me know if there's anything specific you'd like me to weigh.`,
    direct: `${homeownerFirst} — ${body} ${next}`,
    formal: `Hello ${homeownerFirst}, ${body} ${next} I will await your guidance.`,
  };
  const draft = greetings[tone] || greetings.warm;
  state.concierge.composer = state.concierge.composer || {};
  state.concierge.composer[req.id] = { draft, tone, critique: assessConciergeReplyTone(draft, tone) };
  renderConciergeCockpit();
}

function escapeForDraft(s) {
  // Lower the first letter for in-sentence flow; preserve everything else.
  if (!s) return s;
  return s.charAt(0).toLowerCase() + s.slice(1);
}

// "Summarize thread" — runs the existing analyze_request action when no
// summary is cached. When a summary exists, just shows it in an alert
// (lightweight UX; the full brief tab already carries it).
async function summarizeConciergeThread(req, btn) {
  if (btn) {
    btn.disabled = true;
    btn.textContent = "Summarizing…";
  }
  try {
    const cached = state.chezAnalysisByRequest && state.chezAnalysisByRequest[req.id];
    if (cached?.analysis?.summary) {
      alert(`Thread summary:\n\n${cached.analysis.summary}\n\n${cached.analysis.recommended_approach || ""}`);
    } else {
      runChezAnalysis(req.id, true);
      alert("Refreshing analysis — the case brief above will update with a fresh summary in a few seconds.");
    }
  } finally {
    if (btn) {
      btn.disabled = false;
      btn.innerHTML = `<span class="cockpit-spark cockpit-spark--sm">✦</span>Summarize thread`;
    }
  }
}

// Alfred case-scoped chat. Posts to the Edge Function's `ask_alfred` action
// (added in Phase 83) which builds case context server-side and streams
// back a single-shot reply.
async function sendConciergeAlfredMessage(req) {
  const inputMap = state.concierge.alfred.input || {};
  const text = (inputMap[req.id] || "").trim();
  if (!text) return;
  state.concierge.alfred.chat[req.id] = state.concierge.alfred.chat[req.id] || [];
  // Push user message + a loading placeholder, switch to chat tab so the
  // exchange is visible.
  state.concierge.alfred.chat[req.id].push({ from: "user", text });
  state.concierge.alfred.chat[req.id].push({ from: "alfred", text: "Thinking…", _loading: true });
  state.concierge.alfred.input[req.id] = "";
  state.concierge.alfred.tab = "chat";
  renderConciergeCockpit();

  try {
    const result = await callChezConcierge({
      action: "ask_alfred",
      request_id: req.id,
      question: text,
    });
    // Replace the loading placeholder with the real answer.
    const arr = state.concierge.alfred.chat[req.id];
    const lastIdx = arr.length - 1;
    if (arr[lastIdx]?._loading) {
      arr[lastIdx] = { from: "alfred", text: result.answer || "(empty response)" };
    } else {
      arr.push({ from: "alfred", text: result.answer || "(empty response)" });
    }
  } catch (err) {
    const arr = state.concierge.alfred.chat[req.id];
    const lastIdx = arr.length - 1;
    if (arr[lastIdx]?._loading) {
      arr[lastIdx] = { from: "alfred", text: `(I couldn't reach the server — ${err.message || "try again"}.)` };
    }
  }
  renderConciergeCockpit();
}

// Vendor-card handler attachment — wires expand/collapse, slot management,
// per-field input, ✨ Summarize, recommend toggle. Lifted from the legacy
// attachChezPanelHandlers but scoped to the cockpit host so the cockpit's
// vendor sheet works without depending on el.auditFocused.
function attachConciergeVendorHandlers(host, req) {
  // Slot inputs persist on every keystroke.
  host.querySelectorAll("[data-vendor-slot-input]").forEach((input) => {
    const handler = () => {
      const card = input.closest("[data-vendor-key]");
      if (!card) return;
      const key = card.getAttribute("data-vendor-key");
      const idx = Number(input.dataset.slotIndex);
      state.chezVendorCallsByRequest = state.chezVendorCallsByRequest || {};
      state.chezVendorCallsByRequest[req.id] = state.chezVendorCallsByRequest[req.id] || {};
      const slot = state.chezVendorCallsByRequest[req.id][key] = state.chezVendorCallsByRequest[req.id][key] || {};
      slot.availability_slots = slot.availability_slots || [];
      slot.availability_slots[idx] = input.value;
    };
    input.addEventListener("input", handler);
    input.addEventListener("change", handler);
  });

  // Phase 95.1 bug fix — the cockpit's main click delegator handles
  // `data-cockpit-action` but the per-vendor card uses `data-action`
  // (a legacy convention from the pre-cockpit focused panel). The
  // legacy focused-detail surface (`el.auditFocused`, line ~9804)
  // wires expand/collapse-vendor against `[data-action]`, but the
  // cockpit context has no equivalent — so clicking "Log this call"
  // on any vendor whose form wasn't already expanded did literally
  // nothing. Tom's report: "I can only save notes for one vendor
  // call." Diagnosis: the first vendor expanded was a happy accident
  // (state persisted across re-renders); no one had wired the
  // toggle in the cockpit codepath. Fix: same handler shape as the
  // legacy surface, scoped to the cockpit host. Toggles each
  // vendor's expand state independently — multiple vendors can be
  // open at once so the operator can copy notes between them or
  // capture a follow-up while a previous one is fresh.
  //
  // The header div (line ~6284) ALSO carries data-action; clicking
  // anywhere on the vendor head row should expand/collapse the same
  // way as the CTA button, matching the original design intent.
  host.querySelectorAll("[data-vendor-key] [data-action='expand-vendor'], [data-vendor-key] [data-action='collapse-vendor']").forEach((btn) => {
    btn.addEventListener("click", (e) => {
      e.stopPropagation();
      const card = btn.closest("[data-vendor-key]");
      if (!card) return;
      const key = card.getAttribute("data-vendor-key");
      const action = btn.dataset.action;
      state.chezExpandedVendorKeys = state.chezExpandedVendorKeys || {};
      state.chezExpandedVendorKeys[req.id] = state.chezExpandedVendorKeys[req.id] || {};
      state.chezExpandedVendorKeys[req.id][key] = action === "expand-vendor";
      renderConciergeCockpit();
    });
  });

  // The vendor card head row is also data-action="expand-vendor" /
  // "collapse-vendor" — match the legacy clickable-header pattern.
  // We skip nodes that are also inner buttons (they have their own
  // listener above and stopPropagation), so this only fires for
  // bare-head clicks.
  host.querySelectorAll("[data-vendor-key] .cockpit-vendor__head[data-action]").forEach((head) => {
    head.addEventListener("click", (e) => {
      // If the click came from an inner button / link, let the
      // dedicated handler above own the toggle.
      if (e.target.closest("button, a")) return;
      const card = head.closest("[data-vendor-key]");
      if (!card) return;
      const key = card.getAttribute("data-vendor-key");
      const action = head.dataset.action;
      state.chezExpandedVendorKeys = state.chezExpandedVendorKeys || {};
      state.chezExpandedVendorKeys[req.id] = state.chezExpandedVendorKeys[req.id] || {};
      state.chezExpandedVendorKeys[req.id][key] = action === "expand-vendor";
      renderConciergeCockpit();
    });
  });

  // Slot add/remove buttons (rendered with data-action="add-slot" /
  // "remove-slot" — these are scoped INSIDE [data-vendor-key], not the
  // cockpit-action delegation, so they need their own listener).
  host.querySelectorAll("[data-action='add-slot'], [data-action='remove-slot']").forEach((btn) => {
    btn.addEventListener("click", () => {
      const card = btn.closest("[data-vendor-key]");
      if (!card) return;
      const key = card.getAttribute("data-vendor-key");
      state.chezVendorCallsByRequest = state.chezVendorCallsByRequest || {};
      state.chezVendorCallsByRequest[req.id] = state.chezVendorCallsByRequest[req.id] || {};
      const slot = state.chezVendorCallsByRequest[req.id][key] = state.chezVendorCallsByRequest[req.id][key] || {};
      const slots = Array.isArray(slot.availability_slots) ? slot.availability_slots : [];
      // Snapshot in-progress text inputs first.
      card.querySelectorAll("[data-vendor-slot-input]").forEach((input) => {
        const idx = Number(input.dataset.slotIndex);
        if (Number.isFinite(idx) && slots[idx] !== undefined) slots[idx] = input.value;
      });
      if (btn.dataset.action === "add-slot") {
        slots.push("");
      } else {
        const removeIdx = Number(btn.dataset.slotIndex);
        slots.splice(removeIdx, 1);
      }
      slot.availability_slots = slots;
      renderConciergeCockpit();
    });
  });

  // Per-field input bindings.
  host.querySelectorAll("[data-vendor-field]").forEach((input) => {
    const handler = () => {
      const card = input.closest("[data-vendor-key]");
      if (!card) return;
      const key = card.getAttribute("data-vendor-key");
      state.chezVendorCallsByRequest = state.chezVendorCallsByRequest || {};
      state.chezVendorCallsByRequest[req.id] = state.chezVendorCallsByRequest[req.id] || {};
      const slot = state.chezVendorCallsByRequest[req.id][key] = state.chezVendorCallsByRequest[req.id][key] || {};
      const field = input.dataset.vendorField;
      if (input.type === "checkbox") slot[field] = input.checked;
      else slot[field] = input.value;
      // cost_range "custom" toggles the custom-text row inline.
      if (field === "cost_range") {
        const customRow = card.querySelector("[data-vendor-cost-custom-row]");
        if (customRow) customRow.classList.toggle("is-hidden", input.value !== "custom");
      }
      // Recommend toggles trigger a re-render so the proposal preview +
      // recommended count update.
      if (field === "recommended") {
        renderConciergeCockpit();
      }
    };
    input.addEventListener("change", handler);
    if (input.tagName === "TEXTAREA" || (input.tagName === "INPUT" && input.type !== "checkbox" && input.type !== "select-one")) {
      input.addEventListener("input", handler);
    }
  });

  // ✨ Summarize buttons (per vendor card).
  host.querySelectorAll("[data-vendor-suggest]").forEach((btn) => {
    btn.addEventListener("click", async () => {
      const card = btn.closest("[data-vendor-key]");
      if (!card) return;
      const key = card.getAttribute("data-vendor-key");
      const cached = state.chezAnalysisByRequest?.[req.id];
      if (!cached) return;
      const allCandidates = [
        ...(cached.existing_vendors || []).map((v) => ({ ...v, _source: "existing" })),
        ...(cached.places_candidates || []).map((v) => ({ ...v, _source: "places" })),
      ];
      const v = allCandidates.find((cand) => vendorCandidateKey(cand) === key);
      if (!v) return;
      btn.disabled = true; btn.textContent = "Writing…";
      try {
        const dossier = (state.chezDossiersByHousehold || {})[req.household_id] || {};
        const profile = dossier.profile || {};
        const property = (dossier.properties || [])[0];
        const propertyContext = property
          ? `${property.year_built ? property.year_built + " " : ""}${property.property_type || "home"} in ${property.city || ""}, ${property.state || ""}`
          : "";
        const callData = state.chezVendorCallsByRequest?.[req.id]?.[key] || {};
        const costRange = callData.cost_range === "custom"
          ? (callData.cost_custom || "")
          : (callData.cost_range || "");
        const slotInputs = Array.from(card.querySelectorAll("[data-vendor-slot-input]"))
          .map((el) => el.value.trim())
          .filter(Boolean);
        const result = await callChezConcierge({
          action: "suggest_vendor_framing",
          household_id: req.household_id,
          request_summary: req.summary,
          request_category: req.category,
          vendor: {
            name: v.company_name || v.name,
            category: v.category,
            rating: v.rating,
            review_count: v.user_ratings_total || v.review_count,
          },
          homeowner_about: profile.about_us,
          property_context: propertyContext,
          call_notes: callData.notes || "",
          availability_slots: slotInputs,
          cost_range: costRange,
        });
        if (result.framing) {
          state.chezVendorCallsByRequest = state.chezVendorCallsByRequest || {};
          state.chezVendorCallsByRequest[req.id] = state.chezVendorCallsByRequest[req.id] || {};
          const slot = state.chezVendorCallsByRequest[req.id][key] = state.chezVendorCallsByRequest[req.id][key] || {};
          slot.rationale = result.framing;
          renderConciergeCockpit();
        }
      } catch (err) {
        console.warn("[concierge] suggest framing failed", err);
      } finally {
        btn.disabled = false;
        btn.innerHTML = `<span class="cockpit-spark cockpit-spark--sm">✦</span>Summarize from notes`;
      }
    });
  });
}

// Visit-card field bindings — same approach as vendor cards. Snapshots
// in-progress text into the cached visit object so subsequent state
// transitions pick up the latest values.
function attachConciergeVisitHandlers(host, req) {
  host.querySelectorAll("[data-visit-field]").forEach((input) => {
    const handler = () => {
      const card = input.closest("[data-visit-id]");
      if (!card) return;
      const visitId = card.getAttribute("data-visit-id");
      const visit = (state.chezVisitsByRequest?.[req.id] || []).find((v) => v.id === visitId);
      if (!visit) return;
      const field = input.dataset.visitField;
      visit[field] = input.value;
    };
    input.addEventListener("change", handler);
    if (input.tagName === "TEXTAREA" || (input.tagName === "INPUT" && input.type !== "checkbox")) {
      input.addEventListener("input", handler);
    }
  });
}

// Phase 81.1 — AI analysis panel state. Cached per request so we
// don't re-run Claude on every panel re-render. Re-runs only when
// the user explicitly clicks "Re-analyze".
function renderChezAnalysisPanelHtml(req, opts = {}) {
  state.chezAnalysisByRequest = state.chezAnalysisByRequest || {};
  const cached = state.chezAnalysisByRequest[req.id];

  if (cached === undefined) {
    // Kick off analysis in the background. Re-renders when done.
    runChezAnalysis(req.id);
    return `
      <section class="admin-chez__analysis admin-chez__analysis--loading">
        <header>
          <span>✨ Chez analysis</span>
          <span class="admin-muted">Researching…</span>
        </header>
        <p class="admin-muted">Reading the request, matching existing vendors, pre-fetching local options, drafting your call script.</p>
      </section>
    `;
  }
  if (cached === null) {
    return `
      <section class="admin-chez__analysis admin-chez__analysis--empty">
        <header>
          <span>✨ Chez analysis</span>
          <button type="button" class="admin-button admin-button--ghost admin-button--small" data-action="rerun-analysis">Re-run</button>
        </header>
        <p class="admin-muted">Analysis didn't return. Click Re-run.</p>
      </section>
    `;
  }

  const a = cached.analysis || {};
  const existing = cached.existing_vendors || [];
  const places = cached.places_candidates || [];
  const allCandidates = [
    ...existing.map((v) => ({ ...v, _source: "existing" })),
    ...places.map((v) => ({ ...v, _source: "places" })),
  ];

  const callState = (state.chezVendorCallsByRequest && state.chezVendorCallsByRequest[req.id]) || {};
  const recommendedCount = Object.values(callState).filter((s) => s && s.recommended).length;

  // Phase 82 — When active visits exist, the analysis panel
  // collapses to a one-liner so the visits section becomes the
  // primary focus. Tom can click the toolbar button to re-research
  // or expand back to the full pre-call workflow.
  if (opts.collapsed) {
    return `
      <section class="admin-chez__analysis admin-chez__analysis--collapsed-line">
        <span>✨ Chez analysis</span>
        <span class="admin-muted">${allCandidates.length} vendor${allCandidates.length === 1 ? "" : "s"} researched · ${recommendedCount} sent</span>
        <button type="button" class="admin-button admin-button--ghost admin-button--small" data-action="expand-analysis">Re-open research</button>
      </section>
    `;
  }

  return `
    <section class="admin-chez__analysis">
      <header>
        <span>✨ Chez analysis</span>
        <button type="button" class="admin-button admin-button--ghost admin-button--small" data-action="rerun-analysis">Re-run</button>
      </header>

      ${a.summary ? `<p class="admin-chez__analysis-summary">${escapeHtml(a.summary)}</p>` : ""}

      ${a.key_considerations ? `
        <div class="admin-chez__analysis-section">
          <h4>Key considerations</h4>
          <p>${escapeHtml(a.key_considerations)}</p>
        </div>
      ` : ""}

      ${a.recommended_approach ? `
        <div class="admin-chez__analysis-section">
          <h4>Recommended approach</h4>
          <p>${escapeHtml(a.recommended_approach)}</p>
        </div>
      ` : ""}

      ${(a.questions_to_ask && a.questions_to_ask.length > 0) ? `
        <details class="admin-chez__analysis-section">
          <summary>Questions to ask each vendor (${a.questions_to_ask.length})</summary>
          <ul>${a.questions_to_ask.map((q) => `<li>${escapeHtml(q)}</li>`).join("")}</ul>
        </details>
      ` : ""}

      ${a.call_script ? `
        <details class="admin-chez__analysis-section">
          <summary>Call script</summary>
          <pre>${escapeHtml(a.call_script)}</pre>
        </details>
      ` : ""}

      <div class="admin-chez__candidates">
        <header>
          <h4>Vendors to call · ${allCandidates.length}</h4>
          ${recommendedCount > 0 ? `<button type="button" class="admin-button admin-button--primary admin-button--small" data-action="package-send">Package & send ${recommendedCount} to homeowner</button>` : ""}
        </header>
        ${allCandidates.length === 0 ? `<p class="admin-muted">No vendor candidates pre-researched. Use Manual proposal below.</p>` : ""}
        ${allCandidates.map((v, i) => renderVendorCandidateCardHtml(req, v, i, callState[vendorCandidateKey(v)] || null)).join("")}
      </div>
    </section>
  `;
}

function vendorCandidateKey(v) {
  return v._source === "existing" ? `existing:${v.id}` : `places:${v.name}`;
}

function renderVendorCandidateCardHtml(req, v, idx, callData) {
  const key = vendorCandidateKey(v);
  const isExpanded = state.chezExpandedVendorKeys?.[req.id]?.[key];
  const isExisting = v._source === "existing";
  const name = v.company_name || v.name || "(unnamed)";
  const phone = v.phone || v.formatted_phone_number || "";
  const cleanedPhone = String(phone).replace(/[^0-9+]/g, "");
  const ratingChip = v.rating ? `${v.rating}★ (${v.user_ratings_total || v.review_count || "?"})` : "";
  const recommended = !!callData?.recommended;
  const noAnswer = callData?.outcome === "no_answer";

  // Phase 81.2 — Multi-slot availability + cost combobox + AI summary.
  // Tom can add 1-N suggested time windows the vendor offered, pick from
  // 8 sensible cost ranges (with Custom escape hatch), and get the AI
  // to summarize his raw notes into homeowner-facing recommendation
  // copy.
  const slots = Array.isArray(callData?.availability_slots)
    ? callData.availability_slots
    : (callData?.availability ? [callData.availability] : []);
  const costRange = callData?.cost_range || "";
  const costCustom = callData?.cost_custom || "";
  const showCustomCost = costRange === "custom" || (costCustom && !costRange);
  const slotsHtml = slots.map((s, slotIdx) => `
    <div class="admin-chez__slot-row">
      <input type="text" data-vendor-slot-input data-slot-index="${slotIdx}" value="${escapeHtml(s)}" placeholder="e.g. Tue May 12 (PM)" />
      <button type="button" class="admin-chez__proposal-row-remove" data-action="remove-slot" data-slot-index="${slotIdx}" aria-label="Remove">×</button>
    </div>
  `).join("");

  const callForm = isExpanded ? `
    <div class="admin-chez__vendor-call-form">
      <label>Outcome
        <select data-vendor-field="outcome">
          <option value="">Pick an outcome…</option>
          <option value="answered" ${callData?.outcome === "answered" ? "selected" : ""}>Answered</option>
          <option value="no_answer" ${callData?.outcome === "no_answer" ? "selected" : ""}>No answer / VM</option>
          <option value="not_a_fit" ${callData?.outcome === "not_a_fit" ? "selected" : ""}>Not a fit</option>
        </select>
      </label>

      <div class="admin-chez__slot-section">
        <div class="admin-chez__slot-section-head">
          <span>Times they offered</span>
          <span class="admin-muted">Add as many as the vendor suggested — homeowner picks one.</span>
        </div>
        <div data-vendor-slots>${slotsHtml}</div>
        <button type="button" class="admin-button admin-button--ghost admin-button--small" data-action="add-slot">+ Add a time</button>
      </div>

      <label>Cost (optional — pick a range)
        <select data-vendor-field="cost_range">
          <option value="" ${!costRange ? "selected" : ""}>— Will know after site visit —</option>
          <option value="Will quote on site visit" ${costRange === "Will quote on site visit" ? "selected" : ""}>Will quote on site visit</option>
          <option value="$100–500" ${costRange === "$100–500" ? "selected" : ""}>$100 – $500</option>
          <option value="$500–1,000" ${costRange === "$500–1,000" ? "selected" : ""}>$500 – $1,000</option>
          <option value="$1,000–2,500" ${costRange === "$1,000–2,500" ? "selected" : ""}>$1,000 – $2,500</option>
          <option value="$2,500–5,000" ${costRange === "$2,500–5,000" ? "selected" : ""}>$2,500 – $5,000</option>
          <option value="$5,000–10,000" ${costRange === "$5,000–10,000" ? "selected" : ""}>$5,000 – $10,000</option>
          <option value="$10,000+" ${costRange === "$10,000+" ? "selected" : ""}>$10,000+</option>
          <option value="custom" ${costRange === "custom" ? "selected" : ""}>Custom — type below</option>
        </select>
      </label>
      <label data-vendor-cost-custom-row class="${showCustomCost ? "" : "is-hidden"}">
        <span>Custom cost text</span>
        <input type="text" data-vendor-field="cost_custom" value="${escapeHtml(costCustom)}" placeholder="e.g. $1,200 firm; $400 + $50/sqft" />
      </label>

      <label>Your notes from the call
        <textarea rows="3" data-vendor-field="notes" placeholder="Raw notes — what did they say? Anything specific to this home? AI uses this to write the homeowner-facing recommendation.">${escapeHtml(callData?.notes || "")}</textarea>
      </label>

      <label class="admin-chez__vendor-rationale">
        <span>Recommendation summary — homeowner sees this on the proposal card
          <button type="button" class="admin-chez__proposal-ai-suggest" data-vendor-suggest>✨ Summarize from notes</button>
        </span>
        <textarea rows="3" data-vendor-field="rationale" placeholder="Polished, professional 2-3 sentences. Click ✨ to auto-write from your notes above.">${escapeHtml(callData?.rationale || "")}</textarea>
      </label>

      <div class="admin-chez__vendor-call-actions">
        <label class="admin-chez__vendor-recommend">
          <input type="checkbox" data-vendor-field="recommended" ${recommended ? "checked" : ""} />
          <span>✅ Recommend to homeowner</span>
        </label>
        <button type="button" class="admin-button admin-button--ghost admin-button--small" data-action="collapse-vendor">Done editing</button>
      </div>
    </div>
  ` : "";

  return `
    <article class="admin-chez__vendor-card${recommended ? " is-recommended" : ""}${noAnswer ? " is-noanswer" : ""}" data-vendor-key="${escapeHtml(key)}">
      <header class="admin-chez__vendor-card-head">
        <div class="admin-chez__vendor-card-title">
          <strong>${idx + 1}. ${escapeHtml(name)}</strong>
          ${isExisting ? `<span class="admin-pill admin-pill--note">In your network</span>` : ""}
          ${recommended ? `<span class="admin-pill" data-tone="green">Recommended</span>` : ""}
          ${callData?.outcome === "no_answer" ? `<span class="admin-pill" data-tone="amber">No answer</span>` : ""}
          ${callData?.outcome === "not_a_fit" ? `<span class="admin-pill" data-tone="muted">Not a fit</span>` : ""}
        </div>
        <div class="admin-chez__vendor-card-meta">
          ${ratingChip ? `<span>${escapeHtml(ratingChip)}</span>` : ""}
          ${v.address || v.city || v.formatted_address ? `<span class="admin-muted">${escapeHtml(v.address || v.formatted_address || v.city || "")}</span>` : ""}
        </div>
      </header>
      <div class="admin-chez__vendor-card-actions">
        ${cleanedPhone ? `<a class="admin-button admin-button--primary admin-button--small" href="tel:${escapeHtml(cleanedPhone)}">📞 ${escapeHtml(phone)}</a>` : ""}
        <button type="button" class="admin-button admin-button--ghost admin-button--small" data-action="${isExpanded ? "collapse-vendor" : "expand-vendor"}">
          ${isExpanded ? "Hide form" : (callData ? "Edit notes" : "Log this call")}
        </button>
      </div>
      ${callForm}
    </article>
  `;
}

async function runChezAnalysis(requestId, force = false) {
  state.chezAnalysisByRequest = state.chezAnalysisByRequest || {};
  state.chezAnalysisInFlight = state.chezAnalysisInFlight || new Set();
  if (state.chezAnalysisInFlight.has(requestId)) return;
  if (!force && state.chezAnalysisByRequest[requestId] !== undefined) return;
  state.chezAnalysisInFlight.add(requestId);
  if (force) {
    delete state.chezAnalysisByRequest[requestId];
    if (state.selectedChezRequest && state.selectedChezRequest.id === requestId) {
      renderFocusedChezDetail(state.selectedChezRequest);
    }
  }
  try {
    const result = await callChezConcierge({
      action: "analyze_request",
      request_id: requestId,
    });
    state.chezAnalysisByRequest[requestId] = result;
  } catch (e) {
    console.warn("[admin] analyze_request failed", e);
    state.chezAnalysisByRequest[requestId] = null;
  } finally {
    state.chezAnalysisInFlight.delete(requestId);
  }
  if (state.selectedChezRequest && state.selectedChezRequest.id === requestId) {
    renderFocusedChezDetail(state.selectedChezRequest);
  }
}

// ============================================================================
// Phase 82 — Stage tracker + visit cards
// ============================================================================
// Tom asked for "a tracker up top" so he can see where each case is in
// its lifecycle at a glance. Once a vendor proposal is approved the
// case turns into tracking the resulting visits, so we surface those
// as a dedicated section between the header and the (now-collapsed)
// analysis panel.

const CHEZ_STAGES = [
  { id: "submitted", label: "Submitted" },
  { id: "research", label: "Research" },
  { id: "sent", label: "Sent" },
  { id: "picked", label: "Picked" },
  { id: "booked", label: "Booked" },
  { id: "visit", label: "Visit" },
  { id: "done", label: "Done" },
];

function renderStageTrackerHtml(req, messages, visits) {
  const proposals = (messages || []).filter((m) => m.proposal && m.proposal.kind === "vendor");
  const anyProposal = proposals.length > 0;
  const anyApproved = proposals.some((m) => m.proposal.status === "approved");
  const visitsArr = Array.isArray(visits) ? visits : [];
  const livingVisits = visitsArr.filter((v) => v.state !== "cancelled");
  const allBooked = livingVisits.length > 0 && livingVisits.every((v) => v.state === "scheduled" || v.state === "completed");
  const allCompleted = livingVisits.length > 0 && livingVisits.every((v) => v.state === "completed");
  const hasAnalysis = !!(state.chezAnalysisByRequest && state.chezAnalysisByRequest[req.id] && state.chezAnalysisByRequest[req.id] !== null);

  const done = {
    submitted: !!req.created_at,
    research: hasAnalysis,
    sent: anyProposal,
    picked: anyApproved,
    booked: allBooked,
    visit: allCompleted,
    done: req.status === "resolved",
  };

  // The first non-done stage becomes "current". Everything after stays
  // pending. The dot-by-dot cadence makes "where are we" obvious.
  const stages = CHEZ_STAGES.map((s) => ({ ...s, done: !!done[s.id], current: false }));
  let currentSet = false;
  for (const s of stages) {
    if (!s.done && !currentSet) { s.current = true; currentSet = true; }
  }
  // If everything's done, mark the last as current.
  if (!currentSet && stages.length > 0) stages[stages.length - 1].current = true;

  // Phase 83.5 — Stages are clickable buttons. Clicking jumps the
  // workspace to the most relevant section (research → brief, sent →
  // thread, booked → visits panel, etc.). Operators can re-orient
  // themselves without scrolling.
  return `
    <nav class="admin-chez__stage-tracker" aria-label="Case stage">
      ${stages.map((s, i) => `
        <button type="button" class="admin-chez__stage ${s.done ? "is-done" : ""} ${s.current ? "is-current" : ""}" data-cockpit-stage="${escapeHtml(s.id)}" title="Jump to ${escapeHtml(s.label)} section">
          <div class="admin-chez__stage-dot">${s.done ? "✓" : (s.current ? "●" : "")}</div>
          <div class="admin-chez__stage-label">${escapeHtml(s.label)}</div>
          ${i < stages.length - 1 ? `<div class="admin-chez__stage-rail ${s.done ? "is-done" : ""}"></div>` : ""}
        </button>
      `).join("")}
    </nav>
  `;
}

function renderVisitsPanelHtml(req, visits) {
  // Lazy-fetch visits once per request open, caching the result.
  if (visits === undefined) {
    fetchChezVisits(req.id);
    return ""; // wait for fetch to populate cache
  }
  const visitsArr = Array.isArray(visits) ? visits : [];
  if (visitsArr.length === 0) return ""; // no approvals yet → no panel

  // Active = anything not cancelled. Completed shown collapsed at the
  // bottom so Tom keeps the audit trail without taking up real estate.
  const active = visitsArr.filter((v) => v.state !== "cancelled" && v.state !== "completed");
  const completed = visitsArr.filter((v) => v.state === "completed");
  const cancelled = visitsArr.filter((v) => v.state === "cancelled");

  const headerSubtitle = active.length > 0
    ? `${active.length} active${completed.length ? ` · ${completed.length} completed` : ""}`
    : completed.length > 0
    ? `All ${completed.length} visit${completed.length === 1 ? "" : "s"} completed`
    : "No active visits";

  return `
    <section class="admin-chez__visits">
      <header>
        <div>
          <h3>Active visits</h3>
          <span class="admin-muted">${headerSubtitle}</span>
        </div>
        ${active.length === 0 && completed.length > 0 && req.status !== "resolved" ? `
          <button type="button" class="admin-button admin-button--primary admin-button--small" data-action="mark-resolved-from-visits">Mark case resolved</button>
        ` : ""}
      </header>
      ${active.map((v) => renderVisitCardHtml(req, v)).join("")}
      ${completed.length > 0 ? `
        <details class="admin-chez__visits-completed">
          <summary>Completed (${completed.length})</summary>
          ${completed.map((v) => renderVisitCardHtml(req, v, { compact: true })).join("")}
        </details>
      ` : ""}
      ${cancelled.length > 0 ? `
        <details class="admin-chez__visits-cancelled">
          <summary>Cancelled (${cancelled.length})</summary>
          ${cancelled.map((v) => renderVisitCardHtml(req, v, { compact: true })).join("")}
        </details>
      ` : ""}
    </section>
  `;
}

function renderVisitCardHtml(req, visit, opts = {}) {
  const stateLabel = {
    awaiting_date: "Awaiting date",
    scheduled: "Scheduled",
    completed: "Completed",
    cancelled: "Cancelled",
  }[visit.state] || visit.state;
  const stateTone = {
    awaiting_date: "amber",
    scheduled: "green",
    completed: "muted",
    cancelled: "muted",
  }[visit.state] || "muted";
  const phone = visit.vendor_phone || (visit.vendor_payload && visit.vendor_payload.phone) || "";
  const phoneCleaned = String(phone).replace(/[^0-9+]/g, "");
  const slots = (visit.vendor_payload && Array.isArray(visit.vendor_payload.availability_slots))
    ? visit.vendor_payload.availability_slots : [];
  const scheduledFor = visit.scheduled_for ? formatDateTimeShort(visit.scheduled_for) : "";

  if (opts.compact) {
    return `
      <div class="admin-chez__visit-card admin-chez__visit-card--compact" data-visit-id="${escapeHtml(visit.id)}">
        <span class="admin-pill" data-tone="${stateTone}">${escapeHtml(stateLabel)}</span>
        <strong>${escapeHtml(visit.vendor_name || "")}</strong>
        ${scheduledFor ? `<span class="admin-muted">${escapeHtml(scheduledFor)}</span>` : ""}
        ${visit.outcome ? `<span class="admin-muted">— ${escapeHtml(visit.outcome)}</span>` : ""}
      </div>
    `;
  }

  // Active card — full controls.
  const isScheduled = visit.state === "scheduled";
  const dateValue = visit.scheduled_for ? new Date(visit.scheduled_for).toISOString().slice(0, 16) : "";

  return `
    <article class="admin-chez__visit-card" data-visit-id="${escapeHtml(visit.id)}">
      <header>
        <div class="admin-chez__visit-card-title">
          <strong>${escapeHtml(visit.vendor_name || "")}</strong>
          <span class="admin-pill" data-tone="${stateTone}">${escapeHtml(stateLabel)}</span>
        </div>
        ${phoneCleaned ? `<a class="admin-button admin-button--ghost admin-button--small" href="tel:${escapeHtml(phoneCleaned)}">📞 ${escapeHtml(phone)}</a>` : ""}
      </header>

      ${visit.state === "awaiting_date" ? `
        <div class="admin-chez__visit-coachmark">
          <strong>Step 2 · Confirm a date</strong>
          <span>Vendor's locked in. Send the homeowner 2-3 dates, or paste their pick into Confirmed date / time below.</span>
        </div>
      ` : ""}

      ${slots.length > 0 ? `
        <div class="admin-chez__visit-slots">
          <span class="admin-muted">Vendor offered:</span>
          ${slots.map((s) => {
            // Phase 83.4 — vendor proposals no longer carry slots, but legacy
            // visit rows may still have them. Render as adoption chips so
            // Tom can drop them into the date_slot proposal flow if useful.
            // Goes through formatSlotDisplay so mixed-format legacy data
            // ("Thursday 6PM" / "5.24" / ISO) lands as one consistent label.
            const display = formatSlotDisplay(s);
            const iso = toLocalDateTimeInputValue(s);
            return `<button type="button" class="admin-chez__visit-slot-chip" data-cockpit-action="adopt-slot" data-slot-text="${escapeHtml(display)}" data-slot-iso="${escapeHtml(iso)}">${escapeHtml(display)}</button>`;
          }).join("")}
        </div>
      ` : ""}

      <div class="admin-chez__visit-grid">
        <label>Confirmed date / time
          <input type="datetime-local" data-visit-field="scheduled_for" value="${escapeHtml(dateValue)}" />
        </label>
        <label>Window note (optional)
          <input type="text" data-visit-field="scheduled_window" value="${escapeHtml(visit.scheduled_window || "")}" placeholder="e.g. arrives 2-4pm" />
        </label>
      </div>

      <label>Notes
        <textarea rows="2" data-visit-field="notes" placeholder="Running notes — what's been confirmed, follow-ups, anything quirky.">${escapeHtml(visit.notes || "")}</textarea>
      </label>

      ${isScheduled ? `
        <label>Outcome (when complete)
          <input type="text" data-visit-field="outcome" value="${escapeHtml(visit.outcome || "")}" placeholder="e.g. Completed cleanly. Quoted $1,800 for follow-up." />
        </label>
      ` : ""}

      <div class="admin-chez__visit-card-actions">
        ${visit.state === "awaiting_date" ? `
          <button type="button" class="admin-button admin-button--primary admin-button--small" data-cockpit-action="propose-alternate-dates" title="Open the proposal builder in date-slot mode. Homeowner picks one — visit auto-confirms.">📨 Send dates to homeowner</button>
          <button type="button" class="admin-button admin-button--secondary admin-button--small" data-cockpit-action="visit-mark-scheduled" title="If you've already confirmed a date with the homeowner over the phone, enter it above and click here.">📅 Confirm scheduled</button>
        ` : ""}
        ${isScheduled ? `
          <button type="button" class="admin-button admin-button--primary admin-button--small" data-cockpit-action="visit-mark-completed">✅ Mark completed</button>
          <button type="button" class="admin-button admin-button--ghost admin-button--small" data-cockpit-action="propose-alternate-dates" title="Re-offer dates if the homeowner needs to reschedule.">📨 Reschedule</button>
        ` : ""}
        <button type="button" class="admin-button admin-button--ghost admin-button--small" data-cockpit-action="visit-save-notes">💾 Save notes</button>
        <button type="button" class="admin-button admin-button--ghost admin-button--small" data-cockpit-action="visit-cancel">Cancel visit</button>
      </div>
    </article>
  `;
}

async function fetchChezVisits(requestId) {
  state.chezVisitsByRequest = state.chezVisitsByRequest || {};
  state.chezVisitsInFlight = state.chezVisitsInFlight || new Set();
  if (state.chezVisitsInFlight.has(requestId)) return;
  if (state.chezVisitsByRequest[requestId] !== undefined) return;
  state.chezVisitsInFlight.add(requestId);
  try {
    const result = await callChezConcierge({
      action: "fetch_visits",
      request_id: requestId,
    });
    state.chezVisitsByRequest[requestId] = result.visits || [];
  } catch (e) {
    console.warn("[admin] fetch_visits failed", e);
    state.chezVisitsByRequest[requestId] = [];
  } finally {
    state.chezVisitsInFlight.delete(requestId);
  }
  if (state.selectedChezRequest && state.selectedChezRequest.id === requestId) {
    renderFocusedChezDetail(state.selectedChezRequest);
  }
}

function formatDateTimeShort(iso) {
  if (!iso) return "";
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return iso;
  return d.toLocaleString(undefined, {
    weekday: "short",
    month: "short",
    day: "numeric",
    hour: "numeric",
    minute: "2-digit",
  });
}

// Phase 80.1 — Profile summary shown at the top of every focused chez
// panel. Lazy-loaded once per request open; cached on
// `state.chezProfilesByHousehold` keyed by household_id so subsequent
// opens within the session don't re-fetch.
// Phase 81 — Customer dossier renderer. Replaces the Phase 80.1
// profile-only summary with the full household snapshot (property,
// family, systems, contractors, tasks, vehicles, recent activity).
// Tom now has every signal he needs to respond to a Chez request
// without leaving the focused panel. Click any chip to drill into
// detail — the chez-dossier-drawer slides in with the entity's
// full record.
function renderChezProfileSummaryHtml(req) {
  const householdId = req.household_id;
  if (!householdId) return "";
  state.chezDossiersByHousehold = state.chezDossiersByHousehold || {};
  const dossier = state.chezDossiersByHousehold[householdId];
  if (dossier === undefined) {
    fetchChezHouseholdDossier(householdId);
    return `
      <section class="admin-chez__dossier">
        <h3>Household dossier</h3>
        <p class="admin-muted">Loading homeowner context…</p>
      </section>
    `;
  }
  if (!dossier) {
    return `
      <section class="admin-chez__dossier admin-chez__dossier--empty">
        <h3>Household dossier</h3>
        <p class="admin-muted">Couldn't load the homeowner's data. Tap the request again to retry.</p>
      </section>
    `;
  }
  return renderHouseholdDossierHtml(dossier);
}

function renderHouseholdDossierHtml(d) {
  const property = (d.properties && d.properties[0]) || null;
  const homeowner = primaryHomeownerLabel(d);
  const tiers = d.profile?.spending_tiers || {};
  const tierLine = (tiers.auto_approve_under !== undefined)
    ? `Auto-approve &lt; $${tiers.auto_approve_under} · Ping &lt; $${tiers.ping_under} · Always ask &gt; $${tiers.explicit_above}`
    : "Spending tiers not set — defaults (200 / 500 / 500) apply.";
  const profile = d.profile || {};
  const profileLines = [];
  if (profile.about_us) profileLines.push({ label: "About", value: profile.about_us });
  if (profile.vendor_preferences?.budget_orientation) profileLines.push({ label: "Budget", value: profile.vendor_preferences.budget_orientation });
  if (profile.vendor_preferences?.notes) profileLines.push({ label: "Vendor notes", value: profile.vendor_preferences.notes });
  if (profile.communication?.vacation_mode) profileLines.push({ label: "Vacation mode", value: profile.communication.vacation_notes || "ON" });
  if (profile.logistics?.has_pets && profile.logistics?.pet_notes) profileLines.push({ label: "Pets", value: profile.logistics.pet_notes });
  if (profile.logistics?.entry_instructions) profileLines.push({ label: "Entry", value: profile.logistics.entry_instructions });

  const propBlock = property ? `
    <div class="admin-chez__dossier-card" data-dossier-entity="property" data-dossier-id="${escapeHtml(property.id)}">
      <div class="admin-chez__dossier-card-head">🏠 Property</div>
      <div class="admin-chez__dossier-card-body">
        <strong>${escapeHtml(formatAddress(property))}</strong>
        <div class="admin-chez__dossier-meta">
          ${property.year_built ? `Built ${escapeHtml(String(property.year_built))} · ` : ""}
          ${property.square_footage ? `${escapeHtml(String(property.square_footage))} sq ft · ` : ""}
          ${property.property_type ? `${escapeHtml(property.property_type)}` : ""}
        </div>
        ${property.current_estimated_value ? `<div class="admin-chez__dossier-meta">Estimated value: <strong>$${formatCompact(property.current_estimated_value)}</strong></div>` : ""}
      </div>
    </div>
  ` : "";

  const systemCount = (d.home_systems || []).length;
  const systemsList = (d.home_systems || []).slice(0, 12).map((s) => `
    <button type="button" class="admin-chez__dossier-chip" data-dossier-entity="home_system" data-dossier-id="${escapeHtml(s.id)}">
      <span class="admin-chez__dossier-chip-title">${escapeHtml(s.name || s.category || "(unnamed)")}</span>
      ${s.category ? `<span class="admin-chez__dossier-chip-sub">${escapeHtml(s.category)}</span>` : ""}
    </button>
  `).join("");

  const contractorCount = (d.contractors || []).length;
  const handyman = (d.contractors || []).find((c) => (c.category || "").toLowerCase().includes("handyman"));
  const contractorsList = (d.contractors || []).slice(0, 12).map((c) => `
    <button type="button" class="admin-chez__dossier-chip" data-dossier-entity="contractor" data-dossier-id="${escapeHtml(c.id)}">
      <span class="admin-chez__dossier-chip-title">${escapeHtml(c.company_name || "(unnamed)")}</span>
      ${c.category ? `<span class="admin-chez__dossier-chip-sub">${escapeHtml(c.category)}</span>` : ""}
      ${c.chez_owned ? `<span class="admin-chez__dossier-chip-badge">Chez</span>` : ""}
    </button>
  `).join("");

  const activeTasks = (d.tasks || []).filter((t) => !t.is_archived);
  const overdueCount = activeTasks.filter((t) => t.next_due_date && new Date(t.next_due_date) < new Date()).length;
  const tasksList = activeTasks.slice(0, 8).map((t) => `
    <button type="button" class="admin-chez__dossier-row" data-dossier-entity="task" data-dossier-id="${escapeHtml(t.id)}">
      <span class="admin-chez__dossier-row-title">${escapeHtml(t.title)}</span>
      <span class="admin-chez__dossier-row-meta">
        ${t.next_due_date ? escapeHtml(formatDateOnly(t.next_due_date)) : ""}
        ${t.assignment_type ? ` · ${escapeHtml(t.assignment_type)}` : ""}
        ${t.chez_owned ? ` · <span class="admin-chez__chez-badge">Chez</span>` : ""}
      </span>
    </button>
  `).join("");

  const vehicleCount = (d.vehicles || []).length;
  const vehiclesList = (d.vehicles || []).slice(0, 6).map((v) => `
    <button type="button" class="admin-chez__dossier-chip" data-dossier-entity="vehicle" data-dossier-id="${escapeHtml(v.id)}">
      <span class="admin-chez__dossier-chip-title">${escapeHtml((v.year ? v.year + " " : "") + (v.make || "") + " " + (v.model || ""))}</span>
      ${v.license_plate ? `<span class="admin-chez__dossier-chip-sub">${escapeHtml(v.license_plate)}</span>` : ""}
    </button>
  `).join("");

  const pastReqCount = (d.past_requests || []).filter((r) => r.id !== state.selectedChezRequest?.id).length;
  const familyCount = (d.family_members || []).length + (d.users || []).length;
  const routineCount = (d.routines || []).length;

  return `
    <section class="admin-chez__dossier">
      <header class="admin-chez__dossier-head">
        <div>
          <h3>${escapeHtml(homeowner)}</h3>
          ${property ? `<div class="admin-muted">${escapeHtml(formatAddress(property))}</div>` : ""}
        </div>
        <div class="admin-chez__dossier-tier" data-tone="amber">${tierLine}</div>
      </header>

      ${profileLines.length ? `
        <details class="admin-chez__dossier-profile" open>
          <summary>Standing instructions (${profileLines.length})</summary>
          <div class="admin-chez__dossier-profile-lines">
            ${profileLines.map((l) => `<div><strong>${escapeHtml(l.label)}:</strong> ${escapeHtml(l.value)}</div>`).join("")}
          </div>
        </details>
      ` : `<p class="admin-muted">No standing instructions on file yet.</p>`}

      <div class="admin-chez__dossier-grid">
        ${propBlock}

        <div class="admin-chez__dossier-card">
          <div class="admin-chez__dossier-card-head">👨‍👩‍👧 Household · ${familyCount}</div>
          <div class="admin-chez__dossier-card-body">
            ${(d.users || []).map((u) => `<div>${escapeHtml(u.full_name || u.email || "—")} <span class="admin-muted">(${escapeHtml(u.role || "member")})</span></div>`).join("")}
            ${(d.family_members || []).map((m) => `<div>${escapeHtml((m.first_name || "") + " " + (m.last_name || ""))} <span class="admin-muted">(${escapeHtml(m.relationship || "family")})</span></div>`).join("")}
          </div>
        </div>

        <div class="admin-chez__dossier-card">
          <div class="admin-chez__dossier-card-head">⚙️ Home systems · ${systemCount}</div>
          <div class="admin-chez__dossier-card-body admin-chez__dossier-chips">
            ${systemsList || `<p class="admin-muted">No systems on file.</p>`}
          </div>
        </div>

        <div class="admin-chez__dossier-card">
          <div class="admin-chez__dossier-card-head">🔧 Vendors · ${contractorCount}${handyman ? ` · 🛠️ ${escapeHtml(handyman.company_name)}` : ""}</div>
          <div class="admin-chez__dossier-card-body admin-chez__dossier-chips">
            ${contractorsList || `<p class="admin-muted">No vendors on file.</p>`}
          </div>
        </div>

        <div class="admin-chez__dossier-card">
          <div class="admin-chez__dossier-card-head">📋 Active tasks · ${activeTasks.length}${overdueCount ? ` · <span class="admin-pill" data-tone="red">${overdueCount} overdue</span>` : ""}</div>
          <div class="admin-chez__dossier-card-body">
            ${tasksList || `<p class="admin-muted">No active tasks.</p>`}
          </div>
        </div>

        ${vehicleCount > 0 ? `
          <div class="admin-chez__dossier-card">
            <div class="admin-chez__dossier-card-head">🚗 Vehicles · ${vehicleCount}</div>
            <div class="admin-chez__dossier-card-body admin-chez__dossier-chips">${vehiclesList}</div>
          </div>
        ` : ""}

        ${routineCount > 0 ? `
          <div class="admin-chez__dossier-card">
            <div class="admin-chez__dossier-card-head">🔁 Recurring routines · ${routineCount}</div>
            <div class="admin-chez__dossier-card-body">
              ${(d.routines || []).slice(0, 6).map((r) => `<div>${escapeHtml(r.label || r.routine_kind || "—")}${r.chez_owned ? ` <span class="admin-chez__chez-badge">Chez</span>` : ""}</div>`).join("")}
            </div>
          </div>
        ` : ""}

        ${pastReqCount > 0 ? `
          <div class="admin-chez__dossier-card">
            <div class="admin-chez__dossier-card-head">📜 Past Chez requests · ${pastReqCount}</div>
            <div class="admin-chez__dossier-card-body">
              ${(d.past_requests || []).filter((r) => r.id !== state.selectedChezRequest?.id).slice(0, 5).map((r) => `
                <div>${escapeHtml(r.summary || "—")} <span class="admin-muted">(${escapeHtml(r.status)})</span></div>
              `).join("")}
            </div>
          </div>
        ` : ""}
      </div>
    </section>
  `;
}

function primaryHomeownerLabel(d) {
  const u = (d.users || [])[0];
  if (u && (u.full_name || u.email)) return u.full_name || u.email;
  const f = (d.family_members || [])[0];
  if (f) return ((f.first_name || "") + " " + (f.last_name || "")).trim() || "Homeowner";
  return d.household?.name || "Homeowner";
}

function formatAddress(p) {
  if (!p) return "";
  const parts = [p.street, p.city, p.state, p.zip].filter(Boolean);
  return parts.join(", ");
}

function formatDateOnly(iso) {
  if (!iso) return "";
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return iso;
  return d.toLocaleDateString(undefined, { month: "short", day: "numeric", year: "numeric" });
}

function formatCompact(n) {
  const num = Number(n);
  if (!isFinite(num) || num === 0) return "0";
  if (num >= 1_000_000) return `${(num / 1_000_000).toFixed(1)}M`;
  if (num >= 1_000) return `${(num / 1_000).toFixed(0)}K`;
  return String(Math.round(num));
}

async function fetchChezHouseholdDossier(householdId) {
  state.chezDossiersByHousehold = state.chezDossiersByHousehold || {};
  if (state.chezDossiersByHousehold[householdId] !== undefined) return;
  state.chezDossiersByHousehold[householdId] = null;
  try {
    const dossier = await callChezConcierge({
      action: "fetch_dossier",
      household_id: householdId,
    });
    // Add the profile blob from households.chez_profile so the
    // existing standing-instructions UI renders cleanly.
    dossier.profile = (dossier.household && dossier.household.chez_profile) || {};
    state.chezDossiersByHousehold[householdId] = dossier;
    if (state.selectedChezRequest) {
      renderFocusedChezDetail(state.selectedChezRequest);
    }
  } catch (e) {
    console.warn("[admin] chez dossier fetch failed", e);
    // Keep null so the empty-state renders rather than re-fetching forever.
    state.chezDossiersByHousehold[householdId] = null;
  }
}

// Phase 80.1 — Render a structured proposal as a colored card so Tom
// can see at a glance whether it's pending / approved / declined and
// what kind it is. Mirrors the iOS `ChezProposalCard` shape.
function renderProposalCardHtml(proposal) {
  if (!proposal || !proposal.kind) return "";
  const status = proposal.status || "pending";
  const tone = status === "approved" ? "green"
             : status === "declined" ? "red"
             : status === "countered" ? "amber"
             : "amber";
  const kindLabel = {
    vendor: "Vendor proposal",
    date_slot: "Date options",
    cost: "Cost proposal",
    quote: "Quote proposal",
  }[proposal.kind] || "Proposal";
  let body = "";
  if (proposal.kind === "vendor" && proposal.vendor) {
    const v = proposal.vendor;
    const slots = Array.isArray(v.availability_slots) ? v.availability_slots : null;
    const slotsHtml = slots && slots.length > 0
      ? `<div>Times offered:<ul style="margin:2px 0 0 16px;padding:0;">${slots.map((s) => `<li>${escapeHtml(s)}</li>`).join("")}</ul></div>`
      : (v.estimated_window ? `<div>Earliest: ${escapeHtml(v.estimated_window)}</div>` : "");
    const costStr = v.estimated_cost_range
      ? escapeHtml(v.estimated_cost_range)
      : (v.estimated_cost ? `$${escapeHtml(String(v.estimated_cost))}` : "");
    body = `
      <strong>${escapeHtml(v.name || "(unnamed vendor)")}</strong>
      ${costStr ? `<div>Estimated: ${costStr}</div>` : ""}
      ${slotsHtml}
      ${v.rationale ? `<div class="admin-muted">${escapeHtml(v.rationale)}</div>` : ""}
    `;
  } else if (proposal.kind === "date_slot" && proposal.date_slot) {
    body = (proposal.date_slot.options || [])
      .map((o) => `<div>📅 ${escapeHtml(o.label || o.iso || "—")}</div>`)
      .join("");
  } else if (proposal.kind === "cost" && proposal.cost) {
    body = `
      <strong>$${escapeHtml(String(proposal.cost.amount || ""))}</strong>
      ${proposal.cost.scope ? `<div>${escapeHtml(proposal.cost.scope)}</div>` : ""}
    `;
  } else if (proposal.kind === "quote" && proposal.quote) {
    body = `
      <strong>${escapeHtml(proposal.quote.vendor_name || "")}</strong>
      ${proposal.quote.total ? `<div>Total: $${escapeHtml(String(proposal.quote.total))}</div>` : ""}
    `;
  }
  return `
    <div class="admin-chez__proposal">
      <div class="admin-chez__proposal-head">
        <strong>${kindLabel}</strong>
        <span class="admin-pill" data-tone="${tone}">${escapeHtml(status)}</span>
      </div>
      <div class="admin-chez__proposal-body">${body}</div>
    </div>
  `;
}

// Phase 80.1 — "Propose vendor / date / cost" affordance. Opens a
// minimal prompt-driven flow rather than a full modal — keeps the
// admin surface small while still letting Tom send structured
// proposals one click after typing.
// Phase 81 — Proposal builder modal. Replaces the prompt-driven Phase
// 80.1 flow with a proper form + multi-vendor support + research pane.
// One Send action packages 1-3 separate proposal messages so the
// homeowner sees clean Approve/Counter/Decline cards in their thread.

async function startProposalFlow(req) {
  openProposalBuilder(req);
}

function openProposalBuilder(req) {
  // Tear down any existing modal first.
  document.querySelector("[data-chez-proposal-modal]")?.remove();

  const dossier = (state.chezDossiersByHousehold || {})[req.household_id] || null;
  const homeAddress = dossier?.properties?.[0] ? formatAddress(dossier.properties[0]) : "";
  const town = dossier?.properties?.[0]?.city || "";
  const stateCode = dossier?.properties?.[0]?.state || "";
  const existingVendors = dossier?.contractors || [];

  const modal = document.createElement("div");
  modal.className = "admin-modal admin-chez__proposal-modal";
  modal.setAttribute("data-chez-proposal-modal", "");
  modal.innerHTML = `
    <div class="admin-modal__backdrop" data-modal-close></div>
    <div class="admin-modal__panel">
      <header class="admin-modal__head">
        <div>
          <h2>Send proposal</h2>
          <p class="admin-muted">${escapeHtml(homeAddress || "Homeowner")} · ${escapeHtml(req.summary || "")}</p>
        </div>
        <button type="button" class="admin-modal__close" data-modal-close aria-label="Close">×</button>
      </header>
      <div class="admin-modal__body">
        <nav class="admin-chez__proposal-tabs" role="tablist">
          <button type="button" data-proposal-tab="vendor" class="is-active">Vendors (1-3)</button>
          <button type="button" data-proposal-tab="date">Dates</button>
          <button type="button" data-proposal-tab="cost">Cost</button>
          <button type="button" data-proposal-tab="quote">Quote</button>
        </nav>

        <section class="admin-chez__proposal-tab-pane" data-proposal-pane="vendor">
          <div class="admin-chez__proposal-intro">
            <p>Add up to 3 vendors. The homeowner will see each as a clickable card with Approve / Counter / Decline.</p>
            <button type="button" class="admin-button admin-button--ghost" data-proposal-action="research-vendors">🔍 Research local vendors</button>
          </div>
          ${existingVendors.length ? `
            <div class="admin-chez__proposal-existing">
              <h4>Existing vendors on file</h4>
              <p class="admin-muted">Already in their household — could any of these handle this request?</p>
              <div class="admin-chez__proposal-existing-chips">
                ${existingVendors.slice(0, 12).map((v) => `
                  <button type="button" class="admin-chez__proposal-existing-chip" data-existing-vendor='${escapeHtml(JSON.stringify({ name: v.company_name, category: v.category, phone: v.phone }))}'>
                    + ${escapeHtml(v.company_name)}${v.category ? ` <span class="admin-muted">(${escapeHtml(v.category)})</span>` : ""}
                  </button>
                `).join("")}
              </div>
            </div>
          ` : ""}
          <div data-vendor-rows></div>
          <button type="button" class="admin-button admin-button--ghost" data-proposal-action="add-vendor-row">+ Add another vendor</button>
        </section>

        <section class="admin-chez__proposal-tab-pane is-hidden" data-proposal-pane="date">
          <p class="admin-muted">List 2-4 date options the homeowner can pick from.</p>
          <div data-date-rows></div>
          <button type="button" class="admin-button admin-button--ghost" data-proposal-action="add-date-row">+ Add another date</button>
        </section>

        <section class="admin-chez__proposal-tab-pane is-hidden" data-proposal-pane="cost">
          <label>Amount (USD)<input type="number" step="1" name="cost-amount" /></label>
          <label>Scope (one line)<input type="text" name="cost-scope" /></label>
          <label>Vendor name (optional)<input type="text" name="cost-vendor" /></label>
        </section>

        <section class="admin-chez__proposal-tab-pane is-hidden" data-proposal-pane="quote">
          <label>Vendor name<input type="text" name="quote-vendor" /></label>
          <label>Total (USD)<input type="number" step="1" name="quote-total" /></label>
          <label>Valid until<input type="text" name="quote-valid" placeholder="e.g. May 15" /></label>
        </section>

        <label class="admin-chez__proposal-message">
          <span>Message to send with the proposal (optional)</span>
          <textarea name="content" rows="3" placeholder="One-line context the homeowner sees above the cards…"></textarea>
        </label>
      </div>
      <footer class="admin-modal__foot">
        <button type="button" class="admin-button admin-button--ghost" data-modal-close>Cancel</button>
        <button type="button" class="admin-button admin-button--primary" data-proposal-action="send">Send proposal</button>
      </footer>
    </div>
  `;
  document.body.appendChild(modal);
  attachProposalBuilderHandlers(modal, req, { town, stateCode, existingVendors });
  // Seed one vendor row + two date rows by default.
  modal.querySelector("[data-proposal-action='add-vendor-row']").click();
  modal.querySelector("[data-proposal-action='add-date-row']").click();
  modal.querySelector("[data-proposal-action='add-date-row']").click();
}

function attachProposalBuilderHandlers(modal, req, ctx) {
  const close = () => modal.remove();
  modal.querySelectorAll("[data-modal-close]").forEach((btn) => btn.addEventListener("click", close));

  // Tab switching.
  modal.querySelectorAll("[data-proposal-tab]").forEach((tabBtn) => {
    tabBtn.addEventListener("click", () => {
      modal.querySelectorAll("[data-proposal-tab]").forEach((b) => b.classList.toggle("is-active", b === tabBtn));
      modal.querySelectorAll("[data-proposal-pane]").forEach((pane) => {
        pane.classList.toggle("is-hidden", pane.getAttribute("data-proposal-pane") !== tabBtn.dataset.proposalTab);
      });
    });
  });

  const vendorRowsContainer = modal.querySelector("[data-vendor-rows]");
  const dateRowsContainer = modal.querySelector("[data-date-rows]");

  const addVendorRow = (preset = {}) => {
    if (vendorRowsContainer.children.length >= 3) {
      alert("Max 3 vendors per proposal.");
      return;
    }
    const row = document.createElement("div");
    row.className = "admin-chez__proposal-vendor-row";
    row.innerHTML = `
      <div class="admin-chez__proposal-vendor-head">
        <strong>Vendor ${vendorRowsContainer.children.length + 1}</strong>
        <button type="button" class="admin-chez__proposal-row-remove" data-remove>×</button>
      </div>
      <label>Name<input type="text" name="v-name" value="${escapeHtml(preset.name || "")}" /></label>
      <label>Category<input type="text" name="v-category" value="${escapeHtml(preset.category || "")}" placeholder="e.g. Roofing" /></label>
      <div class="admin-chez__proposal-grid-2">
        <label>Estimated cost ($)<input type="number" step="1" name="v-cost" value="${preset.estimated_cost || ""}" /></label>
        <label>Earliest window<input type="text" name="v-window" value="${escapeHtml(preset.estimated_window || "")}" placeholder="e.g. Tue 2pm" /></label>
      </div>
      <div class="admin-chez__proposal-grid-2">
        <label>Rating (0-5)<input type="number" step="0.1" min="0" max="5" name="v-rating" value="${preset.rating || ""}" /></label>
        <label>Reviews<input type="number" step="1" name="v-reviews" value="${preset.review_count || ""}" /></label>
      </div>
      <label>Phone<input type="text" name="v-phone" value="${escapeHtml(preset.phone || "")}" /></label>
      <label class="admin-chez__proposal-rationale">
        <span>Why this fits — homeowner sees this on their card
          <button type="button" class="admin-chez__proposal-ai-suggest" data-ai-suggest>✨ Suggest framing</button>
        </span>
        <textarea name="v-rationale" rows="2" placeholder="Tailored to their home + your context. e.g. Specializes in old colonials; A+ BBB, no chain.">${escapeHtml(preset.rationale || "")}</textarea>
      </label>
    `;
    vendorRowsContainer.appendChild(row);
    row.querySelector("[data-remove]").addEventListener("click", () => row.remove());
    row.querySelector("[data-ai-suggest]").addEventListener("click", async (e) => {
      const btn = e.currentTarget;
      const nameInput = row.querySelector("[name='v-name']");
      const categoryInput = row.querySelector("[name='v-category']");
      const ratingInput = row.querySelector("[name='v-rating']");
      const reviewsInput = row.querySelector("[name='v-reviews']");
      const rationaleField = row.querySelector("[name='v-rationale']");
      if (!nameInput.value.trim()) {
        alert("Add a vendor name first so AI has something to work with.");
        return;
      }
      btn.disabled = true; btn.textContent = "Thinking…";
      try {
        const dossier = (state.chezDossiersByHousehold || {})[req.household_id] || {};
        const profile = dossier.profile || {};
        const property = (dossier.properties || [])[0];
        const propertyContext = property
          ? `${property.year_built ? property.year_built + " " : ""}${property.property_type || "home"} in ${property.city || ""}, ${property.state || ""}`
          : "";
        const result = await callChezConcierge({
          action: "suggest_vendor_framing",
          household_id: req.household_id,
          request_summary: req.summary,
          request_category: req.category,
          vendor: {
            name: nameInput.value.trim(),
            category: categoryInput.value.trim() || undefined,
            rating: ratingInput.value ? Number(ratingInput.value) : undefined,
            review_count: reviewsInput.value ? Number(reviewsInput.value) : undefined,
          },
          homeowner_about: profile.about_us,
          property_context: propertyContext,
        });
        if (result.framing) rationaleField.value = result.framing;
      } catch (err) {
        console.warn("[admin] suggest framing failed", err);
      } finally {
        btn.disabled = false; btn.textContent = "✨ Suggest framing";
      }
    });
  };

  // Phase 83.2 — date_slot rows in the proposal builder now use a
  // datetime-local picker so every option the homeowner sees is rendered
  // from a single canonical ISO datetime (formatted via formatSlotDisplay
  // before send). Forces consistent format across every proposal we ship.
  const addDateRow = (label = "") => {
    const row = document.createElement("div");
    row.className = "admin-chez__proposal-date-row";
    row.innerHTML = `
      <input type="datetime-local" name="d-iso" value="${escapeHtml(toLocalDateTimeInputValue(label))}" />
      <button type="button" class="admin-chez__proposal-row-remove" data-remove>×</button>
    `;
    dateRowsContainer.appendChild(row);
    row.querySelector("[data-remove]").addEventListener("click", () => row.remove());
  };

  // Existing-vendor chip → seeds a new vendor row.
  modal.querySelectorAll("[data-existing-vendor]").forEach((btn) => {
    btn.addEventListener("click", () => {
      try { addVendorRow(JSON.parse(btn.getAttribute("data-existing-vendor"))); }
      catch (e) { /* ignore parse failure */ }
    });
  });

  // Local vendor research — calls find-local-vendors and seeds rows.
  modal.querySelector("[data-proposal-action='research-vendors']")?.addEventListener("click", async (e) => {
    const btn = e.currentTarget;
    const category = window.prompt(
      `Search for vendors near ${ctx.town}, ${ctx.stateCode}. What category? (e.g. roofing, plumbing, hvac)`,
      req.category === "find_handyman" ? "handyman" : ""
    );
    if (!category) return;
    btn.disabled = true; btn.textContent = "Searching…";
    try {
      const session = (await supabase.auth.getSession()).data.session;
      const resp = await fetch(`${SUPABASE_URL}/functions/v1/find-local-vendors`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "apikey": SUPABASE_ANON_KEY,
          "Authorization": `Bearer ${session?.access_token || SUPABASE_ANON_KEY}`,
        },
        body: JSON.stringify({
          town: ctx.town,
          state: ctx.stateCode,
          category: category.trim(),
        }),
      });
      const data = await resp.json();
      const vendors = data.vendors || [];
      if (vendors.length === 0) {
        alert("No vendors returned. Try a different category or add manually.");
        return;
      }
      // Show a sub-picker so Tom can choose which to seed.
      showVendorPickerOverlay(modal, vendors, addVendorRow);
    } catch (err) {
      console.warn("[admin] vendor research failed", err);
      alert(`Vendor research failed: ${err.message || err}`);
    } finally {
      btn.disabled = false; btn.textContent = "🔍 Research local vendors";
    }
  });

  // Add-row buttons.
  modal.querySelector("[data-proposal-action='add-vendor-row']").addEventListener("click", () => addVendorRow());
  modal.querySelector("[data-proposal-action='add-date-row']").addEventListener("click", () => addDateRow());

  // Send button.
  modal.querySelector("[data-proposal-action='send']").addEventListener("click", async () => {
    const activeTab = modal.querySelector("[data-proposal-tab].is-active")?.dataset.proposalTab;
    const content = modal.querySelector("[name='content']").value.trim();
    const sendBtn = modal.querySelector("[data-proposal-action='send']");
    sendBtn.disabled = true; sendBtn.textContent = "Sending…";
    try {
      if (activeTab === "vendor") {
        const rows = Array.from(vendorRowsContainer.querySelectorAll(".admin-chez__proposal-vendor-row"));
        const vendors = rows.map((r) => ({
          name: r.querySelector("[name='v-name']").value.trim(),
          category: r.querySelector("[name='v-category']").value.trim() || undefined,
          phone: r.querySelector("[name='v-phone']").value.trim() || undefined,
          estimated_cost: r.querySelector("[name='v-cost']").value ? Number(r.querySelector("[name='v-cost']").value) : undefined,
          estimated_window: r.querySelector("[name='v-window']").value.trim() || undefined,
          rating: r.querySelector("[name='v-rating']").value ? Number(r.querySelector("[name='v-rating']").value) : undefined,
          review_count: r.querySelector("[name='v-reviews']").value ? Number(r.querySelector("[name='v-reviews']").value) : undefined,
          rationale: r.querySelector("[name='v-rationale']").value.trim() || undefined,
        })).filter((v) => v.name);
        if (vendors.length === 0) {
          alert("Add at least one vendor.");
          return;
        }
        // Send vendors as separate proposal messages so each renders as
        // an individual Approve/Counter/Decline card. The intro message
        // (only on the first one) carries the framing context.
        for (let i = 0; i < vendors.length; i++) {
          const v = vendors[i];
          const intro = i === 0
            ? (content || (vendors.length > 1 ? `Here are ${vendors.length} options for you. Tap Approve on whichever fits.` : ""))
            : "";
          await callChezConcierge({
            action: "propose",
            request_id: req.id,
            proposal: { kind: "vendor", vendor: v },
            content: intro,
          });
        }
      } else if (activeTab === "date") {
        // Phase 83.2 — the input is now `datetime-local`; values arrive
        // as "YYYY-MM-DDTHH:mm". We send both an ISO string (for clients
        // that can format) and a friendly label (homeowner-facing copy).
        const rows = Array.from(dateRowsContainer.querySelectorAll(".admin-chez__proposal-date-row"));
        const options = rows
          .map((r) => r.querySelector("[name='d-iso']").value.trim())
          .filter(Boolean)
          .map((localValue) => {
            const date = new Date(localValue);
            const iso = isNaN(date.getTime()) ? null : date.toISOString();
            const label = formatSlotDisplay(localValue);
            return { label, iso };
          });
        if (options.length === 0) {
          alert("Pick at least one date / time option.");
          return;
        }
        await callChezConcierge({
          action: "propose",
          request_id: req.id,
          proposal: { kind: "date_slot", date_slot: { options } },
          content,
        });
      } else if (activeTab === "cost") {
        const amount = Number(modal.querySelector("[name='cost-amount']").value);
        if (!amount) { alert("Enter a cost amount."); return; }
        await callChezConcierge({
          action: "propose",
          request_id: req.id,
          proposal: {
            kind: "cost",
            cost: {
              amount,
              currency: "USD",
              scope: modal.querySelector("[name='cost-scope']").value.trim() || undefined,
              vendor_name: modal.querySelector("[name='cost-vendor']").value.trim() || undefined,
            },
          },
          content,
        });
      } else if (activeTab === "quote") {
        const vendor = modal.querySelector("[name='quote-vendor']").value.trim();
        if (!vendor) { alert("Enter a vendor name."); return; }
        const total = Number(modal.querySelector("[name='quote-total']").value);
        await callChezConcierge({
          action: "propose",
          request_id: req.id,
          proposal: {
            kind: "quote",
            quote: {
              vendor_name: vendor,
              total: total || undefined,
              valid_until: modal.querySelector("[name='quote-valid']").value.trim() || undefined,
            },
          },
          content,
        });
      }
      close();
      await loadAdminData();
      await loadChezMessages(req.id);
      const refreshed = state.chezRequests.find((r) => r.id === req.id);
      if (refreshed) state.selectedChezRequest = refreshed;
      renderChezRequestsView();
    } catch (err) {
      console.warn("[admin] send proposal failed", err);
      alert(`Send failed: ${err.message || err}`);
    } finally {
      sendBtn.disabled = false; sendBtn.textContent = "Send proposal";
    }
  });
}

function showVendorPickerOverlay(parentModal, vendors, addVendorRow) {
  const overlay = document.createElement("div");
  overlay.className = "admin-chez__vendor-picker-overlay";
  overlay.innerHTML = `
    <div class="admin-chez__vendor-picker">
      <header>
        <h3>Pick vendors to propose</h3>
        <button type="button" data-close>×</button>
      </header>
      <div class="admin-chez__vendor-picker-list">
        ${vendors.map((v, i) => `
          <button type="button" class="admin-chez__vendor-picker-row" data-pick="${i}">
            <div>
              <strong>${escapeHtml(v.name || "(unnamed)")}</strong>
              <div class="admin-muted">${escapeHtml(v.address || "")}</div>
            </div>
            <div class="admin-chez__vendor-picker-meta">
              ${v.rating ? `${escapeHtml(String(v.rating))}★` : ""}
              ${v.user_ratings_total ? ` (${escapeHtml(String(v.user_ratings_total))})` : ""}
              ${v.is_haven_certified || v.is_top_rated ? ` <span class="admin-pill" data-tone="green">Top-rated</span>` : ""}
            </div>
          </button>
        `).join("")}
      </div>
    </div>
  `;
  parentModal.appendChild(overlay);
  overlay.querySelector("[data-close]").addEventListener("click", () => overlay.remove());
  overlay.querySelectorAll("[data-pick]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const v = vendors[Number(btn.dataset.pick)];
      addVendorRow({
        name: v.name,
        phone: v.phone || v.formatted_phone_number,
        rating: v.rating,
        review_count: v.user_ratings_total,
      });
      btn.classList.add("is-picked");
    });
  });
}

function attachChezPanelHandlers(req) {
  // Status select — fires immediately on change.
  const statusSelect = el.auditFocused.querySelector("[data-chez-status]");
  if (statusSelect) {
    statusSelect.addEventListener("change", async (e) => {
      const newStatus = e.target.value;
      if (!newStatus || newStatus === req.status) return;
      await performChezTransition(req, newStatus);
    });
  }

  // Reply form.
  const form = el.auditFocused.querySelector("[data-chez-reply-form]");
  if (form) {
    form.addEventListener("submit", async (e) => {
      e.preventDefault();
      const content = form.elements.content.value.trim();
      if (!content) return;
      const ack = form.elements.acknowledgement_required.checked;
      const toStatus = form.elements.to_status.value || null;
      const feedback = form.querySelector("[data-chez-feedback]");
      const submitBtn = form.querySelector('button[type="submit"]');
      submitBtn.disabled = true;
      submitBtn.textContent = "Sending…";
      try {
        await callChezConcierge({
          action: "reply",
          request_id: req.id,
          content,
          acknowledgement_required: ack,
          to_status: toStatus,
        });
        if (feedback) feedback.textContent = "Sent.";
        form.elements.content.value = "";
        form.elements.acknowledgement_required.checked = false;
        form.elements.to_status.value = "";
        await loadAdminData();
        await loadChezMessages(req.id);
        const refreshed = state.chezRequests.find((r) => r.id === req.id);
        if (refreshed) state.selectedChezRequest = refreshed;
        renderChezRequestsView();
      } catch (err) {
        console.error("[admin] chez reply failed", err);
        if (feedback) feedback.textContent = `Failed: ${err.message || err}`;
      } finally {
        submitBtn.disabled = false;
        submitBtn.textContent = "Send reply";
      }
    });
  }

  // Quick-action buttons.
  el.auditFocused.querySelectorAll("[data-chez-action]").forEach((btn) => {
    btn.addEventListener("click", async () => {
      const action = btn.dataset.chezAction;
      if (action === "waiting") {
        await performChezTransition(req, "waiting_customer");
      } else if (action === "resolved") {
        await performChezTransition(req, "resolved");
      } else if (action === "reopen") {
        await performChezTransition(req, "open");
      } else if (action === "propose") {
        await startProposalFlow(req);
      }
    });
  });

  // Phase 81 — dossier entity drilldown. Click any chip / row in the
  // dossier to open a slide-in drawer with the full entity record.
  el.auditFocused.querySelectorAll("[data-dossier-entity]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const entity = btn.dataset.dossierEntity;
      const id = btn.dataset.dossierId;
      openDossierDrawer(req.household_id, entity, id);
    });
  });

  // Phase 81.1 — vendor candidate cards in the AI analysis panel.
  el.auditFocused.querySelectorAll("[data-action]").forEach((btn) => {
    btn.addEventListener("click", async (e) => {
      const action = btn.dataset.action;
      if (action === "open-profile-drawer") {
        openHouseholdProfileDrawer(req.household_id);
      } else if (action === "rerun-analysis") {
        runChezAnalysis(req.id, true);
        renderFocusedChezDetail(req);
      } else if (action === "expand-vendor" || action === "collapse-vendor") {
        const card = btn.closest("[data-vendor-key]");
        if (!card) return;
        const key = card.getAttribute("data-vendor-key");
        state.chezExpandedVendorKeys = state.chezExpandedVendorKeys || {};
        state.chezExpandedVendorKeys[req.id] = state.chezExpandedVendorKeys[req.id] || {};
        state.chezExpandedVendorKeys[req.id][key] = action === "expand-vendor";
        renderFocusedChezDetail(req);
      } else if (action === "package-send") {
        await packageAndSendRecommendedVendors(req);
      } else if (action === "add-slot") {
        const card = btn.closest("[data-vendor-key]");
        if (!card) return;
        const key = card.getAttribute("data-vendor-key");
        state.chezVendorCallsByRequest = state.chezVendorCallsByRequest || {};
        state.chezVendorCallsByRequest[req.id] = state.chezVendorCallsByRequest[req.id] || {};
        const slot = state.chezVendorCallsByRequest[req.id][key] = state.chezVendorCallsByRequest[req.id][key] || {};
        const slots = Array.isArray(slot.availability_slots) ? slot.availability_slots : [];
        // Snapshot any in-progress text inputs in case the user just typed
        // and hasn't blurred yet — re-render would lose them otherwise.
        card.querySelectorAll("[data-vendor-slot-input]").forEach((input) => {
          const idx = Number(input.dataset.slotIndex);
          if (Number.isFinite(idx) && slots[idx] !== undefined) slots[idx] = input.value;
        });
        slots.push("");
        slot.availability_slots = slots;
        renderFocusedChezDetail(req);
      } else if (action === "remove-slot") {
        const card = btn.closest("[data-vendor-key]");
        if (!card) return;
        const key = card.getAttribute("data-vendor-key");
        const removeIdx = Number(btn.dataset.slotIndex);
        const slot = state.chezVendorCallsByRequest?.[req.id]?.[key];
        if (!slot || !Array.isArray(slot.availability_slots)) return;
        // Snapshot in-progress text first.
        card.querySelectorAll("[data-vendor-slot-input]").forEach((input) => {
          const idx = Number(input.dataset.slotIndex);
          if (Number.isFinite(idx) && slot.availability_slots[idx] !== undefined) slot.availability_slots[idx] = input.value;
        });
        slot.availability_slots.splice(removeIdx, 1);
        renderFocusedChezDetail(req);
      } else if (action === "expand-analysis") {
        // Phase 82 — Re-open the analysis panel from the collapsed
        // line so Tom can re-research vendors mid-case.
        state.chezAnalysisExpandedByRequest = state.chezAnalysisExpandedByRequest || {};
        state.chezAnalysisExpandedByRequest[req.id] = true;
        renderFocusedChezDetail(req);
      } else if (action === "mark-resolved-from-visits") {
        await performChezTransition(req, "resolved");
      } else if (action === "adopt-slot") {
        // Phase 82 — Click a "Times offered" chip on a visit card to
        // copy that slot's text into the datetime field. Tom still
        // confirms (since chips are free-form text, not parseable
        // dates), but the UX bypasses re-typing.
        const card = btn.closest("[data-visit-id]");
        if (!card) return;
        const slotText = btn.dataset.slotText || "";
        const noteInput = card.querySelector("[data-visit-field='scheduled_window']");
        if (noteInput) {
          noteInput.value = slotText;
          noteInput.dispatchEvent(new Event("change", { bubbles: true }));
        }
      } else if (action === "visit-mark-scheduled") {
        await visitMarkAction(req, btn, "scheduled");
      } else if (action === "visit-mark-completed") {
        await visitMarkAction(req, btn, "completed");
      } else if (action === "visit-cancel") {
        await visitMarkAction(req, btn, "cancelled");
      } else if (action === "visit-save-notes") {
        await visitSaveAction(req, btn);
      }
    });
  });

  // Phase 81.2 — Slot inputs persist on every keystroke so AI suggest /
  // package-send sees the current values without requiring a blur.
  el.auditFocused.querySelectorAll("[data-vendor-slot-input]").forEach((input) => {
    const handler = () => {
      const card = input.closest("[data-vendor-key]");
      if (!card) return;
      const key = card.getAttribute("data-vendor-key");
      const idx = Number(input.dataset.slotIndex);
      state.chezVendorCallsByRequest = state.chezVendorCallsByRequest || {};
      state.chezVendorCallsByRequest[req.id] = state.chezVendorCallsByRequest[req.id] || {};
      const slot = state.chezVendorCallsByRequest[req.id][key] = state.chezVendorCallsByRequest[req.id][key] || {};
      slot.availability_slots = slot.availability_slots || [];
      slot.availability_slots[idx] = input.value;
    };
    input.addEventListener("input", handler);
    input.addEventListener("change", handler);
  });

  // Vendor call-form field bindings — write to in-memory state on
  // change so the UI keeps current data without round-tripping
  // through the server. Persisted only when the user clicks
  // "Package & send" (or could be persisted to local storage if
  // we want survive refresh; for now memory is enough).
  el.auditFocused.querySelectorAll("[data-vendor-field]").forEach((input) => {
    const handler = () => {
      const card = input.closest("[data-vendor-key]");
      if (!card) return;
      const key = card.getAttribute("data-vendor-key");
      state.chezVendorCallsByRequest = state.chezVendorCallsByRequest || {};
      state.chezVendorCallsByRequest[req.id] = state.chezVendorCallsByRequest[req.id] || {};
      const slot = state.chezVendorCallsByRequest[req.id][key] = state.chezVendorCallsByRequest[req.id][key] || {};
      const field = input.dataset.vendorField;
      if (input.type === "checkbox") slot[field] = input.checked;
      else slot[field] = input.value;
      // Phase 81.2 — toggle the Custom cost row visibility without a
      // full re-render so the user's typing focus survives.
      if (field === "cost_range") {
        const customRow = card.querySelector("[data-vendor-cost-custom-row]");
        if (customRow) customRow.classList.toggle("is-hidden", input.value !== "custom");
      }
      // Refresh just enough to update the recommended pill + count
      // without redrawing from scratch (keeps focus in the input).
      if (field === "recommended") {
        renderFocusedChezDetail(req);
      }
    };
    input.addEventListener("change", handler);
    if (input.tagName === "TEXTAREA" || (input.tagName === "INPUT" && input.type !== "checkbox" && input.type !== "select-one")) {
      input.addEventListener("input", handler);
    }
  });

  // "✨ Summarize from notes" button per vendor card. Pulls the
  // current call data (raw notes, slots, cost range) into the AI
  // prompt so the homeowner sees a polished recommendation summary.
  el.auditFocused.querySelectorAll("[data-vendor-suggest]").forEach((btn) => {
    btn.addEventListener("click", async () => {
      const card = btn.closest("[data-vendor-key]");
      if (!card) return;
      const key = card.getAttribute("data-vendor-key");
      const cached = state.chezAnalysisByRequest?.[req.id];
      if (!cached) return;
      const allCandidates = [
        ...(cached.existing_vendors || []).map((v) => ({ ...v, _source: "existing" })),
        ...(cached.places_candidates || []).map((v) => ({ ...v, _source: "places" })),
      ];
      const v = allCandidates.find((cand) => vendorCandidateKey(cand) === key);
      if (!v) return;
      btn.disabled = true; btn.textContent = "Writing…";
      try {
        const dossier = (state.chezDossiersByHousehold || {})[req.household_id] || {};
        const profile = dossier.profile || {};
        const property = (dossier.properties || [])[0];
        const propertyContext = property
          ? `${property.year_built ? property.year_built + " " : ""}${property.property_type || "home"} in ${property.city || ""}, ${property.state || ""}`
          : "";
        const callData = state.chezVendorCallsByRequest?.[req.id]?.[key] || {};
        // Resolve cost range — prefer custom text when "custom" is selected.
        const costRange = callData.cost_range === "custom"
          ? (callData.cost_custom || "")
          : (callData.cost_range || "");
        // Snapshot in-progress slot inputs.
        const slotInputs = Array.from(card.querySelectorAll("[data-vendor-slot-input]"))
          .map((el) => el.value.trim())
          .filter(Boolean);
        const result = await callChezConcierge({
          action: "suggest_vendor_framing",
          household_id: req.household_id,
          request_summary: req.summary,
          request_category: req.category,
          vendor: {
            name: v.company_name || v.name,
            category: v.category,
            rating: v.rating,
            review_count: v.user_ratings_total || v.review_count,
          },
          homeowner_about: profile.about_us,
          property_context: propertyContext,
          call_notes: callData.notes || "",
          availability_slots: slotInputs,
          cost_range: costRange,
        });
        if (result.framing) {
          state.chezVendorCallsByRequest = state.chezVendorCallsByRequest || {};
          state.chezVendorCallsByRequest[req.id] = state.chezVendorCallsByRequest[req.id] || {};
          const slot = state.chezVendorCallsByRequest[req.id][key] = state.chezVendorCallsByRequest[req.id][key] || {};
          slot.rationale = result.framing;
          renderFocusedChezDetail(req);
        }
      } catch (err) {
        console.warn("[admin] suggest framing failed", err);
      } finally {
        btn.disabled = false; btn.textContent = "✨ Summarize from notes";
      }
    });
  });

  // Phase 82 — Visit-card field bindings. Same pattern as the vendor
  // call form: write to in-memory cache on every input so save / state
  // changes pick up the latest values without requiring blur.
  el.auditFocused.querySelectorAll("[data-visit-field]").forEach((input) => {
    const handler = () => {
      const card = input.closest("[data-visit-id]");
      if (!card) return;
      const visitId = card.getAttribute("data-visit-id");
      const visit = (state.chezVisitsByRequest?.[req.id] || []).find((v) => v.id === visitId);
      if (!visit) return;
      const field = input.dataset.visitField;
      // Stash on the cached visit so re-renders see the latest text
      // without round-tripping. The persist call sends to the server.
      visit[field] = input.value;
    };
    input.addEventListener("change", handler);
    if (input.tagName === "TEXTAREA" || (input.tagName === "INPUT" && input.type !== "checkbox")) {
      input.addEventListener("input", handler);
    }
  });
}

// Phase 82 — Visit state-transition button handler. "Confirm scheduled",
// "Mark completed", "Cancel visit" all flow through here. Sends the
// current form values + the new state to the Edge Function, which
// persists, posts a system message in the thread, and (if the admin
// added a reply note) sends it as a normal homeowner reply too.
async function visitMarkAction(req, btn, newState) {
  const card = btn.closest("[data-visit-id]");
  if (!card) return;
  const visitId = card.getAttribute("data-visit-id");
  const visit = (state.chezVisitsByRequest?.[req.id] || []).find((v) => v.id === visitId);
  if (!visit) return;

  // Validation: scheduling requires a date.
  const dateInput = card.querySelector("[data-visit-field='scheduled_for']");
  if (newState === "scheduled" && (!dateInput || !dateInput.value)) {
    alert("Pick a date and time before marking scheduled.");
    return;
  }
  // Validation: cancellation prompts for a reason.
  let reason = "";
  if (newState === "cancelled") {
    reason = window.prompt("Why is this visit cancelled? (optional, lands in the homeowner thread)", "") || "";
  }

  // Optional one-line reply to lend the homeowner a heads-up. The
  // Edge Function only sends if non-empty.
  let sendReply = "";
  if (newState === "scheduled") {
    const when = dateInput?.value ? new Date(dateInput.value).toLocaleString(undefined, {
      weekday: "long", month: "long", day: "numeric", hour: "numeric", minute: "2-digit",
    }) : "the confirmed time";
    const proposed = window.prompt(
      `Reply to homeowner? (leave blank to skip)`,
      `Booked ${visit.vendor_name} for ${when}. We'll be in touch as the date approaches.`
    );
    if (proposed && proposed.trim()) sendReply = proposed.trim();
  } else if (newState === "completed") {
    const proposed = window.prompt(
      `Reply to homeowner? (leave blank to skip)`,
      `${visit.vendor_name} just finished — work complete. Anything you want me to follow up on?`
    );
    if (proposed && proposed.trim()) sendReply = proposed.trim();
  } else if (newState === "cancelled" && reason.trim()) {
    sendReply = `Heads up — the visit with ${visit.vendor_name} was cancelled. ${reason.trim()}`;
  }

  btn.disabled = true;
  const originalText = btn.textContent;
  btn.textContent = "Saving…";
  try {
    await callChezConcierge({
      action: "update_visit",
      visit_id: visitId,
      state: newState,
      scheduled_for: dateInput?.value ? new Date(dateInput.value).toISOString() : undefined,
      scheduled_window: card.querySelector("[data-visit-field='scheduled_window']")?.value || undefined,
      notes: card.querySelector("[data-visit-field='notes']")?.value || undefined,
      outcome: card.querySelector("[data-visit-field='outcome']")?.value || (newState === "cancelled" ? reason : undefined),
      send_reply: sendReply || undefined,
      acknowledgement_required: false,
    });
    // Invalidate the visits cache so the next render fetches fresh.
    if (state.chezVisitsByRequest) delete state.chezVisitsByRequest[req.id];
    await loadChezMessages(req.id);
    renderFocusedChezDetail(req);
  } catch (err) {
    console.warn("[admin] update_visit failed", err);
    alert(`Save failed: ${err.message || err}`);
    btn.disabled = false;
    btn.textContent = originalText;
  }
}

async function visitSaveAction(req, btn) {
  const card = btn.closest("[data-visit-id]");
  if (!card) return;
  const visitId = card.getAttribute("data-visit-id");
  const dateInput = card.querySelector("[data-visit-field='scheduled_for']");
  btn.disabled = true;
  const originalText = btn.textContent;
  btn.textContent = "Saving…";
  try {
    await callChezConcierge({
      action: "update_visit",
      visit_id: visitId,
      scheduled_for: dateInput?.value ? new Date(dateInput.value).toISOString() : null,
      scheduled_window: card.querySelector("[data-visit-field='scheduled_window']")?.value || null,
      notes: card.querySelector("[data-visit-field='notes']")?.value || null,
      outcome: card.querySelector("[data-visit-field='outcome']")?.value || null,
    });
    if (state.chezVisitsByRequest) delete state.chezVisitsByRequest[req.id];
    renderFocusedChezDetail(req);
  } catch (err) {
    console.warn("[admin] save visit failed", err);
    alert(`Save failed: ${err.message || err}`);
  } finally {
    btn.disabled = false;
    btn.textContent = originalText;
  }
}

// Phase 81.1 — Package recommended vendors and send each as a
// proposal message. One click → all recommended vendors land in
// the homeowner's thread as separate Approve/Counter/Decline cards.
// Phase 85 dispatch — admin Concierge "Assign handyman" flow.
// Renders a workspace picker modal, lets the operator confirm the
// default assignee (or override), then calls
// chez-concierge.assign_handyman_to_assessment which creates the
// provider_visit_assignment + posts a system message into this thread.
// On success, refreshes the cockpit so the new audit row appears.
async function assignHandymanToAssessmentFlow(req, btn) {
  if (!isHomeAssessmentRequest(req)) {
    alert("Assign handyman only applies to home-assessment requests.");
    return;
  }
  const ctx = req.context || {};
  const assessmentId = ctx.assessment_id;
  if (!assessmentId) {
    alert("Missing assessment_id on this request — cannot dispatch.");
    return;
  }

  // Try to surface the property's state so we can prefer in-state
  // workspaces. The dossier is loaded lazily; fall back to "" if absent.
  const dossier = (state.chezDossiersByHousehold || {})[req.household_id];
  const propertyState = dossier?.properties?.[0]?.state || "";

  const origLabel = btn ? btn.textContent : "";
  if (btn) { btn.disabled = true; btn.textContent = "Loading…"; }
  let workspaces = [];
  try {
    const resp = await callChezConcierge({
      action: "list_eligible_workspaces",
      property_state: propertyState,
    });
    workspaces = resp.workspaces || [];
  } catch (err) {
    if (btn) { btn.disabled = false; btn.textContent = origLabel; }
    alert(`Couldn't load eligible workspaces: ${err.message || err}`);
    return;
  }
  if (btn) { btn.disabled = false; btn.textContent = origLabel; }

  if (workspaces.length === 0) {
    alert("No workspaces with active members are available. Add a handyman workspace first via Vendor Apps.");
    return;
  }

  const modal = document.createElement("div");
  modal.className = "admin-modal";
  modal.innerHTML = `
    <div class="admin-modal__backdrop" data-modal-close></div>
    <div class="admin-modal__panel" style="max-width: 600px;">
      <header class="admin-modal__head">
        <div>
          <h2>Assign a handyman</h2>
          <p class="admin-muted">Pick a workspace to dispatch this free home assessment to. ${propertyState ? `In-state (${escapeHtml(propertyState)}) workspaces are listed first.` : ""}</p>
        </div>
        <button type="button" class="admin-modal__close" data-modal-close aria-label="Close">×</button>
      </header>
      <div class="admin-modal__body">
        <div class="admin-assign-list" style="display:flex;flex-direction:column;gap:8px;max-height:50vh;overflow:auto;">
          ${workspaces.map((w) => {
            const def = w.defaultMember;
            return `
              <button type="button" class="admin-assign-row"
                data-ws-id="${escapeHtml(w.id)}"
                data-member-id="${escapeHtml(def?.id || "")}"
                data-member-label="${escapeHtml(def?.fullName || "")}"
                style="display:flex;align-items:center;gap:12px;padding:12px;border:1px solid var(--neutral-200, #EDEEF0);border-radius:10px;background:#fff;cursor:pointer;text-align:left;width:100%;">
                <div style="flex:1;min-width:0;">
                  <div style="font-size:14px;font-weight:600;color:var(--text, #111);display:flex;gap:6px;align-items:center;">
                    <span>${escapeHtml(w.companyName || "(unnamed workspace)")}</span>
                    ${w.stateMatch ? `<span class="cockpit-pill cockpit-pill--success cockpit-pill--xs">In state</span>` : ""}
                  </div>
                  <div style="font-size:12px;color:var(--text-muted, #666);margin-top:2px;">
                    ${escapeHtml([w.serviceCity, w.serviceState].filter(Boolean).join(", ") || "Service area not set")}
                    · ${w.activeMemberCount} active ${w.activeMemberCount === 1 ? "member" : "members"}
                  </div>
                  ${def
                    ? `<div style="font-size:12px;color:var(--text-muted, #666);margin-top:4px;"><span class="cockpit-pill cockpit-pill--indigo cockpit-pill--xs">Default</span> ${escapeHtml(def.fullName)}${def.email ? ` · ${escapeHtml(def.email)}` : ""}</div>`
                    : `<div style="font-size:12px;color:var(--text-muted, #666);margin-top:4px;font-style:italic;">No default assignee set</div>`}
                </div>
                <span style="color:var(--text-soft, #999);">→</span>
              </button>
            `;
          }).join("")}
        </div>
        <p class="admin-muted" style="margin-top:12px;font-size:12px;">
          Dispatching creates a provider_visit_assignment, sets the assessment to <b>scheduled</b>, posts an audit row into this thread, and notifies the assigned handyman by push + email.
        </p>
      </div>
      <footer class="admin-modal__foot">
        <button type="button" class="admin-button admin-button--ghost" data-modal-close>Cancel</button>
      </footer>
    </div>
  `;
  document.body.appendChild(modal);
  modal.querySelectorAll("[data-modal-close]").forEach((b) =>
    b.addEventListener("click", () => modal.remove())
  );

  modal.querySelectorAll(".admin-assign-row").forEach((row) => {
    row.addEventListener("click", async () => {
      const wsId = row.getAttribute("data-ws-id");
      const memberId = row.getAttribute("data-member-id") || null;
      const memberLabel = row.getAttribute("data-member-label") || "the workspace's default";
      const wsName = row.querySelector("div span").textContent.trim();
      if (!confirm(`Dispatch this assessment to ${wsName}${memberLabel ? ` (${memberLabel})` : ""}?`)) return;

      row.style.opacity = "0.6";
      row.querySelectorAll("button, .admin-assign-row").forEach((b) => { b.disabled = true; });
      try {
        await callChezConcierge({
          action: "assign_handyman_to_assessment",
          assessment_id: assessmentId,
          workspace_id: wsId,
          member_id: memberId,
          request_id: req.id,
        });
        modal.remove();
        // Refresh thread immediately so the audit row is visible; do
        // a backgrounded loadAdminData() so the queue picks up any
        // status flips on the chez_request side.
        delete state.chezMessages[req.id];
        await loadChezMessages(req.id);
        loadAdminData().finally(() => renderConciergeCockpit());
        renderConciergeCockpit();
      } catch (err) {
        row.style.opacity = "1";
        row.querySelectorAll("button, .admin-assign-row").forEach((b) => { b.disabled = false; });
        alert(`Dispatch failed: ${err.message || err}`);
      }
    });
  });
}

async function packageAndSendRecommendedVendors(req) {
  const callState = state.chezVendorCallsByRequest?.[req.id] || {};
  const cached = state.chezAnalysisByRequest?.[req.id];
  if (!cached) {
    alert("Run analysis first.");
    return;
  }
  const allCandidates = [
    ...(cached.existing_vendors || []).map((v) => ({ ...v, _source: "existing" })),
    ...(cached.places_candidates || []).map((v) => ({ ...v, _source: "places" })),
  ];
  const recommended = [];
  for (const v of allCandidates) {
    const key = vendorCandidateKey(v);
    const data = callState[key];
    if (data && data.recommended) {
      recommended.push({ vendor: v, data });
    }
  }
  if (recommended.length === 0) {
    alert("Mark at least one vendor as Recommended first.");
    return;
  }
  const introText = recommended.length > 1
    ? `Here are ${recommended.length} options for you. Tap Approve on whichever fits — Chez handles the rest.`
    : "Chez found a vendor for you. Tap Approve to move forward.";
  if (!confirm(`Send ${recommended.length} proposal${recommended.length > 1 ? "s" : ""} to the homeowner?`)) return;

  try {
    for (let i = 0; i < recommended.length; i++) {
      const { vendor, data } = recommended[i];
      // Resolve cost range — when "custom" picked use the typed text;
      // otherwise pass the picker label verbatim. We DO NOT stamp a
      // numeric estimated_cost unless the admin typed a real number
      // into the custom field — the iOS card renders cost as a string
      // when it's a range like "$1,000–2,500".
      const rawCost = data.cost_range === "custom" ? (data.cost_custom || "") : (data.cost_range || "");
      const numericCost = Number(rawCost.replace(/[^0-9.]/g, ""));
      const useNumeric = data.cost_range === "custom"
        && Number.isFinite(numericCost)
        && numericCost > 0
        && /^\$?\s*[\d,]+\s*$/.test(rawCost);  // single number, not a range
      // Phase 83.4 — vendor proposals NO LONGER carry availability slots.
      // The homeowner picks based on vendor + price + fit; date
      // coordination happens AFTER approval via the visit card's
      // "Send dates to homeowner" date_slot proposal flow.
      const proposal = {
        kind: "vendor",
        vendor: {
          name: vendor.company_name || vendor.name,
          phone: vendor.phone || vendor.formatted_phone_number,
          rating: vendor.rating,
          review_count: vendor.user_ratings_total || vendor.review_count,
          // Numeric cost only when the admin clearly typed one.
          estimated_cost: useNumeric ? numericCost : undefined,
          // Range string preferred — homeowner sees "$1,000–2,500"
          // verbatim instead of a fake-precise dollar amount.
          estimated_cost_range: useNumeric ? undefined : (rawCost || undefined),
          rationale: data.rationale,
        },
      };
      // Strip undefined / empty so the card renders cleanly.
      Object.keys(proposal.vendor).forEach((k) => {
        const val = proposal.vendor[k];
        if (val === undefined || val === "" || (Array.isArray(val) && val.length === 0)) delete proposal.vendor[k];
      });
      await callChezConcierge({
        action: "propose",
        request_id: req.id,
        proposal,
        content: i === 0 ? introText : "",
      });
    }
    // Clear the in-memory call state so the user starts fresh after
    // sending. Keep the analysis cached.
    if (state.chezVendorCallsByRequest) delete state.chezVendorCallsByRequest[req.id];
    await loadAdminData();
    await loadChezMessages(req.id);
    const refreshed = state.chezRequests.find((r) => r.id === req.id);
    if (refreshed) state.selectedChezRequest = refreshed;
    renderChezRequestsView();
  } catch (err) {
    console.warn("[admin] package & send failed", err);
    alert(`Send failed: ${err.message || err}`);
  }
}

// Phase 81.1 — Slide-in profile drawer that contains the full
// household dossier. Replaces the inline-flooded version with a
// browse-on-demand pattern.
function openHouseholdProfileDrawer(householdId) {
  document.querySelector("[data-household-profile-drawer]")?.remove();
  const dossier = (state.chezDossiersByHousehold || {})[householdId];
  if (!dossier) {
    alert("Homeowner data still loading. Try again in a moment.");
    return;
  }
  const drawer = document.createElement("div");
  drawer.className = "admin-chez__dossier-drawer admin-chez__dossier-drawer--profile";
  drawer.setAttribute("data-household-profile-drawer", "");
  drawer.innerHTML = `
    <div class="admin-chez__dossier-drawer-backdrop" data-drawer-close></div>
    <aside class="admin-chez__dossier-drawer-panel admin-chez__dossier-drawer-panel--wide">
      <header>
        <div>
          <span class="admin-muted">Homeowner profile</span>
          <h2>${escapeHtml(primaryHomeownerLabel(dossier))}</h2>
        </div>
        <button type="button" data-drawer-close aria-label="Close">×</button>
      </header>
      <div class="admin-chez__dossier-drawer-body">
        ${renderHouseholdDossierHtml(dossier)}
      </div>
    </aside>
  `;
  document.body.appendChild(drawer);
  // Phase 85.5: Esc closes the drawer (audit found Esc only worked for
  // modals, not this drawer — operators had to mouse-hunt for the X).
  const onKey = (e) => {
    if (e.key === "Escape") {
      e.preventDefault();
      document.removeEventListener("keydown", onKey);
      drawer.remove();
    }
  };
  document.addEventListener("keydown", onKey);
  drawer.querySelectorAll("[data-drawer-close]").forEach((b) => b.addEventListener("click", () => {
    document.removeEventListener("keydown", onKey);
    drawer.remove();
  }));
  // Re-bind dossier chips inside the drawer to open the deeper
  // entity drilldown drawer.
  drawer.querySelectorAll("[data-dossier-entity]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const entity = btn.dataset.dossierEntity;
      const id = btn.dataset.dossierId;
      openDossierDrawer(householdId, entity, id);
    });
  });
}

// Phase 81 — Sliding drawer that shows the full record for an entity
// the admin clicked from the dossier. Renders read-only — pure context
// surface so Tom can navigate around without leaving the request.
function openDossierDrawer(householdId, entity, id) {
  document.querySelector("[data-chez-dossier-drawer]")?.remove();
  const dossier = (state.chezDossiersByHousehold || {})[householdId];
  if (!dossier) return;

  let row = null;
  let title = "";
  let bodyHtml = "";

  if (entity === "property") {
    row = (dossier.properties || []).find((p) => p.id === id);
    if (row) {
      title = formatAddress(row);
      bodyHtml = renderEntityKVList([
        ["Type", row.property_type],
        ["Year built", row.year_built],
        ["Square footage", row.square_footage],
        ["Bedrooms", row.bedrooms],
        ["Bathrooms", row.bathrooms],
        ["Lot size", row.lot_size],
        ["Estimated value", row.current_estimated_value ? `$${formatCompact(row.current_estimated_value)}` : null],
        ["Estimated value range", (row.current_estimated_value_low && row.current_estimated_value_high) ? `$${formatCompact(row.current_estimated_value_low)} – $${formatCompact(row.current_estimated_value_high)}` : null],
        ["Purchase price", row.purchase_price ? `$${formatCompact(row.purchase_price)}` : null],
        ["Purchase date", row.purchase_date],
      ]);
    }
  } else if (entity === "home_system") {
    row = (dossier.home_systems || []).find((s) => s.id === id);
    if (row) {
      title = row.name || row.category || "System";

      // Phase 83.5 — Full system mirror. Surface everything the homeowner
      // sees on the iOS Property tab so the operator can answer any
      // question about it without context-switching.

      // Parent + child relationships (Phase 19+ sub-system hierarchy).
      const parent = row.parent_system_id
        ? (dossier.home_systems || []).find((s) => s.id === row.parent_system_id)
        : null;
      const children = (dossier.home_systems || []).filter((s) => s.parent_system_id === row.id);

      // Sibling systems in the same top-level category.
      const siblings = (dossier.home_systems || []).filter((s) =>
        s.id !== row.id && !s.parent_system_id && String(s.category || "").toLowerCase() === String(row.category || "").toLowerCase()
      );

      // Linked vendor (matched by category).
      const matchedVendor = (dossier.contractors || []).find((c) =>
        String(c.category || "").toLowerCase() === String(row.category || "").toLowerCase()
      );

      // Linked tasks (active first, then completed).
      const allTasks = (dossier.tasks || []).filter((t) => t.system_id === id);
      const activeTasks = allTasks.filter((t) => !t.is_archived);
      const completedTasks = allTasks.filter((t) => t.is_archived || t.last_completed_date);

      // Section: identity + parent breadcrumb.
      bodyHtml = "";
      if (parent) {
        bodyHtml += `
          <div class="admin-chez__system-breadcrumb">
            <button type="button" class="cockpit-overview-link" data-dossier-entity="home_system" data-dossier-id="${escapeHtml(parent.id)}">${escapeHtml(parent.name || parent.category)}</button>
            <span class="admin-muted"> → ${escapeHtml(row.name || row.category || "Sub-system")}</span>
          </div>
        `;
      }

      bodyHtml += renderEntityKVList([
        ["Category", row.category],
        ["Subtype", row.subtype],
        ["Manufacturer", row.manufacturer],
        ["Model", row.model],
        ["Serial #", row.serial_number],
        ["Install date", row.install_date ? formatDateOnly(row.install_date) : null],
        ["Last service", row.last_service_date ? formatDateOnly(row.last_service_date) : null],
        ["Service interval", row.service_interval_days ? `${row.service_interval_days} days` : null],
        ["Service vendor (string)", row.service_vendor],
        ["Tank capacity", row.tank_capacity ? `${row.tank_capacity} gal` : null],
        ["Estimated remaining", row.estimated_remaining ? `${row.estimated_remaining} gal` : null],
        ["Filter change interval", row.filter_change_interval_months ? `${row.filter_change_interval_months} months` : null],
        ["Last filter change", row.last_filter_change ? formatDateOnly(row.last_filter_change) : null],
        ["Notes", row.notes],
      ]);

      // Vendor coverage status.
      if (matchedVendor) {
        bodyHtml += `
          <h4>Vendor on file · 1</h4>
          <button type="button" class="admin-chez__dossier-row" data-dossier-entity="contractor" data-dossier-id="${escapeHtml(matchedVendor.id)}">
            <span class="admin-chez__dossier-row-title">${escapeHtml(matchedVendor.company_name)}${matchedVendor.chez_recommended_at ? ` <span class="admin-pill" data-tone="amber">Sourced by Chez</span>` : ""}</span>
            <span class="admin-chez__dossier-row-meta">${escapeHtml(matchedVendor.category || "—")}${matchedVendor.phone ? ` · ${escapeHtml(matchedVendor.phone)}` : ""}</span>
          </button>
        `;
      } else {
        bodyHtml += `<h4>Vendor coverage</h4><p class="admin-muted">No vendor on file for this category. Coverage gap.</p>`;
      }

      // Sub-systems beneath this one.
      if (children.length) {
        bodyHtml += `
          <h4>Sub-systems · ${children.length}</h4>
          ${children.map((c) => `
            <button type="button" class="admin-chez__dossier-row" data-dossier-entity="home_system" data-dossier-id="${escapeHtml(c.id)}">
              <span class="admin-chez__dossier-row-title">${escapeHtml(c.name || c.category)}</span>
              <span class="admin-chez__dossier-row-meta">${escapeHtml(c.subtype || c.category || "—")}</span>
            </button>
          `).join("")}
        `;
      }

      // Sibling systems in same category (peer drilldown).
      if (siblings.length) {
        bodyHtml += `
          <h4>Other ${escapeHtml(row.category || "systems")} systems · ${siblings.length}</h4>
          ${siblings.slice(0, 6).map((s) => `
            <button type="button" class="admin-chez__dossier-row" data-dossier-entity="home_system" data-dossier-id="${escapeHtml(s.id)}">
              <span class="admin-chez__dossier-row-title">${escapeHtml(s.name || s.category)}</span>
              <span class="admin-chez__dossier-row-meta">${escapeHtml(s.subtype || "—")}${s.manufacturer ? ` · ${escapeHtml(s.manufacturer)}` : ""}</span>
            </button>
          `).join("")}
        `;
      }

      // Active tasks for this system.
      if (activeTasks.length) {
        bodyHtml += `
          <h4>Active tasks · ${activeTasks.length}</h4>
          ${activeTasks.slice(0, 6).map((t) => `
            <button type="button" class="admin-chez__dossier-row" data-dossier-entity="task" data-dossier-id="${escapeHtml(t.id)}">
              <span class="admin-chez__dossier-row-title">${escapeHtml(t.title)}</span>
              <span class="admin-chez__dossier-row-meta">${t.next_due_date ? "Due " + escapeHtml(formatDateOnly(t.next_due_date)) : "—"}${t.assignment_type ? ` · ${escapeHtml(t.assignment_type)}` : ""}</span>
            </button>
          `).join("")}
        `;
      }

      // Service history.
      if (completedTasks.length) {
        bodyHtml += `
          <h4>Service history · ${completedTasks.length}</h4>
          ${completedTasks.slice(0, 5).map((t) => `<div>${escapeHtml(t.title)} <span class="admin-muted">— ${t.last_completed_date ? "completed " + escapeHtml(formatDateOnly(t.last_completed_date)) : "archived"}</span></div>`).join("")}
        `;
      }
    }
  } else if (entity === "contractor") {
    row = (dossier.contractors || []).find((c) => c.id === id);
    if (row) {
      title = row.company_name;
      bodyHtml = renderEntityKVList([
        ["Category", row.category],
        ["Specialties", (row.specialties || []).join(", ")],
        ["Contact", row.contact_name],
        ["Phone", row.phone],
        ["Email", row.email],
        ["Address", row.address],
        ["Website", row.website ? `<a href="${escapeHtml(row.website)}" target="_blank">${escapeHtml(row.website)}</a>` : null],
        ["Source", row.source],
        ["Chez owns", row.chez_owned ? "✅ yes" : null],
        ["Notes", row.notes],
      ]);
      const linkedTasks = (dossier.tasks || []).filter((t) => t.assigned_contractor_id === id && !t.is_archived);
      if (linkedTasks.length) {
        bodyHtml += `
          <h4>Active tasks for this vendor · ${linkedTasks.length}</h4>
          ${linkedTasks.slice(0, 8).map((t) => `<div>${escapeHtml(t.title)} — <span class="admin-muted">${escapeHtml(formatDateOnly(t.next_due_date))}</span></div>`).join("")}
        `;
      }
    }
  } else if (entity === "task") {
    row = (dossier.tasks || []).find((t) => t.id === id);
    if (row) {
      title = row.title;
      const sys = (dossier.home_systems || []).find((s) => s.id === row.system_id);
      const con = (dossier.contractors || []).find((c) => c.id === row.assigned_contractor_id);
      bodyHtml = renderEntityKVList([
        ["Description", row.description],
        ["System", sys ? sys.name || sys.category : null],
        ["Vendor", con ? con.company_name : null],
        ["Frequency", row.frequency],
        ["Next due", formatDateOnly(row.next_due_date)],
        ["Last completed", formatDateOnly(row.last_completed_date)],
        ["Priority", row.priority],
        ["Assignment type", row.assignment_type],
        ["Needs vendor", row.needs_vendor ? "yes" : null],
        ["Chez owns", row.chez_owned ? "✅ yes" : null],
        ["Estimated cost", row.estimated_cost ? `$${formatCompact(row.estimated_cost)}` : null],
        ["Notes", row.notes],
      ]);
    }
  } else if (entity === "vehicle") {
    row = (dossier.vehicles || []).find((v) => v.id === id);
    if (row) {
      title = `${row.year || ""} ${row.make || ""} ${row.model || ""}`.trim();
      bodyHtml = renderEntityKVList([
        ["Trim", row.trim],
        ["VIN", row.vin],
        ["License plate", row.license_plate],
        ["Mileage", row.current_mileage],
        ["Color", row.color],
        ["Ownership", row.ownership],
        ["Mechanic", row.preferred_service_shop],
        ["Registration expiry", row.registration_expiry],
        ["Insurance expiry", row.insurance_expiry],
      ]);
    }
  }

  if (!row) {
    console.warn("[admin] dossier drawer: entity not found", entity, id);
    return;
  }

  const drawer = document.createElement("div");
  drawer.className = "admin-chez__dossier-drawer";
  drawer.setAttribute("data-chez-dossier-drawer", "");
  drawer.innerHTML = `
    <div class="admin-chez__dossier-drawer-backdrop" data-drawer-close></div>
    <aside class="admin-chez__dossier-drawer-panel">
      <header>
        <div>
          <span class="admin-muted">${escapeHtml(entity.replace(/_/g, " "))}</span>
          <h2>${escapeHtml(title)}</h2>
        </div>
        <button type="button" data-drawer-close aria-label="Close">×</button>
      </header>
      <div class="admin-chez__dossier-drawer-body">${bodyHtml}</div>
    </aside>
  `;
  document.body.appendChild(drawer);
  drawer.querySelectorAll("[data-drawer-close]").forEach((b) => b.addEventListener("click", () => drawer.remove()));
  // Phase 83.5 — In-drawer drilldown. Clicking a sibling/child system or
  // linked task inside the drawer navigates to that entity without
  // closing the drawer (we close + reopen with the new id).
  drawer.querySelectorAll("[data-dossier-entity]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const newEntity = btn.dataset.dossierEntity;
      const newId = btn.dataset.dossierId;
      drawer.remove();
      openDossierDrawer(householdId, newEntity, newId);
    });
  });
}

function renderEntityKVList(pairs) {
  const lines = pairs
    .filter(([_, v]) => v !== null && v !== undefined && v !== "")
    .map(([k, v]) => `<div class="admin-chez__dossier-drawer-kv"><span>${escapeHtml(k)}</span><strong>${typeof v === "string" && v.startsWith("<a ") ? v : escapeHtml(String(v))}</strong></div>`);
  return lines.length ? lines.join("") : `<p class="admin-muted">No additional details on file.</p>`;
}

// Phase 83.5 — Family-member drilldown drawer. Click a person in the
// homeowner panel to see role + access + their related cases + tasks +
// vehicles. Reuses the dossier slice already loaded server-side.
function openFamilyMemberDrawer(householdId, kind, id) {
  document.querySelector("[data-chez-family-drawer]")?.remove();
  const dossier = (state.chezDossiersByHousehold || {})[householdId];
  if (!dossier) return;

  let person = null;
  let nameLine = "";
  let roleLine = "";
  let identityRows = [];

  if (kind === "user") {
    person = (dossier.users || []).find((u) => u.id === id);
    if (!person) return;
    nameLine = person.full_name || person.email || "—";
    roleLine = `${person.role || "Primary client"} · linked account`;
    identityRows = [
      ["Email", person.email],
      ["Role", person.role],
      ["Account created", person.created_at ? formatDateOnly(person.created_at) : null],
    ];
  } else {
    person = (dossier.family_members || []).find((m) => m.id === id);
    if (!person) return;
    nameLine = `${person.first_name || ""} ${person.last_name || ""}`.trim() || "Family member";
    roleLine = person.relationship || person.member_type || "family";
    identityRows = [
      ["Relationship", person.relationship],
      ["Member type", person.member_type],
      ["Date of birth", person.date_of_birth ? formatDateOnly(person.date_of_birth) : null],
      ["Email", person.email],
      ["Phone", person.phone],
    ];
  }
  const initials = nameLine.split(" ").map((p) => p[0]).join("").slice(0, 2).toUpperCase();

  const personId = kind === "user" ? person.id : (person.linked_user_id || null);
  const personalCases = (dossier.past_requests || []).filter((r) => r.user_id === personId);
  const linkedCases = personalCases.filter((r) => r.id !== state.selectedChezRequest?.id);
  const tasksAssigned = (dossier.tasks || []).filter((t) =>
    !t.is_archived && (t.assigned_to_user_id === personId || (kind === "family_member" && t.assigned_to_family_member_id === id))
  );
  const vehiclesDriven = (dossier.vehicles || []).filter((v) =>
    Array.isArray(v.covered_driver_ids) && v.covered_driver_ids.includes(id)
  );

  const drawer = document.createElement("div");
  drawer.className = "admin-chez__dossier-drawer";
  drawer.setAttribute("data-chez-family-drawer", "");
  drawer.innerHTML = `
    <div class="admin-chez__dossier-drawer-backdrop" data-drawer-close></div>
    <aside class="admin-chez__dossier-drawer-panel">
      <header>
        <div style="display:flex;align-items:center;gap:12px;">
          <span class="cockpit-avatar cockpit-avatar--lg ${kind === "user" ? "cockpit-avatar--indigo" : "cockpit-avatar--soft"}">${escapeHtml(initials)}</span>
          <div>
            <span class="admin-muted">${escapeHtml(kind === "user" ? "Linked account" : "Family member")}</span>
            <h2 style="margin:0;">${escapeHtml(nameLine)}</h2>
            <span class="admin-muted">${escapeHtml(roleLine)}</span>
          </div>
        </div>
        <button type="button" data-drawer-close aria-label="Close">×</button>
      </header>
      <div class="admin-chez__dossier-drawer-body">
        ${renderEntityKVList(identityRows)}

        <h4>Related cases · ${linkedCases.length}</h4>
        ${linkedCases.length === 0
          ? `<p class="admin-muted">No prior cases tied to this person.</p>`
          : linkedCases.slice(0, 8).map((r) => `
              <button type="button" class="admin-chez__dossier-row" data-family-case-id="${escapeHtml(r.id)}">
                <span class="admin-chez__dossier-row-title">${escapeHtml(r.summary || "(no summary)")}</span>
                <span class="admin-chez__dossier-row-meta">
                  ${escapeHtml(CHEZ_CATEGORY_LABELS[r.category] || r.category || "—")}
                  · ${escapeHtml(CHEZ_STATUS_LABELS[r.status] || r.status || "—")}
                  · ${escapeHtml(r.created_at ? formatDateOnly(r.created_at) : "")}
                </span>
              </button>
            `).join("")}

        <h4>Tasks assigned · ${tasksAssigned.length}</h4>
        ${tasksAssigned.length === 0
          ? `<p class="admin-muted">No tasks currently assigned to this person.</p>`
          : tasksAssigned.slice(0, 6).map((t) => `
              <div>${escapeHtml(t.title)} <span class="admin-muted">${escapeHtml(t.next_due_date ? "· due " + formatDateOnly(t.next_due_date) : "")}</span></div>
            `).join("")}

        ${vehiclesDriven.length > 0 ? `
          <h4>Vehicles · ${vehiclesDriven.length}</h4>
          ${vehiclesDriven.map((v) => `<div>${escapeHtml(((v.year ? v.year + " " : "") + (v.make || "") + " " + (v.model || "")).trim())}</div>`).join("")}
        ` : ""}
      </div>
    </aside>
  `;
  document.body.appendChild(drawer);
  drawer.querySelectorAll("[data-drawer-close]").forEach((b) => b.addEventListener("click", () => drawer.remove()));
  drawer.querySelectorAll("[data-family-case-id]").forEach((b) => {
    b.addEventListener("click", async () => {
      const caseId = b.dataset.familyCaseId;
      drawer.remove();
      const found = (state.chezRequests || []).find((r) => r.id === caseId);
      if (!found) {
        alert("That case isn't loaded in the queue. Refresh and try again.");
        return;
      }
      state.selectedChezRequest = found;
      state.concierge.queueMode = "case";
      await loadChezMessages(caseId);
      renderConciergeCockpit();
    });
  });
}

// Phase 83.5 — Stage-click navigation.
function scrollWorkspaceToStage(stage) {
  const host = el.conciergeHost;
  if (!host) return;
  let target = null;
  if (stage === "submitted") target = host.querySelector(".cockpit-case-header");
  else if (stage === "research") target = host.querySelector(".cockpit-brief");
  else if (stage === "sent" || stage === "picked") {
    target = host.querySelector(".cockpit-chatpanel__thread") || host.querySelector(".cockpit-conversation");
  } else if (stage === "booked" || stage === "visit") {
    target = host.querySelector(".admin-chez__visits");
  } else if (stage === "done") {
    target = host.querySelector(".cockpit-case-header");
  }
  if (target) {
    target.scrollIntoView({ behavior: "smooth", block: "center" });
    target.classList.add("is-pulsing");
    setTimeout(() => target.classList.remove("is-pulsing"), 1500);
  }
}

async function performChezTransition(req, toStatus) {
  try {
    await callChezConcierge({
      action: "transition_status",
      request_id: req.id,
      to_status: toStatus,
    });
    await loadAdminData();
    await loadChezMessages(req.id);
    const refreshed = state.chezRequests.find((r) => r.id === req.id);
    if (refreshed) state.selectedChezRequest = refreshed;
    renderChezRequestsView();
  } catch (err) {
    console.error("[admin] chez transition failed", err);
    alert(`Couldn't update status: ${err.message || err}`);
  }
}

/// Wraps the chez-concierge Edge Function. Reuses the existing
/// supabase auth context — admin email is allowlisted server-side.
async function callChezConcierge(body) {
  const session = (await supabase.auth.getSession()).data.session;
  if (!session) throw new Error("Not signed in");
  const url = `${SUPABASE_URL}/functions/v1/chez-concierge`;
  const resp = await fetch(url, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "apikey": SUPABASE_ANON_KEY,
      "Authorization": `Bearer ${session.access_token}`,
    },
    body: JSON.stringify(body),
  });
  if (!resp.ok) {
    const text = await resp.text();
    let message = `Request failed (${resp.status})`;
    try {
      const json = JSON.parse(text);
      if (json.error) message = json.error;
    } catch {
      if (text) message = text.slice(0, 200);
    }
    throw new Error(message);
  }
  return resp.json();
}

// =============================================================================
// Phase 72.5 — Vendor application review desk
// =============================================================================
//
// In-portal version of the standalone admin-vendors.html surface. Lists
// every vendor_applications row (status filter chips), shows the lifecycle
// at a glance, and lets Tom resend confirmation emails / certify / reject
// without leaving the cockpit. Backed by the admin-vendor-applications
// edge function — same one the standalone page uses, gated on
// CHEZ_ADMIN_EMAILS.

const VENDOR_APP_STATUS_LABELS = {
  pending_email_confirm: "Pending email",
  live_unverified: "Live · review me",
  chez_certified: "Chez Certified",
  rejected: "Rejected",
};

const VENDOR_APP_FILTER_CHIPS = [
  { id: "all", label: "All" },
  { id: "pending_email_confirm", label: "Pending email" },
  { id: "live_unverified", label: "Live · review me" },
  { id: "chez_certified", label: "Certified" },
  { id: "rejected", label: "Rejected" },
];

async function callAdminVendorApplications(action, payload = {}) {
  const session = (await supabase.auth.getSession()).data.session;
  if (!session) throw new Error("Not signed in");
  const url = `${SUPABASE_URL}/functions/v1/admin-vendor-applications`;
  const resp = await fetch(url, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "apikey": SUPABASE_ANON_KEY,
      "Authorization": `Bearer ${session.access_token}`,
    },
    body: JSON.stringify({ action, ...payload }),
  });
  if (!resp.ok) {
    const text = await resp.text();
    let message = `Request failed (${resp.status})`;
    try {
      const json = JSON.parse(text);
      if (json.error) message = json.error;
    } catch {
      if (text) message = text.slice(0, 200);
    }
    throw new Error(message);
  }
  return resp.json();
}

function renderVendorApplicationsView() {
  const va = state.vendorApps;

  // Hide legacy detail/empty-detail — this is a flat queue, no drill-down
  el.detail?.classList.add("is-hidden");
  el.emptyDetail?.classList.add("is-hidden");
  // Hide the legacy admin-status-filter <select> — chips replace it
  el.statusFilter?.classList.add("is-hidden");
  el.search.value = state.search || "";
  el.search.placeholder = "Search business, contact, email, phone…";

  // Per-status counts come from the cached list
  const counts = {
    all: va.applications.length,
    pending_email_confirm: 0,
    live_unverified: 0,
    chez_certified: 0,
    rejected: 0,
  };
  va.applications.forEach((a) => {
    if (counts[a.status] !== undefined) counts[a.status] += 1;
  });

  el.stats.innerHTML = `
    <div class="admin-stats__tiles">
      <div class="admin-stat"><strong>${counts.pending_email_confirm}</strong><span>Awaiting email confirm</span></div>
      <div class="admin-stat"><strong>${counts.live_unverified}</strong><span>Live · ready to review</span></div>
      <div class="admin-stat"><strong>${counts.chez_certified}</strong><span>Chez Certified</span></div>
      <div class="admin-stat"><strong>${counts.rejected}</strong><span>Rejected</span></div>
    </div>
  `;

  el.list.innerHTML = `
    <div class="admin-vendor-apps">
      <div class="admin-vendor-apps__toolbar">
        <div class="admin-vendor-apps__chips" role="tablist">
          ${VENDOR_APP_FILTER_CHIPS.map((chip) => `
            <button type="button"
                    class="admin-vendor-apps__chip ${va.filter === chip.id ? "is-active" : ""}"
                    data-vapps-filter="${chip.id}"
                    role="tab">
              ${escapeHtml(chip.label)}
            </button>
          `).join("")}
        </div>
        <button type="button" class="admin-button admin-button--ghost" data-vapps-refresh>↻ Refresh</button>
      </div>
      <div class="admin-vendor-apps__feedback" data-vapps-feedback hidden></div>
      <div class="admin-vendor-apps__rows" data-vapps-rows>
        ${va.loading ? `<p class="admin-vendor-apps__empty admin-muted">Loading vendor applications…</p>` : ""}
        ${va.error ? `<p class="admin-vendor-apps__empty admin-vendor-apps__empty--error">Error: ${escapeHtml(va.error)}</p>` : ""}
      </div>
    </div>
  `;

  el.list.querySelectorAll("[data-vapps-filter]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const next = btn.dataset.vappsFilter;
      if (va.filter === next) return;
      va.filter = next;
      loadVendorApplications();
    });
  });

  el.list.querySelector("[data-vapps-refresh]")?.addEventListener("click", () => {
    loadVendorApplications();
  });

  const rowsEl = el.list.querySelector("[data-vapps-rows]");
  rowsEl?.addEventListener("click", handleVendorAppAction);

  // Initial load if cache is empty, otherwise just paint
  if (va.applications.length === 0 && !va.loading && !va.error) {
    loadVendorApplications();
  } else {
    renderVendorAppRows();
  }
}

async function loadVendorApplications() {
  const va = state.vendorApps;
  va.loading = true;
  va.error = null;
  if (state.view === "vendor_apps") renderVendorApplicationsView();
  try {
    const payload = va.filter === "all" ? {} : { status_filter: va.filter };
    const data = await callAdminVendorApplications("list", { ...payload, limit: 200 });
    va.applications = data.applications || [];
    va.total = data.total || 0;
  } catch (err) {
    console.error("[vendor-apps] list failed:", err);
    va.error = err.message || String(err);
    va.applications = [];
  } finally {
    va.loading = false;
    if (state.view === "vendor_apps") renderVendorApplicationsView();
  }
}

function renderVendorAppRows() {
  const va = state.vendorApps;
  const rowsEl = el.list.querySelector("[data-vapps-rows]");
  if (!rowsEl) return;

  // Client-side search across the loaded set
  const q = (state.search || "").trim().toLowerCase();
  const searched = q
    ? va.applications.filter((a) => {
        const hay = [
          a.business_name,
          a.contact_name,
          a.email,
          a.phone,
          a.category,
          (a.service_area_states || []).join(" "),
        ].join(" ").toLowerCase();
        return hay.includes(q);
      })
    : va.applications;

  // Phase 72.5: prioritize action-needed rows + most-complete profiles.
  // Status priority — live_unverified first (the queue Tom calls), then
  // pending email confirm (waiting on vendor), then certified (already
  // done), then rejected (archive). Within each tier, higher
  // profile_completion_pct floats up so the most-cookable leads are at
  // the top. The chip filters narrow further; this is the order inside
  // whatever's selected.
  const STATUS_ORDER = {
    live_unverified: 0,
    pending_email_confirm: 1,
    chez_certified: 2,
    rejected: 3,
  };
  const filtered = searched.slice().sort((a, b) => {
    const sa = STATUS_ORDER[a.status] ?? 99;
    const sb = STATUS_ORDER[b.status] ?? 99;
    if (sa !== sb) return sa - sb;
    const pa = typeof a.profile_completion_pct === "number" ? a.profile_completion_pct : 0;
    const pb = typeof b.profile_completion_pct === "number" ? b.profile_completion_pct : 0;
    if (pa !== pb) return pb - pa;
    // Tiebreak: newer first
    return new Date(b.created_at).getTime() - new Date(a.created_at).getTime();
  });

  if (filtered.length === 0) {
    rowsEl.innerHTML = `
      <p class="admin-vendor-apps__empty admin-muted">
        ${va.applications.length === 0
          ? "No vendor applications match this filter yet. Tell a few vendors about getchez.com/vendor-apply.html and they'll show up here."
          : "No applications match your search."}
      </p>
    `;
    return;
  }

  rowsEl.innerHTML = filtered.map((app) => {
    const buttons = vendorAppActionButtons(app);
    const states = (app.service_area_states || []).join(", ");
    const websiteHref = app.website && /^https?:\/\//i.test(app.website)
      ? app.website
      : (app.website ? `https://${app.website}` : "");
    return `
      <article class="admin-vendor-apps__row" data-vapps-row="${escapeHtml(app.id)}">
        <header class="admin-vendor-apps__row-head">
          <div class="admin-vendor-apps__row-title">
            <strong>${escapeHtml(app.business_name)}</strong>
            ${websiteHref ? `<a href="${escapeHtml(websiteHref)}" target="_blank" rel="noopener" class="admin-vendor-apps__row-website">${escapeHtml(app.website.replace(/^https?:\/\//, ""))} ↗</a>` : ""}
          </div>
          <div class="admin-vendor-apps__row-pills">
            ${vendorAppCompletionPill(app.profile_completion_pct)}
            ${vendorAppStatusPill(app.status)}
          </div>
        </header>
        <div class="admin-vendor-apps__row-grid">
          <div class="admin-vendor-apps__row-cell">
            <span class="admin-vendor-apps__row-label">Contact</span>
            <span>${escapeHtml(app.contact_name)}</span>
            <a href="mailto:${escapeHtml(app.email)}" class="admin-muted">${escapeHtml(app.email)}</a>
            <a href="tel:${escapeHtml(app.phone)}" class="admin-muted">${escapeHtml(app.phone)}</a>
          </div>
          <div class="admin-vendor-apps__row-cell">
            <span class="admin-vendor-apps__row-label">Category</span>
            <span>${escapeHtml(app.category)}</span>
          </div>
          <div class="admin-vendor-apps__row-cell">
            <span class="admin-vendor-apps__row-label">States</span>
            <span class="admin-vendor-apps__row-states">${escapeHtml(states || "—")}</span>
          </div>
          <div class="admin-vendor-apps__row-cell">
            <span class="admin-vendor-apps__row-label">Submitted</span>
            <span>${escapeHtml(formatDateTime(app.created_at))}</span>
            ${app.email_confirmed_at ? `<span class="admin-muted">Confirmed ${escapeHtml(formatDateTime(app.email_confirmed_at))}</span>` : ""}
            ${app.verified_at ? `<span class="admin-muted">Certified ${escapeHtml(formatDateTime(app.verified_at))}</span>` : ""}
            ${app.rejected_at ? `<span class="admin-muted">Rejected ${escapeHtml(formatDateTime(app.rejected_at))}</span>` : ""}
          </div>
        </div>
        ${app.verified_notes ? `<p class="admin-vendor-apps__row-note"><strong>Notes:</strong> ${escapeHtml(app.verified_notes)}</p>` : ""}
        ${app.rejection_notes ? `<p class="admin-vendor-apps__row-note admin-vendor-apps__row-note--reject"><strong>Reason:</strong> ${escapeHtml(app.rejection_notes)}</p>` : ""}
        ${app.linked_google_place_id ? `<p class="admin-vendor-apps__row-meta admin-muted">↪ Linked to Google Place ${escapeHtml(app.linked_google_place_id)}</p>` : ""}
        ${buttons ? `<div class="admin-vendor-apps__row-actions">${buttons}</div>` : ""}
      </article>
    `;
  }).join("");
}

function vendorAppStatusPill(status) {
  const label = VENDOR_APP_STATUS_LABELS[status] || status;
  return `<span class="admin-pill admin-vendor-apps__status admin-vendor-apps__status--${escapeHtml(status)}">${escapeHtml(label)}</span>`;
}

// Phase 72.5: completion pill — shows how filled-in the vendor's profile is.
// Tone tracks completeness so Tom can scan the queue and pick the most-
// cookable leads to call first.
//   ≥80%  success (green) — rich profile, ready for the certify call
//   ≥40%  indigo         — a real attempt, getting there
//   else   warning (amber) — bare-bones, may need a nudge or be a ghost
function vendorAppCompletionPill(pct) {
  const value = typeof pct === "number" ? pct : null;
  if (value === null) return "";
  let tone = "warning";
  if (value >= 80) tone = "success";
  else if (value >= 40) tone = "indigo";
  return `<span class="admin-pill admin-vendor-apps__completion admin-vendor-apps__completion--${tone}" title="Profile completion">${value}% profile</span>`;
}

function vendorAppActionButtons(app) {
  const buttons = [];
  if (app.status === "pending_email_confirm") {
    buttons.push(`<button type="button" class="admin-button admin-button--ghost" data-vapps-action="resend_confirm" data-vapps-id="${escapeHtml(app.id)}" data-vapps-name="${escapeHtml(app.business_name)}">Resend email</button>`);
  }
  if (app.status === "live_unverified") {
    buttons.push(`<button type="button" class="admin-button admin-button--primary" data-vapps-action="mark_certified" data-vapps-id="${escapeHtml(app.id)}" data-vapps-name="${escapeHtml(app.business_name)}">Certify</button>`);
  }
  if (app.status === "chez_certified") {
    buttons.push(`<button type="button" class="admin-button admin-button--danger" data-vapps-action="mark_rejected" data-vapps-id="${escapeHtml(app.id)}" data-vapps-name="${escapeHtml(app.business_name)}">Revoke certification</button>`);
  }
  if (app.status !== "rejected" && app.status !== "chez_certified") {
    buttons.push(`<button type="button" class="admin-button admin-button--danger" data-vapps-action="mark_rejected" data-vapps-id="${escapeHtml(app.id)}" data-vapps-name="${escapeHtml(app.business_name)}">Reject</button>`);
  }
  return buttons.join("");
}

async function handleVendorAppAction(e) {
  const btn = e.target.closest("button[data-vapps-action]");
  if (!btn) return;
  const action = btn.dataset.vappsAction;
  const applicationId = btn.dataset.vappsId;
  const businessName = btn.dataset.vappsName || "this application";

  if (action === "resend_confirm") {
    btn.disabled = true;
    const original = btn.textContent;
    btn.textContent = "Sending…";
    try {
      await callAdminVendorApplications("resend_confirm", { application_id: applicationId });
      showVendorAppFeedback(`Confirmation email re-sent to ${businessName}.`, "success");
      await loadVendorApplications();
    } catch (err) {
      showVendorAppFeedback(`Resend failed: ${err.message}`, "error");
      btn.disabled = false;
      btn.textContent = original;
    }
    return;
  }

  if (action === "mark_certified" || action === "mark_rejected") {
    openVendorAppNotesModal({ action, applicationId, businessName });
  }
}

function showVendorAppFeedback(message, kind) {
  const fb = el.list.querySelector("[data-vapps-feedback]");
  if (!fb) return;
  fb.textContent = message;
  fb.dataset.kind = kind;
  fb.hidden = false;
  clearTimeout(showVendorAppFeedback._t);
  showVendorAppFeedback._t = setTimeout(() => { fb.hidden = true; }, 4000);
}

function openVendorAppNotesModal({ action, applicationId, businessName }) {
  document.querySelector("[data-vapps-modal]")?.remove();

  const isCertify = action === "mark_certified";
  const modal = document.createElement("div");
  modal.className = "admin-modal";
  modal.setAttribute("data-vapps-modal", "");
  modal.innerHTML = `
    <div class="admin-modal__backdrop" data-vapps-modal-close></div>
    <div class="admin-modal__panel">
      <header class="admin-modal__head">
        <div>
          <h2>${isCertify ? "Mark Chez Certified" : "Reject application"}</h2>
          <p class="admin-muted">${escapeHtml(businessName)}</p>
        </div>
        <button type="button" class="admin-modal__close" data-vapps-modal-close aria-label="Close">×</button>
      </header>
      <div class="admin-modal__body">
        <p class="admin-muted">
          ${isCertify
            ? "Vendor will appear at the top of homeowner search results with the Chez Certified badge. They'll get a confirmation email."
            : "Vendor will be removed from search results. No email is sent. They can re-apply with the same email after rejection."}
        </p>
        <label class="admin-vendor-apps__modal-label">
          <span>${isCertify ? "Verification notes (optional, internal)" : "Rejection notes (optional, internal)"}</span>
          <textarea data-vapps-modal-notes rows="4" placeholder="${isCertify ? 'e.g. Spoke with Joe, 15 yrs experience, COI on file' : 'e.g. Could not reach, business no longer operating'}"></textarea>
        </label>
      </div>
      <footer class="admin-modal__foot">
        <button type="button" class="admin-button" data-vapps-modal-close>Cancel</button>
        <button type="button" class="admin-button ${isCertify ? "admin-button--primary" : "admin-button--danger"}" data-vapps-modal-confirm>
          ${isCertify ? "Certify" : "Reject"}
        </button>
      </footer>
    </div>
  `;
  document.body.appendChild(modal);

  const close = () => modal.remove();
  modal.querySelectorAll("[data-vapps-modal-close]").forEach((btn) => {
    btn.addEventListener("click", close);
  });

  modal.querySelector("[data-vapps-modal-confirm]").addEventListener("click", async (e) => {
    const confirmBtn = e.currentTarget;
    const notesEl = modal.querySelector("[data-vapps-modal-notes]");
    confirmBtn.disabled = true;
    const original = confirmBtn.textContent;
    confirmBtn.textContent = "Working…";
    try {
      await callAdminVendorApplications(action, {
        application_id: applicationId,
        notes: notesEl?.value.trim() || null,
      });
      close();
      showVendorAppFeedback(
        isCertify
          ? `${businessName} marked Chez Certified.`
          : `${businessName} rejected.`,
        "success",
      );
      await loadVendorApplications();
    } catch (err) {
      confirmBtn.disabled = false;
      confirmBtn.textContent = original;
      let errEl = modal.querySelector("[data-vapps-modal-error]");
      if (!errEl) {
        errEl = document.createElement("p");
        errEl.dataset.vappsModalError = "";
        errEl.className = "admin-vendor-apps__modal-error";
        modal.querySelector(".admin-modal__body").appendChild(errEl);
      }
      errEl.textContent = err.message || String(err);
    }
  });

  setTimeout(() => modal.querySelector("[data-vapps-modal-notes]")?.focus(), 50);
}

function formatDateTime(iso) {
  if (!iso) return "";
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return iso;
  return d.toLocaleString(undefined, {
    month: "short",
    day: "numeric",
    hour: "numeric",
    minute: "2-digit",
  });
}

// Phase 5z+19 — Focused audit panel renderer. Same shape as the
// focused decision panel: header, recommendation card (salmon, leads),
// "what we're looking at" context, "what happens if you act" bullets,
// then the action buttons with the recommended option leftmost.
function renderFocusedAuditDetail(finding) {
  if (!finding) return;
  el.emptyDetail.classList.add("is-hidden");
  el.detail.classList.remove("is-hidden");

  // Hide every other detail-pane mode.
  el.detailTabs?.classList.add("is-hidden");
  el.curatedForm?.classList.add("is-hidden");
  if (el.formHost) el.formHost.innerHTML = "";
  if (el.diffHost) el.diffHost.innerHTML = "";
  document.querySelector("[data-detail-quick-actions]")?.classList.add("is-hidden");
  el.noteFocused?.classList.add("is-hidden");
  el.decisionFocused?.classList.add("is-hidden");
  // Phase 5z+20 — hide the legacy detail-actions row + notes-box so
  // the focused panel content reads cleanly. Each focused panel
  // includes its own "Note for Claude" form at the bottom.
  el.detailActionsRow?.classList.add("is-hidden");
  el.notesBox?.classList.add("is-hidden");
  el.promoteItem.disabled = true;
  el.duplicateItem.disabled = true;
  el.deleteItem.disabled = true;
  el.saveItem.textContent = "Save";
  el.saveItem.disabled = true;

  // Header.
  const kindLabel = {
    task_no_vendor: "Task without a vendor",
    quiz_adrift: "Quiz question adrift",
    vendor_no_tasks: "Vendor with no tasks",
    missing_vendor: "Missing vendor type",
    missing_routine: "Missing routine",
  }[finding.kind] || "Audit finding";
  const tone = ["missing_vendor", "missing_routine"].includes(finding.kind) ? "reshape" : "draft";
  el.detailKind.textContent = kindLabel.toLowerCase();
  el.detailTitle.textContent = finding.title;
  el.detailSubtitle.textContent = finding.subtitle || "";
  el.detailStatus.textContent = kindLabel;
  el.detailStatus.dataset.tone = tone;

  el.auditFocused?.classList.remove("is-hidden");
  if (el.auditFocused) {
    el.auditFocused.innerHTML = renderFocusedAuditPanelHtml(finding);
    attachFocusedAuditHandlers(finding);
  }
}

// Phase 5z+20 — Shared "Note for Claude" form rendered at the BOTTOM
// of every focused panel (decision + audit). Tom: "have claudes
// recommendations go above the note for claude section. I should be
// able to understand what was identified easily first, the problem is
// presents, what claudes fix suggestions will do, and then see what
// actions to take. the notes for claude should be below that"
//
// The reading order is now: identification → recommendation →
// alternatives → actions → custom note.
function focusedNoteFormHtml() {
  return `
    <div class="admin-decision-focused__section admin-decision-focused__section--notes">
      <div class="admin-decision-focused__section-head">
        <h4>Note for Claude</h4>
        <span class="admin-muted admin-decision-focused__action-hint">Optional. Add context, ask a question, or document a decision.</span>
      </div>
      <form class="admin-focused-note-form" data-focused-note-form>
        <textarea data-focused-note-body rows="3" placeholder="What's on your mind about this? (optional)"></textarea>
        <div class="admin-focused-note-form__row">
          <label class="admin-focused-note-form__field">
            <span>Intent</span>
            <select data-focused-note-intent>
              <option value="feedback">Feedback (just remember)</option>
              <option value="change_request">Change request (apply next session)</option>
              <option value="proposal_add">Proposal: add new entity</option>
              <option value="proposal_delete">Proposal: cut this entity</option>
              <option value="bug">Bug</option>
              <option value="idea">Idea (explore later)</option>
              <option value="question_for_claude">Question for Claude (answer first)</option>
            </select>
          </label>
          <button type="submit" class="admin-button admin-button--primary admin-button--small" data-focused-note-save>Save note</button>
        </div>
      </form>
    </div>
  `;
}

// Phase 5z+20 — Wire a focused-panel note form to writeNote. Caller
// passes a scopeBuilder() callback that returns the scope object
// (scopeType, scopeId, scopeTitle, snapshot) at submit time so the
// scope reflects the current decision/audit context.
function attachFocusedNoteFormHandler(root, scopeBuilder) {
  const form = root?.querySelector("[data-focused-note-form]");
  if (!form) return;
  form.addEventListener("submit", async (event) => {
    event.preventDefault();
    const body = form.querySelector("[data-focused-note-body]")?.value?.trim() || "";
    const intent = form.querySelector("[data-focused-note-intent]")?.value || "feedback";
    if (!body) {
      alert("Note can't be empty.");
      return;
    }
    const scope = (typeof scopeBuilder === "function" ? scopeBuilder() : null) || {};
    await writeNote({
      scopeType: scope.scopeType || "general",
      scopeId: scope.scopeId || null,
      scopeTitle: scope.scopeTitle || "Focused-panel note",
      body,
      intent,
      target: "claude",
      snapshot: scope.snapshot || {},
    });
    // Clear the form so the user can write another if they want.
    form.querySelector("[data-focused-note-body]").value = "";
    form.querySelector("[data-focused-note-intent]").value = "feedback";
    alert("Note saved. Open the Notes tab to see it.");
  });
}

function renderFocusedAuditPanelHtml(finding) {
  // Each kind has its own recommendation + action set + context body.
  // Recommended action is always FIRST (primary salmon button).
  const r = auditRecommendationFor(finding);
  return `
    <section class="admin-decision-focused__body">
      <div class="admin-decision-focused__section admin-decision-focused__section--rec">
        <div class="admin-decision-focused__section-head">
          <h4>Claude's recommendation</h4>
        </div>
        <p class="admin-decision-focused__rec">${escapeHtml(r.recommendation)}</p>
      </div>

      <div class="admin-decision-focused__section">
        <div class="admin-decision-focused__section-head">
          <h4>What we're looking at</h4>
        </div>
        ${r.contextHtml}
      </div>

      <div class="admin-decision-focused__section">
        <div class="admin-decision-focused__section-head">
          <h4>What happens if you act</h4>
        </div>
        <div class="admin-decision-focused__what">
          <ul>${r.whatHappens.map((s) => `<li>${s}</li>`).join("")}</ul>
        </div>
      </div>

      <div class="admin-decision-focused__section admin-decision-focused__section--actions">
        <div class="admin-decision-focused__section-head">
          <h4>Choose one</h4>
          <span class="admin-muted admin-decision-focused__action-hint">Recommended action is on the left.</span>
        </div>
        <div class="admin-decision-focused__actions">
          ${r.actions.map((a) => `
            <button type="button" class="admin-button ${a.primary ? "admin-button--primary" : a.danger ? "admin-button--ghost admin-button--danger" : "admin-button--secondary"} admin-button--small" data-audit-fa="${escapeHtml(a.id)}">${escapeHtml(a.label)}</button>
          `).join("")}
        </div>
      </div>

      ${focusedNoteFormHtml()}
    </section>
  `;
}

// Phase 5z+20 — Per-kind scope builder for the focused audit panel's
// note form. Returns the scope object writeNote expects.
function buildAuditNoteScope(finding) {
  if (!finding) return { scopeType: "general", scopeId: null, scopeTitle: "Audit note" };
  const data = finding.data || {};
  if (finding.kind === "task_no_vendor") {
    return {
      scopeType: "task",
      scopeId: data.templateKey,
      scopeTitle: data.title || finding.title,
      snapshot: { source: "audit_focused_panel", finding: finding.kind, category: data.category },
    };
  }
  if (finding.kind === "quiz_adrift") {
    return {
      scopeType: "question",
      scopeId: data.questionId,
      scopeTitle: data.title || data.questionId,
      snapshot: { source: "audit_focused_panel", finding: finding.kind },
    };
  }
  if (finding.kind === "vendor_no_tasks") {
    return {
      scopeType: "vendor",
      scopeId: data.vendor,
      scopeTitle: data.vendor,
      snapshot: { source: "audit_focused_panel", finding: finding.kind },
    };
  }
  if (finding.kind === "voice_fix" || finding.kind === "needs_review") {
    const item = data.targetItem || {};
    return {
      scopeType: item.itemType,
      scopeId: liveEntityIdFor(item),
      scopeTitle: item.title || finding.title,
      snapshot: { source: "audit_focused_panel", finding: finding.kind, payload: item.payload },
    };
  }
  // missing_vendor / missing_routine — general scope.
  return {
    scopeType: "general",
    scopeId: null,
    scopeTitle: `Audit: ${finding.title}`,
    snapshot: { source: "audit_focused_panel", finding: finding.kind, name: data.name, role: data.role },
  };
}

function attachFocusedAuditHandlers(finding) {
  // Phase 5z+20 — wire the bottom-of-panel note form. Scope depends
  // on the finding kind: scoped-entity findings (task/quiz/vendor)
  // attach to the relevant scope; missing-vendor / missing-routine
  // are general (no entity yet).
  attachFocusedNoteFormHandler(el.auditFocused, () => buildAuditNoteScope(finding));
  el.auditFocused?.querySelectorAll("[data-audit-fa]").forEach((btn) => {
    btn.addEventListener("click", async () => {
      await handleFocusedAuditAction(finding, btn.dataset.auditFa);
    });
  });
}

// Phase 5z+19 — Per-kind recommendation builder. Returns:
//   {
//     recommendation: string,        // headline for the salmon card
//     contextHtml: string,           // "what we're looking at" body
//     whatHappens: string[],         // bullets — strings can carry inline HTML
//     actions: { id, label, primary?, danger? }[]
//   }
function auditRecommendationFor(finding) {
  if (finding.kind === "task_no_vendor") {
    const t = finding.data;
    // Use the value analysis to figure out whether to lean toward
    // "cut" (low value) or "remap to existing vendor" (high value).
    const item = (state.liveData["templates"]?.entries || []).find((x) => x.templateKey === t.templateKey);
    const valueItem = item ? { title: item.title, payload: item, description: item.description } : null;
    const value = valueItem ? valueAnalysisFor(valueItem) : null;
    const isLowValue = value?.tier === "low";
    const recommendation = isLowValue
      ? `Low-value task in a category we don't cover with a vendor. Cut the task — it's not pulling its weight, and adding a brand-new vendor type just to support it is overkill.`
      : `This task is real work but the catalog has no vendor who can take it. Easiest fix: remap "${t.category}" to an existing vendor type that already does similar work. If that's a stretch, propose adding a new vendor type.`;
    return {
      recommendation,
      contextHtml: `
        <div class="admin-audit-focused__context">
          <p><strong>Task:</strong> ${escapeHtml(t.title)}</p>
          <p><strong>Category:</strong> <code>${escapeHtml(t.category)}</code></p>
          <p class="admin-muted">${escapeHtml(t.reason)}</p>
        </div>
      `,
      whatHappens: isLowValue
        ? [
            `<strong>Cut the task</strong> writes a proposal_delete note. Claude removes the template on the next code session.`,
            `<strong>Remap to a vendor</strong> drafts a note asking Claude to point ${escapeHtml(t.category)} at one of the 15 existing vendor categories.`,
            `<strong>Propose adding a vendor</strong> drafts a "we need a vendor for ${escapeHtml(t.category)}" note. Heavier lift than a remap.`,
            `<strong>Open template</strong> jumps to the Tasks tab so you can read the full template + edit fields.`,
          ]
        : [
            `<strong>Remap to a vendor</strong> drafts a note pointing this category at an existing vendor type. Quickest fix — no new entries to add.`,
            `<strong>Propose adding a vendor</strong> drafts a proposal note for a brand-new vendor type. Right call when "${escapeHtml(t.category)}" is genuinely a different trade.`,
            `<strong>Cut the task</strong> writes a proposal_delete note if you decide it's not worth carrying.`,
            `<strong>Open template</strong> jumps to the Tasks tab so you can read the full template + edit fields.`,
          ],
      actions: isLowValue
        ? [
            { id: "task-cut", label: "Cut the task", primary: true, danger: true },
            { id: "task-remap", label: "Remap to existing vendor" },
            { id: "task-new-vendor", label: "Propose new vendor type" },
            { id: "task-open", label: "Open template" },
          ]
        : [
            { id: "task-remap", label: "Remap to existing vendor", primary: true },
            { id: "task-new-vendor", label: "Propose new vendor type" },
            { id: "task-open", label: "Open template" },
            { id: "task-cut", label: "Cut the task", danger: true },
          ],
    };
  }
  if (finding.kind === "quiz_adrift") {
    const q = finding.data;
    return {
      recommendation: `Heads up: this might be a false positive. The audit can't see wiring that lives in HouseQuizAnswerMapper.swift (system-creation rules, contractor-mirror logic). Open the question first to confirm — if it really doesn't drive anything, propose cutting it.`,
      contextHtml: `
        <div class="admin-audit-focused__context">
          <p><strong>Question:</strong> ${escapeHtml(q.title || q.questionId)}</p>
          <p><strong>ID:</strong> <code>${escapeHtml(q.questionId)}</code></p>
          ${q.kind ? `<p><strong>Kind:</strong> ${escapeHtml(q.kind)}</p>` : ""}
          ${q.chapter ? `<p><strong>Chapter:</strong> ${escapeHtml(q.chapter)}</p>` : ""}
          <p class="admin-muted">${escapeHtml(q.reason)}</p>
        </div>
      `,
      whatHappens: [
        `<strong>Open question</strong> jumps to the Quiz tab. The "Here is what this question does for the app" lead at the top of the detail panel will tell you whether it really is unwired or whether the audit missed something.`,
        `<strong>Document its wiring</strong> writes a feedback note explaining what the question DOES drive — useful when the audit's heuristic is missing real wiring. Helps the next session.`,
        `<strong>Propose cutting it</strong> drafts a proposal_delete note. Use this only after you've confirmed the question really is dead.`,
      ],
      actions: [
        { id: "quiz-open", label: "Open question", primary: true },
        { id: "quiz-document", label: "Document its wiring" },
        { id: "quiz-cut", label: "Propose cutting it", danger: true },
      ],
    };
  }
  if (finding.kind === "vendor_no_tasks") {
    const v = finding.data;
    return {
      recommendation: `Either we're missing tasks for this vendor's trade (add some), or the vendor type is a relic that no template uses (cut it). Open the vendor card first to read the full description, then decide.`,
      contextHtml: `
        <div class="admin-audit-focused__context">
          <p><strong>Vendor type:</strong> ${escapeHtml(v.vendor)}</p>
          ${v.role ? `<p><strong>What they do:</strong> ${escapeHtml(v.role)}</p>` : ""}
          <p class="admin-muted">${escapeHtml(v.reason)}</p>
        </div>
      `,
      whatHappens: [
        `<strong>Open vendor</strong> jumps to the Vendors tab so you can read the full description + write a note in context.`,
        `<strong>Propose tasks for this vendor</strong> drafts a note asking Claude to add 2-3 templates that map to this vendor's trade.`,
        `<strong>Cut the vendor type</strong> drafts a proposal_delete note. Use this if no template uses it AND HNW homes don't typically have this vendor.`,
      ],
      actions: [
        { id: "vendor-open", label: "Open vendor", primary: true },
        { id: "vendor-add-tasks", label: "Propose tasks for this vendor" },
        { id: "vendor-cut", label: "Cut the vendor type", danger: true },
      ],
    };
  }
  if (finding.kind === "missing_vendor") {
    const v = finding.data;
    return {
      recommendation: `HNW homes typically have a "${v.name}" — the catalog is missing them. Drafting the proposal note tells Claude to add the entry on the next code session.`,
      contextHtml: `
        <div class="admin-audit-focused__context">
          <p><strong>Vendor type:</strong> ${escapeHtml(v.name)}</p>
          ${v.role ? `<p><strong>What they do:</strong> ${escapeHtml(v.role)}</p>` : ""}
        </div>
      `,
      whatHappens: [
        `<strong>Draft "add this vendor type" note</strong> writes a proposal_add note. Claude will add the entry to DEFAULT_VENDOR_CATEGORIES on the next session, including a role description and Q15b chip wiring.`,
        `<strong>Skip / dismiss</strong> writes a feedback note saying we don't actually want this vendor type. The audit will keep flagging it (it's hardcoded into the curated list), but the note documents your decision.`,
      ],
      actions: [
        { id: "missing-vendor-add", label: "Draft \"add this vendor\" note", primary: true },
        { id: "missing-vendor-skip", label: "Skip — don't want this vendor" },
      ],
    };
  }
  if (finding.kind === "missing_routine") {
    const r = finding.data;
    return {
      recommendation: `HNW homes typically have a "${r.name}" routine — the catalog doesn't seed it. Drafting the proposal note tells Claude to add it on the next code session.`,
      contextHtml: `
        <div class="admin-audit-focused__context">
          <p><strong>Routine:</strong> ${escapeHtml(r.name)}</p>
          ${r.role ? `<p><strong>What it is:</strong> ${escapeHtml(r.role)}</p>` : ""}
        </div>
      `,
      whatHappens: [
        `<strong>Draft "add this routine" note</strong> writes a proposal_add note. Claude will add the routine to DEFAULT_ROUTINES with a default cadence and surface a Q15b-style chip if it's vendor-backed.`,
        `<strong>Skip / dismiss</strong> writes a feedback note saying we don't want this routine. The audit will keep flagging it (curated list), but your decision is documented.`,
      ],
      actions: [
        { id: "missing-routine-add", label: "Draft \"add this routine\" note", primary: true },
        { id: "missing-routine-skip", label: "Skip — don't want this routine" },
      ],
    };
  }
  // Phase 5z+19 — Voice / style fixes (merged from Decisions). Same
  // engine as the focused decision panel, ported into the audit
  // panel. Mechanical fixes get a before/after preview; rule with no
  // mechanical fix shows "what Claude will do" instead.
  if (finding.kind === "voice_fix") {
    const hit = finding.data.lintHit || {};
    const fix = suggestLintFix(hit);
    const previewBlock = fix?.kind === "mechanical" && fix.text
      ? `<div class="admin-decision-focused__lint-block admin-decision-focused__lint-block--suggested">
          <strong>Suggested fix</strong>
          <pre>${escapeHtml(fix.text)}</pre>
        </div>`
      : fix?.kind === "rewrite" && fix.summary
      ? `<div class="admin-decision-focused__lint-block admin-decision-focused__lint-block--rewrite">
          <strong>What Claude will do</strong>
          <p>${escapeHtml(fix.summary)}</p>
        </div>`
      : "";
    const applyExplain = fix?.kind === "mechanical"
      ? "applies the exact swap above on the next code session"
      : "writes a note asking Claude to rewrite the text on the next code session";
    return {
      recommendation: lintRecommendationFor(hit) || "Apply the suggested voice fix and move on.",
      contextHtml: `
        <div class="admin-decision-focused__lint">
          <p class="admin-muted">Field: <code>${escapeHtml(hit.field || "—")}</code></p>
          <div class="admin-decision-focused__lint-block">
            <strong>What's there now</strong>
            <pre>${escapeHtml(hit.snippet || "—")}</pre>
          </div>
          ${previewBlock}
        </div>
      `,
      whatHappens: [
        fix ? `<strong>${escapeHtml(fix.label)}</strong> ${escapeHtml(applyExplain)}.` : `<strong>Apply suggested fix</strong> drafts a voice-fix note.`,
        `<strong>Approve as-is</strong> locks the entity so this lint rule stops flagging it. Use this when the wording is intentional.`,
        `<strong>Open to edit</strong> jumps to the entity so you can rework the wording yourself.`,
        `<strong>Cut entity</strong> removes it from the catalog. Use sparingly.`,
      ],
      actions: [
        { id: "voice-apply", label: fix?.label || "Apply suggested fix", primary: true },
        { id: "voice-approve", label: "Approve as-is" },
        { id: "voice-open", label: "Open to edit" },
        { id: "voice-cut", label: "Cut entity", danger: true },
      ],
    };
  }
  // Phase 5z+19/+21 — Needs review. Tom's frustration: "I have no
  // idea what this means. is it asking me to keep or remove the
  // task?" Make it decisive: pick approve / edit / cut explicitly,
  // surface the actual entity content so Tom can read it without
  // jumping tabs, and frame each action's effect in concrete user-
  // facing terms (what happens to homeowners, not abstract Haven
  // plumbing).
  if (finding.kind === "needs_review") {
    const item = finding.data.targetItem || {};
    const t = item.payload || {};
    const value = finding.data.valueAnalysis || valueAnalysisFor(item);
    const pick = decisivePickFor(item, value);
    // Build the actual content card so Tom reads the title/desc/etc.
    const description = (item.description || t.description || "").trim();
    const frequency = t.frequency || "—";
    const seasonal = t.seasonalTiming || "Year-round";
    const assignment = ({
      vendor: "A pro (always)",
      personal: "Homeowner (DIY only)",
      either: "Either — homeowner or pro",
    })[t.assignmentType] || t.assignmentType || "—";
    const cost = t.estimatedCostRange || "—";
    const universal = (t.requiredSubtypes || []).length === 0;
    const audience = universal
      ? "Every homeowner who finishes the quiz gets this on their schedule."
      : `Only homes that match certain conditions get this (${(t.requiredSubtypes || []).map((s) => (typeof humanizeSubtype === "function" ? humanizeSubtype(s) : s)).join(", ")}).`;

    const contextHtml = `
      <div class="admin-audit-needsreview">
        <p class="admin-audit-needsreview__audience"><strong>Who sees this:</strong> ${escapeHtml(audience)}</p>
        <div class="admin-audit-needsreview__card">
          <h5 class="admin-audit-needsreview__title">${escapeHtml(item.title || finding.title)}</h5>
          ${description ? `<p class="admin-audit-needsreview__desc">${escapeHtml(description)}</p>` : `<p class="admin-audit-needsreview__desc admin-muted"><em>No description set. The homeowner sees just the title — that's likely too thin.</em></p>`}
          <dl class="admin-audit-needsreview__fields">
            <dt>How often</dt><dd>${escapeHtml(frequency)}</dd>
            <dt>Time of year</dt><dd>${escapeHtml(seasonal)}</dd>
            <dt>Who handles it</dt><dd>${escapeHtml(assignment)}</dd>
            <dt>Cost</dt><dd>${escapeHtml(cost)}</dd>
          </dl>
        </div>
        ${value.substitutes && value.substitutes.length ? `
          <div class="admin-decision-focused__substitutes">
            <strong>If you cut it, here's what HNW homes actually want instead</strong>
            <ul>
              ${value.substitutes.slice(0, 5).map((s) => `<li><span class="admin-decision-focused__substitute-text">${escapeHtml(s)}</span></li>`).join("")}
            </ul>
          </div>
        ` : ""}
      </div>
    `;

    // Phase 5z+22 — Tom: "if its giving me a recommendation to edit
    // the task — dont tell me to manually go do it. claude should
    // just take this one and put a change request in with a button
    // click that I enter."
    //
    // For "edit" picks we now render a "Draft this fix" primary
    // button that writes the change-request note for Tom. Mechanical
    // fixes (em-dash, Professional-X) ship with a structured
    // proposed_diff the voice-fix script auto-applies. Rewrite picks
    // (vague title, thin description) ship a regular change_request
    // note describing what to change — Claude rewrites manually.
    //
    // The "Open to edit manually" option stays as a secondary so
    // power users can still hand-edit if they want.
    const actions = [];
    const whatHappens = [];
    if (pick.action === "approve") {
      actions.push({ id: "review-approve", label: "Looks good — lock it in", primary: true });
      actions.push({ id: "review-open", label: "Open to edit" });
      actions.push({ id: "review-cut", label: "Cut it from the catalog", danger: true });
      whatHappens.push(`<strong>Looks good — lock it in:</strong> stops showing up in your audit list. Every new homeowner still gets it on their schedule. Nothing changes for them.`);
      whatHappens.push(`<strong>Open to edit:</strong> jumps to the Tasks tab so you can tweak wording / frequency / cost / who handles it yourself.`);
      whatHappens.push(`<strong>Cut it from the catalog:</strong> new homeowners won't see it. Existing homeowners keep it on their schedule until they complete or archive it themselves.`);
    } else if (pick.action === "edit") {
      const isMechanical = pick.fix?.kind === "mechanical";
      const fixLabel = isMechanical ? "Apply Claude's fix" : "Draft this fix for Claude";
      actions.push({ id: "review-draft-fix", label: fixLabel, primary: true });
      actions.push({ id: "review-open", label: "Open to edit manually" });
      actions.push({ id: "review-approve", label: "Lock as-is anyway" });
      actions.push({ id: "review-cut", label: "Cut it from the catalog", danger: true });
      if (isMechanical) {
        whatHappens.push(`<strong>${escapeHtml(fixLabel)}:</strong> Claude writes a structured note with the exact before/after below. The voice-fix script applies it on the next code session — no manual editing required.`);
      } else {
        whatHappens.push(`<strong>${escapeHtml(fixLabel)}:</strong> Claude writes a change-request note describing what needs to change (no specific replacement text — Claude picks the wording on the next session). You don't have to hand-edit anything.`);
      }
      whatHappens.push(`<strong>Open to edit manually:</strong> jumps to the Tasks tab so you can rewrite it yourself if you'd rather pick the exact wording.`);
      whatHappens.push(`<strong>Lock as-is anyway:</strong> approves the current wording and stops showing it here. Use this if you disagree with the recommendation.`);
      whatHappens.push(`<strong>Cut it from the catalog:</strong> removes it entirely. New homeowners won't see it.`);
    } else {
      // cut
      actions.push({ id: "review-cut", label: "Cut it from the catalog", primary: true, danger: true });
      actions.push({ id: "review-approve", label: "Lock as-is anyway" });
      actions.push({ id: "review-open", label: "Open to edit instead" });
      whatHappens.push(`<strong>Cut it from the catalog:</strong> removes it entirely. New homeowners won't see it. Existing homeowners keep what they already have until they complete or archive.`);
      whatHappens.push(`<strong>Lock as-is anyway:</strong> approves it and stops showing it here. Use this if you think it's worth keeping.`);
      whatHappens.push(`<strong>Open to edit instead:</strong> jumps to the Tasks tab so you can rework it before deciding.`);
    }
    // Substitute action buttons (low-tier only, when we have a list).
    const substituteActions = pick.action === "cut" && value.substitutes && value.substitutes.length
      ? value.substitutes.slice(0, 3).map((_, i) => ({
          id: `review-substitute-${i}`,
          label: `Draft swap → ${(value.substitutes[i] || "").split("(")[0].trim().slice(0, 30)}…`,
        }))
      : [];

    // Phase 5z+22 — Append the suggested before/after preview to the
    // context block when we have a mechanical fix. Tom can see the
    // rewrite before clicking Apply.
    let contextWithFix = contextHtml;
    if (pick.fix?.kind === "mechanical") {
      contextWithFix += `
        <div class="admin-decision-focused__lint">
          <div class="admin-decision-focused__lint-block">
            <strong>${escapeHtml(pick.fix.field)} — current</strong>
            <pre>${escapeHtml(pick.fix.from || "")}</pre>
          </div>
          <div class="admin-decision-focused__lint-block admin-decision-focused__lint-block--suggested">
            <strong>${escapeHtml(pick.fix.field)} — Claude's fix</strong>
            <pre>${escapeHtml(pick.fix.to || "")}</pre>
          </div>
        </div>
      `;
    } else if (pick.fix?.kind === "rewrite") {
      contextWithFix += `
        <div class="admin-decision-focused__lint">
          <div class="admin-decision-focused__lint-block admin-decision-focused__lint-block--rewrite">
            <strong>What Claude will do</strong>
            <p>${escapeHtml(pick.fix.instruction || "Rewrite this on the next session.")}</p>
          </div>
        </div>
      `;
    }

    // Stash the pick on the finding so the action handler can read it.
    finding.data._pick = pick;

    return {
      recommendation: pick.recommendation,
      contextHtml: contextWithFix,
      whatHappens,
      actions: [...actions, ...substituteActions],
    };
  }
  return {
    recommendation: "(no recommendation available)",
    contextHtml: "",
    whatHappens: [],
    actions: [],
  };
}

// Phase 5z+21/+22 — Pick a specific action (approve / edit / cut) for
// a "needs review" finding based on content quality + value tier.
// Each "edit" pick also carries a `fix` payload describing exactly
// what should change — mechanical (suggested before/after we can
// preview) or rewrite (Claude does it on the next session). The
// focused panel reads `fix` and renders a one-click "Draft this fix"
// button so Tom doesn't have to manually edit.
//
// Heuristic order:
//   safety floor              → approve
//   bundle parent             → approve
//   value tier = low          → cut
//   description missing/<40   → edit (rewrite — Claude writes)
//   em-dash in copy           → edit (mechanical — voice fix)
//   "Professional X" title    → edit (mechanical — rename)
//   title <8 chars OR 1 word  → edit (rewrite — Claude rewrites)
//   else                      → approve
function decisivePickFor(item, value) {
  const t = item.payload || {};
  const title = (item.title || "").trim();
  const description = (item.description || t.description || "").trim();

  if (t.safetyFloor === true) {
    return {
      action: "approve",
      fix: null,
      recommendation: `Safety-required work — homeowners can't safely DIY this. Lock it in. The wording is fine; the audit's just flagging it because it's not yet marked approved.`,
    };
  }
  if (t.bundleTitle) {
    return {
      action: "approve",
      fix: null,
      recommendation: `This is a seasonal visit that bundles several individual tasks together. Bundle parents are already vetted by the time they ship. Lock it in.`,
    };
  }
  if (value?.tier === "low") {
    return {
      action: "cut",
      fix: null,
      recommendation: `Low-value chore most HNW homeowners would forget without missing. ${value.reasoning ? value.reasoning.split(".")[0] + "." : ""} Cut it — open the slot for a higher-value HNW service.`,
    };
  }
  if (!description || description.length < 40) {
    return {
      action: "edit",
      fix: {
        kind: "rewrite",
        field: "description",
        currentValue: description || null,
        instruction: `Write a sentence or two describing exactly what gets done, what equipment is needed, and what "good" looks like. The current description is ${description ? `${description.length} chars — too thin` : "empty"}.`,
      },
      recommendation: `Description is ${description ? "thin" : "missing"}. Every homeowner sees just the title — that's not enough context for them to act on. Click below to draft a "fill in the description" change request.`,
    };
  }
  // Em-dash → mechanical fix (period replacement).
  if (/—/.test(title) || /—/.test(description)) {
    const target = /—/.test(title) ? "title" : "description";
    const current = target === "title" ? title : description;
    const fixed = current.replace(/\s+—\s+/g, ". ").replace(/—/g, ", ")
      .replace(/\.\s+([a-z])/g, (_, c) => `. ${c.toUpperCase()}`)
      .replace(/\s\s+/g, " ").trim();
    return {
      action: "edit",
      fix: {
        kind: "mechanical",
        rule: "no-em-dash",
        field: target,
        from: current,
        to: fixed,
        currentValue: current,
        suggestedValue: fixed,
      },
      recommendation: `${target === "title" ? "Title" : "Description"} uses an em-dash (—), which reads as AI-generated to HNW homeowners. Click below to apply Claude's voice fix in one shot.`,
    };
  }
  // "Professional X" → mechanical rename to "Annual X".
  if (/^Professional\s+/i.test(title)) {
    const fixed = title.replace(/^Professional\s+/i, "Annual ");
    return {
      action: "edit",
      fix: {
        kind: "mechanical",
        rule: "no-professional-x-titles",
        field: "title",
        from: title,
        to: fixed,
        currentValue: title,
        suggestedValue: fixed,
      },
      recommendation: `Title starts with "Professional X" — Chez's voice rule says use "Annual X" instead. Click below to rename in one shot.`,
    };
  }
  // Phase 5z+22 — Tom: "Bleed Radiators" is FINE — 2-word action-
  // first titles read cleanly. Loosened from <12 chars / <3 words
  // to <8 chars / <2 words. Catches genuinely-vague titles like
  // "Boiler" or "Inspection" without false-positiving on tight
  // verb-noun pairs.
  if (title.length < 8 || title.split(/\s+/).length < 2) {
    return {
      action: "edit",
      fix: {
        kind: "rewrite",
        field: "title",
        currentValue: title,
        instruction: `Rewrite the title to be action-first (verb + noun, e.g. "Tune up the boiler", "Inspect attic insulation"). Current title is too short to read clearly on a homeowner's task list.`,
      },
      recommendation: `Title is too short to scan cleanly on a task list. Click below to draft a "rewrite the title to be action-first" change request.`,
    };
  }
  // Default — content looks solid.
  return {
    action: "approve",
    fix: null,
    recommendation: `This looks good as-is. Title is sharp, description is specific, frequency + assignment are set. Lock it in so it stops showing up in your audit list.`,
  };
}

async function handleAuditAction(dataset) {
  const action = dataset.auditAction;
  if (action === "open-task" && dataset.templateKey) {
    const items = liveItemsForView("tasks") || [];
    const target = items.find((i) => i.payload?.templateKey === dataset.templateKey);
    if (target) {
      state.view = "tasks";
      state.selected = target;
      render();
    }
    return;
  }
  if (action === "open-question" && dataset.questionId) {
    const items = liveItemsForView("quiz") || [];
    const target = items.find((i) => i.payload?.questionId === dataset.questionId);
    if (target) {
      state.view = "quiz";
      state.selected = target;
      render();
    }
    return;
  }
  if (action === "open-vendor" && dataset.vendor) {
    const items = liveItemsForView("vendors") || [];
    const target = items.find((i) => i.payload?.category === dataset.vendor);
    if (target) {
      state.view = "vendors";
      state.selected = target;
      render();
    }
    return;
  }
  if (action === "propose-vendor" && dataset.category) {
    await writeNote({
      scopeType: "general",
      scopeId: null,
      scopeTitle: `Add a vendor type for ${dataset.category}`,
      body: `Coverage audit found tasks in the "${dataset.category}" category but no vendor type that can do them.\n\nProposal: add a vendor entry that covers this category, OR remap "${dataset.category}" to an existing vendor type.\n\n(Drafted from the Audit tab.)`,
      intent: "proposal_add",
      target: "claude",
      snapshot: { category: dataset.category, source: "coverage_audit" },
    });
    alert(`Drafted a proposal note for "${dataset.category}". Check the Notes tab.`);
    return;
  }
  if (action === "propose-cut" && dataset.questionId) {
    await writeNote({
      scopeType: "question",
      scopeId: dataset.questionId,
      scopeTitle: dataset.questionId,
      body: `Coverage audit flagged this question as not driving anything in the app — no template gates on its answers, it doesn't create a system or vendor, and its kind doesn't drive a known UI branch.\n\nProposal: cut it from the quiz, OR (if it should drive something) document what it should drive in a follow-up note.\n\n(Drafted from the Audit tab.)`,
      intent: "proposal_delete",
      target: "claude",
      snapshot: { questionId: dataset.questionId, source: "coverage_audit" },
    });
    alert(`Drafted a "cut this question" proposal note. Check the Notes tab.`);
    return;
  }
  if (action === "propose-tasks" && dataset.vendor) {
    await writeNote({
      scopeType: "vendor",
      scopeId: dataset.vendor,
      scopeTitle: dataset.vendor,
      body: `Coverage audit found that the "${dataset.vendor}" vendor type has no tasks mapping to it.\n\nProposal: either add tasks under this vendor's trade category, OR cut the vendor type if it's a relic.\n\n(Drafted from the Audit tab.)`,
      intent: "proposal_add",
      target: "claude",
      snapshot: { vendor: dataset.vendor, source: "coverage_audit" },
    });
    alert(`Drafted a proposal note for "${dataset.vendor}". Check the Notes tab.`);
    return;
  }
  if (action === "propose-vendor-type" && dataset.name) {
    await writeNote({
      scopeType: "general",
      scopeId: null,
      scopeTitle: `Add ${dataset.name} as a vendor type`,
      body: `Coverage audit found that HNW homes typically have a "${dataset.name}" vendor but the catalog doesn't list them.\n\nWhat they do: ${dataset.role || "(see audit description)"}\n\nProposal: add "${dataset.name}" to DEFAULT_VENDOR_CATEGORIES with a role description and example tasks. The Q15b chip array picks it up automatically.\n\n(Drafted from the Audit tab.)`,
      intent: "proposal_add",
      target: "claude",
      snapshot: { name: dataset.name, role: dataset.role, source: "coverage_audit_vendor_gap" },
    });
    alert(`Drafted a "add ${dataset.name}" proposal note.`);
    return;
  }
  if (action === "propose-routine" && dataset.name) {
    await writeNote({
      scopeType: "general",
      scopeId: null,
      scopeTitle: `Add ${dataset.name} as a routine`,
      body: `Coverage audit found that HNW homes typically have a "${dataset.name}" routine but the catalog doesn't seed it.\n\nWhat it is: ${dataset.role || "(see audit description)"}\n\nProposal: add "${dataset.name}" to DEFAULT_ROUTINES with a default cadence + day-time, and surface a Q15b-equivalent chip if it's vendor-backed.\n\n(Drafted from the Audit tab.)`,
      intent: "proposal_add",
      target: "claude",
      snapshot: { name: dataset.name, role: dataset.role, source: "coverage_audit_routine_gap" },
    });
    alert(`Drafted a "add ${dataset.name}" proposal note.`);
    return;
  }
}

// Phase 5z+19 — Action dispatcher for the focused audit panel. Each
// finding kind has its own action set; this routes the click to the
// right helper. Most actions either jump to an entity tab or write a
// note, then re-render so the finding drops out of the list (the
// audit recomputes against current notes / data).
async function handleFocusedAuditAction(finding, action) {
  if (!finding) return;
  const data = finding.data || {};

  // ---- task_no_vendor ----
  if (action === "task-cut") {
    if (!confirm(`Draft a proposal_delete note for "${data.title}"?`)) return;
    await writeNote({
      scopeType: "task",
      scopeId: data.templateKey,
      scopeTitle: data.title,
      body: `Audit recommends cutting this template. The "${data.category}" category has no vendor type that can do the work, and value analysis flags the task as low-value.\n\nReason: ${data.reason}\n\n(Drafted from the Audit tab → Tasks without a vendor.)`,
      intent: "proposal_delete",
      target: "claude",
      snapshot: { templateKey: data.templateKey, source: "audit_task_no_vendor" },
    });
    state.selectedAudit = null;
    alert(`Drafted "cut this task" note for "${data.title}".`);
    render();
    return;
  }
  if (action === "task-remap") {
    await writeNote({
      scopeType: "task",
      scopeId: data.templateKey,
      scopeTitle: data.title,
      body: `Audit asks Claude to remap the "${data.category}" category to one of the existing ${DEFAULT_VENDOR_CATEGORIES.length} vendor categories.\n\nCurrent reason: ${data.reason}\n\nQuickest fix: pick the closest match in DEFAULT_VENDOR_CATEGORIES (or update SYSTEM_CATEGORY_TO_VENDOR in admin.js so the audit stops flagging it).\n\n(Drafted from the Audit tab.)`,
      intent: "change_request",
      target: "claude",
      snapshot: { templateKey: data.templateKey, category: data.category, source: "audit_task_remap" },
    });
    state.selectedAudit = null;
    alert(`Drafted remap note for "${data.category}".`);
    render();
    return;
  }
  if (action === "task-new-vendor") {
    await handleAuditAction({ auditAction: "propose-vendor", category: data.category });
    state.selectedAudit = null;
    render();
    return;
  }
  if (action === "task-open") {
    await handleAuditAction({ auditAction: "open-task", templateKey: data.templateKey });
    return;
  }

  // ---- quiz_adrift ----
  if (action === "quiz-open") {
    await handleAuditAction({ auditAction: "open-question", questionId: data.questionId });
    return;
  }
  if (action === "quiz-document") {
    await writeNote({
      scopeType: "question",
      scopeId: data.questionId,
      scopeTitle: data.title || data.questionId,
      body: `Audit flagged this question as adrift but it might be a false positive.\n\nDocumenting what this question DRIVES so the next audit pass can pick it up:\n\n[fill in: e.g. "Sets has_pool attribute on property", "Creates Pool/Spa system in the home_systems table", "Captures contractor in Q15b chip array", etc.]\n\n(Drafted from the Audit tab → Quiz adrift.)`,
      intent: "feedback",
      target: "claude",
      snapshot: { questionId: data.questionId, source: "audit_quiz_document_wiring" },
    });
    state.selectedAudit = null;
    alert(`Drafted documentation note for "${data.questionId}". Open the Notes tab to fill in the wiring.`);
    render();
    return;
  }
  if (action === "quiz-cut") {
    await handleAuditAction({ auditAction: "propose-cut", questionId: data.questionId });
    state.selectedAudit = null;
    render();
    return;
  }

  // ---- vendor_no_tasks ----
  if (action === "vendor-open") {
    await handleAuditAction({ auditAction: "open-vendor", vendor: data.vendor });
    return;
  }
  if (action === "vendor-add-tasks") {
    await handleAuditAction({ auditAction: "propose-tasks", vendor: data.vendor });
    state.selectedAudit = null;
    render();
    return;
  }
  if (action === "vendor-cut") {
    if (!confirm(`Draft a proposal_delete note for the "${data.vendor}" vendor type?`)) return;
    await writeNote({
      scopeType: "vendor",
      scopeId: data.vendor,
      scopeTitle: data.vendor,
      body: `Audit recommends cutting this vendor type. No template's systemCategory maps to it.\n\nReason: ${data.reason}\n\n(Drafted from the Audit tab → Vendor with no tasks.)`,
      intent: "proposal_delete",
      target: "claude",
      snapshot: { vendor: data.vendor, source: "audit_vendor_no_tasks" },
    });
    state.selectedAudit = null;
    alert(`Drafted "cut this vendor" note for "${data.vendor}".`);
    render();
    return;
  }

  // ---- missing_vendor / missing_routine ----
  if (action === "missing-vendor-add") {
    await handleAuditAction({ auditAction: "propose-vendor-type", name: data.name, role: data.role });
    state.selectedAudit = null;
    render();
    return;
  }
  if (action === "missing-vendor-skip") {
    await writeNote({
      scopeType: "general",
      scopeId: null,
      scopeTitle: `Don't add ${data.name} as a vendor`,
      body: `Audit suggested adding "${data.name}" as a vendor type. Decision: skip — not relevant to Chez's audience right now.\n\nThe audit's HNW gap list is hardcoded in admin.js (COMMON_HNW_VENDOR_GAPS), so this finding will keep surfacing until we either add the vendor or strip the entry from that list.\n\n(Drafted from the Audit tab.)`,
      intent: "feedback",
      target: "claude",
      snapshot: { name: data.name, source: "audit_missing_vendor_skip" },
    });
    state.selectedAudit = null;
    alert(`Documented your decision to skip "${data.name}".`);
    render();
    return;
  }
  if (action === "missing-routine-add") {
    await handleAuditAction({ auditAction: "propose-routine", name: data.name, role: data.role });
    state.selectedAudit = null;
    render();
    return;
  }
  if (action === "missing-routine-skip") {
    await writeNote({
      scopeType: "general",
      scopeId: null,
      scopeTitle: `Don't add ${data.name} as a routine`,
      body: `Audit suggested adding "${data.name}" as a routine. Decision: skip — not relevant to Chez's audience right now.\n\nThe audit's HNW routine gap list is hardcoded in admin.js (COMMON_HNW_ROUTINE_GAPS).\n\n(Drafted from the Audit tab.)`,
      intent: "feedback",
      target: "claude",
      snapshot: { name: data.name, source: "audit_missing_routine_skip" },
    });
    state.selectedAudit = null;
    alert(`Documented your decision to skip "${data.name}".`);
    render();
    return;
  }

  // ---- voice_fix (merged from Decisions) ----
  if (action === "voice-apply") {
    // Mirror draftLintFixProposal but trigger from the audit context.
    const decision = {
      lintHit: data.lintHit,
      targetItem: data.targetItem,
    };
    await draftLintFixProposal(decision);
    state.selectedAudit = null;
    return;
  }
  if (action === "voice-approve") {
    state.selected = data.targetItem;
    await toggleLockSelected();
    state.selectedAudit = null;
    render();
    return;
  }
  if (action === "voice-cut") {
    state.selected = data.targetItem;
    if (!confirm(`Mark "${data.targetItem.title}" as cut?`)) return;
    await markCutLive(data.targetItem);
    state.selectedAudit = null;
    render();
    return;
  }
  if (action === "voice-open") {
    if (data.targetItem && data.targetView) {
      state.view = data.targetView;
      state.selected = data.targetItem;
      render();
    }
    return;
  }

  // ---- needs_review (merged from Decisions) ----
  if (action === "review-approve") {
    state.selected = data.targetItem;
    await toggleLockSelected();
    state.selectedAudit = null;
    render();
    return;
  }
  if (action === "review-cut") {
    state.selected = data.targetItem;
    if (!confirm(`Mark "${data.targetItem.title}" as cut?`)) return;
    await markCutLive(data.targetItem);
    state.selectedAudit = null;
    render();
    return;
  }
  if (action === "review-open") {
    if (data.targetItem && data.targetView) {
      state.view = data.targetView;
      state.selected = data.targetItem;
      render();
    }
    return;
  }
  if (action === "review-draft-fix") {
    // Phase 5z+22 — One-click "draft this fix" from the focused
    // audit panel. Mechanical fixes write a structured voice_fix
    // note (apply-voice-fixes script handles it). Rewrite picks
    // write a regular change_request describing what to change.
    const pick = data._pick;
    const item = data.targetItem;
    if (!pick || !pick.fix || !item) {
      alert("No fix payload — can't draft this automatically.");
      return;
    }
    const fix = pick.fix;
    if (fix.kind === "mechanical") {
      const body = `Apply voice fix:\n\nRule: ${fix.rule || "voice"}\nField: ${fix.field}\nBefore: ${fix.from}\nAfter: ${fix.to}\n\n(Drafted from the Audit tab → Needs review → Apply Claude's fix.)`;
      await writeNote({
        scopeType: item.itemType,
        scopeId: liveEntityIdFor(item),
        scopeTitle: item.title,
        body,
        intent: "change_request",
        target: "claude",
        proposedDiff: {
          kind: "voice_fix",
          rule: fix.rule || "voice",
          field: fix.field,
          from: fix.from,
          to: fix.to,
        },
        snapshot: {
          itemType: item.itemType,
          payload: item.payload,
          source: "audit_focused_panel_mechanical_fix",
          capturedAt: new Date().toISOString(),
        },
      });
      state.selectedAudit = null;
      alert(`Voice fix drafted as a note. Claude will apply it on the next session.\n\nBefore: ${fix.from}\nAfter:  ${fix.to}`);
      render();
      return;
    }
    // Rewrite kind — describe what to change without a specific
    // before/after.
    const body = `Rewrite this entity to comply with audit feedback:\n\nField: ${fix.field}\nCurrent value: ${fix.currentValue || "(empty)"}\n\nWhat needs to change: ${fix.instruction}\n\n(Drafted from the Audit tab → Needs review → Draft this fix.)`;
    await writeNote({
      scopeType: item.itemType,
      scopeId: liveEntityIdFor(item),
      scopeTitle: item.title,
      body,
      intent: "change_request",
      target: "claude",
      proposedDiff: {
        kind: "audit_rewrite",
        field: fix.field,
        currentValue: fix.currentValue,
        instruction: fix.instruction,
      },
      snapshot: {
        itemType: item.itemType,
        payload: item.payload,
        source: "audit_focused_panel_rewrite",
        capturedAt: new Date().toISOString(),
      },
    });
    state.selectedAudit = null;
    alert(`Rewrite request drafted as a note. Claude will pick the right wording on the next session.\n\nField: ${fix.field}\nCurrent: ${fix.currentValue || "(empty)"}`);
    render();
    return;
  }
  if (action?.startsWith("review-substitute-")) {
    const idx = parseInt(action.replace("review-substitute-", ""), 10);
    const substitute = data.valueAnalysis?.substitutes?.[idx];
    if (!substitute) return;
    const decision = { targetItem: data.targetItem, valueAnalysis: data.valueAnalysis };
    await draftSubstituteProposal(decision, substitute);
    state.selectedAudit = null;
    return;
  }
}

// =============================================================================
// Phase 7.5 — Decisions queue
// =============================================================================
// Auto-flagged entities awaiting Tom's call. Rules:
//   - Live entities not yet approved AND with high impact (large bundle,
//     gates other questions, or template count > 5 in category)
//   - Entities with lint hits AND launch_status != approved
//   - Entities with question_for_claude notes pending
//   - Entities with change_request notes pending application
// Each row gets one-click Approve / Cut / Open buttons so the tab can be
// burned through quickly.

function renderDecisionsView() {
  const decisions = computeDecisionQueue();
  el.search.value = state.search || "";

  // Phase 5z+14/+15 — Stats tiles. Decisions tab now only surfaces
  // auto-detected issues that don't already have a pending note about
  // them — Tom-authored notes (questions, change requests, proposals)
  // live on the Notes tab. So the tiles are: everything waiting, plus
  // the two auto-detected categories (voice/style fixes + needs review).
  el.stats.innerHTML = `
    <div class="admin-stat"><strong>${decisions.length}</strong><span>Decisions waiting</span></div>
    <div class="admin-stat"><strong>${decisions.filter((d) => d.severity === "lint").length}</strong><span>Voice + style fixes</span></div>
    <div class="admin-stat"><strong>${decisions.filter((d) => d.severity === "impact").length}</strong><span>Needs review</span></div>
  `;

  const filtered = state.search
    ? decisions.filter((d) =>
        [d.title, d.reason, d.itemType].join(" ").toLowerCase().includes(state.search.toLowerCase())
      )
    : decisions;

  el.list.innerHTML = filtered.length
    ? filtered.map((d) => decisionRowHtml(d, state.selectedDecision?.id === d.id)).join("")
    : `<div class="admin-empty-detail" style="min-height:240px"><h3>No decisions waiting</h3><p>Every surface is clean. Move to another tab for active curation.</p></div>`;

  el.list.querySelectorAll("[data-decision-action]").forEach((btn) => {
    btn.addEventListener("click", async (event) => {
      event.stopPropagation();
      const decisionId = btn.closest("[data-decision-id]")?.dataset.decisionId;
      const action = btn.dataset.decisionAction;
      const decision = decisions.find((d) => d.id === decisionId);
      if (!decision) return;
      await handleDecisionAction(decision, action);
    });
  });
  // Phase 5z+14 — Click a row → focused decision panel on the right
  // (no more entity-jump). The panel explains what the decision is,
  // recommends an action, and gives Tom one-click choices for every
  // option. Same pattern as the focused note panel.
  el.list.querySelectorAll("[data-decision-id][data-open-detail]").forEach((row) => {
    row.addEventListener("click", () => {
      const decisionId = row.dataset.decisionId;
      const decision = decisions.find((d) => d.id === decisionId);
      if (!decision) return;
      state.selectedDecision = decision;
      renderFocusedDecisionDetail(decision);
      // Re-render the list so the active row gets a highlight.
      renderDecisionsView();
    });
  });

  // Either show the focused decision panel (if a decision is selected
  // and still in the queue) or fall back to the empty-detail card.
  const stillSelected = state.selectedDecision && decisions.some((d) => d.id === state.selectedDecision.id);
  if (stillSelected) {
    // Refresh the decision object from the freshly-computed queue (it
    // may carry updated entity payloads after a refresh).
    const fresh = decisions.find((d) => d.id === state.selectedDecision.id);
    state.selectedDecision = fresh;
    renderFocusedDecisionDetail(fresh);
  } else {
    state.selectedDecision = null;
    el.decisionFocused?.classList.add("is-hidden");
    el.noteFocused?.classList.add("is-hidden");
    el.emptyDetail.classList.remove("is-hidden");
    el.detail.classList.add("is-hidden");
    el.emptyDetail.querySelector("h3").textContent = decisions.length
      ? "Pick a decision to see the details"
      : "No decisions waiting";
    el.emptyDetail.querySelector("p").textContent = decisions.length
      ? "Click any card on the left. You'll see what the decision is, what would happen if you act on it, plus one-click buttons for each option. Auto-detected issues only — anything you've written a note about lives on the Notes tab."
      : "Every surface is clean right now. Auto-detected issues show up here — voice / style fixes Claude flagged, and high-impact entities that haven't been reviewed yet. Anything you've already written a note about lives on the Notes tab.";
  }
}

// Phase 5z+15 — Build a quick lookup of "entities that already have a
// pending note authored about them." Used to skip lint + impact rows
// from the decision queue when Tom has already written a note about
// the entity (the note lives on the Notes tab and is the canonical
// place to act on it). Keeps Decisions focused on auto-detected
// issues that don't have a human-authored note yet.
function entitiesWithPendingNote() {
  const set = new Set();
  for (const note of state.notes) {
    if (note.appliedAt || note.revertedAt) continue;
    if (!note.scopeId) continue;
    set.add(`${note.scopeType || "any"}::${note.scopeId}`);
  }
  return set;
}

function computeDecisionQueue() {
  const queue = [];
  const surfaces = ["quiz", "tasks", "routines", "handyman", "systems", "vehicles", "prompts"];

  // Phase 5z+15 — Tom: "if something is already in the notes review or
  // to be worked on then it shouldnt show in decisions."
  //
  // Two consequences:
  //   (a) question_for_claude + change_request + proposal_* note rows
  //       are dropped from the queue entirely. Those live in the Notes
  //       tab's "Not applied" bucket, which is where they get acted on.
  //   (b) Lint + impact rows skip any entity that already has a pending
  //       note authored about it — Tom is already on it, no need to
  //       double-surface.
  const pendingNoteScopes = entitiesWithPendingNote();
  const hasPendingNote = (item, scopeType) => {
    if (!item) return false;
    const scopeId = liveEntityIdFor(item);
    if (!scopeId) return false;
    return pendingNoteScopes.has(`${scopeType}::${scopeId}`);
  };

  // 1. Lint violations on un-approved live entities — emit one queue
  // entry per actual lint hit so Tom sees the specific issue + the
  // offending snippet, not 35 rows of canned copy.
  for (const surfaceId of surfaces) {
    const items = liveItemsForView(surfaceId) || [];
    for (const item of items) {
      const lintHits = item.payload?._lint || [];
      if (!lintHits.length) continue;
      const launch = effectiveLaunchStatus(item);
      if (launch === "approved" || launch === "shipped") continue;
      // Phase 5z+15 — skip if already being worked on via a note.
      if (hasPendingNote(item, item.itemType)) continue;
      for (const hit of lintHits) {
        queue.push({
          id: `lint-${surfaceId}-${item.id}-${hit.ruleId}-${hit.field}`,
          severity: "lint",
          title: item.title,
          reason: lintReasonFor(hit),
          itemType: item.itemType,
          targetView: surfaceId,
          targetItem: item,
          // Phase 5z+14 — keep the raw lint hit so the focused panel
          // can compute the suggested fix and render before/after.
          lintHit: hit,
          recommendation: lintRecommendationFor(hit),
          primaryActions: ["open", "approve", "cut"],
        });
      }
    }
  }

  // 2. High-impact entities not yet approved (top tier in registry, or
  // bundle parents). Phase 5z+24 — cap removed; the count must reflect
  // reality so resolutions actually drop the number.
  for (const surfaceId of surfaces) {
    const items = liveItemsForView(surfaceId) || [];
    for (const item of items) {
      const launch = effectiveLaunchStatus(item);
      if (launch === "approved" || launch === "shipped") continue;
      // Phase 5z+15 — skip if already being worked on via a note.
      if (hasPendingNote(item, item.itemType)) continue;
      const high = isHighImpact(item);
      if (!high) continue;
      // Skip if already in queue from earlier rules.
      const already = queue.some((q) => q.targetItem?.id === item.id);
      if (already) continue;
      // Phase 5z+16 — attach value analysis so the focused panel can
      // surface a real recommendation (keep / review / cut + replace)
      // instead of a canned "skim this" line.
      const value = valueAnalysisFor(item);
      queue.push({
        id: `impact-${surfaceId}-${item.id}`,
        severity: "impact",
        title: item.title,
        reason: high,
        itemType: item.itemType,
        targetView: surfaceId,
        targetItem: item,
        valueAnalysis: value,
        recommendation: value.summary,
        primaryActions: ["open", "approve", "cut"],
      });
    }
  }

  return queue;
}

// Phase 5f — turn raw lint hits into specific, actionable rows.
function lintReasonFor(hit) {
  const fieldLabel = (hit.field || "").replace("answerOption.", "answer label ");
  const snippet = (hit.snippet || "").trim();
  const trimmed = snippet.length > 140 ? snippet.slice(0, 137) + "…" : snippet;
  if (hit.ruleId === "no-em-dash") {
    return `Em-dash in ${fieldLabel}: "${trimmed}"`;
  }
  if (hit.ruleId === "no-professional-x-titles") {
    return `Title starts with "Professional X": "${trimmed}"`;
  }
  if (hit.ruleId === "answer-label-max-words") {
    return `Answer label is too long: "${trimmed}"`;
  }
  return `${hit.ruleId} on ${fieldLabel}: "${trimmed}"`;
}

function lintRecommendationFor(hit) {
  if (hit.ruleId === "no-em-dash") {
    return "Replace the em-dash with a comma or hyphen — em-dashes read as AI-generated to HNW readers.";
  }
  if (hit.ruleId === "no-professional-x-titles") {
    return 'Use action-first phrasing instead — "Annual X" or "Schedule X".';
  }
  if (hit.ruleId === "answer-label-max-words") {
    return "Trim the label to 7 or fewer words. Long answer chips wrap awkwardly.";
  }
  return "Open the entity, fix the flagged copy, then approve.";
}

function isHighImpact(item) {
  const p = item.payload || {};
  // Phase 67I.5: only flag bundle PARENTS for review (templates with
  // `bundleTitle` set). Bundle members (bundleId set, bundleTitle
  // absent) ride on the parent — when the parent visit is approved,
  // every "what's included" line item rides along. The homeowner
  // never sees members as standalone tasks either, so the audit
  // shouldn't ask Tom to approve them as standalone entities. This
  // mirrors the iOS UX: one row per visit, sub-tasks revealed inside.
  if (p.bundleId && p.bundleTitle) return `Bundle parent (${p.bundleId})`;
  // Bundle members (bundleId set, no bundleTitle) ride on the parent —
  // bail out before any other rule fires so they never show as their
  // own row.
  if (p.bundleId) return null;
  if ((p._impact?.templates_in_category || []).length > 5) {
    return `${p._impact.templates_in_category.length} templates depend on this category`;
  }
  if (p.tier === "universal") return "Universal-tier system (every household)";
  if (p.safetyFloor === true) return "Safety-floor template";
  if (p.requiredSubtypes?.length === 0 && item.itemType === "task") return "Universal template (no gating)";
  return null;
}

// Phase 67I.5: which needs-review patterns can Tom safely bulk-approve?
// The audit's "needs review" pool mixes two kinds of work:
//   (a) "Look at this once and bless it" — bundle parents, safety-floor
//       templates, universal-tier system rows, opt-in library items.
//       These are correctly classified; they just haven't been blessed.
//   (b) "I'm uncertain about this" — universal templates with empty
//       requiredSubtypes that ARE essential (auto-seed). Could need
//       gating, could be too universal, could be low value. Real review.
//
// Bulk-approve covers (a) only. (b) keeps its individual review row.
// Saves Tom from clicking through ~80% of the queue manually.
function isBulkApprovable(finding) {
  const reason = finding.reason || "";
  if (reason.startsWith("Bundle parent")) return true;
  if (reason === "Safety-floor template") return true;
  if (reason === "Universal-tier system (every household)") return true;
  if (reason.includes("templates depend on this category")) return true;
  // Universal-no-gating templates are bulk-approvable when they're
  // OPT-IN — the homeowner adds them deliberately via Recommended
  // Services, so universal applicability isn't a problem (the
  // homeowner is the gate).
  if (reason === "Universal template (no gating)") {
    const p = finding.item?.payload || finding.data?.payload || {};
    if (p.isEssential === false) return true;
  }
  return false;
}

// Phase 67I.5: bulk-approve a set of audit findings. Each goes through
// the same `toggleLockSelected` write path one entry at a time so the
// shadow row anchoring is consistent with the per-item flow. Sequential
// (not parallel) so concurrent updates can't fight over the same shadow.
async function bulkApproveAuditFindings(findings) {
  if (!findings.length) return;
  const ok = confirm(
    `Approve ${findings.length} catalog ${findings.length === 1 ? "entity" : "entities"} in one batch?\n\n` +
    `Bundle parents · safety-floor templates · universal-tier system rows · opt-in library items. ` +
    `Anything genuinely uncertain (essential universal templates that may need gating) stays in the queue.`
  );
  if (!ok) return;

  let succeeded = 0;
  let failed = 0;
  for (const f of findings) {
    if (!f.item) continue;
    state.selected = f.item;
    try {
      await toggleLockSelected();
      succeeded += 1;
    } catch (err) {
      failed += 1;
    }
  }
  state.selected = null;
  state.selectedAudit = null;
  await refreshAdminData("manual");
  if (failed > 0) {
    alert(`Approved ${succeeded} · ${failed} failed (see console).`);
  }
}

// Phase 5z+16 — Value analysis for "Needs review" decisions. Tom:
// "some of the tasks are low value like garage door stuff. we should
// maybe substitute with higher value things, so for all the needs
// review things in decisions queue give recommendations also for
// what to replace with low value maintenance tasks."
//
// Returns:
//   {
//     tier: "high" | "medium" | "low",
//     verdict: "keep" | "review" | "cut_or_replace",
//     summary: string,             // one-liner for the recommendation field
//     reasoning: string,           // longer explanation for the panel
//     substitutes: string[]|null,  // higher-value HNW alternatives
//   }
//
// Heuristics are intentionally simple and conservative. They flag the
// obvious low-value items (garage door cosmetics, weather-stripping,
// doorbell battery checks) and the obvious high-value items (safety
// floor, expensive vendor visits). Everything else lands as "review."
function valueAnalysisFor(item) {
  const t = item.payload || {};
  const title = (item.title || "").toLowerCase();
  const desc = (item.description || t.description || "").toLowerCase();
  const haystack = `${title} ${desc}`;

  // Always-high signals — these never get cut.
  if (t.safetyFloor === true) {
    return {
      tier: "high",
      verdict: "keep",
      summary: "Safety-required work — homeowners can't safely DIY this. Approve + lock.",
      reasoning: "Anything stamped safetyFloor: true (gas, panel, septic, roof, generator) is non-negotiable in the catalog. Cutting it leaves a gap homeowners shouldn't be expected to fill themselves.",
      substitutes: null,
    };
  }
  if (/\b(gas|panel|chimney sweep|septic pump|smoke detector|carbon monoxide|generator service|water heater)\b/i.test(haystack) || /\bco\s+detector\b/i.test(haystack)) {
    return {
      tier: "high",
      verdict: "keep",
      summary: "Safety + system-critical work HNW homeowners definitely want tracked. Approve + lock.",
      reasoning: "Items that touch fire / gas / panel / septic / generator / water-heater systems are the ones HNW homeowners actually pay people for. They're the catalog's load-bearing entries.",
      substitutes: null,
    };
  }

  // High-value trades — HVAC, boiler, plumbing, pool, tree service.
  // Catches "Spring HVAC tune-up" / "Annual boiler service" / "Pool
  // opening" / "Roof inspection" even when the cost number is under
  // our $200 threshold. Verb stems use a leading-only \b so they
  // match tense variations (inspect / inspection / inspecting).
  if (
    /\b(hvac|boiler|furnace|condenser|heat pump|mini[- ]?split|water heater)\b/i.test(haystack) ||
    /\btune[- ]?up/i.test(haystack) ||
    /\b(pool|spa)\b.*\b(open|clos|servic|maintenance|chemistry|filter|heater)/i.test(haystack) ||
    (/\btree\b/i.test(haystack) && /\b(servic|assess|prun|remov|trim|fell|stump|health)/i.test(haystack)) ||
    /\b(roof|gutter)\b.*\b(inspect|repair|servic|clean|maintenance)/i.test(haystack) ||
    (/\b(septic|well|irrigation|sprinkler)\b/i.test(haystack) && /\b(servic|test|pump|inspect|maintenance|winteriz|backflow|valve|filter)/i.test(haystack))
  ) {
    return {
      tier: "high",
      verdict: "keep",
      summary: "Recurring trade work HNW homeowners genuinely want tracked. Approve + lock.",
      reasoning: "HVAC tune-ups, boiler service, pool opening/closing, tree work, septic / well / irrigation visits, and roof/gutter maintenance are the high-leverage items that prevent expensive damage when neglected. Always worth keeping.",
      substitutes: null,
    };
  }

  // Vendor-managed visits with real cost = high value.
  const costMatch = (t.estimatedCostRange || "").match(/\$(\d{2,4})/);
  const dollars = costMatch ? parseInt(costMatch[1], 10) : 0;
  if (t.assignmentType === "vendor" && dollars >= 200) {
    return {
      tier: "high",
      verdict: "keep",
      summary: `${t.estimatedCostRange || "Significant"} vendor visit — high enough cost that homeowners want it on their schedule. Approve + lock.`,
      reasoning: "Vendor work above ~$200/visit is the kind of thing homeowners forget to schedule and then pay extra for when it becomes urgent. Worth keeping in the auto-seed catalog.",
      substitutes: null,
    };
  }

  // Low-value patterns — garage door cosmetics, doorbell, weather strip.
  // The "garage door" check looks for the noun in proximity to a soft-
  // maintenance verb ANYWHERE in the haystack so wording variants
  // ("Lubricate garage door tracks" vs "Garage door inspection") all
  // catch. Verb stems use a leading-only \b so they match tense
  // variations (lubricate / lubricating / lubricates → "lubricat").
  const lowValueHits = [];
  if (/\bgarage door\b/i.test(haystack) && /\b(lubricat|greas|tun(?:e|ing|es)|servic|inspect|test|adjust|tighten|seal|track)/i.test(haystack)) {
    lowValueHits.push("garage-door soft maintenance");
  }
  if (/\bdoorbell\b/i.test(haystack)) lowValueHits.push("doorbell maintenance");
  if (/weather[- ]?strip(ping)?/i.test(haystack)) lowValueHits.push("weather-stripping check");
  if (/\bcaulk/i.test(haystack) && !/\b(roof|chimney|window)\b/i.test(haystack)) lowValueHits.push("interior caulking");
  if (/touch[- ]?up\b/i.test(haystack) && /paint/i.test(haystack)) lowValueHits.push("paint touch-up");
  if (/photo album|family photo|memorabilia/i.test(haystack)) lowValueHits.push("memorabilia care");
  if (/\bdust/i.test(haystack) && /(blade|fan|baseboard|vent)/i.test(haystack)) lowValueHits.push("light dusting");
  if (/cabinet hinge|drawer slide/i.test(haystack)) lowValueHits.push("cabinet hardware care");
  if (lowValueHits.length > 0) {
    return {
      tier: "low",
      verdict: "cut_or_replace",
      summary: `Low value — ${lowValueHits[0]}. Most HNW homeowners skip this without missing it. Consider cutting or replacing with a higher-value HNW service.`,
      reasoning: `Tom's read: "some of the tasks are low value like garage door stuff." This entry leans into that bucket. Things HNW households genuinely care about tend to be safety, comfort, or expensive-if-neglected — none of which describes ${lowValueHits[0]}.`,
      substitutes: HNW_HIGH_VALUE_SUBSTITUTES,
    };
  }

  // Bundle parents — already vetted as auto-seed visits, recommend lock.
  if (t.bundleTitle) {
    return {
      tier: "high",
      verdict: "keep",
      summary: `Bundle parent (${t.bundleTitle}) — homeowners see this as their seasonal visit. Approve + lock.`,
      reasoning: "Bundle parent rows are the homeowner-facing scheduled task. Cutting one would orphan its sub-tasks. Almost always a keep.",
      substitutes: null,
    };
  }

  // High-impact universal templates — review carefully, don't auto-recommend cut.
  if (t.tier === "universal" || (t.requiredSubtypes?.length === 0 && item.itemType === "task")) {
    return {
      tier: "medium",
      verdict: "review",
      summary: "Universal — applies to every household. Skim it carefully before locking, since it'll show up everywhere.",
      reasoning: "Universal-tier items don't gate on any property signal — every household gets them. That makes the wording especially important: a generic title pollutes everyone's task list. If the wording is sharp + the task is genuinely useful for HNW, lock it. If it's filler, cut it.",
      substitutes: null,
    };
  }

  // Default — neutral review.
  return {
    tier: "medium",
    verdict: "review",
    summary: "Skim and decide. Approve + lock if it fits the catalog vision; cut it if not.",
    reasoning: "Nothing flags this as obviously high or low value. Read the title + description and make the call based on whether HNW homeowners would notice it missing.",
    substitutes: null,
  };
}

// Phase 5z+16 — Curated higher-value substitutes for low-value
// templates. These are services HNW Westchester families actually
// pay for or notice when missing. Surfaced as inspiration in the
// focused decision panel — the user can act on them later by
// proposing a new template, expanding the catalog, etc.
const HNW_HIGH_VALUE_SUBSTITUTES = [
  "Whole-home humidifier service (winter dryness in finished basements + wood floors)",
  "Wine cellar / cigar room climate check (temp + humidity calibration)",
  "Smart-home audit (locks, cameras, leak sensors — battery + firmware)",
  "Built-in fridge + ice-maker filter swap (Sub-Zero, Wolf, Thermador)",
  "Pool cover service + winterization details beyond basic open/close",
  "Backflow preventer test (irrigation — required annually in many towns)",
  "Range hood ducting + filter service (commercial-grade hoods)",
  "Steam shower / sauna service (heating element + drainage)",
  "Outdoor lighting transformer + bulb audit (low-voltage landscape)",
  "EV charger inspection + connection check",
  "Standby generator transfer-switch test (separate from oil/filter service)",
  "Whole-house water filter + UV bulb replacement",
  "Driveway sealcoat + paver re-leveling (HNW curb appeal)",
];

function viewIdForType(type) {
  return (
    {
      question: "quiz",
      task: "tasks",
      handyman: "handyman",
      recommended: "recommended",
      routine: "routines",
      system: "systems",
      vehicle: "vehicles",
      prompt: "prompts",
      vendor: "vendors",
    }[type] || "quiz"
  );
}

function locateLiveItemByScope(note) {
  const surface = viewIdForType(note.scopeType);
  const items = liveItemsForView(surface) || [];
  return (
    items.find((i) =>
      [i.payload?.id, i.payload?.templateKey, i.payload?.categoryKey, i.payload?.functionName, i.payload?.rawValue]
        .filter(Boolean)
        .includes(note.scopeId)
    ) ||
    items.find((i) => i.title === note.scopeTitle) ||
    null
  );
}

function decisionRowHtml(decision, isActive = false) {
  // Phase 5z+14 — Friendlier severity labels + plain-English type hint.
  // The detailed action set lives in the focused panel now; the row
  // is a clean preview that's safe to scan + click.
  const severityLabel =
    {
      question: "Question for you",
      proposal: "Pending proposal",
      lint: "Voice / style fix",
      impact: "Needs review",
    }[decision.severity] || decision.severity;
  const severityTone =
    {
      question: "reshape",
      proposal: "active",
      lint: "draft",
      impact: "defer",
    }[decision.severity] || "active";
  const itemTypeLabel = friendlyScopeLabel(decision.itemType);
  return `
    <div class="admin-decision ${isActive ? "is-active" : ""}" data-decision-id="${escapeHtml(decision.id)}" data-open-detail>
      <div class="admin-decision__top">
        <span class="admin-pill" data-tone="${severityTone}">${escapeHtml(severityLabel)}</span>
        <strong>${escapeHtml(decision.title)}</strong>
        ${itemTypeLabel ? `<span class="admin-muted">${escapeHtml(itemTypeLabel)}</span>` : ""}
      </div>
      <p class="admin-decision__reason">${escapeHtml(decision.reason)}</p>
    </div>
  `;
}

async function handleDecisionAction(decision, action) {
  if (action === "open" && decision.targetItem) {
    state.view = decision.targetView;
    state.selected = decision.targetItem;
    render();
    return;
  }
  if (action === "approve" && decision.targetItem) {
    state.selected = decision.targetItem;
    await toggleLockSelected(); // toggles to approved (or unlocks if already)
    state.selectedDecision = null; // clear so the empty state shows
    render();
    return;
  }
  if (action === "cut" && decision.targetItem) {
    state.selected = decision.targetItem;
    const ok = confirm(`Mark "${decision.targetItem.title}" as cut?`);
    if (!ok) return;
    await markCutLive(decision.targetItem);
    state.selectedDecision = null;
    render();
    return;
  }
  if (action === "open_note" && decision.noteId) {
    // Phase 5z+14 — for question/proposal decisions, jump into the
    // Notes tab with the source note focused. Tom can reply, mark
    // applied, or edit from there.
    const note = state.notes.find((n) => n.id === decision.noteId);
    if (!note) return;
    state.view = "notes";
    state.selected = note;
    state.selectedDecision = null;
    render();
    return;
  }
  if (action === "apply_lint_fix" && decision.lintHit) {
    // Phase 5z+14 — for voice / style lint decisions, save a proposal
    // note that records the suggested fix. Claude applies it on the
    // next session via the existing voice-fix scripts.
    await draftLintFixProposal(decision);
    return;
  }
  if (action === "mark_applied" && decision.noteId) {
    await markNoteApplied(decision.noteId);
    state.selectedDecision = null;
    render();
    return;
  }
  if (action === "propose_substitute" && decision.targetItem) {
    // Phase 5z+16 — clicking a substitute on the focused panel drafts
    // a proposal_add note so Tom can ship it next session as a real
    // template addition. The substitute index rides on the third
    // positional arg (passed by attachFocusedDecisionHandlers from
    // the button's data-substitute-idx attribute).
    const idx = parseInt((typeof arguments[2] !== "undefined" ? arguments[2] : "0") || "0", 10);
    const substitute = decision.valueAnalysis?.substitutes?.[idx];
    if (!substitute) return;
    await draftSubstituteProposal(decision, substitute);
    return;
  }
}

// =============================================================================
// Phase 5z+14 — Focused decision panel
// =============================================================================
//
// Tom's ask: "in the 'Decisions' tab when I click on an entity/card it
// should bring up a decision details information screen to the right
// on the same page to tell me what I need to make a decision on. give
// your recommendation on the suggested change, and other options as
// well that I can just click on."
//
// Renders inside the same admin-detail panel slot as the focused note
// view. Each decision severity has its own body shape:
//
//   question  — Tom asked something; Claude needs to reply first.
//   proposal  — A change request / add / delete is pending.
//   lint      — Voice or style violation; suggested fix available.
//   impact    — High-impact entity not yet approved.
//
// All four share the same scaffold: header (kind / title / one-line
// "what is this") → context (why it surfaced + entity preview) → "what
// would happen" → action buttons. Action buttons are the centerpiece —
// one click per decision instead of "open then figure out what to do."

function renderFocusedDecisionDetail(decision) {
  if (!decision) return;
  el.emptyDetail.classList.add("is-hidden");
  el.detail.classList.remove("is-hidden");

  // Hide every other detail-pane mode.
  el.detailTabs?.classList.add("is-hidden");
  el.curatedForm?.classList.add("is-hidden");
  if (el.formHost) el.formHost.innerHTML = "";
  if (el.diffHost) el.diffHost.innerHTML = "";
  document.querySelector("[data-detail-quick-actions]")?.classList.add("is-hidden");
  el.noteFocused?.classList.add("is-hidden");
  // Phase 5z+20 — hide the legacy detail-actions row + notes-box.
  el.detailActionsRow?.classList.add("is-hidden");
  el.notesBox?.classList.add("is-hidden");
  el.promoteItem.disabled = true;
  el.duplicateItem.disabled = true;
  el.deleteItem.disabled = true;
  el.saveItem.textContent = "Save";
  el.saveItem.disabled = true;

  // Header: eyebrow + title + plain-English subtitle.
  const severityLabel = {
    question: "Question for you",
    proposal: "Pending proposal",
    lint: "Voice / style fix",
    impact: "Needs review",
  }[decision.severity] || decision.severity;
  const tone = {
    question: "reshape",
    proposal: "active",
    lint: "draft",
    impact: "defer",
  }[decision.severity] || "active";
  el.detailKind.textContent = severityLabel.toLowerCase();
  el.detailTitle.textContent = decision.title;
  el.detailSubtitle.textContent = decisionSubtitle(decision);
  el.detailStatus.textContent = severityLabel;
  el.detailStatus.dataset.tone = tone;

  // Render the focused panel body.
  el.decisionFocused?.classList.remove("is-hidden");
  if (el.decisionFocused) {
    el.decisionFocused.innerHTML = renderFocusedDecisionPanelHtml(decision);
    attachFocusedDecisionHandlers(decision);
  }
}

function decisionSubtitle(decision) {
  return ({
    question: "Tom is waiting on an answer. Reply first; no code changes until you both agree.",
    proposal: "A pending change is sitting on this entity. Apply it, defer it, or revert it.",
    lint: "The text breaks one of Chez's voice rules (em-dashes, 'Professional X', long answer chips, etc.). Suggested fix is below.",
    impact: "This entity affects a lot of households. Worth a careful review before it ships to TestFlight.",
  })[decision.severity] || "";
}

function renderFocusedDecisionPanelHtml(decision) {
  const note = decision.noteId ? state.notes.find((n) => n.id === decision.noteId) : null;
  const entity = decision.targetItem || null;
  const recommendation = decision.recommendation || "";

  // Per-severity content body.
  let contextHtml = "";
  let actionsHtml = "";
  let whatHappensHtml = "";

  if (decision.severity === "question") {
    contextHtml = `
      <div class="admin-decision-focused__quote">
        <p class="admin-muted">Tom wrote on ${escapeHtml(formatDate(note?.createdAt))}:</p>
        <blockquote>${escapeHtml(note?.body || "(empty)")}</blockquote>
      </div>
      ${entity ? entityPreviewCardHtml(entity, { scopeType: decision.itemType, scopeTitle: entity.title }) : ""}
    `;
    whatHappensHtml = `
      <ul>
        <li>Open this question in the Notes tab and write your answer as a reply.</li>
        <li>Once you're aligned, mark the note as applied so it stops showing here.</li>
        <li>If the question doesn't need an answer anymore, mark it applied with a quick "won't do" note.</li>
      </ul>
    `;
    actionsHtml = `
      <button type="button" class="admin-button admin-button--primary" data-decision-fa="open_note">Open + reply</button>
      <button type="button" class="admin-button admin-button--secondary" data-decision-fa="mark_applied">Mark answered</button>
    `;
  } else if (decision.severity === "proposal") {
    const intent = note?.intent || "change_request";
    const intentLabel = {
      change_request: "Change request",
      proposal_add: "Suggested addition",
      proposal_delete: "Suggested removal",
    }[intent] || intent;
    contextHtml = `
      <div class="admin-decision-focused__quote">
        <p class="admin-muted">${escapeHtml(intentLabel)} written on ${escapeHtml(formatDate(note?.createdAt))}:</p>
        <blockquote>${escapeHtml(note?.body || "(empty)")}</blockquote>
      </div>
      ${entity ? entityPreviewCardHtml(entity, { scopeType: decision.itemType, scopeTitle: entity.title }) : ""}
    `;
    whatHappensHtml = `
      <ul>
        <li>Open the note to see Claude's full read on whether the feedback is good and what would change if applied.</li>
        <li>If you want it applied, mark it as such — Claude picks it up on the next code session.</li>
        <li>If you've changed your mind, edit or delete the note from the focused note panel.</li>
      </ul>
    `;
    actionsHtml = `
      <button type="button" class="admin-button admin-button--primary" data-decision-fa="open_note">Open in Notes</button>
      <button type="button" class="admin-button admin-button--secondary" data-decision-fa="mark_applied">Mark applied</button>
    `;
  } else if (decision.severity === "lint") {
    const hit = decision.lintHit || {};
    const fix = suggestLintFix(hit);
    // Phase 5z+15 — Always render the Apply button. When we have a
    // mechanical before→after, show it. When we don't, show what
    // Claude will do instead. Tom: "make sure every decision has an
    // apply suggested fix option."
    const previewBlock = fix?.kind === "mechanical" && fix.text
      ? `
        <div class="admin-decision-focused__lint-block admin-decision-focused__lint-block--suggested">
          <strong>Suggested fix</strong>
          <pre>${escapeHtml(fix.text)}</pre>
        </div>
      `
      : fix?.kind === "rewrite" && fix.summary
      ? `
        <div class="admin-decision-focused__lint-block admin-decision-focused__lint-block--rewrite">
          <strong>What Claude will do</strong>
          <p>${escapeHtml(fix.summary)}</p>
        </div>
      `
      : "";
    contextHtml = `
      <div class="admin-decision-focused__lint">
        <p class="admin-muted">Field: <code>${escapeHtml(hit.field || "—")}</code></p>
        <div class="admin-decision-focused__lint-block">
          <strong>What's there now</strong>
          <pre>${escapeHtml(hit.snippet || "—")}</pre>
        </div>
        ${previewBlock}
      </div>
      ${entity ? entityPreviewCardHtml(entity, { scopeType: decision.itemType, scopeTitle: entity.title }) : ""}
    `;
    const applyLabel = fix?.label || "Apply suggested fix";
    const applyExplain = fix?.kind === "mechanical"
      ? "applies the exact swap above on the next code session"
      : "writes a note asking Claude to rewrite the text on the next code session";
    whatHappensHtml = `
      <ul>
        <li><strong>${escapeHtml(applyLabel)}</strong> ${escapeHtml(applyExplain)}.</li>
        <li><strong>Approve as-is</strong> locks the entity so this lint rule stops flagging it. Use this when the wording is intentional.</li>
        <li><strong>Cut entity</strong> removes it from the catalog entirely. Use sparingly — there's no undo.</li>
      </ul>
    `;
    actionsHtml = `
      ${fix ? `<button type="button" class="admin-button admin-button--primary" data-decision-fa="apply_lint_fix">${escapeHtml(fix.label)}</button>` : ""}
      <button type="button" class="admin-button admin-button--secondary" data-decision-fa="approve">Approve as-is</button>
      <button type="button" class="admin-button admin-button--ghost" data-decision-fa="open">Open to edit</button>
      <button type="button" class="admin-button admin-button--ghost admin-button--danger" data-decision-fa="cut">Cut entity</button>
    `;
  } else if (decision.severity === "impact") {
    // Phase 5z+16 — Value-driven recommendation. Three buckets:
    //   high   → keep + lock (vendor work, safety floor, big bundles)
    //   medium → review + lock if it fits the vision
    //   low    → consider cut + replace with HNW substitutes
    const value = decision.valueAnalysis || valueAnalysisFor(entity || {});
    const tierBadge = {
      high: { tone: "active", label: "High value" },
      medium: { tone: "draft", label: "Worth a review" },
      low: { tone: "cut", label: "Low value" },
    }[value.tier] || { tone: "draft", label: value.tier };
    const substitutesBlock = value.substitutes && value.substitutes.length
      ? `
        <div class="admin-decision-focused__substitutes">
          <strong>Higher-value swap ideas</strong>
          <p class="admin-muted">If this slot opens up, these are the kinds of things HNW Westchester homes actually want tracked. Pick one to draft a "let's add this" note, or come up with your own.</p>
          <ul>
            ${value.substitutes.map((s, i) => `
              <li>
                <span class="admin-decision-focused__substitute-text">${escapeHtml(s)}</span>
                <button type="button" class="admin-button admin-button--ghost admin-button--small" data-decision-fa="propose_substitute" data-substitute-idx="${i}">Draft note</button>
              </li>
            `).join("")}
          </ul>
        </div>
      `
      : "";
    contextHtml = `
      <div class="admin-decision-focused__impact">
        <div class="admin-decision-focused__value-row">
          <span class="admin-pill" data-tone="${escapeHtml(tierBadge.tone)}">${escapeHtml(tierBadge.label)}</span>
          <p class="admin-decision-focused__value-summary">${escapeHtml(value.reasoning || decision.reason)}</p>
        </div>
        <p class="admin-muted admin-decision-focused__value-why">${escapeHtml(decision.reason)}</p>
      </div>
      ${entity ? entityPreviewCardHtml(entity, { scopeType: decision.itemType, scopeTitle: entity.title }) : ""}
      ${substitutesBlock}
    `;
    if (value.tier === "low") {
      whatHappensHtml = `
        <ul>
          <li><strong>Cut entity</strong> removes it. The slot opens up for a higher-value HNW service. The substitute list above is starting inspiration.</li>
          <li><strong>Approve + lock</strong> keeps it as-is. Use this only if you've thought about it and decided it's pulling its weight.</li>
          <li><strong>Open to edit</strong> brings up the full detail panel so you can rework the wording / cadence / cost.</li>
        </ul>
      `;
      actionsHtml = `
        <button type="button" class="admin-button admin-button--primary admin-button--danger" data-decision-fa="cut">Cut entity</button>
        <button type="button" class="admin-button admin-button--secondary" data-decision-fa="approve">Approve + lock</button>
        <button type="button" class="admin-button admin-button--ghost" data-decision-fa="open">Open to edit</button>
      `;
    } else {
      whatHappensHtml = `
        <ul>
          <li><strong>Approve + lock</strong> tells Chez this entity is final. It stops surfacing here.</li>
          <li><strong>Open to edit</strong> brings up the entity's full detail panel so you can change fields.</li>
          <li><strong>Cut entity</strong> removes it. Existing households keep what they already have, but new households won't see it.</li>
        </ul>
      `;
      actionsHtml = `
        <button type="button" class="admin-button admin-button--primary" data-decision-fa="approve">Approve + lock</button>
        <button type="button" class="admin-button admin-button--secondary" data-decision-fa="open">Open to edit</button>
        <button type="button" class="admin-button admin-button--ghost admin-button--danger" data-decision-fa="cut">Cut entity</button>
      `;
    }
  }

  return `
    <section class="admin-decision-focused__body">
      <div class="admin-decision-focused__section admin-decision-focused__section--rec">
        <div class="admin-decision-focused__section-head">
          <h4>Claude's recommendation</h4>
        </div>
        <p class="admin-decision-focused__rec">${escapeHtml(recommendation)}</p>
      </div>

      <div class="admin-decision-focused__section">
        <div class="admin-decision-focused__section-head">
          <h4>What we're looking at</h4>
        </div>
        ${contextHtml}
      </div>

      <div class="admin-decision-focused__section">
        <div class="admin-decision-focused__section-head">
          <h4>What happens if you act</h4>
        </div>
        <div class="admin-decision-focused__what">${whatHappensHtml}</div>
      </div>

      <div class="admin-decision-focused__section admin-decision-focused__section--actions">
        <div class="admin-decision-focused__section-head">
          <h4>Choose one</h4>
          <span class="admin-muted admin-decision-focused__action-hint">One click per option. ${decision.severity === "lint" ? "The recommended action is on the left." : ""}</span>
        </div>
        <div class="admin-decision-focused__actions">${actionsHtml}</div>
      </div>

      ${focusedNoteFormHtml()}
    </section>
  `;
}

function attachFocusedDecisionHandlers(decision) {
  // Phase 5z+20 — wire the bottom-of-panel note form for decisions
  // (legacy code path — Decisions tab is folded into Audit but the
  // renderer is still callable via the redirect).
  attachFocusedNoteFormHandler(el.decisionFocused, () => {
    const item = decision.targetItem || {};
    return {
      scopeType: item.itemType || decision.itemType || "general",
      scopeId: item ? liveEntityIdFor(item) : null,
      scopeTitle: item.title || decision.title,
      snapshot: { source: "decision_focused_panel", severity: decision.severity },
    };
  });
  el.decisionFocused?.querySelectorAll("[data-decision-fa]").forEach((btn) => {
    btn.addEventListener("click", async () => {
      // Phase 5z+16 — propose_substitute carries an index via
      // data-substitute-idx; pass it through as the third arg so
      // handleDecisionAction can resolve which substitute was clicked.
      await handleDecisionAction(decision, btn.dataset.decisionFa, btn.dataset.substituteIdx);
    });
  });
}

// Phase 5z+14/+15 — Compute the suggested fix for a lint hit. Tom's
// rule: every lint decision has an "Apply" action. When we can produce
// a deterministic before→after, the action drafts a structured voice-
// fix note the script auto-applies. When we can't, the action drafts a
// regular change-request note describing the rule and what needs
// rewriting — Claude picks the right wording on the next session.
//
// Returns:
//   {
//     kind: "mechanical" | "rewrite",
//     text: string | null,    // the rewrite text (mechanical only)
//     label: string,          // button label
//     summary: string | null, // shown when no mechanical preview is
//                             //   available, describes what Claude
//                             //   will do
//   }
//   or null if there's nothing to fix (snippet missing).
function suggestLintFix(hit) {
  if (!hit?.snippet) return null;
  const snippet = hit.snippet;

  // 1. Em-dash → period + capitalize, or bare em-dash → comma. Always
  //    mechanical since Tom's rule is unambiguous.
  if (hit.ruleId === "no-em-dash") {
    let out = snippet.replace(/\s+—\s+/g, ". ").replace(/—/g, ", ");
    out = out.replace(/\.\s+([a-z])/g, (_, c) => `. ${c.toUpperCase()}`);
    out = out.replace(/\s\s+/g, " ").trim();
    if (out && out !== snippet) {
      return { kind: "mechanical", text: out, label: "Apply suggested fix", summary: null };
    }
    return {
      kind: "rewrite",
      text: null,
      label: "Ask Claude to rewrite",
      summary: "We couldn't compute a clean before→after automatically. Claude will rewrite the line to drop the em-dash on the next session.",
    };
  }

  // 2. "Professional X" title → "Annual X". Mechanical.
  if (hit.ruleId === "no-professional-x-titles") {
    const out = snippet.replace(/^Professional\s+/i, "Annual ");
    if (out !== snippet) {
      return { kind: "mechanical", text: out, label: "Apply suggested fix", summary: null };
    }
  }

  // 3. Long answer label. Try four trim heuristics in order; the first
  //    one that gets us under 7 words wins. If none do, fall through
  //    to the rewrite action so Claude picks the right phrasing.
  if (hit.ruleId === "answer-label-max-words") {
    const tryTrim = trimLongAnswerLabel(snippet);
    if (tryTrim) {
      return {
        kind: "mechanical",
        text: tryTrim,
        label: "Apply suggested fix",
        summary: null,
      };
    }
    return {
      kind: "rewrite",
      text: null,
      label: "Ask Claude to trim this",
      summary: `This label is ${snippet.split(/\s+/).length} words. We couldn't auto-shorten it without losing meaning. Claude will pick a clean ≤7-word version on the next session.`,
    };
  }

  // 4. Generic fallback — any voice rule we don't know how to fix
  //    deterministically. The action becomes "ask Claude to rewrite";
  //    the note describes the rule violation so Claude can act.
  return {
    kind: "rewrite",
    text: null,
    label: "Ask Claude to rewrite",
    summary: `Voice rule "${hit.ruleId}" was flagged on this field. Claude will rewrite the text to comply on the next session.`,
  };
}

// Phase 5z+16 — Draft a proposal_add note recording that this slot
// could be replaced by a higher-value HNW service. The note lives in
// the Notes tab going forward; the original "needs review" decision
// drops out (Phase 5z+15 dedupes against pending notes).
async function draftSubstituteProposal(decision, substituteText) {
  const item = decision.targetItem;
  if (!item || !substituteText) return;
  const body = `Replace low-value template with HNW alternative:

Current: ${item.title}
Why low-value: ${decision.valueAnalysis?.reasoning || "—"}

Suggested replacement: ${substituteText}

Action plan:
1. Cut the current template (it's the slot opening up).
2. Add the suggested replacement (or whatever variant fits the catalog).
3. Wire it into the right system category + bundle if applicable.

(Drafted from the Decisions tab → Needs review → "Higher-value swap ideas" list.)`;
  await writeNote({
    scopeType: item.itemType,
    scopeId: liveEntityIdFor(item),
    scopeTitle: item.title,
    body,
    intent: "proposal_add",
    target: "claude",
    snapshot: {
      itemType: item.itemType,
      payload: item.payload,
      currentTier: decision.valueAnalysis?.tier,
      substituteSuggested: substituteText,
      capturedAt: new Date().toISOString(),
    },
  });
  state.selectedDecision = null;
  alert(`Substitute proposal drafted as a note. It'll show up in the Notes tab.\n\nReplacement: ${substituteText}`);
  render();
}

// Phase 5z+15 — Smart trim for `answer-label-max-words`. Tries four
// patterns; returns the cleanest cut that fits in 7 words. Returns
// null when none of the patterns produce a clean result (the focused
// panel falls back to "Ask Claude to trim this" in that case).
//
// Pattern A (em-dash split) wins outright when it produces a valid
// candidate — the part before " — " is almost always the actual
// answer, the part after is help text the user shouldn't have to read.
// The other three patterns compete by longest-clean-fit.
function trimLongAnswerLabel(snippet) {
  const wordCount = (s) => s.trim().split(/\s+/).length;
  const isClean = (s) => {
    if (!s || s.length === 0) return false;
    // Reject candidates with unbalanced brackets — Pattern B can
    // produce "Detached garage (separate building" by splitting at
    // the first comma inside a parenthetical.
    const open = (s.match(/[(\[]/g) || []).length;
    const close = (s.match(/[)\]]/g) || []).length;
    if (open !== close) return false;
    // Reject candidates ending with a dangling punctuation mark.
    if (/[,\-—]\s*$/.test(s)) return false;
    return true;
  };
  const fits = (s) => wordCount(s) <= 7 && wordCount(s) >= 1;

  // Pattern A — em-dash split. Highest priority because the suffix is
  // usually help text, not the answer itself.
  // "Not sure — take a photo and we'll tell you" → "Not sure"
  const emDashSplit = snippet.split(/\s+—\s+|\s+--\s+/);
  if (emDashSplit.length > 1) {
    const first = emDashSplit[0].trim();
    if (first !== snippet && isClean(first) && fits(first)) {
      return first;
    }
  }

  const candidates = [];

  // Pattern B — drop the suffix after the first comma.
  // "Yes, but only sometimes during winter months" → "Yes"
  const commaSplit = snippet.split(/,/);
  if (commaSplit.length > 1) candidates.push(commaSplit[0].trim());

  // Pattern C — drop trailing "and we'll/we will/I'll/I will…" filler.
  // "Snap a photo and we'll identify it" → "Snap a photo"
  const fillerStripped = snippet.replace(/\s*(,|—)?\s*and\s+(we['']?ll|we\s+will|i['']?ll|i\s+will)\b.*$/i, "").trim();
  if (fillerStripped !== snippet) candidates.push(fillerStripped);

  // Pattern D — drop trailing parenthetical.
  // "Detached garage (separate building, not attached)" → "Detached garage"
  const parenStripped = snippet.replace(/\s*\([^)]*\)\s*$/, "").trim();
  if (parenStripped !== snippet) candidates.push(parenStripped);

  // Pick the longest candidate that fits the word budget AND is
  // structurally clean — preserve as much meaning as possible while
  // still passing the rule.
  const fitting = candidates.filter((c) => c && c !== snippet && fits(c) && isClean(c));
  if (fitting.length === 0) return null;
  fitting.sort((a, b) => wordCount(b) - wordCount(a));
  return fitting[0];
}

// Phase 5z+14/+15 — Apply-fix action handler for lint decisions.
// Two paths depending on whether we computed a deterministic before→
// after:
//
//   mechanical  — proposed_diff carries from/to. The voice-fix script
//                 (scripts/apply_voice_fixes.mjs) reads it next session
//                 and edits the Swift file directly. No human in the
//                 loop.
//   rewrite     — proposed_diff carries the rule + field + reason.
//                 Claude reads the note and rewrites the text by hand
//                 next session. Slower but handles cases without a
//                 clean mechanical transform (long answer labels that
//                 need genuine rewording, etc.).
//
// Either way, drafting the note adds it to the Notes tab. On the next
// recompute, the lint decision drops out of the Decisions queue
// (Phase 5z+15 dedupes against pending notes) so Tom doesn't see it
// twice.
async function draftLintFixProposal(decision) {
  const hit = decision.lintHit;
  if (!hit || !decision.targetItem) return;
  const fix = suggestLintFix(hit);
  if (!fix) {
    alert("This lint hit doesn't have a snippet — nothing to act on.");
    return;
  }
  const item = decision.targetItem;
  const isMechanical = fix.kind === "mechanical" && fix.text && fix.text !== hit.snippet;

  const body = isMechanical
    ? `Apply voice fix:

Rule: ${hit.ruleId}
Field: ${hit.field}
Before: ${hit.snippet}
After: ${fix.text}

(Drafted from the Decisions tab. The voice-fix script picks up this note's proposed_diff next session.)`
    : `Rewrite to comply with voice rule:

Rule: ${hit.ruleId}
Field: ${hit.field}
Current: ${hit.snippet}

${fix.summary || "Please pick the right phrasing on the next code session."}

(Drafted from the Decisions tab. Claude rewrites the text manually on the next session — there's no mechanical fix Tom can preview.)`;

  const proposedDiff = isMechanical
    ? {
        kind: "voice_fix",
        rule: hit.ruleId,
        field: hit.field,
        from: hit.snippet,
        to: fix.text,
      }
    : {
        kind: "voice_rewrite",
        rule: hit.ruleId,
        field: hit.field,
        from: hit.snippet,
        reason: fix.summary || null,
      };

  await writeNote({
    scopeType: item.itemType,
    scopeId: liveEntityIdFor(item),
    scopeTitle: item.title,
    body,
    intent: "change_request",
    target: "claude",
    proposedDiff,
    snapshot: {
      itemType: item.itemType,
      payload: item.payload,
      capturedAt: new Date().toISOString(),
    },
  });

  // Dismiss the focused panel and re-render so the now-resolved
  // decision drops out of the queue (the change-request note exists,
  // so Phase 5z+15's dedup hides it).
  state.selectedDecision = null;
  if (isMechanical) {
    alert(`Voice fix drafted as a note. Claude will apply it on the next session.\n\nBefore: ${hit.snippet}\nAfter:  ${fix.text}`);
  } else {
    alert(`Rewrite request drafted as a note. Claude will pick the right wording on the next session.\n\nCurrent: ${hit.snippet}`);
  }
  render();
}

async function markCutLive(item) {
  if (state.storageMode !== "cloud") return;
  const liveId = liveEntityIdFor(item);
  if (!liveId) return;
  const shadow = findLockShadow(item);
  const row = {
    item_type: item.itemType,
    title: item.title,
    status: "cut",
    category: item.category || null,
    description: item.description || null,
    sort_order: item.sortOrder ?? 0,
    payload: shadow?.payload ?? { live_entity_id: liveId, source: "live_lock" },
    live_entity_id: liveId,
    launch_status: "sunset",
    locked_at: new Date().toISOString(),
  };
  try {
    if (shadow?.id) {
      await supabase.from("admin_content_items").update(row).eq("id", shadow.id);
    } else {
      await supabase.from("admin_content_items").insert(row);
    }
    await loadAdminData();
  } catch (error) {
    alert(`Cut save failed: ${error.message}`);
  }
}

// =============================================================================
// Phase 7.5 — Activity feed
// =============================================================================

function renderActivityView() {
  // Applied notes + reverted notes, reverse chronological
  const events = [];
  for (const note of state.notes) {
    if (note.appliedAt) {
      events.push({
        type: "applied",
        when: note.appliedAt,
        note,
      });
    }
    if (note.revertedAt) {
      events.push({ type: "reverted", when: note.revertedAt, note });
    }
  }
  // Locks too — admin_content_items that have locked_at
  for (const item of state.adminItems) {
    if (item.lockedAt) {
      events.push({ type: "locked", when: item.lockedAt, item });
    }
  }
  events.sort((a, b) => +new Date(b.when) - +new Date(a.when));

  el.stats.innerHTML = `
    <div class="admin-stat"><strong>${events.length}</strong><span>Events</span></div>
    <div class="admin-stat"><strong>${events.filter((e) => e.type === "applied").length}</strong><span>Applied</span></div>
    <div class="admin-stat"><strong>${events.filter((e) => e.type === "locked").length}</strong><span>Locks</span></div>
    <div class="admin-stat"><strong>${events.filter((e) => e.type === "reverted").length}</strong><span>Reverted</span></div>
  `;

  el.list.innerHTML = events.length
    ? events.map(activityRowHtml).join("")
    : `<div class="admin-empty-detail" style="min-height:240px"><h3>No activity yet</h3><p>Apply a note or lock an entity to see it here.</p></div>`;

  el.emptyDetail.classList.add("is-hidden");
  el.detail.classList.add("is-hidden");
}

function activityRowHtml(event) {
  if (event.type === "applied" || event.type === "reverted") {
    const note = event.note;
    const tone = event.type === "applied" ? "active" : "cut";
    return `
      <article class="admin-activity admin-activity--${event.type}">
        <header>
          <span class="admin-pill" data-tone="${tone}">${event.type}</span>
          <strong>${escapeHtml(note.scopeTitle || "(unscoped)")}</strong>
          <span class="admin-muted">${escapeHtml(formatDate(event.when))}</span>
        </header>
        <p class="admin-muted">${escapeHtml(note.scopeType || "general")}${note.appliedCommit ? ` · commit ${escapeHtml(note.appliedCommit.slice(0, 7))}` : ""}</p>
        <pre>${escapeHtml(note.body || "")}</pre>
      </article>
    `;
  }
  if (event.type === "locked") {
    return `
      <article class="admin-activity admin-activity--locked">
        <header>
          <span class="admin-pill" data-tone="active">locked</span>
          <strong>${escapeHtml(event.item.title || "(untitled)")}</strong>
          <span class="admin-muted">${escapeHtml(formatDate(event.when))}</span>
        </header>
        <p class="admin-muted">${escapeHtml(event.item.itemType)} · launch_status: ${escapeHtml(event.item.launchStatus || "?")}</p>
      </article>
    `;
  }
  return "";
}

// =============================================================================
// Phase 5e — Architecture surface
// =============================================================================
// Walkable object-relationship map. Renders the OBJECT_MAP as a single
// scrollable surface (no list/detail split — it's already self-organized
// by cluster). The list panel is hidden; everything goes in the right
// pane.

function renderArchitectureSurface() {
  el.emptyDetail.classList.add("is-hidden");
  el.detail.classList.remove("is-hidden");

  // Hide everything else in the detail panel that doesn't apply.
  el.curatedForm?.classList.add("is-hidden");
  if (el.formHost) el.formHost.innerHTML = "";
  if (el.diffHost) el.diffHost.innerHTML = "";
  if (el.lockToggle) el.lockToggle.classList.add("is-hidden");
  if (el.previewQuestion) el.previewQuestion.classList.add("is-hidden");
  if (el.launchPill) el.launchPill.classList.add("is-hidden");
  if (el.detailTabs) el.detailTabs.classList.add("is-hidden");

  // Header reflects whether we're looking at an object or the overview.
  const focused = state.archSelectedKey ? findArchObject(state.archSelectedKey) : null;
  if (focused) {
    el.detailKind.textContent = focused.cluster;
    el.detailTitle.textContent = `${focused.emoji} ${focused.name}`;
    el.detailSubtitle.textContent = "Click any related object to navigate to it.";
    el.detailStatus.textContent = "object";
  } else {
    el.detailKind.textContent = "object map";
    el.detailTitle.textContent = "Pick an object to start";
    el.detailSubtitle.textContent = "Or use the left rail to jump straight in.";
    el.detailStatus.textContent = "overview";
  }
  el.detailStatus.dataset.tone = "active";

  // Render the appropriate body into formHost.
  if (el.formHost) {
    const extras = focused?.key === "edge_function_prompt"
      ? { edge_function_prompt: renderEdgeFunctionInventory() }
      : {};
    el.formHost.innerHTML = focused
      ? renderArchitectureObject(focused.key, extras)
      : renderArchitectureOverview();
    attachArchitectureHandlers(el.formHost, {
      onOpen: openArchitectureObject,
      onBack: clearArchitectureObject,
    });
    // Wire edge-function click-throughs to jump to the Prompts surface.
    el.formHost.querySelectorAll("[data-edge-fn-jump]").forEach((btn) => {
      btn.addEventListener("click", () => {
        const fnName = btn.dataset.edgeFnJump;
        state.view = "prompts";
        const items = liveItemsForView("prompts") || [];
        state.selected = items.find((i) => i.payload?.functionName === fnName) || null;
        render();
      });
    });
  }

  // Left rail: cluster-grouped quick-jump nav with the current object
  // highlighted (cluster headers separate the list visually).
  const lite = getObjectMapLite();
  const clusters = getClusters();
  el.list.innerHTML = `
    <div class="admin-arch__nav">
      <strong>Object map</strong>
      ${clusters
        .map((cluster) => {
          const objects = lite.filter((o) => o.cluster === cluster.key);
          if (!objects.length) return "";
          return `
            <div class="admin-arch__nav-cluster">
              <span class="admin-arch__nav-cluster-label">${escapeHtml(cluster.label)}</span>
              <ul>
                ${objects
                  .map(
                    (o) => `
                      <li>
                        <button type="button" data-arch-jump="${escapeHtml(o.key)}" class="${state.archSelectedKey === o.key ? "is-active" : ""}">
                          <span>${o.emoji}</span> ${escapeHtml(o.name)}
                        </button>
                      </li>
                    `
                  )
                  .join("")}
              </ul>
            </div>
          `;
        })
        .join("")}
    </div>
  `;
  el.list.querySelectorAll("[data-arch-jump]").forEach((btn) => {
    btn.addEventListener("click", () => openArchitectureObject(btn.dataset.archJump));
  });

  el.stats.innerHTML = focused
    ? `<div class="admin-stat"><strong>${focused.keyFields?.length || 0}</strong><span>Key fields</span></div>
       <div class="admin-stat"><strong>${(focused.relationships || []).length}</strong><span>Outgoing links</span></div>`
    : `<div class="admin-stat"><strong>${lite.length}</strong><span>Objects mapped</span></div>
       <div class="admin-stat"><strong>${clusters.length}</strong><span>Clusters</span></div>`;
}

// Phase 5g — render the edge functions inventory injected into the
// Edge Function Prompt architecture detail. Groups the 50+ functions
// by purpose so the page reads cleanly. Click any row to jump straight
// to that prompt on the Prompts surface.
function renderEdgeFunctionInventory() {
  const fns = state.liveData["edge-function-prompts"]?.entries || [];
  if (!fns.length) {
    return `<section class="admin-arch__panel"><h4>Edge function inventory</h4><p class="admin-muted">No edge functions exported yet — run scripts/export_swift_admin_data.mjs and refresh.</p></section>`;
  }
  const buckets = bucketEdgeFunctions(fns);
  const totalFns = fns.length;
  const withPrompt = fns.filter((f) => f.systemPrompt).length;
  const sectionsHtml = buckets
    .filter((b) => b.fns.length)
    .map(
      (b) => `
        <section class="admin-arch__edge-bucket">
          <header>
            <h5>${escapeHtml(b.label)}</h5>
            <span class="admin-muted">${b.fns.length} function${b.fns.length === 1 ? "" : "s"}</span>
          </header>
          <ul>
            ${b.fns
              .map((fn) => `
                <li>
                  <button type="button" class="admin-arch__edge-fn" data-edge-fn-jump="${escapeHtml(fn.functionName)}">
                    <code>${escapeHtml(fn.functionName)}</code>
                    <span class="admin-arch__edge-fn-meta">
                      ${fn.model ? `<span>${escapeHtml(fn.model)}</span>` : ""}
                      ${fn.systemPrompt ? `<span>${fn.systemPrompt.length} char prompt</span>` : `<span class="admin-arch__edge-fn-warn">no prompt detected</span>`}
                    </span>
                  </button>
                </li>
              `).join("")}
          </ul>
        </section>
      `
    )
    .join("");
  return `
    <section class="admin-arch__panel admin-arch__panel--edge">
      <h4>Edge function inventory (${totalFns})</h4>
      <p class="admin-muted">${withPrompt} of ${totalFns} have a detected system prompt. Click any function to open it on the Prompts surface.</p>
      <div class="admin-arch__edge-buckets">
        ${sectionsHtml}
      </div>
    </section>
  `;
}

const EDGE_FUNCTION_BUCKETS = [
  {
    key: "doc_ai",
    label: "📄 Document + AI insights",
    match: /^(analyze|process-invoice|gap-analysis|simulate-scenario|proactive-scan|chat|extract-vendor)/,
  },
  {
    key: "email",
    label: "📧 Email pipeline",
    match: /^(receive-email|process-inbox-item|send-)/,
  },
  {
    key: "vehicle",
    label: "🚗 Vehicle",
    match: /^(vehicle-|check-vehicle)/,
  },
  {
    key: "property",
    label: "🏠 Property + lookup",
    match: /^(property-lookup|brand-logo|find-local-vendors|view-document|verify-)/,
  },
  {
    key: "equipment",
    label: "🛠 Equipment + manuals",
    match: /^(search-equipment|identify-equipment|lookup-manual|score-equipment|enrich-catalog|expand-catalog|scrape-manuals|download-manuals|upload-manual|send-catalog-request)/,
  },
  {
    key: "quote",
    label: "💵 Quote + project",
    match: /^(analyze-quote|draft-negotiation-email|research-project|project-feasibility|visualize-room|score-property)/,
  },
  {
    key: "household",
    label: "👥 Household + account",
    match: /^(merge-households|delete-account|send-push|cadence-notifications|handyman-portal|find-network-handymen)/,
  },
];

function bucketEdgeFunctions(fns) {
  const buckets = EDGE_FUNCTION_BUCKETS.map((b) => ({ label: b.label, fns: [] }));
  const other = { label: "🧩 Other", fns: [] };
  fns.forEach((fn) => {
    const idx = EDGE_FUNCTION_BUCKETS.findIndex((b) => b.match.test(fn.functionName));
    if (idx >= 0) buckets[idx].fns.push(fn);
    else other.fns.push(fn);
  });
  buckets.forEach((b) => b.fns.sort((a, c) => a.functionName.localeCompare(c.functionName)));
  other.fns.sort((a, c) => a.functionName.localeCompare(c.functionName));
  return [...buckets, other];
}

function openArchitectureObject(key) {
  state.archSelectedKey = key;
  renderArchitectureSurface();
  // Scroll the new detail to the top so it always starts clean.
  if (el.formHost) el.formHost.scrollTop = 0;
}

function clearArchitectureObject() {
  state.archSelectedKey = null;
  renderArchitectureSurface();
}

// =============================================================================
// Phase 5b — CLAUDE_ADMIN_NOTES.md live preview
// =============================================================================
// Mirrors what scripts/sync_claude_admin_notes.mjs produces, rendered in
// the browser so Tom can see exactly what next-session Claude will read
// without dropping into a terminal. Same priority order: questions for
// Claude → pending changes → open feedback by entity → recently applied.

function renderClaudeFileView() {
  el.emptyDetail.classList.add("is-hidden");
  el.detail.classList.add("is-hidden");

  // Filter to claude/both target + non-archived, then group.
  const claudeNotes = state.notes.filter(
    (n) => n.target === "claude" || n.target === "both"
  );

  const pending = claudeNotes.filter(
    (n) =>
      !n.appliedAt &&
      !n.revertedAt &&
      ["change_request", "proposal_add", "proposal_delete"].includes(n.intent)
  );
  const questions = claudeNotes.filter(
    (n) => !n.appliedAt && n.intent === "question_for_claude"
  );
  const feedback = claudeNotes.filter(
    (n) =>
      !n.appliedAt &&
      !n.revertedAt &&
      !["change_request", "proposal_add", "proposal_delete", "question_for_claude"].includes(n.intent)
  );
  const applied = claudeNotes.filter((n) => n.appliedAt && !n.revertedAt);

  el.stats.innerHTML = `
    <div class="admin-stat"><strong>${pending.length}</strong><span>Pending changes</span></div>
    <div class="admin-stat"><strong>${questions.length}</strong><span>Open questions</span></div>
    <div class="admin-stat"><strong>${feedback.length}</strong><span>Feedback</span></div>
    <div class="admin-stat"><strong>${applied.length}</strong><span>Applied</span></div>
  `;

  // Build threaded structure (parent → children) so replies render nested.
  const threaded = nestThreadsForFile(claudeNotes);

  const listHtml = `
    <div class="admin-claude-file">
      <header class="admin-claude-file__header">
        <p class="admin-eyebrow">CLAUDE_ADMIN_NOTES.md</p>
        <h2>${escapeHtml(claudeNotes.length)} note${claudeNotes.length === 1 ? "" : "s"} synced to Claude</h2>
        <p class="admin-muted">Live preview. Saving a note above auto-updates this view. The actual
        <code>CLAUDE_ADMIN_NOTES.md</code> file refreshes on the next sync —
        run <code>node scripts/sync_claude_admin_notes.mjs</code> locally to write the file.</p>
      </header>

      ${
        questions.length
          ? `<section class="admin-claude-file__section admin-claude-file__section--question">
              <h3>❓ Questions for Claude (answer first)</h3>
              ${threaded.filter((n) => questions.includes(n)).map(claudeFileNoteHtml).join("")}
            </section>`
          : ""
      }

      ${
        pending.length
          ? `<section class="admin-claude-file__section admin-claude-file__section--pending">
              <h3>⚡ Pending Changes (act on these first)</h3>
              ${threaded.filter((n) => pending.includes(n)).map(claudeFileNoteHtml).join("")}
            </section>`
          : ""
      }

      ${
        feedback.length
          ? `<section class="admin-claude-file__section">
              <h3>📋 Open Feedback (by entity)</h3>
              ${renderFeedbackByEntity(threaded.filter((n) => feedback.includes(n)))}
            </section>`
          : ""
      }

      ${
        applied.length
          ? `<section class="admin-claude-file__section admin-claude-file__section--applied">
              <h3>✅ Recently Applied</h3>
              <p class="admin-muted">Already shipped. Read for retroactive QA only.</p>
              ${renderFeedbackByEntity(threaded.filter((n) => applied.includes(n)))}
            </section>`
          : ""
      }

      ${
        !claudeNotes.length
          ? `<div class="admin-empty-detail" style="min-height:240px">
              <h3>No notes yet</h3>
              <p>Save a note from any detail panel or quiz preview and it'll show up here.</p>
            </div>`
          : ""
      }
    </div>
  `;

  el.list.innerHTML = listHtml;

  // Wire revert buttons inside the file preview.
  el.list.querySelectorAll("[data-revert-note]").forEach((btn) => {
    btn.addEventListener("click", async (event) => {
      event.stopPropagation();
      await revertNote(btn.dataset.revertNote);
      renderClaudeFileView();
    });
  });
}

function nestThreadsForFile(notes) {
  // Wrap each note with replies array; populate from parentNoteId.
  const byId = new Map(notes.map((n) => [n.id, { ...n, replies: [] }]));
  const top = [];
  for (const n of notes) {
    const wrapped = byId.get(n.id);
    if (n.parentNoteId && byId.has(n.parentNoteId)) {
      byId.get(n.parentNoteId).replies.push(wrapped);
    } else {
      top.push(wrapped);
    }
  }
  top.sort((a, b) => +new Date(b.createdAt) - +new Date(a.createdAt));
  for (const t of top) t.replies.sort((a, b) => +new Date(a.createdAt) - +new Date(b.createdAt));
  return top;
}

function renderFeedbackByEntity(notes) {
  // Group by scopeType + scopeId for a clean per-entity view.
  const groups = new Map();
  for (const note of notes) {
    const key = `${note.scopeType || "general"}::${note.scopeId || note.scopeTitle || "(unscoped)"}`;
    if (!groups.has(key)) {
      groups.set(key, {
        scopeType: note.scopeType || "general",
        scopeTitle: note.scopeTitle || "Unnamed",
        scopeId: note.scopeId,
        notes: [],
      });
    }
    groups.get(key).notes.push(note);
  }
  const ordered = [...groups.values()].sort((a, b) => {
    const order = ["question", "task", "handyman", "routine", "system", "vehicle", "prompt", "general"];
    const ai = order.indexOf(a.scopeType);
    const bi = order.indexOf(b.scopeType);
    if (ai !== bi) return (ai < 0 ? 99 : ai) - (bi < 0 ? 99 : bi);
    return a.scopeTitle.localeCompare(b.scopeTitle);
  });
  return ordered
    .map(
      (g) => `
        <article class="admin-claude-file__entity">
          <header>
            <span class="admin-pill admin-pill--note">${escapeHtml(g.scopeType)}</span>
            <strong>${escapeHtml(g.scopeTitle)}</strong>
            ${g.scopeId ? `<code>${escapeHtml(g.scopeId)}</code>` : ""}
          </header>
          ${g.notes.map(claudeFileNoteHtml).join("")}
        </article>
      `
    )
    .join("");
}

function claudeFileNoteHtml(note, depth = 0) {
  const author = note.author || "tom";
  const ts = note.createdAt ? formatDate(note.createdAt) : "?";
  const intent = note.intent || "feedback";
  const headerBits = [ts, intent, author];
  if (note.appliedAt) {
    headerBits.push(`applied ${formatDate(note.appliedAt)}`);
    if (note.appliedCommit) headerBits.push(`commit ${note.appliedCommit.slice(0, 7)}`);
  }
  if (note.revertedAt) headerBits.push(`reverted ${formatDate(note.revertedAt)}`);

  const diffHtml =
    note.proposedDiff && Object.keys(note.proposedDiff).length
      ? `<details class="admin-claude-file__diff"><summary>Proposed diff</summary><pre>${escapeHtml(JSON.stringify(note.proposedDiff, null, 2))}</pre></details>`
      : "";

  const attachments = (note.attachmentUrls || [])
    .map((url) => `<a href="${escapeHtml(url)}" target="_blank" rel="noopener" class="admin-claude-file__attachment">attachment</a>`)
    .join(" ");

  const revertBtn =
    note.appliedAt && !note.revertedAt
      ? `<button type="button" class="admin-button admin-button--secondary admin-button--xs" data-revert-note="${escapeHtml(note.id)}">Revert</button>`
      : "";

  const replies = (note.replies || []).map((r) => claudeFileNoteHtml(r, depth + 1)).join("");

  return `
    <article class="admin-claude-file__note ${depth > 0 ? "admin-claude-file__note--reply" : ""}">
      <header>
        <span class="admin-claude-file__note-meta">${escapeHtml(headerBits.join(" · "))}</span>
        ${revertBtn}
      </header>
      <pre>${escapeHtml(note.body || "")}</pre>
      ${attachments ? `<div class="admin-claude-file__attachments">${attachments}</div>` : ""}
      ${diffHtml}
      ${replies}
    </article>
  `;
}

// Phase 5z+8 — Tally notes by intent so the filter pills can show
// per-intent counts. The 7 buckets match the <select data-field-intent>
// options in admin.html. Notes that landed before the bug/idea/q4c
// intents existed default to `feedback`.
function countNotesByIntent(notes) {
  const out = {
    feedback: 0,
    change_request: 0,
    proposal_add: 0,
    proposal_delete: 0,
    bug: 0,
    idea: 0,
    question_for_claude: 0,
  };
  for (const n of notes) {
    const i = n.intent || "feedback";
    if (i in out) out[i]++;
    else out.feedback++;
  }
  return out;
}

function renderNotesView() {
  // Phase 5h — text search across body + scope title + scope id. Reuses
  // the existing list-tools search input (state.search) so the same
  // box that filters every other surface filters notes too.
  const query = (state.search || "").trim().toLowerCase();
  const matchesQuery = (n) => {
    if (!query) return true;
    return [n.body, n.scopeTitle, n.scopeId, n.intent, n.scopeType]
      .filter(Boolean)
      .some((s) => String(s).toLowerCase().includes(query));
  };

  // Phase 5z+8/+10 — gather every search-matching top-level note BEFORE
  // applying the segment + intent filters, so the pill counts stay
  // stable as Tom flips between buckets (Apple Mail / Linear pattern).
  const queryMatched = state.notes.filter((n) => !n.parentNoteId).filter(matchesQuery);
  const pendingNotes = queryMatched.filter((n) => !n.appliedAt);
  const appliedNotes = queryMatched.filter((n) => n.appliedAt);
  const segment = state.notesAppliedSegment === "applied" ? "applied" : "pending";
  // Intent counts run against whichever segment is active so the pills
  // reflect "what's available in this segment", not "what exists overall".
  const segmentNotes = segment === "applied" ? appliedNotes : pendingNotes;
  const intentCounts = countNotesByIntent(segmentNotes);

  // Apply the intent filter on top of the segment.
  const intentFilter = state.notesIntentFilter || "all";
  const topLevel = segmentNotes.filter((n) => {
    if (intentFilter !== "all" && (n.intent || "feedback") !== intentFilter) return false;
    return true;
  });

  // Phase 5z+10 — Two-segment top row replaces the old 3-tile stats +
  // show-applied toggle. The active segment is the primary lens; intent
  // pills narrow within it.
  const segmentBtn = (key, label, count, sub) => {
    const isActive = segment === key;
    return `<button type="button" class="admin-segment ${isActive ? "is-active" : ""}" data-notes-segment="${escapeHtml(key)}">
      <span class="admin-segment__label">${escapeHtml(label)}</span>
      <span class="admin-segment__count">${count}</span>
      <span class="admin-segment__sub admin-muted">${escapeHtml(sub)}</span>
    </button>`;
  };

  const segmentRow = `
    <div class="admin-segments">
      ${segmentBtn("pending", "Not applied", pendingNotes.length, "Open work. Claude will analyze each one.")}
      ${segmentBtn("applied", "Applied", appliedNotes.length, "Resolved history. No further analysis.")}
    </div>
  `;

  // Phase 5z+8/+10 — intent filter pills (re-using the facet-pill style)
  // narrow the active segment to a single intent.
  const intentPill = (value, label, count, title) => {
    const isActive = intentFilter === value;
    return `<button type="button" class="admin-facet-pill ${isActive ? "is-active" : ""}" data-facet-axis="notesIntent" data-facet-value="${escapeHtml(value)}" title="${escapeHtml(title)}">
      <span class="admin-facet-pill__label">${escapeHtml(label)}</span>
      <span class="admin-facet-pill__count">${count}</span>
    </button>`;
  };

  const filtersHtml = `
    <div class="admin-facets admin-facets--notes">
      <div class="admin-facet-row">
        <div class="admin-facet-row__head">
          <span class="admin-facet-row__label">Intent</span>
          <span class="admin-facet-row__caption admin-muted">Narrow the ${segment === "applied" ? "applied" : "open"} list to a single note kind.</span>
        </div>
        <div class="admin-facet-row__pills">
          ${intentPill("all", "All", segmentNotes.length, `Show every ${segment === "applied" ? "applied" : "open"} note.`)}
          ${intentPill("change_request", "Change request", intentCounts.change_request, "Specific edits we want made — usually attached to a quiz question, template, or routine.")}
          ${intentPill("feedback", "Feedback", intentCounts.feedback, "Reactions and observations that don't ask for a change.")}
          ${intentPill("proposal_add", "Proposal · add", intentCounts.proposal_add, "An idea for something new — a missing task, system, routine, or quiz answer.")}
          ${intentPill("proposal_delete", "Proposal · cut", intentCounts.proposal_delete, "An entity that probably shouldn't be there — duplicate, low-value, or out of date.")}
          ${intentPill("bug", "Bug", intentCounts.bug, "Something is broken. Usually paired with a screenshot.")}
          ${intentPill("idea", "Idea", intentCounts.idea, "Bigger-picture thinking. Parked for later, not next session.")}
          ${intentPill("question_for_claude", "Question for Claude", intentCounts.question_for_claude, "Asks for an answer first. Claude replies before any change is made.")}
        </div>
      </div>
    </div>
  `;

  el.stats.innerHTML = `${segmentRow}${filtersHtml}`;

  // Wire the segment buttons + intent pills.
  el.stats.querySelectorAll("[data-notes-segment]").forEach((btn) => {
    btn.addEventListener("click", () => {
      state.notesAppliedSegment = btn.dataset.notesSegment === "applied" ? "applied" : "pending";
      // Reset the intent filter when switching segments — counts shift
      // and a previously-active pill might be empty in the new segment.
      state.notesIntentFilter = "all";
      // Drop any selected note since it may not exist in the new segment.
      if (state.selected && (state.notesAppliedSegment === "applied") !== !!state.selected.appliedAt) {
        state.selected = null;
      }
      renderNotesView();
    });
  });
  attachFacetPillHandlers(el.stats);

  el.list.innerHTML = topLevel.map((note) => {
    const canJump = noteCanJumpToEntity(note);
    const intent = note.intent || "feedback";
    const author = note.author || "tom";
    const appliedPill = note.appliedAt
      ? `<span class="admin-pill" data-tone="active">applied</span>`
      : note.revertedAt
      ? `<span class="admin-pill" data-tone="cut">reverted</span>`
      : "";
    const jumpHint = canJump
      ? `<span class="admin-list-item__jump" title="Open the ${escapeHtml(note.scopeType)} this note is about">Open ${escapeHtml(note.scopeType)} →</span>`
      : `<span class="admin-pill">general</span>`;
    // Phase 5z+3 — Delete button on each note row, but ONLY for notes
    // that haven't been applied yet. Applied notes need Revert (audit
    // trail). The button stops propagation so clicking it doesn't
    // trigger the row's jump-to-entity handler.
    const deleteBtn = !note.appliedAt
      ? `<button type="button" class="admin-list-item__delete" data-delete-note-row="${escapeHtml(note.id)}" title="Delete this note">×</button>`
      : "";
    return `
      <div class="admin-list-item-wrap">
        <button class="admin-list-item" data-note-id="${escapeHtml(note.id)}">
          <div class="admin-list-item__top">
            <strong>${escapeHtml(note.scopeTitle || "General note")}</strong>
            <span class="admin-pill admin-pill--note">${escapeHtml(intent)}</span>
            ${author === "claude" ? `<span class="admin-pill admin-pill--note">claude</span>` : ""}
            ${appliedPill}
          </div>
          <p>${escapeHtml((note.body || "").slice(0, 220))}</p>
          <div class="admin-list-item__meta">
            <span>${escapeHtml(formatDate(note.createdAt))}</span>
            ${jumpHint}
          </div>
        </button>
        ${deleteBtn}
      </div>
    `;
  }).join("") || emptyListHtml(
    segmentNotes.length === 0
      ? (query
          ? `No ${segment === "applied" ? "applied" : "open"} notes match "${query}".`
          : segment === "applied"
          ? "Nothing applied yet. Notes land here once Claude or you mark them resolved."
          : "No open notes. Add one from any entity's detail panel — or write a general note from the toolbar.")
      : `No notes match the intent filter. ${segmentNotes.length} ${segmentNotes.length === 1 ? "note" : "notes"} in the ${segment === "applied" ? "applied" : "open"} bucket — click All to see them.`
  );

  // Phase 5z+3 — Wire row-level delete buttons (separate from the row
  // click which navigates to the entity).
  el.list.querySelectorAll("[data-delete-note-row]").forEach((btn) => {
    btn.addEventListener("click", async (event) => {
      event.preventDefault();
      event.stopPropagation();
      await deleteNote(btn.dataset.deleteNoteRow);
    });
  });

  el.list.querySelectorAll("[data-note-id]").forEach((button) => {
    button.addEventListener("click", () => {
      const note = state.notes.find((n) => n.id === button.dataset.noteId);
      if (!note) return;
      // Phase 5z+9 — every note (scoped or general) opens a FOCUSED
      // note panel on the right. No more entity-jump on click — Tom
      // wanted the note itself to be the centerpiece, with the entity
      // shown as a preview card and Claude's analysis surfaced below.
      // The "View {entity} →" escape hatch lives inside the focused
      // panel for users who still want to jump.
      state.selected = note;
      renderFocusedNoteDetail(note);
    });
  });

  // Initial pane state — empty until a note is clicked. If a note is
  // already selected (e.g. user navigated back to Notes after editing
  // one), keep it open.
  if (state.selected && state.notes.some((n) => n.id === state.selected?.id)) {
    renderFocusedNoteDetail(state.selected);
  } else {
    // Hide the focused panel — we're back at the empty state.
    el.noteFocused?.classList.add("is-hidden");
    el.emptyDetail.classList.remove("is-hidden");
    el.detail.classList.add("is-hidden");
    const filterIsActive = intentFilter !== "all";
    el.emptyDetail.querySelector("h3").textContent = query
      ? `${topLevel.length} note${topLevel.length === 1 ? "" : "s"} matching "${query}"`
      : filterIsActive
      ? `${topLevel.length} of ${segmentNotes.length} ${segment === "applied" ? "applied" : "open"} note${segmentNotes.length === 1 ? "" : "s"} shown.`
      : segment === "applied"
      ? "Pick an applied note to read its history."
      : "Pick a note to read it.";
    el.emptyDetail.querySelector("p").textContent = query
      ? "Click any matching note to open it on the right."
      : segment === "applied"
      ? "Applied notes are the audit trail of changes Claude has made. Click one to see what changed and when. No analysis on these — the change already happened."
      : "Click any note to open it. You'll see the body, the entity it's about, Claude's read on whether the feedback is good and what would happen if we apply it, plus controls to edit, delete, mark applied, or reply — all in one place.";
  }
}

function noteCanJumpToEntity(note) {
  if (!note?.scopeType || !note?.scopeId) return false;
  return ["question", "task", "handyman", "routine", "system", "vehicle", "prompt"].includes(note.scopeType);
}

// =============================================================================
// Phase 5z+9 — Focused note panel
// =============================================================================
//
// When Tom clicks a note row on the Notes tab, the right pane renders the
// note itself as the centerpiece (instead of jumping to the entity it's
// attached to, which was the pre-5z+9 behavior). The panel has four
// sections:
//
//   1. Note preview      — body, intent pill, author, applied/reverted
//                          status, timestamps. Editable inline via Edit.
//   2. Entity preview    — read-only summary card of the entity this note
//                          is on (when scoped). "View entity →" escape hatch.
//   3. Analysis          — heuristic-driven summary of:
//                          * Validity tier (high / medium / low) + reasons
//                          * Impact + blast-radius (counts of dependents)
//                          * Alternative approach (when one looks better)
//   4. Replies + actions — threaded note replies, reply input, and the
//                          full action bar (Edit / Delete / Mark applied /
//                          Revert / View entity).
//
// Edit mode swaps the note body to a textarea + intent dropdown. Delete /
// Mark applied / Revert all share the existing async helpers (deleteNote,
// revertNote, plus the new updateNoteFields and markNoteApplied).

function renderFocusedNoteDetail(note) {
  if (!note) return;
  el.emptyDetail.classList.add("is-hidden");
  el.detail.classList.remove("is-hidden");

  // Hide the schema-driven entity machinery — none of it applies to a
  // pure note view. The header (kind / title / subtitle / status pill)
  // stays since we use it to label the panel.
  el.detailTabs?.classList.add("is-hidden");
  el.curatedForm?.classList.add("is-hidden");
  if (el.formHost) el.formHost.innerHTML = "";
  if (el.diffHost) el.diffHost.innerHTML = "";
  // Hide legacy quick-action buttons (Lock, Preview question, etc.).
  document.querySelector("[data-detail-quick-actions]")?.classList.add("is-hidden");
  // Phase 5z+20 — hide the legacy detail-actions row + notes-box. The
  // focused note panel has its own reply form which is the right
  // surface for "add a note about this note."
  el.detailActionsRow?.classList.add("is-hidden");
  el.notesBox?.classList.add("is-hidden");
  // Disable the "Save item" / "Promote" / etc. buttons that live in the
  // edit pane's action bar — they don't apply here.
  el.promoteItem.disabled = true;
  el.duplicateItem.disabled = true;
  el.deleteItem.disabled = true;
  // The empty form's Save button is shared infrastructure; neutralize it.
  el.saveItem.textContent = "Save";
  el.saveItem.disabled = true;

  // Header eyebrow + title + subtitle + status pill.
  const intent = note.intent || "feedback";
  const isApplied = !!note.appliedAt;
  const isReverted = !!note.revertedAt;
  el.detailKind.textContent = note.scopeType ? `${note.scopeType} note` : "general note";
  el.detailTitle.textContent = note.scopeTitle || "General note";
  const ts = formatDate(note.createdAt);
  const meta = [`written ${ts}`];
  if (isApplied) meta.push(`applied ${formatDate(note.appliedAt)}`);
  if (isReverted) meta.push(`reverted ${formatDate(note.revertedAt)}`);
  meta.push(`target: ${note.target || "claude"}`);
  meta.push(`author: ${note.author || "tom"}`);
  el.detailSubtitle.textContent = meta.join(" · ");
  el.detailStatus.textContent = isReverted ? "reverted" : isApplied ? "applied" : intent;
  el.detailStatus.dataset.tone = isReverted ? "cut" : isApplied ? "active" : "draft";

  // Locate the entity (if scoped) so the entity preview + analysis can
  // pull from its payload. Falls back to whatever's in note.snapshot.
  const entityItem = noteCanJumpToEntity(note) ? locateLiveItemByScope(note) : null;
  const analysis = analyzeNote(note, entityItem);

  // Render the focused panel. Show the container (was hidden by default).
  el.noteFocused?.classList.remove("is-hidden");
  if (el.noteFocused) {
    el.noteFocused.innerHTML = renderFocusedNotePanelHtml(note, entityItem, analysis);
    attachFocusedNoteHandlers(note, entityItem, analysis);
  }
}

function renderFocusedNotePanelHtml(note, entityItem, analysis) {
  const intent = note.intent || "feedback";
  const isApplied = !!note.appliedAt;
  const isReverted = !!note.revertedAt;
  const author = note.author || "tom";
  const attachments = (note.snapshot?.attachment_urls || note.attachmentUrls || [])
    .map((url) => `<img src="${escapeHtml(url)}" alt="attachment" class="admin-note-focused__attachment" />`)
    .join("");

  const replies = state.notes
    .filter((n) => n.parentNoteId === note.id)
    .sort((a, b) => +new Date(a.createdAt) - +new Date(b.createdAt));

  return `
    <section class="admin-note-focused__body">
      <header class="admin-note-focused__header">
        <div class="admin-note-focused__header-pills">
          <span class="admin-pill admin-pill--note" data-tone="${escapeHtml(intentTone(intent))}">${escapeHtml(intent)}</span>
          ${author === "claude" ? `<span class="admin-pill admin-pill--note">claude</span>` : ""}
          ${isReverted ? `<span class="admin-pill" data-tone="cut">reverted</span>` : isApplied ? `<span class="admin-pill" data-tone="active">applied</span>` : ""}
          ${note.scopeType ? `<span class="admin-pill admin-pill--note">on ${escapeHtml(note.scopeType)}</span>` : `<span class="admin-pill admin-pill--note">general</span>`}
        </div>
        <div class="admin-note-focused__header-actions">
          ${noteFocusedActionsHtml(note, entityItem)}
        </div>
      </header>

      <!-- 1. Note body — read-only by default, swaps to textarea via Edit. -->
      <div class="admin-note-focused__section" data-note-section="body">
        <div class="admin-note-focused__section-head">
          <h4>Note</h4>
        </div>
        <div data-note-body-display>
          <pre class="admin-note-focused__body-text">${escapeHtml(note.body || "(empty)")}</pre>
          ${attachments ? `<div class="admin-note-focused__attachments">${attachments}</div>` : ""}
        </div>
        <form class="admin-note-focused__edit is-hidden" data-note-edit-form>
          <label class="admin-note-focused__edit-row">
            <span>Body</span>
            <textarea data-note-edit-body rows="6">${escapeHtml(note.body || "")}</textarea>
          </label>
          <div class="admin-note-focused__edit-grid">
            <label>
              <span>Intent</span>
              <select data-note-edit-intent>
                ${["feedback","change_request","proposal_add","proposal_delete","bug","idea","question_for_claude"]
                  .map((v) => `<option value="${v}" ${intent === v ? "selected" : ""}>${v.replace(/_/g, " ")}</option>`)
                  .join("")}
              </select>
            </label>
            <label>
              <span>Target</span>
              <select data-note-edit-target>
                ${["claude","codex","both"].map((v) => `<option value="${v}" ${(note.target || "claude") === v ? "selected" : ""}>${v}</option>`).join("")}
              </select>
            </label>
          </div>
          <div class="admin-note-focused__edit-actions">
            <button type="submit" class="admin-button admin-button--primary admin-button--small" data-note-edit-save>Save</button>
            <button type="button" class="admin-button admin-button--ghost admin-button--small" data-note-edit-cancel>Cancel</button>
          </div>
        </form>
      </div>

      <!-- 2. Entity preview — only when scoped to a known entity. -->
      ${entityItem ? `
        <div class="admin-note-focused__section">
          <div class="admin-note-focused__section-head">
            <h4>Entity this note is on</h4>
            <button type="button" class="admin-button admin-button--ghost admin-button--small" data-note-view-entity>View ${escapeHtml(note.scopeType)} →</button>
          </div>
          ${entityPreviewCardHtml(entityItem, note)}
        </div>
      ` : note.scopeType && note.scopeType !== "general" ? `
        <div class="admin-note-focused__section">
          <div class="admin-note-focused__section-head">
            <h4>Entity this note is on</h4>
          </div>
          <div class="admin-note-focused__entity admin-note-focused__entity--orphaned">
            <strong>Entity not found in current admin data.</strong>
            <p class="admin-muted">
              Scope: <code>${escapeHtml(note.scopeType)}</code> · id: <code>${escapeHtml(note.scopeId || "(none)")}</code>.
              The entity may have been renamed, deleted, or this note predates the current snapshot.
              The note's <code>snapshot</code> field still carries what the entity looked like when the note was written.
            </p>
            <details class="admin-note-focused__snapshot">
              <summary>Show captured snapshot</summary>
              <pre>${escapeHtml(JSON.stringify(note.snapshot ?? {}, null, 2))}</pre>
            </details>
          </div>
        </div>
      ` : ""}

      <!-- 3. Claude's analysis (Not Applied notes only) OR historical
           card (Applied / Reverted notes). The split keeps the analysis
           focused on what's still pending, per Tom's ask: "you only give
           your feedback on the not applied changes so that we can figure
           out what the impacts are what actually happens." -->
      ${(!isApplied && !isReverted) ? `
        <div class="admin-note-focused__section admin-note-focused__section--analysis">
          <div class="admin-note-focused__section-head">
            <h4>Claude's read</h4>
            <span class="admin-muted admin-note-focused__analysis-source">Plain-English summary. Cross-checks current data.</span>
          </div>
          ${analysisCardHtml(analysis)}
        </div>
      ` : `
        <div class="admin-note-focused__section admin-note-focused__section--history">
          <div class="admin-note-focused__section-head">
            <h4>${isReverted ? "Reverted" : "Applied"}</h4>
          </div>
          ${historicalCardHtml(note)}
        </div>
      `}

      <!-- 4. Replies + reply input. -->
      <div class="admin-note-focused__section">
        <div class="admin-note-focused__section-head">
          <h4>Replies <span class="admin-muted">${replies.length}</span></h4>
        </div>
        ${replies.length ? `<div class="admin-note-focused__replies">${replies.map((r) => renderNoteCard(r, 1)).join("")}</div>` : `<p class="admin-muted admin-note-focused__empty-replies">No replies yet. Add one below to capture follow-up context or a question.</p>`}
        <form class="admin-note-focused__reply" data-note-reply-form>
          <textarea data-note-reply-body rows="3" placeholder="Reply to this note. Useful for clarifying questions, follow-up context, or Claude's draft answer."></textarea>
          <div class="admin-note-focused__reply-actions">
            <button type="submit" class="admin-button admin-button--primary admin-button--small" data-note-reply-save>Post reply</button>
          </div>
        </form>
      </div>
    </section>
  `;
}

function noteFocusedActionsHtml(note, entityItem) {
  const isApplied = !!note.appliedAt;
  const isReverted = !!note.revertedAt;
  const buttons = [];
  // Edit — always available, even on applied notes (in case Tom wants
  // to amend the body after the fact). The save path stamps an
  // edited_at field (TBD) but for now we just rewrite body/intent.
  buttons.push(`<button type="button" class="admin-button admin-button--secondary admin-button--small" data-note-edit-toggle title="Inline-edit the body, intent, and target.">Edit</button>`);
  // Mark applied — only when not yet applied + not reverted. Useful for
  // cases where Tom resolved a note manually outside Claude's workflow.
  if (!isApplied && !isReverted) {
    buttons.push(`<button type="button" class="admin-button admin-button--secondary admin-button--small" data-note-mark-applied title="Mark this note resolved without going through a Claude session. Stamps applied_at = now and applied_commit = 'manual'.">Mark applied</button>`);
  }
  // Revert — only on already-applied notes.
  if (isApplied && !isReverted) {
    buttons.push(`<button type="button" class="admin-button admin-button--secondary admin-button--small" data-note-revert title="Mark this applied change as reverted. Claude reads this on next session as undo instructions.">Revert</button>`);
  }
  // Delete — only when NOT applied (audit-trail rule preserved).
  if (!isApplied) {
    buttons.push(`<button type="button" class="admin-button admin-button--ghost admin-button--small admin-button--danger" data-note-delete title="Hard-delete this note. Replies cascade. Use Revert instead for applied notes.">Delete</button>`);
  }
  return buttons.join("");
}

function attachFocusedNoteHandlers(note, entityItem, analysis) {
  const root = el.noteFocused;
  if (!root) return;

  // Edit toggle.
  root.querySelector("[data-note-edit-toggle]")?.addEventListener("click", () => {
    root.querySelector("[data-note-body-display]")?.classList.add("is-hidden");
    root.querySelector("[data-note-edit-form]")?.classList.remove("is-hidden");
    root.querySelector("[data-note-edit-body]")?.focus();
  });
  root.querySelector("[data-note-edit-cancel]")?.addEventListener("click", () => {
    root.querySelector("[data-note-edit-form]")?.classList.add("is-hidden");
    root.querySelector("[data-note-body-display]")?.classList.remove("is-hidden");
  });
  root.querySelector("[data-note-edit-form]")?.addEventListener("submit", async (event) => {
    event.preventDefault();
    const body = root.querySelector("[data-note-edit-body]")?.value?.trim() || "";
    const intent = root.querySelector("[data-note-edit-intent]")?.value || "feedback";
    const target = root.querySelector("[data-note-edit-target]")?.value || "claude";
    if (!body) {
      alert("Note body can't be empty.");
      return;
    }
    await updateNoteFields(note.id, { body, intent, target });
  });

  // Mark applied / Revert / Delete.
  root.querySelector("[data-note-mark-applied]")?.addEventListener("click", async () => {
    if (!confirm("Mark this note as applied? Stamps applied_at = now + applied_commit = 'manual'. Useful when you resolved the change outside a Claude session.")) return;
    await markNoteApplied(note.id);
  });
  root.querySelector("[data-note-revert]")?.addEventListener("click", async () => {
    await revertNote(note.id);
    // Re-render the focused panel to pick up the reverted state.
    const fresh = state.notes.find((n) => n.id === note.id);
    if (fresh) renderFocusedNoteDetail(fresh);
  });
  root.querySelector("[data-note-delete]")?.addEventListener("click", async () => {
    await deleteNote(note.id);
    // deleteNote re-renders the notes view; clear selection so the
    // empty-state shows.
    if (state.notes.every((n) => n.id !== note.id)) {
      state.selected = null;
      el.noteFocused?.classList.add("is-hidden");
      el.detail.classList.add("is-hidden");
      el.emptyDetail.classList.remove("is-hidden");
    }
  });

  // View entity escape-hatch.
  root.querySelector("[data-note-view-entity]")?.addEventListener("click", () => {
    if (!entityItem) return;
    const targetView = viewIdForType(note.scopeType);
    state.view = targetView;
    state.selected = entityItem;
    render();
  });

  // Reply form.
  root.querySelector("[data-note-reply-form]")?.addEventListener("submit", async (event) => {
    event.preventDefault();
    const body = root.querySelector("[data-note-reply-body]")?.value?.trim() || "";
    if (!body) {
      alert("Reply can't be empty.");
      return;
    }
    await postNoteReply(note, body);
  });
}

// =============================================================================
// Phase 5z+10 — Plain-English note analyzer
// =============================================================================
//
// Tom's ask: "Your replies/feedback should be more focused on the feedback
// itself and if it is good/bad and why. keep it in english and not too
// technical remember we want normal people to be able to read this that
// know our app but not the deep technical parts of it."
//
// Returns four parts:
//
//   verdict     — short line: is this feedback good / soft / unclear?
//                 + one paragraph saying why.
//   ifApplied   — what would actually happen if we made this change?
//                 Plain English, business framing. No code names.
//   reach       — how many other things does this touch? Friendly counts.
//                 e.g. "12 other tasks in Plumbing", "6 households if
//                 we already shipped this".
//   alternative — when there's a smarter way, suggest it. null otherwise.
//
// Only invoked on Not Applied notes — applied notes show a historical
// card instead. The split keeps Claude's brain on what's still pending,
// per "you only give your feedback on the not applied changes so that we
// can figure out what the impacts are what actually happens."

function analyzeNote(note, entityItem) {
  const intent = note.intent || "feedback";
  const body = note.body || "";
  const lower = body.toLowerCase();
  const wordCount = (body.match(/\S+/g) || []).length;
  const ifApplied = [];
  const reach = [];
  let alternative = null;

  // --- Verdict ---
  // Plain-English read on whether the feedback is solid, useful, or thin.
  // Frame: did Tom give us enough to act on cleanly?
  const verdictParts = [];
  let tier = "medium";
  let verdictHeadline = "Worth a read";

  if (wordCount < 6) {
    tier = "low";
    verdictHeadline = "Could use more detail";
    verdictParts.push("This is short. Concrete asks usually need a sentence or two so we can act without guessing.");
  } else if (wordCount > 50) {
    verdictParts.push("Substantive — enough detail to act on.");
  } else {
    verdictParts.push("Reasonable detail — Claude can usually act on this without going back for clarification.");
  }

  if (!note.scopeType || note.scopeType === "general") {
    verdictParts.push("Not attached to a specific thing yet. Pin it to a quiz question, task template, routine, or vendor type from that entity's detail panel — that makes it much easier to act on.");
    if (tier !== "low") tier = "medium";
  } else {
    const friendlyScope = friendlyScopeLabel(note.scopeType);
    verdictParts.push(`Attached to ${friendlyScope === "vendor" ? "a vendor type" : `a ${friendlyScope}`} (${note.scopeTitle || "—"}) — Claude knows exactly where to make the change.`);
    if (tier === "low") tier = "medium";
  }

  // High-signal patterns — file paths, before/after, screenshot, structured diff.
  const mentionsFile = /\.(swift|ts|tsx|js|md|sql|json)\b/.test(lower) || /[A-Z][a-zA-Z0-9]+\.swift/.test(body);
  const hasTransformation = /\bbefore:|\bafter:|\bfrom:|\bto:|→|->|"[^"]+"\s*(?:to|→|->)\s*"[^"]+"/i.test(body);
  const hasAttachment = (note.attachmentUrls?.length || note.snapshot?.attachment_urls?.length || 0) > 0;
  if (mentionsFile) {
    verdictParts.push("Names specific files — easy to find the right spot.");
    tier = tier === "low" ? "medium" : "high";
  }
  if (hasTransformation) {
    verdictParts.push("Spells out what to change to what — an exact swap is possible.");
    tier = "high";
  }
  if (note.proposedDiff) {
    verdictParts.push("Includes a structured patch — Claude can apply it without guessing.");
    tier = "high";
  }
  if (hasAttachment && intent === "bug") {
    verdictParts.push("Includes a screenshot — that gives us a lot to go on.");
    tier = tier === "low" ? "medium" : "high";
  }

  // Is the ask validly aligned with the entity? E.g. asking to delete an
  // entity that has live dependents is suspicious.
  if (intent === "proposal_delete" && entityItem) {
    const t = entityItem.payload || {};
    const hasBundleChildren = t.bundleTitle && state.adminItems.some((i) => i.payload?.bundleId === t.bundleId && !i.payload?.bundleTitle);
    if (hasBundleChildren) {
      verdictParts.push("Heads up: this entity has sub-tasks rolled up under it. Removing it leaves them without a home — see the alternative below.");
    }
  }

  if (tier === "high") {
    verdictHeadline = "Strong ask";
  } else if (tier === "medium") {
    verdictHeadline = verdictHeadline === "Could use more detail" ? "Could use more detail" : "Worth a read";
  }

  // --- "If we apply this, here's what happens" ---
  switch (intent) {
    case "change_request": {
      ifApplied.push("On Claude's next pass through the code, this change gets made.");
      if (entityItem) {
        const t = entityItem.payload || {};
        if (note.scopeType === "task" || note.scopeType === "handyman" || note.scopeType === "recommended") {
          if (t.bundleTitle) {
            ifApplied.push(`This is a seasonal visit that bundles several individual chores together. The homeowner sees one scheduled task — "${t.bundleTitle}" — that covers all of them. Editing this changes what they see in their calendar.`);
          } else if (t.bundleId) {
            ifApplied.push("This chore is rolled up inside a larger seasonal visit. Homeowners never see it as its own task — it shows up in the 'What's included' checklist on the parent visit.");
          }
          if (t.requiredSubtypes?.length) {
            ifApplied.push(`Only homes that match certain conditions get this task (${t.requiredSubtypes.map(humanizeSubtype).join(", ")}). Other households won't see it at all.`);
          }
          if (t.assignmentType === "vendor") {
            ifApplied.push("Always done by a pro — never DIY-ed. The homeowner sees it as 'Schedule X: …' once their vendor is on file.");
          } else if (t.assignmentType === "personal") {
            ifApplied.push("DIY-only — the homeowner does this themselves. The Q36 preference slider can't flip it to a pro.");
          } else if (t.assignmentType === "either") {
            ifApplied.push("Defaults to DIY but the homeowner can hand it off to a pro. Q36 preference + the delegation sheet can flip it.");
          }
          if (t.isEssential === false) {
            ifApplied.push("This is opt-in — never auto-added. The homeowner picks it up from Recommended Services or the handyman punch list.");
          }
        } else if (note.scopeType === "routine") {
          ifApplied.push("Changing this routine updates every household using it. Tasks parented under it on people's calendars also update.");
        } else if (note.scopeType === "question") {
          ifApplied.push("Anyone in the middle of taking the quiz might see this question shift. Their previous answers may need a one-time fix-up to stay aligned.");
        } else if (note.scopeType === "system") {
          ifApplied.push("Changing a system category affects every household that has this system on file.");
        } else if (note.scopeType === "vendor") {
          ifApplied.push("Vendor type changes affect Q15b in the quiz, the maintenance task router, and the Contacts hub on the property page.");
        }
      } else {
        ifApplied.push("Because this isn't pinned to a specific entity, Claude will read the body and try to figure out where it belongs. Pinning it to the right thing makes the change safer.");
      }
      // Body keyword detection — surface intent inferred from words used.
      if (/\b(delete|remove|drop|cut|kill)\b/.test(lower) && !/drop[-\s]?off/.test(lower)) {
        ifApplied.push("The wording suggests removal. Worth checking what depends on this entity before applying — see Reach below.");
      }
      if (/\b(rename|relabel|reword|change.*to)\b/.test(lower)) {
        ifApplied.push("The wording suggests a rename. Claude will preserve the underlying ID so existing households keep their data.");
      }
      if (/\b(merge|combine|fold)\b/.test(lower)) {
        ifApplied.push("The wording suggests merging two things. Claude will keep the better one and archive the other.");
      }
      break;
    }
    case "proposal_add": {
      ifApplied.push("Claude evaluates the proposal on the next pass — if the idea holds up, the new entity gets added.");
      if (note.scopeType && entityItem) {
        ifApplied.push(`Anchored on an existing ${friendlyScopeLabel(note.scopeType)} — Claude can model the new one after this template's shape.`);
      }
      // Look for similar existing entities to suggest a merge instead.
      if (state.adminItems.length && note.body) {
        const tokens = lower.split(/\s+/).filter((t) => t.length > 4);
        const candidates = state.adminItems
          .filter((i) => i.id !== note.scopeId)
          .map((i) => {
            const title = (i.title || "").toLowerCase();
            const overlap = tokens.filter((t) => title.includes(t)).length;
            return { item: i, overlap };
          })
          .filter((c) => c.overlap >= 3)
          .sort((a, b) => b.overlap - a.overlap)
          .slice(0, 3);
        if (candidates.length) {
          alternative = {
            headline: "Maybe edit one of these instead?",
            body: `${candidates.length} similar thing${candidates.length === 1 ? "" : "s"} already in the app: ${candidates.map((c) => `"${c.item.title}"`).join(", ")}. If your idea overlaps with any of them, editing the existing one is usually cleaner than adding a new one. Adds blur the catalog over time; edits sharpen it.`,
          };
        }
      }
      break;
    }
    case "proposal_delete": {
      if (entityItem) {
        const t = entityItem.payload || {};
        if (note.scopeType === "task" || note.scopeType === "recommended" || note.scopeType === "handyman") {
          if (t.bundleTitle) {
            const childCount = state.adminItems.filter((i) => i.payload?.bundleId === t.bundleId && !i.payload?.bundleTitle).length;
            ifApplied.push(`Removing this seasonal visit leaves ${childCount} sub-task${childCount === 1 ? "" : "s"} without a home. They'd either need to be deleted too or moved into another visit.`);
            reach.push({ label: "sub-tasks affected", count: childCount });
            alternative = {
              headline: "Try opt-in instead of removing",
              body: "Mark it as opt-in (it stops auto-adding to new households but stays available in Recommended Services). Existing households keep what they already have. If it really needs to disappear, do that in a follow-up after seeing the opt-in numbers.",
            };
          } else {
            ifApplied.push("Single template removed — won't show up on new household schedules. Existing tasks stay until they're completed or archived.");
          }
        } else if (note.scopeType === "question") {
          ifApplied.push("Removing a quiz question changes the question count for every in-flight household. Their progress bar might jump or their answers above might re-flow.");
          alternative = {
            headline: "Hide it before deleting",
            body: "Mark the question as 'cut' first so it stops appearing but the existing answers stay readable for analytics. Hard delete in a later cleanup pass after we're sure nothing references it.",
          };
        } else if (note.scopeType === "vendor") {
          ifApplied.push("Removing a vendor type means the Q15b chip disappears for new households and any tasks that route to this vendor will lose their default assignee.");
        }
      }
      ifApplied.push("Once it's gone, it's gone. This note will be the only record of why we removed it.");
      break;
    }
    case "bug": {
      ifApplied.push("Claude tries to reproduce and fix this in the next pass.");
      if (!hasAttachment) {
        ifApplied.push("Adding a screenshot would help reproduce it.");
      }
      if (entityItem) {
        ifApplied.push(`The likely place to look: ${friendlyScopeLabel(note.scopeType)} → "${entityItem.title || note.scopeTitle || "—"}".`);
      }
      break;
    }
    case "idea": {
      ifApplied.push("Parked for later thinking. Claude won't act on this next session — it's here for when we revisit the bigger direction.");
      break;
    }
    case "question_for_claude": {
      ifApplied.push("Claude will answer this in a reply — no code changes happen until we agree on the answer.");
      break;
    }
    case "feedback":
    default: {
      ifApplied.push("Observation only. Nothing happens automatically — if you want a change made, switch the intent to 'Change request' or write a follow-up note.");
      break;
    }
  }

  // --- Reach (cross-references in plain English) ---
  // Sibling notes on the same entity.
  if (note.scopeId) {
    const siblings = state.notes.filter((n) => n.scopeId === note.scopeId && n.id !== note.id && !n.parentNoteId);
    if (siblings.length) reach.push({ label: `other note${siblings.length === 1 ? "" : "s"} on the same thing`, count: siblings.length });
  }
  // Replies on this note.
  const replyCount = state.notes.filter((n) => n.parentNoteId === note.id).length;
  if (replyCount) reach.push({ label: `repl${replyCount === 1 ? "y" : "ies"} on this note`, count: replyCount });
  // Templates sharing the same category.
  if (entityItem?.payload?.systemCategory) {
    const cat = entityItem.payload.systemCategory;
    const same = state.adminItems.filter((i) => i.payload?.systemCategory === cat && i.id !== entityItem.id).length;
    if (same) reach.push({ label: `other tasks in the ${cat} category`, count: same });
  }
  // Bundle siblings.
  if (entityItem?.payload?.bundleId && !entityItem.payload?.bundleTitle) {
    const bundle = entityItem.payload.bundleId;
    const siblings = state.adminItems.filter((i) => i.payload?.bundleId === bundle && i.id !== entityItem.id).length;
    const friendly = bundle.replace(/Handyman:/, "").replace(/[_-]/g, " ").trim() || bundle;
    if (siblings) reach.push({ label: `other items in the ${friendly} visit`, count: siblings });
  }

  return {
    verdict: { tier, headline: verdictHeadline, reasons: verdictParts },
    ifApplied,
    reach,
    alternative,
  };
}

// Phase 5z+10 — translate scope_type values into noun phrases normal
// users recognize. Keeps the analyzer text out of code-jargon land.
function friendlyScopeLabel(scopeType) {
  return (
    {
      question: "quiz question",
      task: "maintenance task",
      handyman: "handyman item",
      recommended: "recommended service",
      routine: "routine",
      system: "home system",
      vehicle: "vehicle prompt",
      prompt: "AI prompt",
      vendor: "vendor",
    }[scopeType] || scopeType || "thing"
  );
}

// Phase 5z+10 — translate raw subtype tokens into human phrases.
// "has_pool" → "homes with a pool", "has_well" → "homes on well water",
// etc. Falls back to the raw token if unknown.
function humanizeSubtype(token) {
  const map = {
    has_pool: "homes with a pool",
    has_hot_tub: "homes with a hot tub",
    has_septic: "homes on septic",
    has_well: "homes on well water",
    has_solar: "homes with solar",
    has_generator: "homes with a generator",
    has_pets: "homes with pets",
    has_humidifier: "homes with whole-home humidifiers",
    has_ev_charger: "homes with EV chargers",
    has_leak_detector: "homes with smart leak detectors",
    has_central_vacuum: "homes with central vacuum",
    has_built_in_grill: "homes with a built-in grill",
    has_outdoor_lighting: "homes with outdoor lighting",
    has_radon_mitigation: "homes with radon mitigation",
    has_pool_safety_fence: "homes with a pool safety fence",
    has_scheduled_valuables: "homes with scheduled valuables coverage",
    pool_chlorine: "chlorine pools",
    pool_salt: "salt pools",
    natural: "homes with natural lawn",
    synthetic_turf: "homes with synthetic turf",
    hardscape: "mostly-hardscape yards",
    has_irrigation: "homes with irrigation",
    has_fireplace_wood: "homes with a wood fireplace",
    has_fireplace_gas: "homes with a gas fireplace",
    has_chimney: "homes with a chimney",
  };
  return map[token] || token.replace(/^has_/, "").replace(/_/g, " ");
}

function entityPreviewCardHtml(item, note) {
  // Phase 5z+10 — friendly labels + value translation. Replaces raw
  // field names like "templateKey" / "requiredSubtypes" / "bundleId"
  // with phrases a non-engineer reads at a glance ("Internal ID",
  // "Only for homes with...", "Part of bundle"). Keeps the row dense
  // but readable.
  const t = item.payload || {};
  const rows = [];
  const push = (label, rawValue, transform) => {
    if (rawValue === undefined || rawValue === null || rawValue === "" || (Array.isArray(rawValue) && rawValue.length === 0)) return;
    let display;
    if (transform) {
      display = transform(rawValue);
    } else if (Array.isArray(rawValue)) {
      display = rawValue.join(", ");
    } else if (typeof rawValue === "boolean") {
      display = rawValue ? "Yes" : "No";
    } else {
      display = String(rawValue);
    }
    rows.push(`<dt>${escapeHtml(label)}</dt><dd>${escapeHtml(display)}</dd>`);
  };
  // Per-scope field rendering with humanized labels + values.
  if (note.scopeType === "task" || note.scopeType === "handyman" || note.scopeType === "recommended") {
    push("Category", t.systemCategory || item.category);
    push("How often", t.frequency);
    push("Time of year", t.seasonalTiming);
    push("Who handles it", t.assignmentType, (v) => ({
      vendor: "A pro (always — never DIY)",
      personal: "Homeowner (DIY only)",
      either: "Either / depends on preference",
    }[v] || v));
    push("Auto-added on quiz?", t.isEssential !== false ? "Yes — every household that qualifies" : "No — homeowner opts in");
    push("Only for homes with…", t.requiredSubtypes, (v) => v.map(humanizeSubtype).join(" · "));
    if (t.bundleTitle) {
      push("Seasonal visit", t.bundleTitle);
    } else if (t.bundleId) {
      push("Part of visit", t.bundleId.replace(/Handyman:/, "").replace(/[_-]/g, " "));
    }
    if (t.diyEffortMinutes) push("DIY effort", `~${t.diyEffortMinutes} min`);
    if (t.safetyFloor) push("Safety required?", "Yes — must be a pro");
    push("Internal ID", t.templateKey);
  } else if (note.scopeType === "routine") {
    push("Kind", t.routineKind || t.routine_kind);
    push("Cadence", t.cadenceType || t.cadence_type);
    push("Active months", t.activeMonths || t.active_months);
    push("Setup state", t.setupState || t.setup_state);
  } else if (note.scopeType === "question") {
    push("Question ID", t.questionId || t.id);
    push("Kind", t.kind);
    if (t.prompt || t.text) push("Prompt", (t.prompt || t.text).slice(0, 200) + ((t.prompt || t.text).length > 200 ? "…" : ""));
    if (t.options?.length) push("Choices", `${t.options.length} options`);
  } else if (note.scopeType === "system") {
    push("Internal key", t.categoryKey);
    push("Tier", t.tier);
    push("Priority", t.priority);
  } else if (note.scopeType === "vehicle") {
    push("Make", t.make);
    push("Model", t.model);
    push("Year", t.year);
  } else if (note.scopeType === "prompt") {
    push("Function", t.functionName);
    push("Description", t.description);
  } else if (note.scopeType === "vendor") {
    if (t.role) push("Role", t.role);
    if (t.whatTheyHandle) push("What they handle", t.whatTheyHandle);
    if (t.whenTheyAppear) push("When they appear", t.whenTheyAppear);
    if (t.howTheyConnect) push("How they connect", t.howTheyConnect);
  }
  return `
    <div class="admin-note-focused__entity">
      <strong>${escapeHtml(item.title || note.scopeTitle || "—")}</strong>
      ${item.description ? `<p class="admin-muted admin-note-focused__entity-desc">${escapeHtml(item.description)}</p>` : ""}
      <dl class="admin-note-focused__entity-fields">
        ${rows.join("")}
      </dl>
    </div>
  `;
}

function analysisCardHtml(analysis) {
  // Phase 5z+10 — Verdict tier mapping. Plain-English labels Tom's HNW
  // operators read at a glance. Tone maps into the existing pill palette.
  const tierLabel = { high: "Strong ask", medium: "Worth a read", low: "Could use more detail" }[analysis.verdict.tier] || "Worth a read";
  const tierTone = { high: "active", medium: "draft", low: "cut" }[analysis.verdict.tier] || "draft";
  return `
    <div class="admin-note-focused__analysis">
      <div class="admin-note-focused__analysis-row admin-note-focused__analysis-row--block">
        <div class="admin-note-focused__analysis-headline">
          <strong>${escapeHtml(analysis.verdict.headline)}</strong>
          <span class="admin-pill" data-tone="${escapeHtml(tierTone)}">${escapeHtml(tierLabel)}</span>
        </div>
        ${analysis.verdict.reasons.length ? `
          <ul class="admin-note-focused__analysis-list">
            ${analysis.verdict.reasons.map((r) => `<li>${escapeHtml(r)}</li>`).join("")}
          </ul>
        ` : ""}
      </div>

      ${analysis.ifApplied.length ? `
        <div class="admin-note-focused__analysis-row admin-note-focused__analysis-row--block">
          <strong>If we apply this</strong>
          <ul class="admin-note-focused__analysis-list">
            ${analysis.ifApplied.map((s) => `<li>${escapeHtml(s)}</li>`).join("")}
          </ul>
        </div>
      ` : ""}

      ${analysis.reach.length ? `
        <div class="admin-note-focused__analysis-row admin-note-focused__analysis-row--block">
          <strong>What else this touches</strong>
          <div class="admin-note-focused__blast">
            ${analysis.reach.map((b) => `
              <span class="admin-note-focused__blast-pill">
                <strong>${b.count}</strong>
                <span>${escapeHtml(b.label)}</span>
              </span>
            `).join("")}
          </div>
        </div>
      ` : ""}

      ${analysis.alternative ? `
        <div class="admin-note-focused__analysis-row admin-note-focused__analysis-row--block admin-note-focused__alternative">
          <strong>A better approach?</strong>
          <p><strong>${escapeHtml(analysis.alternative.headline)}</strong></p>
          <p class="admin-muted">${escapeHtml(analysis.alternative.body)}</p>
        </div>
      ` : ""}
    </div>
  `;
}

// Phase 5z+10 — Historical card for Applied / Reverted notes. Replaces
// the analysis section on the focused note panel when the change has
// already happened. No analysis — just the resolved-history record.
function historicalCardHtml(note) {
  const isReverted = !!note.revertedAt;
  if (isReverted) {
    return `
      <div class="admin-note-focused__history">
        <p>
          This was applied on <strong>${escapeHtml(formatDate(note.appliedAt))}</strong>${
            note.appliedCommit ? ` (commit <code>${escapeHtml(note.appliedCommit.slice(0, 7))}</code>)` : ""
          } and then <strong>reverted</strong> on ${escapeHtml(formatDate(note.revertedAt))}.
        </p>
        <p class="admin-muted">
          Claude will read the revert as undo instructions on the next session — the original change gets rolled back.
        </p>
      </div>
    `;
  }
  const manual = note.appliedCommit === "manual";
  return `
    <div class="admin-note-focused__history">
      <p>
        Resolved on <strong>${escapeHtml(formatDate(note.appliedAt))}</strong>${
          note.appliedCommit && !manual ? ` in commit <code>${escapeHtml(note.appliedCommit.slice(0, 7))}</code>` : ""
        }${manual ? " (marked done manually)" : ""}.
      </p>
      <p class="admin-muted">
        ${manual
          ? "You marked this resolved without a Claude code change — useful when the work happened outside the session."
          : "Claude applied this change in a code-shipping session. The note stays here as the audit trail."}
        No further action unless you click <strong>Revert</strong> to undo it.
      </p>
    </div>
  `;
}

function intentTone(intent) {
  return (
    {
      change_request: "active",
      proposal_add: "active",
      proposal_delete: "cut",
      bug: "cut",
      idea: "draft",
      question_for_claude: "reshape",
      feedback: "draft",
    }[intent] || "draft"
  );
}

// Phase 5z+9 — Update an existing note's body / intent / target inline.
// Used by the focused panel's Edit form. Cloud writes go through the
// admin_codex_notes UPDATE; local fallback rewrites the in-memory store.
async function updateNoteFields(noteId, patch) {
  if (!noteId) return;
  if (state.storageMode === "cloud") {
    try {
      const { data, error } = await supabase
        .from("admin_codex_notes")
        .update({
          body: patch.body,
          intent: patch.intent,
          target: patch.target,
        })
        .eq("id", noteId)
        .select("*")
        .single();
      if (error) throw error;
      state.notes = state.notes.map((n) => (n.id === noteId ? dbNoteToUi(data) : n));
    } catch (error) {
      alert(`Save failed: ${error.message}`);
      return;
    }
  } else {
    state.notes = state.notes.map((n) => (n.id === noteId ? { ...n, body: patch.body, intent: patch.intent, target: patch.target } : n));
    writeLocal(LOCAL_NOTES_KEY, state.notes);
  }
  // Re-render notes list + focused panel.
  if (state.view === "notes") {
    const fresh = state.notes.find((n) => n.id === noteId);
    if (fresh) state.selected = fresh;
    renderNotesView();
  }
}

// Phase 5z+9 — Manually mark a note as applied. Stamps applied_at = now,
// applied_commit = "manual" so syncing scripts can distinguish from
// scripted-applies. Used when Tom resolves a note outside Claude.
async function markNoteApplied(noteId) {
  if (!noteId) return;
  const stamp = new Date().toISOString();
  if (state.storageMode === "cloud") {
    try {
      const { data, error } = await supabase
        .from("admin_codex_notes")
        .update({ applied_at: stamp, applied_commit: "manual" })
        .eq("id", noteId)
        .select("*")
        .single();
      if (error) throw error;
      state.notes = state.notes.map((n) => (n.id === noteId ? dbNoteToUi(data) : n));
    } catch (error) {
      alert(`Mark applied failed: ${error.message}`);
      return;
    }
  } else {
    state.notes = state.notes.map((n) => (n.id === noteId ? { ...n, appliedAt: stamp, appliedCommit: "manual" } : n));
    writeLocal(LOCAL_NOTES_KEY, state.notes);
  }
  if (state.view === "notes") {
    const fresh = state.notes.find((n) => n.id === noteId);
    if (fresh) state.selected = fresh;
    renderNotesView();
  }
}

// Phase 5z+9 — Post a reply to a parent note from inside the focused
// panel. Reuses the existing writeNote helper so scope/snapshot/etc
// stay consistent with how the entity-pane reply flow works.
async function postNoteReply(parent, body) {
  if (!parent || !body) return;
  await writeNote({
    parentNoteId: parent.id,
    scopeType: parent.scopeType,
    scopeId: parent.scopeId,
    scopeTitle: parent.scopeTitle,
    body,
    intent: "feedback",
    target: parent.target || "claude",
    snapshot: parent.snapshot ?? {},
  });
  if (state.view === "notes") {
    renderNotesView();
  }
}

function renderContextNotes(item) {
  const allMatching = state.notes.filter((note) => itemNoteMatches(note, item));
  if (!allMatching.length) {
    el.contextNotes.innerHTML = `
      <div class="admin-note-card">
        <strong>No notes on this item yet.</strong>
        <pre>Write one above. The note auto-captures the entity's full Swift configuration so Claude can act on it next session without re-exploring.</pre>
      </div>
    `;
    return;
  }

  // Phase 5 — thread by parent_note_id so Claude's replies nest under
  // Tom's original notes inline.
  const byId = new Map(allMatching.map((n) => [n.id, { ...n, replies: [] }]));
  const top = [];
  for (const n of allMatching) {
    const wrapped = byId.get(n.id);
    if (n.parentNoteId && byId.has(n.parentNoteId)) {
      byId.get(n.parentNoteId).replies.push(wrapped);
    } else {
      top.push(wrapped);
    }
  }
  top.sort((a, b) => +new Date(b.createdAt) - +new Date(a.createdAt));
  for (const t of top) {
    t.replies.sort((a, b) => +new Date(a.createdAt) - +new Date(b.createdAt));
  }

  const limit = 8;
  el.contextNotes.innerHTML = top.slice(0, limit).map((note) => renderNoteCard(note, 0)).join("");
  if (top.length > limit) {
    el.contextNotes.innerHTML += `<p class="admin-muted" style="margin-top:8px">…and ${top.length - limit} more older notes (Notes tab to see all).</p>`;
  }
  // Wire revert buttons
  el.contextNotes.querySelectorAll("[data-revert-note]").forEach((btn) => {
    btn.addEventListener("click", async (event) => {
      event.stopPropagation();
      await revertNote(btn.dataset.revertNote);
    });
  });
  // Phase 5z+3 — Wire delete buttons on each note card.
  el.contextNotes.querySelectorAll("[data-delete-note]").forEach((btn) => {
    btn.addEventListener("click", async (event) => {
      event.stopPropagation();
      await deleteNote(btn.dataset.deleteNote);
    });
  });
}

function renderNoteCard(note, depth) {
  const intent = note.intent || "feedback";
  const author = note.author || "tom";
  const isApplied = !!note.appliedAt;
  const isReverted = !!note.revertedAt;
  const pill = isApplied
    ? `<span class="admin-pill" data-tone="active" title="Applied ${formatDate(note.appliedAt)}${
        note.appliedCommit ? " · " + note.appliedCommit.slice(0, 7) : ""
      }">applied</span>`
    : isReverted
    ? `<span class="admin-pill" data-tone="cut">reverted</span>`
    : `<span class="admin-pill admin-pill--note">${escapeHtml(intent)}</span>`;
  const authorTag = author === "claude"
    ? `<span class="admin-pill admin-pill--note">claude</span>`
    : "";
  const revertBtn = isApplied && !isReverted
    ? `<button type="button" class="admin-button admin-button--secondary admin-button--xs" data-revert-note="${escapeHtml(note.id)}">Revert</button>`
    : "";
  // Phase 5z+3 — Delete button on every note card. Only enabled for
  // notes that haven't been applied yet (applied notes need to use
  // Revert instead — keeps the audit trail of what changed).
  const deleteBtn = !isApplied
    ? `<button type="button" class="admin-button admin-button--ghost admin-button--xs admin-button--danger" data-delete-note="${escapeHtml(note.id)}" title="Delete this note. Replies (if any) are also removed because parent_note_id has ON DELETE CASCADE.">Delete</button>`
    : "";
  const attachments = (note.snapshot?.attachment_urls || note.attachmentUrls || [])
    .map((url) => `<img src="${escapeHtml(url)}" alt="attachment" class="admin-note-card__attachment" />`)
    .join("");
  const replies = (note.replies || [])
    .map((reply) => renderNoteCard(reply, depth + 1))
    .join("");
  return `
    <article class="admin-note-card admin-note-card--depth-${Math.min(depth, 2)}" ${depth > 0 ? 'data-reply="true"' : ""}>
      <div class="admin-note-card__top">
        <strong>${escapeHtml(note.scopeTitle || "Context note")}</strong>
        ${pill}
        ${authorTag}
      </div>
      <small>${escapeHtml(formatDate(note.createdAt))} · target: ${escapeHtml(note.target || "claude")}</small>
      <pre>${escapeHtml(note.body || "")}</pre>
      ${attachments ? `<div class="admin-note-card__attachments">${attachments}</div>` : ""}
      ${(revertBtn || deleteBtn) ? `<div class="admin-note-card__actions">${revertBtn}${deleteBtn}</div>` : ""}
      ${replies}
    </article>
  `;
}

// Phase 5 — flip applied note to reverted; Claude reads this as "undo"
// instructions on next session start.
async function revertNote(noteId) {
  if (!noteId) return;
  if (!confirm("Mark this applied change as reverted? Claude will apply the reverse next session.")) return;
  if (state.storageMode !== "cloud") {
    alert("Revert requires cloud storage.");
    return;
  }
  try {
    const { data, error } = await supabase
      .from("admin_codex_notes")
      .update({ reverted_at: new Date().toISOString() })
      .eq("id", noteId)
      .select("*")
      .single();
    if (error) throw error;
    state.notes = state.notes.map((n) => (n.id === noteId ? dbNoteToUi(data) : n));
    // Phase 5z+9 — view-aware refresh. The legacy code called
    // renderContextNotes(state.selected) which only works when
    // state.selected is an ENTITY. On the Notes tab state.selected is
    // a NOTE, so we re-route to renderNotesView (which re-opens the
    // focused panel via state.selected = fresh note).
    if (state.view === "notes") {
      const fresh = state.notes.find((n) => n.id === noteId);
      if (fresh) state.selected = fresh;
      renderNotesView();
    } else if (state.selected) {
      renderContextNotes(state.selected);
    } else {
      renderActivityView();
    }
  } catch (error) {
    alert(`Revert failed: ${error.message}`);
  }
}

// Phase 5z+3 — Delete a note. Differs from Revert: revert keeps the
// row in admin_codex_notes with reverted_at stamped (audit trail);
// delete actually removes the row. Only allowed for notes that
// haven't been applied yet — applied notes must use Revert.
async function deleteNote(noteId) {
  if (!noteId) return;
  const note = state.notes.find((n) => n.id === noteId);
  if (!note) return;
  if (note.appliedAt) {
    alert("This note has already been applied. Use Revert instead so the audit trail stays intact.");
    return;
  }
  const replyCount = state.notes.filter((n) => n.parentNoteId === noteId).length;
  const replyHint = replyCount > 0 ? ` This will also delete ${replyCount} ${replyCount === 1 ? "reply" : "replies"} (parent_note_id has ON DELETE CASCADE).` : "";
  const preview = (note.body || "").slice(0, 80);
  if (!confirm(`Delete this note?${replyHint}\n\n"${preview}${(note.body || "").length > 80 ? "…" : ""}"`)) return;
  if (state.storageMode === "cloud") {
    try {
      const { error } = await supabase
        .from("admin_codex_notes")
        .delete()
        .eq("id", noteId);
      if (error) throw error;
    } catch (error) {
      alert(`Delete failed: ${error.message}`);
      return;
    }
  }
  // Local state — drop the note + any cascading replies.
  state.notes = state.notes.filter((n) => n.id !== noteId && n.parentNoteId !== noteId);
  // Re-render the right surface.
  if (state.view === "notes") {
    renderNotesView();
  } else if (state.selected) {
    renderContextNotes(state.selected);
  } else if (state.view === "activity") {
    renderActivityView();
  }
}

function itemNoteMatches(note, item) {
  // Phase 4: live entities expose ids under different keys per surface.
  // Quiz: id (e.g. "q3_heating_fuel"). Templates: templateKey / stableId.
  // Systems: categoryKey. Routines: rawValue / swiftCase. Edge fns:
  // functionName. Vehicles: synthetic "vehicle-prompt".
  const possibleIds = new Set([
    item.id,
    item.payload?.id,
    item.payload?.questionId,
    item.payload?.templateKey,
    item.payload?.stableId,
    item.payload?.categoryKey,
    item.payload?.functionName,
    item.payload?.rawValue,
    item.payload?.swiftCase,
    `${item.category || ""}:${item.title || ""}`,
  ].filter(Boolean).map(String));
  return note.scopeType === item.itemType
    && (possibleIds.has(String(note.scopeId || "")) || note.scopeTitle === item.title);
}

function itemRowHtml(item) {
  const isActive = state.selected?.id === item.id;
  const meta = [
    item.source,
    item.category,
    item.payload?.kind,
    item.payload?.operationalType,
    item.payload?.cadence,
    item.payload?.routing,
    item.payload?.assignmentType,
    item.payload?.frequency,
  ].filter(Boolean);
  const noteCount = state.notes.filter((n) => itemNoteMatches(n, item)).length;
  const noteBadge = noteCount > 0
    ? `<span class="admin-pill admin-pill--note">${noteCount} note${noteCount === 1 ? "" : "s"}</span>`
    : "";
  const lintBadge = item.lintCount > 0
    ? `<span class="admin-pill admin-pill--lint" title="${item.lintCount} voice-lint hit(s)">${item.lintCount} lint</span>`
    : "";
  // Phase 7.5 — launch lifecycle pill
  const launch = effectiveLaunchStatus(item);
  const launchBadge = launch && launch !== "draft"
    ? `<span class="admin-pill admin-pill--launch" data-tone="${launch}">${escapeHtml(launch)}</span>`
    : "";
  // Phase 5p — handyman bucket pill so Tom can scan the library for
  // auto-populating items vs. opt-in library items at a glance.
  let handymanBadge = "";
  if (item.itemType === "handyman") {
    if (item.payload?._autoPopulates === "spring") {
      handymanBadge = `<span class="admin-pill admin-pill--bundle-spring" title="Auto-populates the spring handyman punch list">🌷 Auto-pops</span>`;
    } else if (item.payload?._autoPopulates === "fall") {
      handymanBadge = `<span class="admin-pill admin-pill--bundle-fall" title="Auto-populates the fall handyman punch list">🍂 Auto-pops</span>`;
    } else if (item.payload?._libraryOnly) {
      handymanBadge = `<span class="admin-pill admin-pill--library" title="Library item — opt-in via Recommended Services">🛠️ Library</span>`;
    }
  }
  // Phase 5q/5z+16 — Lifecycle badge: explicit "what happens to this
  // template when a homeowner finishes the quiz?" pill on every row.
  // Tom: "we need to see also in the tasks view which ones can
  // populate automatically after a quiz so we know which tasks show
  // up and which ones dont."
  //
  // Three buckets:
  //   ✨ Auto-seeds                 — fires for every household
  //   ✨ Auto-seeds (conditional)   — fires only when subtype gate matches
  //   📚 Opt-in                     — never auto-seeds; homeowner adds it
  //
  // Bundle children fall through to the routingBadge (which shows the
  // parent visit + sibling count) — no separate lifecycle badge.
  let lifecycleBadge = "";
  let seasonBadge = "";
  if (["task", "recommended", "handyman"].includes(item.itemType)) {
    const t = item.payload || {};
    const isBundleChild = t.bundleId && !t.bundleTitle;
    if (!isBundleChild) {
      if (t.isEssential === false) {
        // Opt-in — only show on Tasks (Recommended tab is implicitly
        // all opt-in, so the badge would be noise).
        if (state.view !== "recommended") {
          const optInSurface = t.systemCategory === "Handyman"
            ? "Never auto-seeds. Homeowner adds it via the handyman punch list 'Recommended' section."
            : "Never auto-seeds. Homeowner adds it via Recommended Services on the property page.";
          lifecycleBadge = `<span class="admin-pill admin-pill--optin" title="${escapeHtml(optInSurface)}">📚 Opt-in</span>`;
        }
      } else if (state.view === "tasks") {
        // Auto-seeds — show on Tasks tab so Tom sees at a glance which
        // templates actually fire when a homeowner finishes the quiz.
        if (t.requiredSubtypes?.length) {
          const subtypeList = t.requiredSubtypes.map((s) => (typeof humanizeSubtype === "function" ? humanizeSubtype(s) : s)).join(", ");
          lifecycleBadge = `<span class="admin-pill admin-pill--autoseed-conditional" title="Auto-seeds at quiz completion only for ${escapeHtml(subtypeList)}.">✨ Auto-seeds (conditional)</span>`;
        } else {
          lifecycleBadge = `<span class="admin-pill admin-pill--autoseed" title="Auto-seeds at quiz completion for every household.">✨ Auto-seeds</span>`;
        }
      }
    }
    if (t.seasonalTiming) {
      const seasonEmoji = { Spring: "🌷", Summer: "☀️", Fall: "🍂", Winter: "❄️", "Spring/Fall": "🔁" }[t.seasonalTiming] || "";
      seasonBadge = seasonEmoji
        ? `<span class="admin-pill admin-pill--season" title="${escapeHtml(t.seasonalTiming)} task">${seasonEmoji} ${escapeHtml(t.seasonalTiming)}</span>`
        : "";
    }
  }
  // Phase 5q — Routing-reason badge: shows WHICH lane this template
  // lands in AND WHY (which template-author rule matched). Every row
  // gets one so the routing taxonomy is scannable, not a black box.
  let routingBadge = "";
  if (["task", "recommended", "handyman"].includes(item.itemType)) {
    const reason = routingReason(item.payload || {});
    if (reason) {
      routingBadge = `<span class="admin-pill admin-pill--routing-${reason.tier}" title="${escapeHtml(reason.tooltip)}">${escapeHtml(reason.label)}</span>`;
    }
  }
  // Phase 5x — list row reflects the shadow's disposition (cut/defer/
  // reshape) when one exists, so a curation decision shows on the
  // single visible row instead of disappearing with the hidden shadow.
  const status = effectiveStatus(item);
  // Phase 5z+6 — Pack pills into a dedicated container so they sit
  // tightly together (4px gap) instead of spreading across the row
  // via space-between. Pills wrap as a unit when the row is narrow.
  const statusPill = `<span class="admin-pill" data-tone="${escapeHtml(status)}">${escapeHtml(prettifyEnum(status))}</span>`;
  const allPills = [
    statusPill, handymanBadge, lifecycleBadge, routingBadge,
    seasonBadge, launchBadge, lintBadge, noteBadge,
  ].filter((p) => p && p.trim()).join("");
  return `
    <button class="admin-list-item ${isActive ? "is-active" : ""}" data-item-id="${escapeHtml(item.id)}">
      <div class="admin-list-item__top">
        <strong>${escapeHtml(item.title)}</strong>
        <span class="admin-list-item__pills">${allPills}</span>
      </div>
      <p>${escapeHtml(item.description || "").slice(0, 220)}</p>
      <div class="admin-list-item__meta">
        ${meta.map((m) => `<span>${escapeHtml(String(m))}</span>`).join("")}
      </div>
    </button>
  `;
}

// Phase 5q — Why does this template route the way it does? Returns
// { tier, label, tooltip } where tooltip is a plain-English explanation
// of which template-author rule (in MaintenanceTemplates.swift) matched.
// Tooltip is what shows on hover — full sentence so Tom can read the
// rationale without opening the row.
function routingReason(t) {
  if (!t) return null;
  if (t.bundleId) {
    const parentTitle = prettyBundleTitle(t.bundleId);
    const siblings = countBundleSiblings(t.bundleId);
    // Phase 5y — Differentiate bundle PARENT (has bundleTitle, IS the
    // homeowner-facing task) from child siblings (no bundleTitle, fold
    // into the parent at runtime).
    if (t.bundleTitle) {
      return {
        tier: "bundled",
        label: `Bundles ${siblings - 1} child${siblings - 1 === 1 ? "" : "ren"}`,
        tooltip:
          `Bundle parent — this template IS the homeowner's task. ${siblings - 1} other template${siblings - 1 === 1 ? "" : "s"} fold into this single visit at runtime; the homeowner sees ONE scheduled task ("${t.bundleTitle}") instead of ${siblings} separate to-dos. ` +
          `Trigger: bundleTitle = "${t.bundleTitle}" + bundleId = "${t.bundleId}" in MaintenanceTemplates.swift.`,
      };
    }
    return {
      tier: "bundled",
      label: `↳ ${parentTitle}`,
      tooltip:
        `Bundled into "${parentTitle}" with ${siblings - 1} sibling${siblings - 1 === 1 ? "" : "s"}. ` +
        `The vendor handles ${siblings} items in ONE scheduled visit instead of ${siblings} separate task rows. ` +
        `Trigger: bundleId = "${t.bundleId}" in MaintenanceTemplates.swift.`,
    };
  }
  if (t.safetyFloor === true) {
    return {
      tier: "vendor",
      label: "Vendor",
      tooltip:
        "Vendor — safety floor. Hard-stop rule: tasks marked safetyFloor: true (gas service, panel work, " +
        "roof, septic, generator) always route to a pro regardless of homeowner preference tier. " +
        "Trigger: safetyFloor: true in MaintenanceTemplates.swift.",
    };
  }
  if (t.routingOverride === "vendorOnly") {
    return {
      tier: "vendor",
      label: "Vendor",
      tooltip:
        "Vendor — locked by template author. routingOverride: .vendorOnly explicitly excludes the handyman lane. " +
        "Trigger: routingOverride: .vendorOnly in MaintenanceTemplates.swift.",
    };
  }
  if (t.assignmentType === "vendor" && !t.routingOverride) {
    return {
      tier: "vendor",
      label: "Vendor",
      tooltip:
        "Vendor — explicitly classified as pro work. The template author marked this assignmentType: .vendor " +
        "without a routing override. Trigger: assignmentType: .vendor in MaintenanceTemplates.swift.",
    };
  }
  if (t.routingOverride === "diyDefault") {
    return {
      tier: "handyman",
      label: "Handyman",
      tooltip:
        "Handyman — homeowner default. routingOverride: .diyDefault means this template lands in 'Your tasks' " +
        "even for hire-out users (replace HVAC filters, weather-stripping checks, generator oil checks). " +
        "Hard-floor: never flips to vendor. Trigger: routingOverride: .diyDefault in MaintenanceTemplates.swift.",
    };
  }
  if (t.routingOverride === "diyCapable") {
    return {
      tier: "handyman",
      label: "Handyman",
      tooltip:
        "Handyman — DIY-friendly fallback. routingOverride: .diyCapable means the handyman handles it on a " +
        "punch-list visit by default, but the homeowner can claim it as DIY if they want. " +
        "Trigger: routingOverride: .diyCapable in MaintenanceTemplates.swift.",
    };
  }
  if (t.assignmentType === "personal") {
    return {
      tier: "handyman",
      label: "Handyman",
      tooltip:
        "Handyman — explicitly personal. The template author marked this assignmentType: .personal. " +
        "Trigger: assignmentType: .personal in MaintenanceTemplates.swift.",
    };
  }
  return {
    tier: "vendor_or_handyman",
    label: "Vendor or Handyman",
    tooltip:
      "Vendor or Handyman — flexible default. The template has assignmentType: .either with no special " +
      "routingOverride, so the iOS reconciler resolves it against Q36 preference tier: hire_out → vendor, " +
      "mixed → vendor if effort >30min else personal, diy → personal. " +
      "Trigger: assignmentType: .either + no override in MaintenanceTemplates.swift.",
  };
}

// Phase 5q — Count siblings in a bundle so a "Bundle child" row can
// show "↳ Spring Landscaping visit (4 items)" instead of leaving the
// reader guessing how many things land together.
function countBundleSiblings(bundleId) {
  if (!bundleId) return 0;
  const templates = state.liveData?.templates?.entries || [];
  return templates.filter((t) => t.bundleId === bundleId).length;
}

// Phase 5r — Return all sibling templates for a bundleId, sorted by title.
// Used by the bundle map in the entity summary card so Tom can click any
// sibling to jump to it.
function bundleSiblings(bundleId) {
  if (!bundleId) return [];
  const templates = state.liveData?.templates?.entries || [];
  return templates
    .filter((t) => t.bundleId === bundleId)
    .sort((a, b) => (a.title || "").localeCompare(b.title || ""));
}

// Phase 5r — For a quiz question, summarize what the answer creates in
// plain English: which systems get stamped, which other questions get
// gated, which attributes get written. Pulls from the question's
// _impact + the quiz-mapper-effects digest exported alongside.
function quizQuestionImpact(payload) {
  const out = { creates_systems: [], drives_attributes: [], gates_questions: [] };
  if (!payload) return out;
  const impact = payload._impact || {};
  if (Array.isArray(impact.creates_systems)) out.creates_systems = [...impact.creates_systems];
  if (Array.isArray(impact.drives_attributes)) out.drives_attributes = [...impact.drives_attributes];
  if (Array.isArray(impact.gates_questions)) out.gates_questions = [...impact.gates_questions];
  // quiz-mapper-effects.json is keyed by questionId → array of effect strings
  const mapperEffects = state.liveData?.["quiz-mapper-effects"]?.byQuestion?.[payload.id]
    || state.liveData?.["quiz-mapper-effects"]?.entries?.find?.((e) => e.questionId === payload.id);
  if (Array.isArray(mapperEffects?.effects)) {
    for (const eff of mapperEffects.effects) {
      if (typeof eff !== "string") continue;
      if (/creates? home_system/i.test(eff)) {
        const m = eff.match(/home_system[s]?:?\s*([A-Za-z\/ &]+)/i);
        if (m) out.creates_systems.push(m[1].trim());
      } else if (/writes? attribute|stamps? attribute/i.test(eff)) {
        const m = eff.match(/attribute[s]?:?\s*([a-z_]+)/i);
        if (m) out.drives_attributes.push(m[1].trim());
      }
    }
  }
  out.creates_systems = [...new Set(out.creates_systems)];
  out.drives_attributes = [...new Set(out.drives_attributes)];
  out.gates_questions = [...new Set(out.gates_questions)];
  return out;
}

// Phase 5r — Return templates whose systemCategory matches OR whose
// equipmentKeywords contain a token derived from the system. Lets the
// system detail panel show "templates that depend on this system."
function templatesForSystem(systemCategoryKey) {
  if (!systemCategoryKey) return [];
  const templates = state.liveData?.templates?.entries || [];
  return templates.filter((t) => t.systemCategory === systemCategoryKey);
}

// Phase 5r — Build the plain-English summary card injected at the top
// of every live-entity detail panel. Tom can show this to anyone
// (including his wife) and they can read what the entity does without
// decoding field names. Works across quiz / tasks / handyman /
// recommended / systems / routines.
function renderEntitySummaryCard(item) {
  // Phase 5w — render the summary card whenever we have a payload that
  // can be summarized, regardless of source. Admin shadow rows pass
  // through here with merged payloads (live template + admin overrides),
  // so they get the same rich context as the live entity does.
  if (!item || !item.payload) return "";
  // Skip for hand-created admin drafts that have no template-shaped
  // payload — they have nothing to summarize until they're filled in.
  if (item.source !== "live" && !payloadMatchesSchema(item, viewIdForType(item.itemType))) return "";
  const t = item.itemType;
  if (t === "question") return renderQuizSummaryCard(item);
  if (t === "task" || t === "handyman" || t === "recommended") return renderTaskSummaryCard(item);
  if (t === "system") return renderSystemSummaryCard(item);
  if (t === "routine") return renderRoutineSummaryCard(item);
  return "";
}

function renderQuizSummaryCard(item) {
  const q = item.payload || {};
  const impact = quizQuestionImpact(q);
  const placement = [
    q.chapter && `Chapter: <strong>${escapeHtml(prettyEnumLabel("quizChapter", q.chapter))}</strong>`,
    q.section && `Section: <strong>${escapeHtml(prettyEnumLabel("quizSection", q.section))}</strong>`,
    q.kind && `Kind: <strong>${escapeHtml(prettyEnumLabel("quizKind", q.kind))}</strong>`,
  ].filter(Boolean).join(" · ");

  const goalText = q.subtitle
    ? escapeHtml(q.subtitle)
    : `<em class="admin-muted">No subtitle set. Add one to explain why we're asking.</em>`;

  // Phase 5z+18 — Plain-English "what this does for the app" line up
  // top. Tom: "every quiz question needs to do something in our app,
  // and it needs to be the very first thing we see on the quiz
  // question details 'HERE IS WHAT THIS QUESTION DOES FOR THE APP'
  // in plain english."
  const whatThisDoes = describeQuizImpactPlainEnglish(q, impact);

  // "What it creates" — bullet list of impacts
  const createsBullets = [];
  if (impact.creates_systems.length) {
    createsBullets.push(`<li><strong>Creates systems:</strong> ${
      impact.creates_systems.map((s) => `<button type="button" class="admin-jump-link" data-jump-system="${escapeHtml(s)}">${escapeHtml(s)}</button>`).join(", ")
    }</li>`);
  }
  if (impact.drives_attributes.length) {
    createsBullets.push(`<li><strong>Stamps attributes on the property:</strong> ${
      impact.drives_attributes.map((a) => `<code>${escapeHtml(a)}</code>`).join(", ")
    }</li>`);
  }
  if (impact.gates_questions.length) {
    createsBullets.push(`<li><strong>Affects which other questions show:</strong> ${
      impact.gates_questions.map((qid) => `<button type="button" class="admin-jump-link" data-jump-question="${escapeHtml(qid)}">${escapeHtml(qid)}</button>`).join(", ")
    }</li>`);
  }
  if (q.documentUploadCategory) {
    createsBullets.push(`<li><strong>Doc upload escape hatch:</strong> homeowner can skip and upload a document categorized as <code>${escapeHtml(q.documentUploadCategory)}</code> instead.</li>`);
  }
  if (!createsBullets.length) {
    createsBullets.push(`<li class="admin-muted">No downstream effects captured. (Either this question is purely informational, or the impact heuristic missed it — check Edit tab fields.)</li>`);
  }

  // Skip rules
  const skipNote = q.dynamicSkip
    ? `Auto-skips when prior answers make it irrelevant — see <em>Dynamic skip rule</em> in the form below.`
    : `Always shown to every homeowner who reaches this point in the quiz.`;

  return `
    <section class="admin-summary admin-summary--quiz">
      <header class="admin-summary__head">
        <span class="admin-summary__eyebrow">Quiz question</span>
        <h2 class="admin-summary__title">${escapeHtml(q.title || q.id || "(no title)")}</h2>
        <p class="admin-summary__placement admin-muted">${placement}</p>
      </header>

      <div class="admin-summary__lead">
        <span class="admin-summary__lead-eyebrow">Here is what this question does for the app</span>
        <p class="admin-summary__lead-body">${whatThisDoes}</p>
      </div>

      <div class="admin-summary__body">
        <div class="admin-summary__section">
          <h4>🎯 Goal — what the homeowner sees</h4>
          <p>${goalText}</p>
          ${q.fallbackTitle ? `<p class="admin-muted">Fallback (when tokens like {state} can't resolve): <em>${escapeHtml(q.fallbackTitle)}</em></p>` : ""}
        </div>

        <div class="admin-summary__section">
          <h4>🔁 What this answer creates downstream</h4>
          <ul class="admin-summary__bullets">${createsBullets.join("")}</ul>
        </div>

        <div class="admin-summary__section">
          <h4>⏭️ When does this question appear?</h4>
          <p>${skipNote}</p>
        </div>
      </div>
    </section>
  `;
}

// Phase 5z+18 — Plain-English summary of what a quiz question does
// for the app. Stitches together the impact heuristic into a sentence
// or two that reads naturally to a non-engineer.
function describeQuizImpactPlainEnglish(q, impact) {
  const phrases = [];
  if (impact.creates_systems?.length) {
    const sys = impact.creates_systems.map(escapeHtml).join(", ");
    phrases.push(`Adds the <strong>${sys}</strong> system to the homeowner's profile when answered.`);
  }
  if (impact.creates_contractor) {
    phrases.push(`Captures a <strong>${escapeHtml(impact.creates_contractor)}</strong> vendor and saves them on the household.`);
  }
  if (impact.drives_attributes?.length) {
    const list = impact.drives_attributes.slice(0, 4).map((a) => `<code>${escapeHtml(a)}</code>`).join(", ");
    phrases.push(`Stamps property attributes (${list}) that gate which maintenance tasks the household receives.`);
  }
  if (impact.gates_questions?.length) {
    phrases.push(`Affects whether ${impact.gates_questions.length} downstream question${impact.gates_questions.length === 1 ? "" : "s"} appear${impact.gates_questions.length === 1 ? "s" : ""} later in the quiz.`);
  }
  if (q.documentUploadCategory) {
    phrases.push(`Lets the homeowner skip and upload a <code>${escapeHtml(q.documentUploadCategory)}</code> document instead of typing the answer.`);
  }
  // Special-case kinds that drive UI machinery rather than data.
  const kindDrivers = {
    vehicleAdd: "Walks the homeowner through adding a vehicle (VIN decode, AI maintenance schedule).",
    vehicleCount: "Sets up how many vehicles the next steps capture.",
    yesNoLender: "Captures lender-specific data (insurance / mortgage routing).",
    providerSearch: "Picks a utility / advisor / vendor from Chez's directory and links them to the household.",
    caretakers: "Captures spouse + kids + home-manager profile so the right people get invited and assigned.",
    generatorAdd: "Captures generator type + fuel + supplier so the right service templates seed.",
    householdContractors: "Q15b — captures every recurring vendor the household already has on retainer.",
  };
  if (kindDrivers[q.kind]) {
    phrases.push(escapeHtml(kindDrivers[q.kind]).replace(/&lt;code&gt;/g, "<code>").replace(/&lt;\/code&gt;/g, "</code>"));
  }
  if (phrases.length === 0) {
    return `<em class="admin-muted">We can't trace this question to anything downstream. It might be informational only, or its wiring isn't captured in the impact heuristic — review the form fields below.</em>`;
  }
  return phrases.join(" ");
}

function renderTaskSummaryCard(item) {
  const t = item.payload || {};
  const reason = routingReason(t);
  const seasonEmoji = { Spring: "🌷", Summer: "☀️", Fall: "🍂", Winter: "❄️", "Spring/Fall": "🔁" }[t.seasonalTiming] || "🔄";
  const seasonLabel = t.seasonalTiming || "Year-round";
  const proactive = computeProactiveSurfacing(t);
  // Phase 5s — "Where this came from" = which quiz question creates
  // the system that hosts this template. Walks the reverse index from
  // quiz-questions.json _impact.creates_systems back to the systemCategory.
  const upstreamQuestions = questionsCreatingSystem(t.systemCategory);

  // Bundle map — interactive parent + siblings
  let bundleMap = "";
  if (t.bundleId) {
    const siblings = bundleSiblings(t.bundleId);
    const parentTitle = prettyBundleTitle(t.bundleId);
    const siblingItems = siblings
      .map((s) => {
        const isSelf = s.templateKey === t.templateKey;
        const cls = isSelf ? "admin-summary__sibling is-self" : "admin-summary__sibling";
        const marker = isSelf ? `<span class="admin-summary__sibling-marker">▶ you are here</span>` : "";
        const title = escapeHtml(s.title || "(untitled)");
        const button = isSelf
          ? `<span class="admin-summary__sibling-title">${title}</span>`
          : `<button type="button" class="admin-summary__sibling-title admin-jump-link" data-jump-template-key="${escapeHtml(s.templateKey || "")}">${title}</button>`;
        return `<li class="${cls}">${button}${marker}</li>`;
      }).join("");
    bundleMap = `
      <div class="admin-summary__section">
        <h4>📦 Bundle map — this template lives inside a parent visit</h4>
        <div class="admin-summary__bundle-map">
          <div class="admin-summary__bundle-parent">
            <strong>↳ ${escapeHtml(parentTitle)}</strong>
            <span class="admin-muted">${siblings.length} item${siblings.length === 1 ? "" : "s"} fold into this single visit at runtime. The homeowner sees ONE scheduled task, not ${siblings.length} separate to-dos.</span>
          </div>
          <ol class="admin-summary__siblings">${siblingItems}</ol>
        </div>
      </div>
    `;
  } else {
    // Check if THIS template is the conceptual parent of a bundle (no
    // template literally has children — bundles are flat — but we can
    // check if templates exist with a bundleId derived from this.
    bundleMap = "";
  }

  // System link — clickable jump
  let systemLink = "";
  if (t.systemCategory) {
    const equipmentChips = (t.equipmentKeywords || []).length
      ? `<p class="admin-muted">Migrates to a more specific child system at runtime if any of these keywords match equipment in the home: ${t.equipmentKeywords.map((k) => `<code>${escapeHtml(k)}</code>`).join(", ")}.</p>`
      : "";
    systemLink = `
      <div class="admin-summary__section">
        <h4>🏷️ System this lives under</h4>
        <p><button type="button" class="admin-jump-link admin-jump-link--prominent" data-jump-system="${escapeHtml(t.systemCategory)}">${escapeHtml(t.systemCategory)} →</button></p>
        ${equipmentChips}
      </div>
    `;
  }

  // Goal text — first sentence of description
  const goal = (t.description || "").split(/\.\s+/)[0];
  const goalText = goal
    ? `${escapeHtml(goal)}.`
    : `<em class="admin-muted">No description set.</em>`;

  // Why we have it — notes if set, else default explanation
  const whyText = t.notes
    ? escapeHtml(t.notes)
    : `<em class="admin-muted">No notes set. Use the Pro tips field to explain WHY this cadence exists or what to watch for.</em>`;

  // Lifecycle line
  const lifecycle = t.bundleId
    ? `Folds into the parent visit (never its own task)`
    : t.isEssential === false
      ? `<strong>Opt-in.</strong> ${t.systemCategory === "Handyman" ? "Surfaced in the handyman punch list 'Recommended' section." : "Surfaced in PropertyDetailView → Recommended Services."} Homeowner taps + to schedule.`
      : `<strong>Auto-seeds at quiz completion</strong> if subtypes / region match.`;

  // Phase 5s — "Where this template came from" block. Shows the quiz
  // path that creates the system that hosts this template, so Tom can
  // trace any task back to its provenance with one click.
  let provenanceBlock = "";
  if (upstreamQuestions.length) {
    const links = upstreamQuestions.map((q) =>
      `<button type="button" class="admin-jump-link" data-jump-question="${escapeHtml(q.id)}">${escapeHtml(q.id)} — ${escapeHtml(q.title || "")}</button>`
    ).join(" ");
    provenanceBlock = `
      <div class="admin-summary__section">
        <h4>🧬 Where this came from</h4>
        <p>Created when the homeowner answers ${upstreamQuestions.length === 1 ? "this question" : "any of these questions"} during onboarding:</p>
        <p>${links}</p>
        <p class="admin-muted">Their answer creates the <strong>${escapeHtml(t.systemCategory || "")}</strong> system on the property, and this template seeds against that system at quiz completion (or via Recommended Services if it's opt-in).</p>
      </div>
    `;
  } else if (t.systemCategory) {
    provenanceBlock = `
      <div class="admin-summary__section">
        <h4>🧬 Where this came from</h4>
        <p class="admin-muted">No quiz question directly creates the <strong>${escapeHtml(t.systemCategory)}</strong> system. It's auto-created by the reconciler at quiz completion (universal categories like Plumbing / Water Heater / Electrical / Septic / Well are stamped on every property) or surfaces only via opt-in.</p>
      </div>
    `;
  }

  // Phase 67C / 5t — Surfacing block. Seasonal tasks get the proactive
  // lead-time. Year-round tasks get a clear "no anchor" explanation so
  // the section never goes blank.
  let proactiveBlock = "";
  if (proactive) {
    proactiveBlock = `
      <div class="admin-summary__section admin-summary__section--proactive">
        <h4>🗓️ Proactive surfacing (when the homeowner sees it)</h4>
        <p>
          Surfaces in <strong>${escapeHtml(proactive.surfaceMonth)}</strong>
          for work in <strong>${escapeHtml(proactive.executionMonth)}</strong>
          — ${proactive.leadDays}-day lead time.
        </p>
        <p class="admin-muted">${escapeHtml(proactive.reasoning)}</p>
      </div>
    `;
  } else if (t.frequency) {
    // Year-round / pace tasks — explain the cadence model clearly.
    const cadenceExplain = (t.frequency || "").toLowerCase().includes("week")
      || (t.frequency || "").toLowerCase().includes("month")
      ? "Weekly / monthly tasks tick on their own schedule. The homeowner sees them when they're due — no proactive lead time needed."
      : "No seasonal anchor on this template. The next-due date is set as `today + interval` when the task seeds, so the homeowner schedules it whenever convenient. Add a seasonalTiming if this should anchor to a specific month.";
    proactiveBlock = `
      <div class="admin-summary__section admin-summary__section--proactive">
        <h4>🗓️ When the homeowner sees it</h4>
        <p>${escapeHtml(t.frequency)} cadence, no seasonal anchor.</p>
        <p class="admin-muted">${escapeHtml(cadenceExplain)}</p>
      </div>
    `;
  }

  // Phase 5t — Gating section. Surface requiredSubtypes + region gates
  // explicitly so it's obvious WHO this task applies to.
  let gatingBlock = "";
  const subtypes = t.requiredSubtypes || [];
  const region = t.regionalPack;
  if (subtypes.length > 0 || region || t.isEssential === false) {
    const gatingPills = [];
    if (region) {
      gatingPills.push(`<span class="admin-pill admin-pill--gating-region" title="Only seeds on properties in this regional pack. Other regions skip this template entirely.">📍 ${escapeHtml(region)} only</span>`);
    }
    for (const s of subtypes) {
      gatingPills.push(`<span class="admin-pill admin-pill--gating-subtype" title="The home_systems row must carry this subtype tag for the template to seed. Set during the quiz (e.g. q3b answer = central_ducted stamps 'ducted' on the HVAC system).">🏷️ requires <code>${escapeHtml(s)}</code></span>`);
    }
    if (t.isEssential === false) {
      gatingPills.push(`<span class="admin-pill admin-pill--optin" title="Won't auto-seed. Homeowner picks via Recommended Services / handyman punch list 'Recommended' section.">Opt-in</span>`);
    }
    const gatingExplainer = subtypes.length === 0 && !region && t.isEssential === false
      ? "Doesn't auto-seed at quiz completion."
      : subtypes.length > 0
        ? `Only seeds when the parent ${escapeHtml(t.systemCategory || "system")} row carries the listed subtype${subtypes.length === 1 ? "" : "s"}. Subtypes are stamped during the quiz based on the homeowner's answers.`
        : "Universal — no subtype gating.";
    gatingBlock = `
      <div class="admin-summary__section">
        <h4>🚪 Gating — who actually sees this</h4>
        <p>${gatingPills.join(" ")}</p>
        <p class="admin-muted">${gatingExplainer}</p>
      </div>
    `;
  }

  // Phase 5t — Stats strip: cost / effort / frequency / priority all
  // visible at a glance so Tom doesn't have to scroll the form for the
  // basics.
  const statsStrip = `
    <div class="admin-summary__stats">
      <div class="admin-summary__stat">
        <span class="admin-summary__stat-label">Cadence</span>
        <strong>${escapeHtml(t.frequency || "—")}</strong>
      </div>
      <div class="admin-summary__stat">
        <span class="admin-summary__stat-label">Cost range</span>
        <strong>${escapeHtml(t.estimatedCostRange || "—")}</strong>
      </div>
      <div class="admin-summary__stat">
        <span class="admin-summary__stat-label">Priority</span>
        <strong>${escapeHtml(t.priority || "—")}</strong>
      </div>
      <div class="admin-summary__stat">
        <span class="admin-summary__stat-label">DIY effort</span>
        <strong>${t.diyEffortMinutes ? escapeHtml(`${t.diyEffortMinutes} min`) : "Vendor-only"}</strong>
      </div>
    </div>
  `;

  return `
    <section class="admin-summary admin-summary--task">
      <header class="admin-summary__head">
        <span class="admin-summary__eyebrow">Maintenance template</span>
        <h2 class="admin-summary__title">${escapeHtml(t.title || "(no title)")}</h2>
        <p class="admin-summary__placement admin-muted">
          ${escapeHtml(t.frequency || "?")} · ${seasonEmoji} ${escapeHtml(seasonLabel)} · ${escapeHtml(t.estimatedCostRange || "no cost set")}
        </p>
      </header>

      ${statsStrip}

      <div class="admin-summary__body">
        <div class="admin-summary__section">
          <h4>🎯 Goal — what gets done</h4>
          <p>${goalText}</p>
        </div>

        <div class="admin-summary__section">
          <h4>💡 Why we have it</h4>
          <p>${whyText}</p>
        </div>

        ${reason ? `
        <div class="admin-summary__section">
          <h4>👤 Who handles it by default</h4>
          <p><strong>${escapeHtml(reason.label.replace(/^↳\s+/, ""))}</strong> — ${escapeHtml(reason.tooltip.split(". Trigger:")[0])}.</p>
        </div>
        ` : ""}

        ${gatingBlock}

        <div class="admin-summary__section">
          <h4>🌱 When does it enter the homeowner's task list?</h4>
          <p>${lifecycle}</p>
        </div>

        ${provenanceBlock}
        ${proactiveBlock}
        ${systemLink}
        ${bundleMap}
      </div>
    </section>
  `;
}

// Phase 5s — Reverse index: which quiz questions create the system
// that hosts this template. Built once per render from the quiz JSON's
// _impact.creates_systems field (heuristic, may miss edge cases).
function questionsCreatingSystem(systemCategory) {
  if (!systemCategory) return [];
  const questions = state.liveData?.["quiz-questions"]?.entries || [];
  return questions
    .filter((q) => (q._impact?.creates_systems || []).includes(systemCategory))
    .map((q) => ({ id: q.id, title: q.title }));
}

// Phase 67C — Compute the surfacing month + lead-time explanation for
// the summary card. Mirrors the iOS reconciler's effectiveLeadTimeDays
// helper so the admin shows what the homeowner would actually see.
function computeProactiveSurfacing(t) {
  if (!t || !t.seasonalTiming || t.seasonalTiming === "Spring/Fall") return null;
  const lead = typeof t.effectiveLeadTimeDays === "number" ? t.effectiveLeadTimeDays : null;
  if (!lead) return null;
  const execMonthIdx = { Spring: 3, Summer: 6, Fall: 9, Winter: 0 }[t.seasonalTiming];
  if (execMonthIdx == null) return null;
  const months = ["January","February","March","April","May","June","July","August","September","October","November","December"];
  const anchor = new Date(2025, execMonthIdx, 1);
  anchor.setDate(anchor.getDate() - lead);
  const surfaceMonth = months[anchor.getMonth()];
  const executionMonth = months[execMonthIdx];

  // Lead-time reasoning — match the rules in
  // MaintenanceTemplate.effectiveLeadTimeDays so it stays in sync.
  let reasoning;
  if (t.safetyFloor === true) {
    reasoning = "Safety-floor work (gas, panel, roof, septic, generator) needs the longest lead — these vendors are the most booked at peak season, and overdue work isn't safe to defer.";
  } else if (t.assignmentType === "vendor" && ["Chimney","Septic System","Roofing","Generator"].includes(t.systemCategory)) {
    reasoning = "Pre-winter rush category. Chimney sweeps, septic pumpers, roofers, generator techs all get slammed in fall — booking 8 weeks out keeps the homeowner ahead of their backlog.";
  } else if (t.assignmentType === "vendor" && ["HVAC","Pool/Spa","Hot Tub","Landscaping","Snow Removal","Pest Control","Mosquito & Tick"].includes(t.systemCategory)) {
    reasoning = "Peak-season vendor (HVAC techs in May, pool services in April, landscapers in March). 6-week lead lets the homeowner compare quotes before the rush.";
  } else if (t.systemCategory === "Tree Service") {
    reasoning = "Arborists routinely book 4 weeks out — surfacing earlier gives the homeowner time to walk the property and decide what needs trimming.";
  } else if (t.assignmentType === "vendor") {
    reasoning = "Standard vendor lead time. 4 weeks gives the homeowner time to call, get a quote, and book a slot.";
  } else if (t.routingOverride === "diyDefault" || t.routingOverride === "diyCapable") {
    reasoning = "DIY / handyman item. 2-week lead lets the homeowner plan a weekend (or add it to the next punch-list visit) without scrambling.";
  } else {
    reasoning = "Default lead time for an `either` template — gives the homeowner some breathing room.";
  }
  return { surfaceMonth, executionMonth, leadDays: lead, reasoning };
}

function renderSystemSummaryCard(item) {
  const s = item.payload || {};
  const linked = templatesForSystem(s.categoryKey || s.displayName);
  const linkedSummary = linked.length
    ? `<ul class="admin-summary__system-templates">${linked.slice(0, 8).map((t) => `<li><button type="button" class="admin-jump-link" data-jump-template-key="${escapeHtml(t.templateKey || "")}">${escapeHtml(t.title || "")}</button> <span class="admin-muted">${escapeHtml(t.frequency || "")}</span></li>`).join("")}${linked.length > 8 ? `<li class="admin-muted">… and ${linked.length - 8} more</li>` : ""}</ul>`
    : `<p class="admin-muted">No templates currently target this system. Likely a navigation-only category or a system without canonical maintenance.</p>`;
  return `
    <section class="admin-summary admin-summary--system">
      <header class="admin-summary__head">
        <span class="admin-summary__eyebrow">System category</span>
        <h2 class="admin-summary__title">${escapeHtml(s.displayName || s.categoryKey || "(no name)")}</h2>
        <p class="admin-summary__placement admin-muted">
          Tier: <strong>${escapeHtml(s.tier || "?")}</strong>
          ${s.specialtyGroup ? ` · Specialty group: <strong>${escapeHtml(s.specialtyGroup)}</strong>` : ""}
          ${s.defaultCadence ? ` · Default cadence: <strong>${escapeHtml(s.defaultCadence)}</strong>` : ""}
        </p>
      </header>
      <div class="admin-summary__body">
        <div class="admin-summary__section">
          <h4>🔧 Templates anchored to this system (${linked.length})</h4>
          ${linkedSummary}
        </div>
      </div>
    </section>
  `;
}

function renderRoutineSummaryCard(item) {
  const r = item.payload || {};
  const cadence = r.seederDefault?.cadenceType || "no default";
  const months = (r.seederDefault?.activeMonths || []).length;
  return `
    <section class="admin-summary admin-summary--routine">
      <header class="admin-summary__head">
        <span class="admin-summary__eyebrow">Routine kind</span>
        <h2 class="admin-summary__title">${escapeHtml(r.displayLabel || r.rawValue || "(no label)")}</h2>
        <p class="admin-summary__placement admin-muted">
          ${r.isVendorBased ? "Vendor-based (recurring relationship)" : "Cadence-based (homeowner-managed)"}
          · Default: <strong>${escapeHtml(cadence)}</strong>
          ${months ? ` · ${months} active months` : " · year-round"}
        </p>
      </header>
      <div class="admin-summary__body">
        <div class="admin-summary__section">
          <h4>🎯 What this routine represents</h4>
          <p>${r.isVendorBased
            ? `A recurring vendor relationship the homeowner has with a specific pro (e.g. "Pat the landscaper, every Tuesday April-November"). The Routine card on the Property tab shows the next visit date, vendor logo, and lets the homeowner pause/edit cadence.`
            : `A weekly household rhythm that's not tied to a vendor (trash day, recycling, school pickup). Surfaces as a dashboard banner the night before / morning of.`}</p>
        </div>
      </div>
    </section>
  `;
}

// Phase 5r — Wire up jump links in the summary card. Click a system /
// template / question link → switch surface + select that entity.
function attachSummaryCardHandlers(host) {
  if (!host) return;
  host.querySelectorAll("[data-jump-system]").forEach((btn) => {
    btn.addEventListener("click", (e) => {
      e.preventDefault();
      const key = btn.dataset.jumpSystem;
      const items = liveItemsForView("systems") || [];
      const hit = items.find((i) =>
        (i.payload?.categoryKey || "").toLowerCase() === (key || "").toLowerCase() ||
        (i.payload?.displayName || "").toLowerCase() === (key || "").toLowerCase() ||
        (i.title || "").toLowerCase() === (key || "").toLowerCase()
      );
      if (hit) {
        state.view = "systems";
        state.selected = hit;
        state.search = "";
        state.statusFilter = "all";
        state.lifecycleFilter = "all";
        state.seasonFilter = "all";
        state.routingFilter = "all";
      state.handymanFilter = "all";
        render();
      }
    });
  });
  host.querySelectorAll("[data-jump-question]").forEach((btn) => {
    btn.addEventListener("click", (e) => {
      e.preventDefault();
      const qid = btn.dataset.jumpQuestion;
      const items = liveItemsForView("quiz") || [];
      const hit = items.find((i) => i.payload?.id === qid);
      if (hit) {
        state.view = "quiz";
        state.selected = hit;
        state.search = "";
        state.statusFilter = "all";
        render();
      }
    });
  });
  host.querySelectorAll("[data-jump-template-key]").forEach((btn) => {
    btn.addEventListener("click", (e) => {
      e.preventDefault();
      const key = btn.dataset.jumpTemplateKey;
      jumpToTemplate(key);
    });
  });
}

// Phase 5r — Resolve enum value to its human-readable label using the
// same ENUMS table the form uses, so summary cards read naturally.
function prettyEnumLabel(enumKey, value) {
  const opts = (typeof ENUMS !== "undefined" && ENUMS?.[enumKey]) || [];
  const hit = opts.find((o) => o.value === value);
  return hit?.label || value || "";
}

// Phase 5q — Map a bundleId like "Pool/Spa:opening" or "Landscaping:spring"
// into a homeowner-readable parent visit title. Mirrors the simulator's
// prettifyBundleId() helper but keeps it here so admin.js stays self-
// contained without importing simulator code.
function prettyBundleTitle(bundleId) {
  if (!bundleId) return "";
  const [category, season] = bundleId.split(":");
  const seasonLabel = {
    spring: "Spring", fall: "Fall", summer: "Summer", winter: "Winter",
    annual: "Annual", ongoing: "Ongoing", triennial: "Every 3 yrs",
    opening: "Opening", closing: "Closing",
  }[season] || (season || "").charAt(0).toUpperCase() + (season || "").slice(1);
  return `${seasonLabel} ${category} visit`;
}

function emptyListHtml(text = "Nothing matches this filter.") {
  return `<div class="admin-empty-detail" style="min-height:220px"><h3>${escapeHtml(text)}</h3></div>`;
}

function filterItems(items) {
  const q = state.search.trim().toLowerCase();
  // Phase 5q — facet filters apply on Tasks / Handyman / Recommended
  // surfaces. Other surfaces ignore them so legacy behavior is unchanged.
  const facetSurface = ["tasks", "handyman", "recommended"].includes(state.view);
  return items.filter((item) => {
    // Phase 5y — Bundle grouping: when ON (default), hide non-parent
    // bundle children. A "parent" is a bundle child template that
    // carries bundleTitle (the row that becomes the homeowner's actual
    // task). The other children fold into that parent at runtime, so
    // showing them as separate list rows is duplicative.
    //
    // Exception: when the user explicitly filters by lifecycle =
    // "bundle_child", they're asking to see the children — auto-flatten
    // so the filter has something to show.
    if (facetSurface && state.groupBundles && state.lifecycleFilter !== "bundle_child") {
      const t = item.payload || {};
      if (t.bundleId && !t.bundleTitle) return false;
    }
    if (state.statusFilter !== "all" && effectiveStatus(item) !== state.statusFilter) return false;
    if (facetSurface) {
      if (state.lifecycleFilter !== "all" && lifecycleOf(item) !== state.lifecycleFilter) return false;
      if (state.seasonFilter !== "all") {
        const s = item.payload?.seasonalTiming;
        if (state.seasonFilter === "year_round" && s) return false;
        if (state.seasonFilter !== "year_round" && s !== state.seasonFilter) return false;
      }
      if (state.routingFilter !== "all" && routingOf(item) !== state.routingFilter) return false;
      if (state.view === "handyman" && state.handymanFilter !== "all" && handymanVisitOf(item) !== state.handymanFilter) return false;
      // Phase 5z+7 — Tasks tab fully excludes ALL handyman-context
      // templates (standalone Handyman library + Handyman:spring/fall
      // bundle parents + their children). Handyman items live ONLY on
      // the Handyman tab; period. No override toggle. The bidirectional
      // task ↔ punch flow (Phase 67E/F) is a runtime homeowner action
      // on a task instance, not a template-level dual-listing concern.
      if (state.view === "tasks" && isHandymanContextItem(item)) return false;
    }
    if (!q) return true;
    return [item.title, item.category, item.description, JSON.stringify(item.payload ?? {})]
      .join(" ")
      .toLowerCase()
      .includes(q);
  });
}

async function createNewItem() {
  if (state.view === "notes") {
    // Phase 5z+9 — Explicitly open the curated form for general-note
    // creation. Pre-5z+9 this just hid the detail panel and focused
    // a hidden textarea (broken UX). Now it shows the form pre-cleared
    // so Tom can type a body + intent and click Save.
    state.selected = null;
    renderNotesView();
    el.emptyDetail.classList.add("is-hidden");
    el.detail.classList.remove("is-hidden");
    el.detailTabs?.classList.add("is-hidden");
    el.curatedForm?.classList.remove("is-hidden");
    el.noteFocused?.classList.add("is-hidden");
    document.querySelector("[data-detail-quick-actions]")?.classList.add("is-hidden");
    if (el.formHost) el.formHost.innerHTML = "";
    if (el.diffHost) el.diffHost.innerHTML = "";
    el.detailKind.textContent = "new general note";
    el.detailTitle.textContent = "Add a general note";
    el.detailSubtitle.textContent = "Use this for unscoped reflections and admin-lab observations. To attach a note to a quiz question, template, system, or routine, open that entity's detail panel.";
    el.detailStatus.textContent = "draft";
    el.detailStatus.dataset.tone = "draft";
    el.fieldTitle.value = "";
    el.fieldStatus.value = "active";
    el.fieldCategory.value = "general";
    el.fieldSort.value = "0";
    el.fieldDescription.value = "";
    if (el.fieldPayload) el.fieldPayload.value = "{}";
    el.saveItem.textContent = "Save general note";
    el.saveItem.disabled = false;
    el.promoteItem.disabled = true;
    el.duplicateItem.disabled = true;
    el.deleteItem.disabled = true;
    el.fieldDescription.focus();
    return;
  }
  const view = currentView();
  const item = {
    id: `local-${Date.now()}`,
    source: "admin",
    isNew: true,
    itemType: view.type,
    title: `New ${view.type}`,
    status: "draft",
    category: defaultCategoryForView(view),
    sortOrder: state.adminItems.filter((i) => i.itemType === view.type).length + 1,
    description: "",
    payload: defaultPayloadForView(view),
  };
  state.adminItems.unshift(item);
  state.selected = item;
  render();
}

function defaultCategoryForView(view) {
  if (view.id === "tasks") return "Handyman";
  if (view.id === "quiz") return "Your Home";
  return view.label;
}

function defaultPayloadForView(view) {
  if (view.id === "quiz") {
    return {
      questionId: `admin_question_${Date.now()}`,
      chapter: "your_home",
      section: "homeBasics",
      kind: "singleChoice",
      answerOptions: [
        { id: "yes", label: "Yes" },
        { id: "no", label: "No" },
      ],
      intent: "Low-code admin-created question. Add answer mapping in Swift only if this answer needs custom side effects.",
    };
  }
  if (view.id === "tasks") {
    return {
      systemCategory: "Handyman",
      operationalType: "Handyman task",
      cadence: "Annually",
      season: "",
      priority: "Medium",
      cost: "$150-$400",
      assignmentType: "either",
      routing: "diyCapable",
      requiredSubtypes: [],
      essential: false,
      warrantyLinked: false,
      notes: "Low-code task template created from /admin.",
    };
  }
  if (view.id === "routines") {
    return {
      cadence: "Biweekly",
      defaultDayTime: "Wednesday 9:00 AM",
      activeMonths: "Year-round",
      serviceKey: "custom_routine",
    };
  }
  if (view.id === "vendors") {
    return {
      providerType: "handyman",
      orchestrationDefault: "quote_or_schedule",
      searchEnabled: true,
    };
  }
  if (view.id === "searches") {
    return {
      scopes: ["vendors", "systems"],
      placeholder: "Search vendors, systems, or equipment...",
    };
  }
  if (view.id === "systems") {
    return {
      systemCategory: "Handyman",
      createsSystem: true,
    };
  }
  return {};
}

async function promoteSelectedItem() {
  if (!state.selected || state.selected.source === "admin") return;
  const promoted = {
    ...state.selected,
    id: `local-${Date.now()}`,
    source: "admin",
    isNew: true,
    title: state.selected.title,
    payload: {
      ...state.selected.payload,
      promotedFromAuditId: state.selected.id,
    },
  };
  state.adminItems.unshift(promoted);
  state.selected = promoted;
  render();
}

// Phase 5w — For an admin item, find the matching live entity (by
// liveEntityId or by id-like fields in the admin payload). Used by
// renderDetail to merge the live template's payload underneath the
// admin overlay so shadow rows render the full schema form.
function findUnderlyingLiveItem(adminItem) {
  if (!adminItem || adminItem.source !== "admin") return null;
  const surfaceId = viewIdForType(adminItem.itemType);
  const candidates = liveItemsForView(surfaceId) || [];
  if (!candidates.length) return null;
  // Match strategies, in order: explicit liveEntityId column, payload's
  // live_entity_id field, payload's templateKey/id/categoryKey/etc., or
  // exact title fallback.
  const liveId = adminItem.liveEntityId || adminItem.payload?.live_entity_id;
  if (liveId) {
    const byLiveId = candidates.find((c) => liveEntityIdFor(c) === liveId);
    if (byLiveId) return byLiveId;
  }
  // Try title match — last-resort but handles older shadow rows that
  // didn't capture liveEntityId.
  if (adminItem.title) {
    const byTitle = candidates.find((c) => c.title === adminItem.title);
    if (byTitle) return byTitle;
  }
  return null;
}

// Phase 5w — Plain-English explanation of which flavor of entity the
// detail panel is showing. Replaces the bare "admin task" eyebrow.
// Tom's question: "I have no clue what an admin task is" — now every
// entity announces what it is + what it means in a tooltip.
function describeEntityFlavor(item, underlyingLive) {
  if (!item) return { label: "—", tone: "neutral", tooltip: "" };
  if (item.source === "live") {
    return {
      label: `Live · ${item.itemType}`,
      tone: "live",
      tooltip:
        "Live template — comes straight from Swift code (e.g. MaintenanceTemplates.swift). " +
        "Edits here ship as proposal notes; the underlying Swift source changes when Claude applies them in a future session. " +
        "Every homeowner who completes the quiz gets these.",
    };
  }
  if (item.source === "admin" && underlyingLive) {
    const launchStatus = item.launchStatus || "draft";
    return {
      label: `Admin overlay · ${item.itemType}`,
      tone: "overlay",
      tooltip:
        `Admin overlay on a live ${item.itemType}. The underlying template lives in Swift; this row in admin_content_items adds your overrides on top — locked/approved status, custom notes, disposition (cut/defer/reshape), or attachments. ` +
        `Current launch status: ${launchStatus}. ` +
        "Edits save back to admin_content_items.payload directly (no proposal note needed).",
    };
  }
  if (item.source === "admin") {
    return {
      label: `Admin draft · ${item.itemType}`,
      tone: "draft",
      tooltip:
        `Hand-created in this lab — not yet promoted into Swift. Lives in admin_content_items only. ` +
        "When approved + applied by Claude, it would be added to the Swift source on the next build. " +
        "Use the Promote / Duplicate / Delete buttons to manage its lifecycle.",
    };
  }
  return {
    label: `${item.source} · ${item.itemType}`,
    tone: "neutral",
    tooltip: "Legacy / default fallback row.",
  };
}

// Phase 5v — Detect whether an admin item carries a payload that
// matches the schema's expected shape. We only need a couple of
// canonical fields per surface — if any of them are present, the
// schema form can render meaningfully against the payload.
function payloadMatchesSchema(item, viewId) {
  const p = item?.payload;
  if (!p || typeof p !== "object" || Array.isArray(p)) return false;
  const markers = {
    quiz: ["id", "kind", "title", "answerOptions"],
    tasks: ["templateKey", "systemCategory", "title"],
    handyman: ["templateKey", "systemCategory", "title"],
    recommended: ["templateKey", "systemCategory", "title"],
    routines: ["rawValue", "swiftCase"],
    systems: ["categoryKey", "displayName"],
    vehicles: ["systemPrompt"],
    prompts: ["functionName"],
  }[viewId] || [];
  if (!markers.length) return false;
  return markers.some((m) => p[m] != null && p[m] !== "");
}

// Phase 5v — Save edits made in the schema form against an admin
// draft directly back to admin_content_items.payload (cloud) or
// localStorage (local mode). No proposal note needed — admin drafts
// are already the user's local edits.
async function saveAdminDraftPayload() {
  const current = state.selected;
  if (!current) return;
  const item = {
    ...current,
    source: "admin",
    payload: structuredCloneSafe(editingState.current ?? current.payload ?? {}),
    // Mirror visible top-level fields out of the payload so the list row
    // + nav badges stay in sync without a re-export.
    title: editingState.current?.title || current.title,
    description: editingState.current?.description || current.description,
    category: editingState.current?.systemCategory || editingState.current?.category || current.category,
    isNew: current.source !== "admin" || current.isNew,
  };

  if (state.storageMode === "cloud") {
    try {
      const saved = await saveItemCloud(item);
      replaceAdminItem(saved);
      state.selected = saved;
    } catch (error) {
      alert(`Cloud save failed: ${error.message}`);
      return;
    }
  } else {
    replaceAdminItem(item);
    writeLocal(LOCAL_ITEMS_KEY, state.adminItems);
  }
  flashSavePill();
  render();
}

async function duplicateSelectedItem() {
  if (!state.selected) return;
  // Phase 5 — for live entities, "duplicate" becomes a proposal_add note
  // that captures the cloned payload. Claude reads it as "create a new
  // entity like this one with these tweaks." For curated drafts the
  // existing in-memory clone-as-draft path stays.
  if (state.selected.source === "live") {
    const cloned = structuredCloneSafe(state.selected.payload);
    // Strip identity fields so Claude knows this is meant as a NEW entity
    delete cloned.id;
    delete cloned.templateKey;
    delete cloned.stableId;
    delete cloned.functionName;
    delete cloned.rawValue;
    delete cloned.categoryKey;
    await writeNote({
      scopeType: state.selected.itemType,
      scopeId: liveEntityIdFor(state.selected),
      scopeTitle: `${state.selected.title} (clone proposal)`,
      body:
        `Propose adding a NEW ${state.selected.itemType} based on "${state.selected.title}". ` +
        `Edit the proposed_diff before saving in admin or write a follow-up note here with the changes you want.`,
      intent: "proposal_add",
      target: el.fieldTarget?.value || "claude",
      proposedDiff: { based_on: liveEntityIdFor(state.selected), new_entity: cloned },
      snapshot: {
        itemType: state.selected.itemType,
        category: state.selected.category,
        payload: state.selected.payload,
        capturedAt: new Date().toISOString(),
      },
    });
    flashSavePill();
    renderContextNotes(state.selected);
    return;
  }

  const copy = {
    ...state.selected,
    id: `local-${Date.now()}`,
    source: "admin",
    isNew: true,
    title: `${state.selected.title} copy`,
    payload: structuredCloneSafe(state.selected.payload),
  };
  state.adminItems.unshift(copy);
  state.selected = copy;
  render();
}

// Phase 5 — attachment upload pipeline
async function handleAttachmentSelect(event) {
  const files = Array.from(event.target?.files || []);
  if (!files.length) return;
  if (state.storageMode !== "cloud") {
    alert("Attachments require cloud storage. Local-draft mode skips file uploads.");
    return;
  }
  for (const file of files) {
    setAttachmentStatus(`Uploading ${file.name}…`);
    try {
      const url = await uploadAttachment(file);
      pendingAttachments.push({ name: file.name, url, type: file.type });
      setAttachmentStatus(`${pendingAttachments.length} file(s) ready to attach. Save the note to commit.`);
    } catch (err) {
      console.warn("[admin] attachment upload failed", err);
      setAttachmentStatus(`Upload failed: ${err.message}`);
    }
  }
  // Reset the input so the same file can be re-selected.
  event.target.value = "";
}

async function uploadAttachment(file) {
  // Path: <user_id>/<scope_type>/<timestamp>-<filename>
  const userId = state.session?.user?.id || "anon";
  const scope = state.selected?.itemType || "general";
  const safeName = file.name.replace(/[^a-zA-Z0-9._-]/g, "_");
  const path = `${userId}/${scope}/${Date.now()}-${safeName}`;
  const { error } = await supabase.storage.from("admin-attachments").upload(path, file, {
    upsert: false,
    contentType: file.type,
  });
  if (error) throw error;
  // Signed URL valid for a year; admin is Tom-only so this stays private.
  const { data: signed, error: signErr } = await supabase.storage
    .from("admin-attachments")
    .createSignedUrl(path, 60 * 60 * 24 * 365);
  if (signErr) throw signErr;
  return signed?.signedUrl || null;
}

function setAttachmentStatus(text) {
  if (!el.attachmentStatus) return;
  el.attachmentStatus.textContent = text;
}

function consumePendingAttachments() {
  const urls = pendingAttachments.filter((a) => !!a.url).map((a) => a.url);
  pendingAttachments.length = 0;
  setAttachmentStatus("");
  return urls;
}

async function saveSelectedItem() {
  if (state.view === "notes") {
    await saveGeneralNote();
    return;
  }

  // Phase 4b — live entity edits become structured proposed_diff notes,
  // never direct mutations to admin_content_items.
  if (editingState.viewId && state.selected?.source === "live") {
    await saveLiveProposal();
    return;
  }

  // Phase 5v — admin draft using the schema form: the user has been
  // editing fields in the rich schema view. Save the edited payload
  // back to admin_content_items.payload directly. No proposal-note
  // round trip — admin drafts already represent local edits.
  if (editingState.viewId && state.selected?.source === "admin") {
    await saveAdminDraftPayload();
    return;
  }

  const current = state.selected;
  if (!current) return;
  // Curated mode — payload still shipped as JSON because admin_content_items
  // doesn't have a per-surface schema. Hidden textarea is populated from
  // structured data when we switch to it; otherwise stays the prior value.
  let payload;
  try {
    payload = JSON.parse(el.fieldPayload.value || "{}");
  } catch {
    alert("Payload JSON is invalid. Fix it before saving.");
    return;
  }
  const item = {
    ...current,
    source: "admin",
    itemType: currentView().type,
    title: el.fieldTitle.value.trim() || "Untitled",
    status: el.fieldStatus.value,
    category: el.fieldCategory.value.trim(),
    sortOrder: Number(el.fieldSort.value || 0),
    description: el.fieldDescription.value.trim(),
    payload,
    isNew: current.source !== "admin" || current.isNew,
  };

  if (state.storageMode === "cloud") {
    try {
      const saved = await saveItemCloud(item);
      replaceAdminItem(saved);
      state.selected = saved;
    } catch (error) {
      alert(`Cloud save failed: ${error.message}`);
      return;
    }
  } else {
    replaceAdminItem(item);
    writeLocal(LOCAL_ITEMS_KEY, state.adminItems);
  }
  render();
}

// Phase 7.5 — toggle launch_status between draft and approved on the
// admin_content_items shadow row that tracks lock state for live entities.
async function toggleLockSelected() {
  const item = state.selected;
  if (!item) return;
  const liveId = liveEntityIdFor(item);
  if (!liveId) {
    alert("This entity has no stable identifier to anchor a lock against.");
    return;
  }
  const shadow = findLockShadow(item);
  const targetStatus = shadow?.launchStatus === "approved" ? "draft" : "approved";

  const row = {
    item_type: item.itemType,
    title: item.title,
    status: shadow?.status || "active",
    category: item.category || null,
    description: item.description || null,
    sort_order: item.sortOrder ?? 0,
    payload: shadow?.payload ?? { live_entity_id: liveId, source: "live_lock" },
    live_entity_id: liveId,
    launch_status: targetStatus,
    locked_at: targetStatus === "approved" ? new Date().toISOString() : null,
  };

  if (state.storageMode !== "cloud") {
    alert("Lock requires cloud storage. Local-draft mode can't anchor approval state.");
    return;
  }

  try {
    let saved;
    if (shadow?.id) {
      const { data, error } = await supabase
        .from("admin_content_items")
        .update(row)
        .eq("id", shadow.id)
        .select("*")
        .single();
      if (error) throw error;
      saved = dbItemToUi(data);
      state.adminItems = state.adminItems.map((a) => (a.id === saved.id ? saved : a));
    } else {
      const { data, error } = await supabase
        .from("admin_content_items")
        .insert(row)
        .select("*")
        .single();
      if (error) throw error;
      saved = dbItemToUi(data);
      state.adminItems.unshift(saved);
    }
    renderDetail();
    renderList();
    renderReadiness();
  } catch (error) {
    alert(`Lock save failed: ${error.message}`);
  }
}

async function saveLiveProposal() {
  const item = state.selected;
  if (!item || !editingState.viewId) return;
  const diff = computeProposedDiff(editingState.viewId, editingState.original, editingState.current);
  const changedKeys = Object.keys(diff);
  if (!changedKeys.length) {
    alert("No changes to save. Edit a field first.");
    return;
  }
  const userBody = (el.contextNote.value || "").trim();
  const summary = changedKeys
    .map((k) => `${k}: ${formatDiffValue(diff[k].from)} → ${formatDiffValue(diff[k].to)}`)
    .join("\n");
  const body = userBody
    ? `${userBody}\n\n---\nField changes:\n${summary}`
    : `Field changes:\n${summary}`;
  await writeNote({
    scopeType: item.itemType,
    scopeId:
      item.payload?.id ||
      item.payload?.questionId ||
      item.payload?.templateKey ||
      item.payload?.stableId ||
      item.payload?.categoryKey ||
      item.payload?.functionName ||
      item.payload?.rawValue ||
      item.id,
    scopeTitle: item.title,
    body,
    intent: "change_request",
    target: el.fieldTarget?.value || "claude",
    proposedDiff: diff,
    snapshot: {
      itemType: item.itemType,
      status: item.status,
      category: item.category,
      description: item.description,
      payload: editingState.original,
      capturedAt: new Date().toISOString(),
      capturedFrom: window.location.origin,
    },
  });
  el.contextNote.value = "";
  // Keep the form's `current` values, but reset original to current so the
  // diff strip clears (the proposal is now captured in a note).
  editingState.original = structuredCloneSafe(editingState.current);
  el.formHost.innerHTML = renderEntityForm(editingState.viewId, editingState.current, editingState.original);
  attachFormHandlers(el.formHost, editingState.viewId, editingState.original, editingState.current, () => {
    renderDiff();
  });
  renderDiff();
  renderContextNotes(item);
  flashSavePill();
  el.saveItem.textContent = "Saved ✓";
  setTimeout(() => {
    el.saveItem.textContent = "Save proposed change";
  }, 1500);
}

function formatDiffValue(value) {
  if (value == null || value === "") return "(empty)";
  if (Array.isArray(value)) {
    if (!value.length) return "(empty)";
    return value
      .map((v) => (typeof v === "object" && v ? v.label || v.id || JSON.stringify(v) : String(v)))
      .join(",");
  }
  if (typeof value === "boolean") return value ? "On" : "Off";
  if (typeof value === "object") return JSON.stringify(value).slice(0, 60);
  return String(value);
}

async function deleteSelectedItem() {
  const item = state.selected;
  if (!item || item.source !== "admin") return;
  if (!confirm(`Delete "${item.title}"?`)) return;
  if (state.storageMode === "cloud" && !item.id.startsWith("local-")) {
    const { error } = await supabase.from("admin_content_items").delete().eq("id", item.id);
    if (error) {
      alert(`Delete failed: ${error.message}`);
      return;
    }
  }
  state.adminItems = state.adminItems.filter((existing) => existing.id !== item.id);
  writeLocal(LOCAL_ITEMS_KEY, state.adminItems);
  state.selected = null;
  render();
}

async function saveItemCloud(item) {
  const row = {
    item_type: item.itemType,
    title: item.title,
    status: item.status,
    category: item.category,
    description: item.description,
    sort_order: item.sortOrder,
    payload: item.payload ?? {},
  };
  if (item.id && !item.id.startsWith("local-") && !item.isNew) {
    const { data, error } = await supabase
      .from("admin_content_items")
      .update(row)
      .eq("id", item.id)
      .select("*")
      .single();
    if (error) throw error;
    return dbItemToUi(data);
  }
  const { data, error } = await supabase
    .from("admin_content_items")
    .insert(row)
    .select("*")
    .single();
  if (error) throw error;
  return dbItemToUi(data);
}

async function saveGeneralNote() {
  const body = el.fieldDescription.value.trim();
  if (!body) {
    alert("Write a note first.");
    return;
  }
  await writeNote({
    scopeType: el.fieldCategory.value.trim() || "general",
    scopeId: null,
    scopeTitle: el.fieldTitle.value.trim() || "General admin note",
    body,
    snapshot: parseJsonLoose(el.fieldPayload.value),
  });
  el.fieldDescription.value = "";
  await loadAdminData();
  renderNotesView();
}

async function saveContextNote() {
  const item = state.selected;
  const body = el.contextNote.value.trim();
  if (!item || !body) {
    alert("Select an item and write a note first.");
    return;
  }
  const intent = el.fieldIntent?.value || "feedback";
  const target = el.fieldTarget?.value || "claude";
  await writeNote({
    scopeType: item.itemType,
    scopeId: item.payload?.id || item.payload?.questionId || item.payload?.templateKey || item.payload?.stableId || item.payload?.categoryKey || item.payload?.functionName || item.payload?.rawValue || item.id,
    scopeTitle: item.title,
    body,
    intent,
    target,
    snapshot: {
      itemType: item.itemType,
      status: item.status,
      category: item.category,
      description: item.description,
      // Phase 4: full Swift-derived entity snapshot so Claude can read the
      // note next session with complete context (impact, lint, raw fields).
      payload: item.payload,
      capturedAt: new Date().toISOString(),
      capturedFrom: window.location.origin,
    },
  });
  el.contextNote.value = "";
  renderContextNotes(item);
  flashSavePill();
}

function flashSavePill() {
  const btn = el.saveNote;
  if (!btn) return;
  const original = btn.textContent;
  btn.textContent = "Saved ✓";
  btn.disabled = true;
  setTimeout(() => {
    btn.textContent = original;
    btn.disabled = false;
  }, 1500);
}

async function writeNote(note) {
  // Phase 5 — drain any uploaded attachments staged for this note.
  const attachmentUrls = note.attachmentUrls || consumePendingAttachments();
  const full = {
    id: `note-${Date.now()}`,
    createdAt: new Date().toISOString(),
    intent: note.intent || "feedback",
    target: note.target || "claude",
    author: "tom",
    attachmentUrls,
    ...note,
  };
  if (state.storageMode === "cloud") {
    try {
      const { data, error } = await supabase
        .from("admin_codex_notes")
        .insert({
          scope_type: full.scopeType,
          scope_id: full.scopeId,
          scope_title: full.scopeTitle,
          body: full.body,
          snapshot: full.snapshot ?? {},
          // Admin Lab v2 columns
          intent: full.intent,
          target: full.target,
          author: full.author,
          proposed_diff: full.proposedDiff ?? null,
          attachment_urls: attachmentUrls,
          // Phase 5z+9 — thread replies via parent_note_id. Was
          // previously not part of the insert payload, which meant
          // replies were silently dropped on the client side. The
          // focused note panel's reply form depends on this.
          parent_note_id: full.parentNoteId ?? null,
        })
        .select("*")
        .single();
      if (error) throw error;
      const saved = dbNoteToUi(data);
      state.notes.unshift(saved);
      writeLocal(LOCAL_NOTES_KEY, state.notes);
      mirrorNoteToLocalFile(saved);
      return saved;
    } catch (error) {
      console.warn("[admin] note cloud save failed, falling back to local", error);
      state.storageMode = "local";
      el.storageWarning.hidden = false;
    }
  }
  state.notes.unshift(full);
  writeLocal(LOCAL_NOTES_KEY, state.notes);
  mirrorNoteToLocalFile(full);
  return full;
}

function mirrorNoteToLocalFile(note) {
  if (!["localhost", "127.0.0.1"].includes(window.location.hostname)) return;
  fetch("http://localhost:8787/admin-note", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(note),
  }).catch(() => {
    // Optional local bridge. If it is not running, Supabase/localStorage still saved.
  });
}

function exportConfig() {
  if (state.view === "notes") {
    downloadText("CODEX_ADMIN_NOTES.md", notesMarkdown());
    return;
  }
  const payload = {
    generatedAt: new Date().toISOString(),
    view: state.view,
    storageMode: state.storageMode,
    adminItems: state.adminItems,
    notes: state.notes,
  };
  downloadText("chez-admin-config.json", JSON.stringify(payload, null, 2));
}

function replaceAdminItem(item) {
  state.adminItems = [
    item,
    ...state.adminItems.filter((existing) => existing.id !== item.id && existing.id !== state.selected?.id),
  ];
  if (state.storageMode === "local") writeLocal(LOCAL_ITEMS_KEY, state.adminItems);
}

// Phase 5z+13 — Nav badge counts.
//
// Tom's ask: "Lets make sure all these numbers are real too in our tabs
// on the left… if it says +23 for instance next to tasks…I have no idea
// what that means and when I click into tasks there is nothing about
// that '+23' for me to easily see or filter to."
//
// Returns a flat number per view (or null for tool views that don't
// display a count). Each number reflects what the user sees when they
// click in:
//   - Tasks tab counts post-handyman-exclusion total (handyman items
//     live exclusively on the Handyman tab — Phase 5z+7).
//   - Notes tab counts top-level notes (not replies) so it matches
//     what's stacked on the screen.
//   - Decisions counts live items that need a call.
//   - Activity counts applied/reverted/locked events.
//   - Tool views (Simulator, Architecture, Claude file) return null —
//     their badges don't make sense as item counts.
//
// Drafts (admin_content_items) get folded into the tab total instead
// of rendering as the cryptic "+N" — the drafts breakdown is still
// available inside the tab via the stats area.
function countByView() {
  return Object.fromEntries(VIEWS.map((view) => [view.id, countForView(view)]));
}

function countForView(view) {
  if (view.id === "audit") {
    // Phase 5z+18/+19 — total findings across every audit check
    // (now also includes voice fixes + needs review, merged from
    // the old Decisions tab).
    const a = computeCoverageAudit();
    return a.tasksWithoutVendor.length + a.quizUnwired.length + a.vendorsWithoutTasks.length + a.missingVendorTypes.length + a.missingRoutines.length + (a.voiceFixes?.length || 0) + (a.needsReview?.length || 0);
  }
  if (view.id === "notes") {
    // Top-level notes only (replies nest under their parents).
    return state.notes.filter((n) => !n.parentNoteId).length;
  }
  if (view.id === "activity") {
    let events = 0;
    for (const note of state.notes) {
      if (note.appliedAt) events++;
      if (note.revertedAt) events++;
    }
    for (const item of state.adminItems) {
      if (item.lockedAt) events++;
    }
    return events;
  }
  // Phase 85.5: NEEDS-ATTENTION badges now wire to live counts so the
  // operator's at-a-glance "what's piling up" actually reflects reality.
  // Pre-fix the badges all showed 0 even with 5 open cases / 248
  // households / etc.
  if (view.id === "chez") {
    // Cases that need the operator's reply (open + awaiting their action).
    const reqs = state.chezRequests || [];
    return reqs.filter((r) => r.status === "open" && r.unread_for_admin !== false).length;
  }
  if (view.id === "upcoming") {
    // Overdue + today items. This week is too noisy for a badge.
    const items = state.upcoming?.items || [];
    return items.filter((i) => i.priority === "overdue" || i.priority === "today").length;
  }
  if (view.id === "households") {
    // Total households Chez manages — operator-meaningful "size of book".
    const list = state.households?.list;
    if (Array.isArray(list)) return list.length;
    return null;
  }
  if (view.id === "vendor_apps") {
    // Pending / needs-action vendor applications only — certified ones
    // shouldn't push the badge up since they're "done".
    const apps = state.vendorApplications?.items || [];
    return apps.filter((a) => a.status === "pending_email_confirm" || a.status === "live_unverified").length;
  }
  // Tool/info views don't have an item list — no badge.
  if (["simulator", "architecture", "claude_file"].includes(view.id)) {
    return null;
  }
  // Item-list views: live + drafts, view-level structural exclusions
  // applied (so Tasks tab drops handyman items the same way the dropdown
  // bar does).
  const defaults = defaultItemsForView(view.id) || [];
  const drafts = state.adminItems.filter((item) => item.itemType === view.type);
  return navCountForItems(defaults, view.id) + navCountForItems(drafts, view.id);
}

function navCountForItems(items, viewId) {
  if (viewId === "tasks") return items.filter((i) => !isHandymanContextItem(i)).length;
  return items.length;
}

function currentView() {
  return VIEWS.find((view) => view.id === state.view) ?? VIEWS[0];
}

function recommendedQuestionDisposition(id) {
  const cut = new Set(["q5_mortgage", "q23_vehicle_count", "q24_vehicle_add", "q26_auto_insurance", "q29_estate_docs"]);
  const defer = new Set(["q16_electric", "q17_internet"]);
  const reshape = new Set(["q4_purchase", "q30_priorities"]);
  if (cut.has(id)) return { status: "cut", note: "Cut from homeowner first quiz." };
  if (defer.has(id)) return { status: "defer", note: "Move to optional setup after home operating plan." };
  if (reshape.has(id)) return { status: "reshape", note: "Keep the data only if reframed around operations." };
  return { status: "active", note: "Keep in first homeowner quiz." };
}

function classifyTask(row) {
  if (row.Category === "Handyman" || String(row.Bundle || "").startsWith("Handyman")) return "Handyman task";
  if (/Weekly|Biweekly|Monthly|Quarterly|Semi-annually/i.test(row.Frequency || "")) return "Recurring template";
  return "Task";
}

function dbItemToUi(row) {
  return {
    id: row.id,
    source: "admin",
    itemType: row.item_type,
    title: row.title,
    status: row.status,
    category: row.category ?? "",
    sortOrder: row.sort_order ?? 0,
    description: row.description ?? "",
    payload: row.payload ?? {},
    updatedAt: row.updated_at,
    // Phase 7.5 — launch lifecycle
    launchStatus: row.launch_status || "draft",
    lockedAt: row.locked_at || null,
    reviewedAt: row.reviewed_at || null,
    liveEntityId: row.live_entity_id || null,
  };
}

// Phase 7.5 — given a live item, find its admin_content_items shadow row.
function findLockShadow(item) {
  if (item?.source !== "live") return null;
  const liveId = liveEntityIdFor(item);
  if (!liveId) return null;
  return state.adminItems.find(
    (a) => a.itemType === item.itemType && a.liveEntityId === liveId
  );
}

function liveEntityIdFor(item) {
  return (
    item.payload?.id ||
    item.payload?.questionId ||
    item.payload?.templateKey ||
    item.payload?.stableId ||
    item.payload?.categoryKey ||
    item.payload?.functionName ||
    item.payload?.rawValue ||
    item.id
  );
}

function effectiveLaunchStatus(item) {
  if (item.source === "admin") return item.launchStatus || "draft";
  const shadow = findLockShadow(item);
  return shadow?.launchStatus || "draft";
}

// Phase 5x — Bubble the shadow's curation status (cut / defer /
// reshape) up to the live row. Shadows are no longer visible in the
// list, so without this the disposition would be invisible. With it,
// a "cut" disposition on the shadow shows the live row as cut, which
// matches what the user's "Mark cut" action actually means.
function effectiveStatus(item) {
  if (item.source === "admin") return item.status || "draft";
  const shadow = findLockShadow(item);
  // Shadows default to "active" status when they're created just for
  // a lock — only treat as override when the user explicitly picked
  // a curation status (cut / defer / reshape).
  const dispositionStatuses = new Set(["cut", "defer", "reshape"]);
  if (shadow?.status && dispositionStatuses.has(shadow.status)) return shadow.status;
  return item.status || "active";
}

function dbNoteToUi(row) {
  return {
    id: row.id,
    scopeType: row.scope_type,
    scopeId: row.scope_id,
    scopeTitle: row.scope_title,
    body: row.body,
    snapshot: row.snapshot ?? {},
    createdAt: row.created_at,
    intent: row.intent || "feedback",
    target: row.target || "claude",
    author: row.author || "tom",
    appliedAt: row.applied_at || null,
    appliedCommit: row.applied_commit || null,
    proposedDiff: row.proposed_diff ?? null,
    parentNoteId: row.parent_note_id ?? null,
    revertedAt: row.reverted_at ?? null,
    attachmentUrls: Array.isArray(row.attachment_urls) ? row.attachment_urls : [],
  };
}

function cleanEstateLanguage(value) {
  return String(value || "")
    .replace(/estate planning/gi, "home operations")
    .replace(/estate readiness/gi, "home readiness")
    .replace(/Estate/gi, "Home");
}

function splitPipe(value) {
  return String(value || "")
    .split("|")
    .map((x) => x.trim())
    .filter(Boolean);
}

function splitCsv(value) {
  return String(value || "")
    .split(",")
    .map((x) => x.trim())
    .filter(Boolean);
}

function parseJsonLoose(value) {
  try {
    return JSON.parse(value || "{}");
  } catch {
    return { raw: value };
  }
}

function slug(value) {
  return String(value || "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "")
    .slice(0, 60);
}

function readLocal(key) {
  try {
    return JSON.parse(localStorage.getItem(key) || "[]");
  } catch {
    return [];
  }
}

function writeLocal(key, value) {
  localStorage.setItem(key, JSON.stringify(value));
}

function structuredCloneSafe(value) {
  return JSON.parse(JSON.stringify(value ?? {}));
}

function formatDate(iso) {
  if (!iso) return "";
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) return iso;
  return date.toLocaleString(undefined, { month: "short", day: "numeric", hour: "numeric", minute: "2-digit" });
}

function notesMarkdown() {
  const lines = [
    "# Codex Admin Notes",
    "",
    `Exported: ${new Date().toISOString()}`,
    "",
  ];
  for (const note of state.notes) {
    lines.push(`## ${note.scopeTitle || "General note"}`);
    lines.push("");
    lines.push(`- Type: ${note.scopeType || "general"}`);
    if (note.scopeId) lines.push(`- ID: ${note.scopeId}`);
    lines.push(`- Created: ${note.createdAt || ""}`);
    lines.push("");
    lines.push(note.body || "");
    lines.push("");
    lines.push("```json");
    lines.push(JSON.stringify(note.snapshot ?? {}, null, 2));
    lines.push("```");
    lines.push("");
  }
  return lines.join("\n");
}

function downloadText(filename, text) {
  const blob = new Blob([text], { type: "text/plain;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  a.click();
  URL.revokeObjectURL(url);
}

function escapeHtml(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

// Phase 85.5: convert raw enum values (UPPER_SNAKE, lower_snake, camelCase)
// to human-readable strings for UI display. The audit caught a lot of
// these leaking through as labels — "WAITING_CUSTOMER", "OTHER_SERVICE",
// "internet_cable", "PROPOSAL_ADD", "auto_insurance". This helper
// normalizes them at render time without changing the underlying values.
// Special-cases handle common abbreviations / branded labels that the
// generic word-case rule would mangle ("hvac" → "HVAC", "&" → "and").
const PRETTY_ENUM_OVERRIDES = {
  waiting_customer: "Waiting on customer",
  open: "Open",
  resolved: "Resolved",
  other_service: "Other service",
  internet_cable: "Internet & cable",
  auto_insurance: "Auto insurance",
  home_insurance: "Home insurance",
  homeowners: "Homeowners insurance",
  proposal_add: "Proposal added",
  proposal_accepted: "Proposal accepted",
  proposal_declined: "Proposal declined",
  find_vendor: "Find a vendor",
  get_quote: "Get a quote",
  schedule_visit: "Schedule a visit",
  coordinate_task: "Coordinate a task",
  find_handyman: "Find a handyman",
  general: "General",
  electric: "Electric",
  gas: "Gas",
  oil: "Oil",
  propane: "Propane",
  water: "Water",
  trash: "Trash",
  internet: "Internet",
  hvac_service: "HVAC service",
  hvac: "HVAC",
};
// Phase 85.5: format raw phone digits ("2035550100") as US-readable
// "(203) 555-0100". 10 digits formatted, 11 digits (with leading 1)
// formatted with country code, anything else returned as-is so
// international numbers don't get mangled.
function formatPhoneNumber(value) {
  if (value === null || value === undefined || value === "") return "";
  const raw = String(value).trim();
  const digits = raw.replace(/\D/g, "");
  if (digits.length === 10) {
    return `(${digits.slice(0, 3)}) ${digits.slice(3, 6)}-${digits.slice(6)}`;
  }
  if (digits.length === 11 && digits.startsWith("1")) {
    return `+1 (${digits.slice(1, 4)}) ${digits.slice(4, 7)}-${digits.slice(7)}`;
  }
  return raw;
}

function prettifyEnum(value) {
  if (value === null || value === undefined || value === "") return "";
  const lower = String(value).toLowerCase().trim();
  if (PRETTY_ENUM_OVERRIDES[lower]) return PRETTY_ENUM_OVERRIDES[lower];
  // Generic: split on _ / - / camelCase, capitalize first word, lowercase rest.
  const parts = lower
    .replace(/[-_]+/g, " ")
    .replace(/([a-z])([A-Z])/g, "$1 $2")
    .split(/\s+/)
    .filter(Boolean);
  if (parts.length === 0) return "";
  return parts.map((p, i) => {
    // Preserve known acronyms when they appear standalone.
    if (["hvac", "ac", "id", "url", "vin"].includes(p)) return p.toUpperCase();
    return i === 0 ? p[0].toUpperCase() + p.slice(1) : p;
  }).join(" ");
}

// =============================================================================
// Phase 84 — Households workbench + Upcoming feed (admin surfaces)
// =============================================================================
//
// Two new admin tabs alongside Concierge:
//   • Households (per-household ongoing oversight) — list every household
//     with stats + click into a per-household command center showing
//     every owned entity grouped by type.
//   • Upcoming (cross-household priority queue) — every time-bound item
//     across every household, sorted by urgency.
//
// Both reuse the existing admin layout (el.list + el.auditFocused for
// the focused detail rail), so no new HTML container is needed.

// ----- Households list view --------------------------------------------------

async function renderHouseholdsView() {
  // Use the existing standard layout (el.list + el.auditFocused).
  el.search.value = state.search || "";
  el.stats.innerHTML = `<div class="admin-stat"><strong>—</strong><span>Loading…</span></div>`;
  el.list.innerHTML = `<p class="admin-audit__intro">Loading households…</p>`;

  // Fire fetch on first render or after 60s.
  const stale = Date.now() - state.households.listLoadedAt > 60_000;
  if (stale || state.households.list.length === 0) {
    try {
      const result = await callChezConcierge({ action: "fetch_households_list" });
      state.households.list = (result.households ?? []);
      state.households.listLoadedAt = Date.now();
      // Phase 85.5: sidebar Households badge reads state.households.list.length
      // — re-render the sidebar after the list lands so the badge picks up
      // the count instead of remaining at 0.
      renderNav();
    } catch (e) {
      el.list.innerHTML = `<p class="admin-muted">Couldn't load households: ${escapeHtml(String(e.message || e))}</p>`;
      return;
    }
  }

  const items = state.households.list;
  const totalOwned = items.reduce((s, h) => s + (h.owned_count || 0), 0);
  const totalCases = items.reduce((s, h) => s + (h.open_cases || 0), 0);
  const fullyDelegated = items.filter((h) => (h.group_count || 0) >= 8).length;

  el.stats.innerHTML = `
    <div class="admin-stat"><strong>${items.length}</strong><span>Households</span></div>
    <div class="admin-stat"><strong>${totalOwned}</strong><span>Owned entities</span></div>
    <div class="admin-stat"><strong>${totalCases}</strong><span>Open cases</span></div>
    <div class="admin-stat"><strong>${fullyDelegated}</strong><span>Fully delegated</span></div>
  `;

  // Search filter (over name).
  const query = (state.search || "").toLowerCase().trim();
  const filtered = query
    ? items.filter((h) => (h.name || "").toLowerCase().includes(query))
    : items;

  if (filtered.length === 0) {
    el.list.innerHTML = `
      <div class="admin-audit admin-chez">
        <p class="admin-audit__intro">No households yet. New homeowners land here automatically when they sign up.</p>
      </div>
    `;
    return;
  }

  el.list.innerHTML = `
    <div class="admin-audit admin-chez admin-households">
      <p class="admin-audit__intro">
        Every household and what Chez is currently managing for them. Click a row to open the workbench — every owned entity grouped by type with action buttons.
      </p>
      ${filtered.map(renderHouseholdRowHtml).join("")}
    </div>
  `;

  el.list.querySelectorAll("[data-household-id]").forEach((btn) => {
    btn.addEventListener("click", async () => {
      const id = btn.dataset.householdId;
      state.households.selectedId = id;
      await loadHouseholdWorkbench(id);
      renderHouseholdsView();
      renderHouseholdWorkbenchDetail();
    });
  });

  // Restore the focused panel if a household was previously selected.
  if (state.households.selectedId) {
    renderHouseholdWorkbenchDetail();
  } else {
    el.auditFocused?.classList.add("is-hidden");
    el.noteFocused?.classList.add("is-hidden");
    el.decisionFocused?.classList.add("is-hidden");
    el.emptyDetail?.classList.remove("is-hidden");
    el.detail?.classList.add("is-hidden");
    if (el.emptyDetail) {
      el.emptyDetail.querySelector("h3").textContent = "Click a household to open the workbench";
      el.emptyDetail.querySelector("p").textContent = "The workbench shows every entity Chez owns for that household — routines, systems, vendors, projects, documents, bills, insurance, vehicles — with action buttons per row.";
    }
  }
}

function renderHouseholdRowHtml(h) {
  const isActive = state.households.selectedId === h.id;
  const groupBadge = (h.group_count ?? 0) > 0
    ? `<span class="admin-pill" data-tone="green">${h.group_count} ${h.group_count === 1 ? "group" : "groups"} delegated</span>`
    : "";
  const fullPill = (h.group_count ?? 0) >= 8
    ? `<span class="admin-pill" data-tone="green">FULL DELEGATION</span>` : "";
  const lastActivity = h.last_activity_at
    ? `<span class="admin-muted">Last activity ${escapeHtml(relativeTimeString(h.last_activity_at))}</span>`
    : `<span class="admin-muted">No recent activity</span>`;

  return `
    <button type="button" class="admin-audit__row admin-chez__row ${isActive ? "is-active" : ""}" data-household-id="${escapeHtml(h.id)}">
      <div class="admin-audit__row-top">
        <strong>${escapeHtml(h.name || "Household")}</strong>
        ${fullPill || groupBadge}
      </div>
      <p class="admin-audit__row-reason">
        <span>${h.owned_count} owned</span>
        · <span>${h.open_cases} open ${h.open_cases === 1 ? "case" : "cases"}</span>
        · ${lastActivity}
      </p>
    </button>
  `;
}

async function loadHouseholdWorkbench(householdId) {
  try {
    const result = await callChezConcierge({
      action: "fetch_household_workbench",
      household_id: householdId,
    });
    state.households.workbench = result;
    state.households.workbenchLoadedAt = Date.now();
  } catch (e) {
    console.warn("[households] workbench fetch failed", e);
    state.households.workbench = null;
  }
}

function renderHouseholdWorkbenchDetail() {
  if (!state.households.selectedId || !state.households.workbench) return;
  const wb = state.households.workbench;
  const tab = state.households.workbenchTab || "routines";

  el.emptyDetail?.classList.add("is-hidden");
  el.detail?.classList.remove("is-hidden");
  el.detailTabs?.classList.add("is-hidden");
  el.curatedForm?.classList.add("is-hidden");
  if (el.formHost) el.formHost.innerHTML = "";
  if (el.diffHost) el.diffHost.innerHTML = "";
  document.querySelector("[data-detail-quick-actions]")?.classList.add("is-hidden");
  el.noteFocused?.classList.add("is-hidden");
  el.decisionFocused?.classList.add("is-hidden");
  el.detailActionsRow?.classList.add("is-hidden");
  el.notesBox?.classList.add("is-hidden");
  el.promoteItem.disabled = true;
  el.duplicateItem.disabled = true;
  el.deleteItem.disabled = true;
  el.saveItem.textContent = "Save";
  el.saveItem.disabled = true;

  if (!el.auditFocused) return;
  el.auditFocused.classList.remove("is-hidden");
  el.auditFocused.innerHTML = renderHouseholdWorkbenchHtml(wb, tab);

  // Tab switcher. Clear search query on tab switch (per-tab, not sticky).
  el.auditFocused.querySelectorAll("[data-workbench-tab]").forEach((btn) => {
    btn.addEventListener("click", () => {
      state.households.workbenchTab = btn.dataset.workbenchTab;
      state.households.workbenchQuery = "";
      // Owned-only flag intentionally persists across tab switches so
      // an operator narrowing to "Chez-owned only" stays narrowed.
      renderHouseholdWorkbenchDetail();
    });
  });

  // Phase 85 PR 5B — search input. Debounced re-render.
  const searchInput = el.auditFocused.querySelector("[data-workbench-search]");
  if (searchInput) {
    let searchDebounce;
    searchInput.addEventListener("input", (e) => {
      const v = e.target.value;
      clearTimeout(searchDebounce);
      searchDebounce = setTimeout(() => {
        state.households.workbenchQuery = v;
        renderHouseholdWorkbenchDetail();
        // Restore focus + caret after re-render.
        const newInput = el.auditFocused.querySelector("[data-workbench-search]");
        if (newInput) {
          newInput.focus();
          newInput.setSelectionRange(v.length, v.length);
        }
      }, 120);
    });
  }

  // Phase 85 PR 5B — owned-only toggle chip.
  el.auditFocused.querySelector("[data-workbench-owned-toggle]")?.addEventListener("click", () => {
    state.households.workbenchOwnedOnly = !state.households.workbenchOwnedOnly;
    renderHouseholdWorkbenchDetail();
  });

  // Phase 85.7 — Bulk propose Chez ownership. Sends one batched
  // proposal containing every non-owned, non-pending entity on the
  // current tab. Server caps at 50 entities per proposal.
  el.auditFocused.querySelector("[data-workbench-bulk-propose]")?.addEventListener("click", async (e) => {
    const btn = e.currentTarget;
    const tab = btn.dataset.tab;
    const wb = state.households.workbench;
    if (!wb || !tab) return;
    const entities = proposableEntitiesForTab(wb, tab);
    if (entities.length === 0) {
      showAdminToast("No entities to propose on this tab.", { kind: "info" });
      return;
    }
    const householdId = state.households.selectedId;
    const preface = await openProposeOwnershipModal({
      entityLabel: `${entities.length} ${tab === "vendors" ? "vendor" + (entities.length === 1 ? "" : "s") : tab}`,
      entityType: "bulk",
    });
    if (preface === null) return;
    btn.disabled = true;
    btn.textContent = "Sending…";
    try {
      const result = await callChezConcierge({
        action: "propose_ownership",
        household_id: householdId,
        entities,
        preface: preface || undefined,
      });
      await loadHouseholdWorkbench(householdId);
      renderHouseholdWorkbenchDetail();
      const proposed = result?.proposed ?? entities.length;
      const skippedCount = (result?.skipped_for_cooldown || []).length;
      showAdminToast(
        `Proposal sent to homeowner with ${proposed} ${tab === "vendors" ? "vendor" + (proposed === 1 ? "" : "s") : tab}.` + (skippedCount > 0 ? ` ${skippedCount} skipped (cooldown).` : ""),
        { kind: "info" }
      );
    } catch (err) {
      console.error("[bulk propose] failed", err);
      btn.disabled = false;
      btn.textContent = `Propose Chez ownership of ${entities.length} ${tab}`;
      showAdminToast(`Couldn't send batched proposal: ${err.message || err}`, { kind: "error" });
    }
  });

  // Phase 85 PR 5C — entity row drill-in. Clicking the row (but not a
  // button inside) opens the focused-detail panel for that entity.
  // Action buttons inside the row e.stopPropagation in their own handler
  // so they don't trip this.
  el.auditFocused.querySelectorAll("[data-drill-entity-id]").forEach((row) => {
    row.addEventListener("click", () => {
      const entityType = row.dataset.drillEntityType;
      const entityId = row.dataset.drillEntityId;
      if (!entityType || !entityId) return;
      openFocusedEntityDetail(entityType, entityId);
    });
  });

  // Phase 84 PR 4 — wire per-entity action buttons. Each fires
  // `workbench_action` server-side, which records an audit row +
  // executes the side effect (insert service_record / update task /
  // etc.). The "open_project_workbench" action is handled locally —
  // it opens the negotiation modal instead of firing an Edge
  // Function call.
  el.auditFocused.querySelectorAll('[data-cockpit-action="workbench-action"]').forEach((btn) => {
    btn.addEventListener("click", async (e) => {
      e.stopPropagation();
      const actionId = btn.dataset.actionId;
      const entityType = btn.dataset.entityType;
      const entityId = btn.dataset.entityId;
      if (!actionId || !entityType || !entityId) return;

      // Project negotiation pane — open the modal, don't fire the action yet.
      if (actionId === "open_project_workbench") {
        await openProjectNegotiationModal(entityId);
        return;
      }

      const householdId = state.households.selectedId;
      if (!householdId) return;
      // Phase 85 PR 5E — every action goes through openWorkbenchActionModal
      // which (a) prompts for the action's required payload (date, cost,
      // notes, etc.), (b) fires the workbench_action Edge Function call,
      // and (c) refreshes the workbench in place. Buttons no longer fire
      // empty-payload calls — every click captures the operator's intent.
      const original = btn.textContent;
      btn.disabled = true;
      btn.textContent = "…";
      try {
        const submitted = await openWorkbenchActionModal({
          actionId,
          entityType,
          entityId,
          householdId,
        });
        if (!submitted) {
          btn.disabled = false;
          btn.textContent = original;
          return;
        }
        btn.textContent = "✓ Logged";
        await loadHouseholdWorkbench(householdId);
        renderHouseholdWorkbenchDetail();
      } catch (err) {
        console.error("[workbench-action] failed:", err);
        btn.textContent = "Failed — retry";
        btn.disabled = false;
      }
    });
  });

  // Phase 84 PR 4 — open-cases strip deep-link wiring (was missing in
  // PR 4; landed dead). Click a workbench case row → flip to the
  // cockpit with the case selected.
  el.auditFocused.querySelectorAll("[data-workbench-case-id]").forEach((btn) => {
    btn.addEventListener("click", async () => {
      const id = btn.dataset.workbenchCaseId;
      const req = (state.chezRequests || []).find((r) => r.id === id);
      if (!req) return;
      state.view = "chez";
      state.selectedChezRequest = req;
      state.concierge.queueMode = "case";
      try { await loadChezMessages(id); } catch (e) { console.warn("[workbench→case] message load failed", e); }
      render();
    });
  });
}

// Phase 84 PR 4 — Project negotiation pane modal. Renders
// project_quotes for the selected project + each quote's
// negotiation_history as a chronological feed. Composer at
// the bottom posts a new turn via add_project_negotiation_turn.
async function openProjectNegotiationModal(projectId) {
  const overlay = document.createElement("div");
  overlay.className = "admin-modal-overlay";
  overlay.innerHTML = `
    <div class="admin-modal admin-modal--wide">
      <header class="admin-modal__head">
        <h2>Project negotiation</h2>
        <button type="button" class="admin-modal__close" aria-label="Close">&times;</button>
      </header>
      <div class="admin-modal__body" data-negotiation-body>
        <p class="admin-muted">Loading quotes…</p>
      </div>
    </div>
  `;
  document.body.appendChild(overlay);
  overlay.querySelector(".admin-modal__close").addEventListener("click", () => overlay.remove());
  overlay.addEventListener("click", (e) => { if (e.target === overlay) overlay.remove(); });

  const body = overlay.querySelector("[data-negotiation-body]");
  try {
    // Pull the project's quotes directly from PostgREST — admin uses
    // service-role context via supabase.auth, so the existing
    // PostgREST client suffices for the read.
    const { data: quotes, error } = await supabase
      .from("project_quotes")
      .select("id, project_id, vendor_name, total_amount_cents, status, negotiation_history, updated_at")
      .eq("project_id", projectId)
      .order("created_at", { ascending: true });
    if (error) throw error;
    body.innerHTML = renderNegotiationModalHtml(projectId, quotes || []);
    attachNegotiationModalHandlers(overlay, projectId);
  } catch (e) {
    body.innerHTML = `<p class="admin-error">Failed to load quotes: ${escapeHtml(String(e))}</p>`;
  }
}

function renderNegotiationModalHtml(projectId, quotes) {
  if (!Array.isArray(quotes) || quotes.length === 0) {
    return `<p class="admin-muted">No quotes on this project yet. Vendor sourcing happens in the cockpit's vendor pane.</p>`;
  }
  return `
    <div class="admin-negotiation">
      ${quotes.map((q) => {
        const turns = Array.isArray(q.negotiation_history) ? q.negotiation_history : [];
        const latestPrice = turns
          .slice()
          .reverse()
          .find((t) => typeof t.price_cents === "number")?.price_cents;
        return `
          <article class="admin-negotiation__quote" data-quote-id="${escapeHtml(q.id)}">
            <header class="admin-negotiation__quote-head">
              <strong>${escapeHtml(q.vendor_name || "(unnamed vendor)")}</strong>
              <span class="admin-pill" data-tone="${q.status === "accepted" ? "success" : "muted"}">${escapeHtml(q.status || "pending")}</span>
              <span class="admin-muted">
                ${typeof q.total_amount_cents === "number" ? "Initial: $" + formatCompact(q.total_amount_cents / 100) : ""}
                ${typeof latestPrice === "number" ? " · Current: $" + formatCompact(latestPrice / 100) : ""}
              </span>
            </header>
            <div class="admin-negotiation__feed">
              ${turns.length === 0 ? `<p class="admin-muted">No back-and-forth yet. Add the first turn below.</p>` : turns.map((t) => `
                <div class="admin-negotiation__turn admin-negotiation__turn--${escapeHtml(t.from || "chez")}">
                  <span class="admin-negotiation__turn-from">${t.from === "chez" ? "Chez" : "Vendor"}</span>
                  <span class="admin-negotiation__turn-meta">${escapeHtml(relativeTimeString(t.sent_at))}${typeof t.price_cents === "number" ? " · $" + formatCompact(t.price_cents / 100) : ""}</span>
                  <p>${escapeHtml(t.message || "")}</p>
                </div>
              `).join("")}
            </div>
            <form class="admin-negotiation__composer" data-composer-quote="${escapeHtml(q.id)}">
              <select data-composer-from class="admin-input">
                <option value="chez">Chez (operator)</option>
                <option value="vendor">Vendor (response)</option>
              </select>
              <input type="number" min="0" step="1" placeholder="New price ($)" data-composer-price class="admin-input admin-input--narrow" />
              <textarea placeholder="Message (e.g. 'Can you do better than $12,400?')" data-composer-message class="admin-input" rows="2" required></textarea>
              <button type="submit" class="admin-pill admin-pill--action">Add turn</button>
            </form>
          </article>
        `;
      }).join("")}
    </div>
  `;
}

function attachNegotiationModalHandlers(overlay, projectId) {
  overlay.querySelectorAll('[data-composer-quote]').forEach((form) => {
    form.addEventListener("submit", async (e) => {
      e.preventDefault();
      const quoteId = form.dataset.composerQuote;
      const from = form.querySelector('[data-composer-from]').value;
      const message = form.querySelector('[data-composer-message]').value.trim();
      const priceStr = form.querySelector('[data-composer-price]').value.trim();
      const price_cents = priceStr ? Math.round(Number(priceStr) * 100) : undefined;
      if (!quoteId || !message) return;
      const submitBtn = form.querySelector('button[type="submit"]');
      submitBtn.disabled = true;
      submitBtn.textContent = "Saving…";
      try {
        await callChezConcierge({
          action: "add_project_negotiation_turn",
          quote_id: quoteId,
          from,
          message,
          price_cents,
        });
        // Re-render the modal in place to surface the new turn.
        const body = overlay.querySelector("[data-negotiation-body]");
        body.innerHTML = `<p class="admin-muted">Refreshing…</p>`;
        const { data: quotes } = await supabase
          .from("project_quotes")
          .select("id, project_id, vendor_name, total_amount_cents, status, negotiation_history, updated_at")
          .eq("project_id", projectId)
          .order("created_at", { ascending: true });
        body.innerHTML = renderNegotiationModalHtml(projectId, quotes || []);
        attachNegotiationModalHandlers(overlay, projectId);
      } catch (err) {
        submitBtn.textContent = "Failed — retry";
        submitBtn.disabled = false;
        console.error("[negotiation] add turn failed:", err);
      }
    });
  });
}

// =============================================================================
// Phase 85 PR 5C — Focused entity detail panel
//
// When the operator clicks any entity row on the workbench (or arrives
// via Upcoming), the right pane swaps from the workbench list to a
// focused-detail view of that entity. The view mirrors what the
// homeowner sees in the iOS app, exposed as editable form fields where
// applicable, plus admin-only affordances (Send message to homeowner,
// Add admin note, the workbench actions stack).
// =============================================================================

async function openFocusedEntityDetail(entityType, entityId) {
  if (!entityType || !entityId) return;
  let wb = state.households.workbench;
  // If we're navigating from Upcoming or another household, we may not
  // have the target household's workbench loaded yet. Resolve by walking
  // every household's cache or requesting fresh.
  if (!wb) {
    console.warn("[focused] no workbench loaded — caller should load first");
    return;
  }
  state.households.focusedEntity = { type: entityType, id: entityId };
  state.households.focusedEntityData = lookupFocusedEntity(wb, entityType, entityId);
  state.households.focusedEntityRelations = {};
  renderFocusedEntityDetail();
  hydrateFocusedEntityRelations(entityType, entityId).then(() => {
    if (state.households.focusedEntity?.type === entityType &&
        state.households.focusedEntity?.id === entityId) {
      renderFocusedEntityDetail();
    }
  }).catch((e) => console.warn("[focused] hydrate failed", e));
}

function closeFocusedEntityDetail() {
  state.households.focusedEntity = null;
  state.households.focusedEntityData = null;
  state.households.focusedEntityRelations = {};
  // Phase 85 PR 5.1 — when the focused detail was opened from the
  // Upcoming feed, "Back" should return to the Upcoming empty-state
  // pane, not the households workbench list. Branch on state.view.
  if (state.view === "upcoming") {
    state.upcoming.selectedItemId = null;
    renderUpcomingView();
    return;
  }
  renderHouseholdWorkbenchDetail();
}

function lookupFocusedEntity(wb, entityType, entityId) {
  const find = (arr) => (arr || []).find((x) => x.id === entityId) ?? null;
  switch (entityType) {
    case "task": return find(wb.tasks);
    case "system": return find(wb.home_systems);
    case "routine": return find(wb.routines);
    case "contractor": return find(wb.contractors);
    case "project": return find(wb.projects);
    case "document": return find(wb.documents);
    case "utility": return find(wb.utility_accounts);
    case "vehicle": return find(wb.vehicles);
    // Phase 85.5: handyman_punch_list is a synthetic "entity" that
    // represents the household's pending punch list as a whole. The
    // entityId is the household_id, and the rendered detail iterates
    // wb.handyman_punch_items.
    case "handyman_punch_list":
      return { id: entityId, type: "handyman_punch_list", items: wb.handyman_punch_items || [] };
    default: return null;
  }
}

async function hydrateFocusedEntityRelations(entityType, entityId) {
  const relations = state.households.focusedEntityRelations =
    state.households.focusedEntityRelations || {};
  switch (entityType) {
    case "system": {
      const [services, warranties] = await Promise.all([
        supabase.from("service_records").select("*").eq("system_id", entityId).order("service_date", { ascending: false }).limit(20),
        supabase.from("warranties").select("*").eq("home_system_id", entityId),
      ]);
      relations.services = services.data || [];
      relations.warranties = warranties.data || [];
      break;
    }
    case "routine": {
      const r = await supabase.from("routine_visits").select("*").eq("routine_id", entityId).order("scheduled_date", { ascending: false }).limit(30);
      relations.visits = r.data || [];
      break;
    }
    case "contractor": {
      const r = await supabase.from("contractor_engagement_log").select("*").eq("contractor_id", entityId).order("created_at", { ascending: false }).limit(20);
      relations.engagements = r.data || [];
      break;
    }
    case "vehicle": {
      const r = await supabase.from("vehicle_recalls").select("*").eq("vehicle_id", entityId);
      relations.recalls = r.data || [];
      break;
    }
    default:
      break;
  }
}

function renderFocusedEntityDetail() {
  if (!el.auditFocused) return;
  const focused = state.households.focusedEntity;
  if (!focused) {
    renderHouseholdWorkbenchDetail();
    return;
  }
  // Phase 85.5: when the focused panel is opened from Upcoming, the
  // `admin-detail` parent + sibling `admin-empty-detail` were hidden by
  // renderUpcomingView() so they have to be flipped back on here. Same
  // for the Households view's empty-state pane.
  el.detail?.classList.remove("is-hidden");
  el.emptyDetail?.classList.add("is-hidden");
  el.noteFocused?.classList.add("is-hidden");
  el.decisionFocused?.classList.add("is-hidden");
  const entity = state.households.focusedEntityData;
  if (!entity) {
    // Phase 85.5: Improved error copy — the audit found that when an
    // Upcoming row points at a household that's been archived or has
    // duplicates, the operator just sees "Entity not found" with no
    // explanation. Surface the household + entity type + offer the
    // workbench jump as an explicit recovery action.
    const wb = state.households.workbench || {};
    const householdLabel = wb.household?.primary_name || wb.household?.display_name || "this household";
    el.auditFocused.classList.remove("is-hidden");
    el.auditFocused.innerHTML = `
      <section class="admin-focused">
        <header class="admin-focused__head">
          <button type="button" class="admin-pill" data-focused-back>← Back</button>
          <h2>This ${escapeHtml(focused.type)} isn't in ${escapeHtml(householdLabel)}</h2>
        </header>
        <p class="admin-muted">The Upcoming row's entity (${escapeHtml(focused.id)}) wasn't found in this household's workbench. The most common cause is a duplicate test household — the Upcoming feed routes to one row but the data lives on another. Verify the household name on the Upcoming row matches the one open here.</p>
        <div class="admin-focused__action-row" style="margin-top: 12px;">
          <button type="button" class="admin-pill admin-pill--action" data-focused-open-workbench>Open this household's workbench</button>
          <button type="button" class="admin-pill" data-focused-back>Back to Upcoming</button>
        </div>
      </section>
    `;
    el.auditFocused.querySelectorAll("[data-focused-back]").forEach((b) => b.addEventListener("click", closeFocusedEntityDetail));
    el.auditFocused.querySelector("[data-focused-open-workbench]")?.addEventListener("click", async () => {
      state.view = "households";
      render();
    });
    return;
  }
  const wb = state.households.workbench || {};
  const relations = state.households.focusedEntityRelations || {};
  let body = "";
  switch (focused.type) {
    case "task":      body = renderFocusedTaskHtml(entity, wb); break;
    case "system":    body = renderFocusedSystemHtml(entity, wb, relations); break;
    case "routine":   body = renderFocusedRoutineHtml(entity, wb, relations); break;
    case "contractor": body = renderFocusedContractorHtml(entity, wb, relations); break;
    case "project":   body = renderFocusedProjectHtml(entity, wb); break;
    case "document":  body = renderFocusedDocumentHtml(entity, wb); break;
    case "utility":   body = renderFocusedUtilityHtml(entity, wb); break;
    case "vehicle":   body = renderFocusedVehicleHtml(entity, wb, relations); break;
    case "handyman_punch_list": body = renderFocusedHandymanPunchListHtml(entity, wb); break;
    default:          body = `<p class="admin-muted">Detail view for "${escapeHtml(focused.type)}" not built yet.</p>`;
  }
  el.auditFocused.classList.remove("is-hidden");
  el.auditFocused.innerHTML = `
    <section class="admin-focused admin-households__focused">
      <header class="admin-focused__head admin-focused__head--compact">
        <button type="button" class="admin-pill admin-households__back-pill" data-focused-back>← Back to workbench</button>
      </header>
      ${body}
    </section>
  `;
  attachFocusedEntityHandlers();
}

function attachFocusedEntityHandlers() {
  const focused = state.households.focusedEntity;
  if (!focused) return;
  const householdId = state.households.selectedId;

  el.auditFocused.querySelector("[data-focused-back]")?.addEventListener("click", closeFocusedEntityDetail);

  // Workbench action buttons inside the focused panel use the same
  // dispatcher as the workbench list.
  el.auditFocused.querySelectorAll('[data-cockpit-action="workbench-action"]').forEach((btn) => {
    btn.addEventListener("click", async (e) => {
      e.stopPropagation();
      const actionId = btn.dataset.actionId;
      const entityType = btn.dataset.entityType;
      const entityId = btn.dataset.entityId;
      if (!actionId || !entityType || !entityId) return;
      if (actionId === "open_project_workbench") {
        await openProjectNegotiationModal(entityId);
        return;
      }
      const original = btn.textContent;
      btn.disabled = true;
      btn.textContent = "…";
      try {
        const submitted = await openWorkbenchActionModal({ actionId, entityType, entityId, householdId });
        if (!submitted) {
          btn.disabled = false;
          btn.textContent = original;
          return;
        }
        btn.textContent = "✓ Logged";
        await loadHouseholdWorkbench(householdId);
        state.households.focusedEntityData = lookupFocusedEntity(state.households.workbench, focused.type, focused.id);
        await hydrateFocusedEntityRelations(focused.type, focused.id);
        renderFocusedEntityDetail();
      } catch (err) {
        console.error("[focused] action failed", err);
        btn.textContent = "Failed — retry";
        btn.disabled = false;
      }
    });
  });

  // Drill into related rows (sub-systems, linked tasks, etc.) inside
  // a focused panel — same drill-in pattern as the workbench list.
  el.auditFocused.querySelectorAll("[data-drill-entity-id]").forEach((row) => {
    row.addEventListener("click", (e) => {
      if (e.target.closest("button")) return;
      openFocusedEntityDetail(row.dataset.drillEntityType, row.dataset.drillEntityId);
    });
  });

  // Phase 85.6 Phase C: inline cross-entity links (e.g., the "System"
  // value on a Task panel is a button that drills to that System).
  el.auditFocused.querySelectorAll("[data-drill-link-id]").forEach((btn) => {
    btn.addEventListener("click", (e) => {
      e.stopPropagation();
      openFocusedEntityDetail(btn.dataset.drillLinkType, btn.dataset.drillLinkId);
    });
  });

  // Phase 85.5: handyman punch list actions. Schedule visit → opens the
  // workbench schedule_service modal targeting the household's standing
  // handyman contractor. Mark filed → archives the punch item via direct
  // PostgREST so it drops off the active list immediately.
  el.auditFocused.querySelector("[data-handyman-schedule-visit]")?.addEventListener("click", async () => {
    // Use the existing schedule-visit modal pattern but scoped to handyman
    // — captures date + optional notes, then writes via chez-concierge.
    const submitted = await openWorkbenchActionModal({
      actionId: "schedule_visit",
      entityType: "handyman_punch_list",
      entityId: focused.id,
      householdId,
    });
    if (submitted) {
      await loadHouseholdWorkbench(householdId);
      renderFocusedEntityDetail();
      showAdminToast("Handyman visit scheduled.", { kind: "info" });
    }
  });
  el.auditFocused.querySelectorAll("[data-handyman-mark-filed]").forEach((btn) => {
    btn.addEventListener("click", async () => {
      const punchId = btn.dataset.punchId;
      if (!punchId) return;
      const ok = await openConfirmModal({
        title: "Mark this punch item filed?",
        body: "Drops it off the active backlog. You can still see it in completed history.",
        confirmLabel: "Mark filed",
      });
      if (!ok) return;
      btn.disabled = true;
      btn.textContent = "…";
      try {
        // Direct PostgREST update — handyman_punch_items has RLS scoped
        // to household members; admin operators read via service-role
        // through the workbench fetch but write here via the standard
        // chez-concierge action so the audit log captures the operator.
        await callChezConcierge({
          action: "workbench_action",
          household_id: householdId,
          entity_type: "handyman_punch_item",
          entity_id: punchId,
          action_type: "mark_filed",
          payload: {},
        });
        await loadHouseholdWorkbench(householdId);
        state.households.focusedEntityData = lookupFocusedEntity(state.households.workbench, focused.type, focused.id);
        renderFocusedEntityDetail();
      } catch (err) {
        console.warn("[focused] mark filed failed", err);
        btn.disabled = false;
        btn.textContent = "Mark filed";
        showAdminToast(`Couldn't file: ${err.message || err}`, { kind: "error" });
      }
    });
  });

  // Workbench case rows inside focused panels deep-link to the cockpit.
  el.auditFocused.querySelectorAll("[data-workbench-case-id]").forEach((btn) => {
    btn.addEventListener("click", async () => {
      const id = btn.dataset.workbenchCaseId;
      const req = (state.chezRequests || []).find((r) => r.id === id);
      if (!req) return;
      state.view = "chez";
      state.selectedChezRequest = req;
      state.concierge.queueMode = "case";
      try { await loadChezMessages(id); } catch (e) { console.warn("[focused→case] load failed", e); }
      render();
    });
  });

  // ✉ Message homeowner.
  el.auditFocused.querySelector("[data-focused-message-homeowner]")?.addEventListener("click", () => {
    const requestId = el.auditFocused.querySelector("[data-focused-message-homeowner]").dataset.requestId;
    openMessageHomeownerModal({ requestId, entityType: focused.type, entityId: focused.id, householdId });
  });

  // + Add admin note.
  el.auditFocused.querySelector("[data-focused-add-note]")?.addEventListener("click", async () => {
    const submitted = await openWorkbenchActionModal({
      actionId: "admin_note",
      entityType: focused.type,
      entityId: focused.id,
      householdId,
    });
    if (submitted) {
      await loadHouseholdWorkbench(householdId);
      renderFocusedEntityDetail();
    }
  });

  // Toggle Chez ownership inline.
  // Phase 85.5: gate the revoke direction behind an in-app confirm modal
  // (delegation was previously direct-fire — the audit caught this as
  // a destructive customer-visible action with no undo step). Also passes
  // `household_id` explicitly so admin operators (who don't have a
  // household_id on their user row) don't trip the server's "no household"
  // 404 — root cause of the toggle failure observed in the audit.
  // Phase 85.6: state-aware ownership button. Dispatches on the
  // data-ownership-state attribute set by renderOwnershipPill. Three
  // paths:
  //   owned   → confirm modal → existing delegate_* with delegated:false
  //   pending → jump to the open proposal thread in the cockpit
  //   propose → open the propose-ownership modal → server inserts a
  //             chez_request with category=ownership_request + proposal
  el.auditFocused.querySelector("[data-focused-toggle-owned]")?.addEventListener("click", async (e) => {
    const btn = e.currentTarget;
    const ownershipState = btn.dataset.ownershipState;
    const entity = state.households.focusedEntityData;
    const entityLabel = focusedEntityLabel(focused.type, entity) || focused.type;

    if (ownershipState === "pending") {
      // Jump the operator into the cockpit at the pending proposal thread.
      const reqId = entity?.pending_ownership_request_id;
      if (!reqId) {
        showAdminToast("Pending proposal request not found. Refresh the workbench.", { kind: "error" });
        return;
      }
      const req = (state.chezRequests || []).find((r) => r.id === reqId);
      state.view = "chez";
      if (req) {
        state.selectedChezRequest = req;
        state.concierge.queueMode = "case";
        try { await loadChezMessages(reqId); } catch { /* noop */ }
      }
      render();
      return;
    }

    if (ownershipState === "owned") {
      const ok = await openConfirmModal({
        title: `Revoke Chez ownership?`,
        body: `${entityLabel} will drop off the homeowner's delegated list. The Standing-engagement thread stays but no new system messages will fire.`,
        confirmLabel: "Revoke ownership",
        danger: true,
      });
      if (!ok) return;
      btn.disabled = true;
      btn.textContent = "…";
      try {
        const t = focused.type;
        const body = (t === "task")
          ? { action: "delegate_task",       household_id: householdId, task_id: focused.id,       delegated: false }
          : (t === "routine")
          ? { action: "delegate_routine",    household_id: householdId, routine_id: focused.id,    delegated: false }
          : (t === "contractor" || t === "vendor")
          ? { action: "delegate_contractor", household_id: householdId, contractor_id: focused.id, delegated: false }
          : { action: "delegate_entity",     household_id: householdId, entity_type: t,            entity_id: focused.id, delegated: false };
        await callChezConcierge(body);
        await loadHouseholdWorkbench(householdId);
        state.households.focusedEntityData = lookupFocusedEntity(state.households.workbench, focused.type, focused.id);
        renderFocusedEntityDetail();
        showAdminToast(`Chez no longer owns ${entityLabel}.`, { kind: "info" });
      } catch (err) {
        console.error("[focused] revoke failed", err);
        btn.disabled = false;
        btn.textContent = "Revoke Chez ownership";
        showAdminToast(`Couldn't revoke: ${err.message || err}`, { kind: "error" });
      }
      return;
    }

    // Default path: propose ownership. Opens a modal that captures an
    // optional preface message + sends the proposal to the homeowner.
    const preface = await openProposeOwnershipModal({ entityLabel, entityType: focused.type });
    if (preface === null) return;     // operator cancelled
    btn.disabled = true;
    btn.textContent = "Sending…";
    try {
      const result = await callChezConcierge({
        action: "propose_ownership",
        household_id: householdId,
        entities: [{
          entity_type: focused.type,
          entity_id: focused.id,
          label: entityLabel,
        }],
        preface: preface || undefined,
      });
      await loadHouseholdWorkbench(householdId);
      await loadAdminData();
      state.households.focusedEntityData = lookupFocusedEntity(state.households.workbench, focused.type, focused.id);
      renderFocusedEntityDetail();
      const reqId = result?.request_id;
      showAdminToast(
        `Proposal sent. Homeowner will see it in their iOS inbox.` + (reqId ? ` (Case ${String(reqId).slice(0, 8)})` : ""),
        { kind: "info" }
      );
    } catch (err) {
      console.error("[focused] propose ownership failed", err);
      btn.disabled = false;
      btn.textContent = "Propose Chez ownership";
      // Surface cooldown rejections specifically so the operator
      // understands why the proposal didn't go through.
      const msg = err?.message || err;
      if (typeof msg === "string" && msg.includes("cooldown")) {
        showAdminToast("This entity is on a 60-day cooldown from a prior decline. Try again after the cooldown expires.", { kind: "error", ms: 6000 });
      } else {
        showAdminToast(`Couldn't send proposal: ${msg}`, { kind: "error" });
      }
    }
  });
}

// Phase 85.6: small modal asking the operator for an optional preface
// message before sending an ownership proposal. Returns the typed
// preface (possibly empty string for "use the default") or null on cancel.
function openProposeOwnershipModal({ entityLabel, entityType }) {
  return new Promise((resolve) => {
    const overlay = document.createElement("div");
    overlay.className = "admin-modal-overlay";
    overlay.innerHTML = `
      <div class="admin-modal admin-modal--sm" role="dialog" aria-modal="true">
        <header class="admin-modal__head">
          <h2>Propose ownership: ${escapeHtml(entityLabel)}</h2>
          <button type="button" class="admin-modal__close" aria-label="Close" data-propose-cancel>&times;</button>
        </header>
        <div class="admin-modal__body">
          <p class="admin-modal__intro">The homeowner will see an Approve / Decline card in their iOS inbox. On approve, Chez takes over scheduling + follow-up. On decline, the request goes on a 60-day cooldown.</p>
          <label class="admin-modal__field">
            <span>Optional message (otherwise we send a default)</span>
            <textarea data-propose-preface rows="3" class="admin-input" placeholder="Hey Margaret — I noticed you've been asking about boiler care. Can Chez take this over so you don't have to think about it?"></textarea>
          </label>
        </div>
        <div class="admin-modal__buttons" style="padding: 0 16px 16px;">
          <button type="button" class="admin-pill" data-propose-cancel>Cancel</button>
          <button type="button" class="admin-pill admin-pill--action" data-propose-ok>Send proposal</button>
        </div>
      </div>
    `;
    document.body.appendChild(overlay);
    const textarea = overlay.querySelector("[data-propose-preface]");
    const cleanup = (result) => {
      document.removeEventListener("keydown", onKey);
      overlay.remove();
      resolve(result);
    };
    const onKey = (e) => {
      if (e.key === "Escape") { e.preventDefault(); cleanup(null); }
    };
    document.addEventListener("keydown", onKey);
    overlay.querySelectorAll("[data-propose-cancel]").forEach((b) => b.addEventListener("click", () => cleanup(null)));
    overlay.querySelector("[data-propose-ok]").addEventListener("click", () => cleanup(textarea.value.trim()));
    overlay.addEventListener("click", (e) => { if (e.target === overlay) cleanup(null); });
    requestAnimationFrame(() => textarea.focus());
  });
}

// Phase 85.7: helpers for the bulk propose-ownership button on workbench
// tab headers. countProposableInTab returns just the count for the chip
// label; proposableEntitiesForTab returns the actual [{entity_type, entity_id}]
// list shaped for the propose_ownership action payload. Bills (utilities)
// route through entity_type "utility"; vendors route through "contractor".
function _tabEntityType(tab) {
  return tab === "tasks" ? "task"
    : tab === "systems" ? "system"
    : tab === "routines" ? "routine"
    : tab === "vendors" ? "contractor"
    : tab === "projects" ? "project"
    : tab === "documents" ? "document"
    : tab === "bills" ? "utility"
    : tab === "vehicles" ? "vehicle"
    : null;
}
function _tabCollection(wb, tab) {
  return tab === "tasks" ? (wb.tasks || []).filter((t) => !t.is_archived)
    : tab === "systems" ? (wb.home_systems || [])
    : tab === "routines" ? (wb.routines || [])
    : tab === "vendors" ? (wb.contractors || [])
    : tab === "projects" ? (wb.projects || [])
    : tab === "documents" ? (wb.documents || [])
    : tab === "bills" ? (wb.utility_accounts || [])
    : tab === "vehicles" ? (wb.vehicles || [])
    : [];
}
function proposableEntitiesForTab(wb, tab) {
  const eType = _tabEntityType(tab);
  if (!eType) return [];
  const rows = _tabCollection(wb, tab);
  // Filter out: already owned, pending proposal, or archived. Server-side
  // cooldown check will skip 60-day-declined entities at request time
  // and surface them via the `skipped_for_cooldown` response field.
  return rows
    .filter((r) => !r.chez_owned && !r.pending_ownership_request_id)
    .slice(0, 50)  // server cap
    .map((r) => ({
      entity_type: eType,
      entity_id: r.id,
      label: r.title || r.label || r.name || r.company_name || r.filename || r.provider_name
            || (r.year && r.make ? `${r.year} ${r.make} ${r.model || ""}`.trim() : null)
            || r.id.slice(0, 8),
    }));
}
function countProposableInTab(wb, tab) {
  return proposableEntitiesForTab(wb, tab).length;
}

// Phase 85.6: state-aware ownership pill. The same affordance renders in
// four different states depending on the entity's current ownership +
// any pending proposal:
//
//   1. NOT OWNED, no pending proposal     → "Propose Chez ownership"
//   2. PENDING proposal (homeowner hasn't decided yet) → "Awaiting approval"
//   3. OWNED                                → "Revoke Chez ownership" (confirm)
//   4. On cooldown (declined within 60d)    → server rejects propose; no
//      special UI here, the propose click lands an explanatory toast.
//
// The button is wired by a single shared handler below that dispatches
// on the current state.
function renderOwnershipPill(entity) {
  if (!entity) return "";
  if (entity.chez_owned) {
    return `<button type="button" class="admin-pill" data-focused-toggle-owned data-ownership-state="owned">Revoke Chez ownership</button>`;
  }
  if (entity.pending_ownership_request_id) {
    return `<button type="button" class="admin-pill admin-pill--ghost" data-focused-toggle-owned data-ownership-state="pending" title="Tap to open the open proposal thread.">Awaiting homeowner approval</button>`;
  }
  return `<button type="button" class="admin-pill admin-pill--action" data-focused-toggle-owned data-ownership-state="propose">Propose Chez ownership</button>`;
}

// Tiny helper to label a focused entity for confirm-modal copy.
function focusedEntityLabel(type, entity) {
  if (!entity) return "this item";
  if (type === "task") return entity.title || "this task";
  if (type === "system" || type === "home_system") return entity.name || entity.category || "this system";
  if (type === "routine") return entity.label || "this routine";
  if (type === "contractor" || type === "vendor") return entity.company_name || "this vendor";
  if (type === "project") return entity.name || "this project";
  if (type === "document") return entity.title || entity.filename || "this document";
  if (type === "utility_account" || type === "bill") return entity.provider_name || "this bill";
  if (type === "vehicle") return [entity.year, entity.make, entity.model].filter(Boolean).join(" ") || "this vehicle";
  return "this item";
}

function activeMonthsLabel(months) {
  if (!Array.isArray(months) || months.length === 0) return "Year-round";
  if (months.length === 12) return "Year-round";
  const names = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
  return months.slice().sort((a,b) => a-b).map((m) => names[m-1]).join(" · ");
}

// ----- Per-type focused detail renderers -----------------------------------

// Phase 85.6 Phase C: Task parity rebuild. Mirrors iOS
// MaintenanceTaskDetailSheet section-by-section:
//   1. Header (title + frequency pill + priority pill)
//   2. Status line (Next visit / Last completed / Scheduled / Unscheduled)
//   3. Field grid (system, vendor, estimated cost, assignee)
//   4. Description (cleaned — bundle checklist block stripped)
//   5. WHAT'S INCLUDED — bundle checklist parsed from notes/description
//   6. CUSTOM ADDITIONS — bundle_custom_subitems rows for this bundle_id
//   7. Notes (cleaned — bundle block stripped)
//   8. Actions row (Schedule / Mark complete / Snooze + ownership + msg)
//   9. Linked case (if chez_request_id)

// Helper: extract the "What's included:" checklist block from a notes
// or description string. Mirrors the iOS extractBundledChecklist + filter:
//   - Find "What's included:" marker
//   - Take first paragraph (up to blank line)
//   - Return lines starting with "- "
function extractBundleChecklistLines(text) {
  if (!text) return [];
  const marker = text.indexOf("What's included:");
  if (marker < 0) return [];
  const trailing = text.substring(marker);
  const firstParagraph = trailing.split(/\n\n/)[0] || "";
  const lines = firstParagraph
    .split(/\n/)
    .map((l) => l.trim())
    .filter((l) => l.startsWith("- "))
    .map((l) => l.substring(2).trim())
    .filter((l) => l.length > 0);
  return lines;
}

// Strip the bundle-checklist block from cleaned description/notes so
// the operator doesn't see the same items twice.
function stripBundleChecklistBlock(text) {
  if (!text) return text;
  const marker = text.indexOf("What's included:");
  if (marker < 0) return text;
  const trailing = text.substring(marker);
  const firstParagraph = trailing.split(/\n\n/)[0] || "";
  return text.replace(firstParagraph, "").trim();
}

function renderFocusedTaskHtml(t, wb) {
  const system = (wb.home_systems || []).find((s) => s.id === t.system_id);
  const vendor = (wb.contractors || []).find((c) => c.id === t.assigned_contractor_id);
  const assignee = (wb.users || []).find((u) => u.id === t.assigned_to_user_id);
  const ownedBadge = t.chez_owned ? `<span class="admin-pill admin-pill--owned">★ Chez owns</span>` : "";
  const status = t.last_completed_date
    ? `Completed ${formatDateOnly(t.last_completed_date)}`
    : t.scheduled_date
    ? `Scheduled ${formatDateOnly(t.scheduled_date)}`
    : t.next_due_date
    ? `Due ${formatDateOnly(t.next_due_date)}`
    : "Unscheduled";

  // Phase 85.6 Phase C: bundle checklist parity. iOS pulls from notes
  // first then description; admin does the same.
  const bundleLines = extractBundleChecklistLines(t.notes) .length > 0
    ? extractBundleChecklistLines(t.notes)
    : extractBundleChecklistLines(t.description);
  const isBundleParent = bundleLines.length > 0 && !!t.template_id;
  const cleanDesc = stripBundleChecklistBlock(t.description);
  const cleanNotes = stripBundleChecklistBlock(t.notes);
  const customSubitems = isBundleParent
    ? (wb.bundle_custom_subitems || []).filter((s) => s.bundle_id === t.template_id)
    : [];

  return `
    <article class="admin-focused__entity">
      <header class="admin-focused__entity-head">
        <h2>${escapeHtml(t.title || "(untitled task)")}</h2>
        <div class="admin-focused__entity-meta">
          ${ownedBadge}
          ${t.frequency ? `<span class="admin-pill admin-pill--note">${escapeHtml(prettifyEnum(t.frequency))}</span>` : ""}
          ${t.priority && t.priority !== "high" ? `<span class="admin-pill">${escapeHtml(prettifyEnum(t.priority))}</span>` : ""}
          ${isBundleParent ? `<span class="admin-pill admin-pill--note">Bundle · ${bundleLines.length} items</span>` : ""}
        </div>
      </header>

      <section class="admin-focused__field-grid">
        <div><label>Status</label><strong>${escapeHtml(status)}</strong></div>
        <div><label>Assignment</label><strong>${escapeHtml(prettifyEnum(t.assignment_type) || "Task")}</strong></div>
        <div><label>System</label><strong>${system ? `<button type="button" class="admin-link-inline" data-drill-link-type="system" data-drill-link-id="${escapeHtml(system.id)}">${escapeHtml(system.name || system.category)}</button>` : "—"}</strong></div>
        <div><label>Vendor</label><strong>${vendor ? `<button type="button" class="admin-link-inline" data-drill-link-type="contractor" data-drill-link-id="${escapeHtml(vendor.id)}">${escapeHtml(vendor.company_name)}</button>` : (t.needs_vendor ? "Needs vendor" : "—")}</strong></div>
        ${assignee ? `<div><label>Assigned to</label><strong>${escapeHtml(assignee.full_name || assignee.email || "")}</strong></div>` : ""}
        <div><label>Estimated cost</label><strong>${t.estimated_cost ? "$" + formatCompact(t.estimated_cost) : "—"}</strong></div>
        <div><label>Last completed</label><strong>${t.last_completed_date ? formatDateOnly(t.last_completed_date) : "Never"}</strong></div>
        ${t.diy_effort_minutes ? `<div><label>DIY effort</label><strong>${t.diy_effort_minutes < 60 ? t.diy_effort_minutes + " min" : Math.round(t.diy_effort_minutes / 60 * 10) / 10 + " hr"}</strong></div>` : ""}
      </section>

      ${cleanDesc ? `<section class="admin-focused__notes-block"><h3>Description</h3><p>${escapeHtml(cleanDesc)}</p></section>` : ""}

      ${bundleLines.length > 0 ? `
        <section class="admin-focused__list-block">
          <h3>What's included · ${bundleLines.length}</h3>
          <ul class="admin-focused__checklist">
            ${bundleLines.map((l) => `<li>${escapeHtml(l)}</li>`).join("")}
          </ul>
        </section>` : ""}

      ${isBundleParent ? `
        <section class="admin-focused__list-block">
          <h3>Custom additions${customSubitems.length > 0 ? " · " + customSubitems.length : ""}</h3>
          ${customSubitems.length === 0
            ? `<p class="admin-muted">No homeowner-added items for this visit yet.</p>`
            : customSubitems.map((s) => `
              <div class="admin-households__entity-row">
                <div class="admin-households__entity-main">
                  <strong>${escapeHtml(s.title)}</strong>
                  <span class="admin-muted">${s.recurrence === "always" ? "Every visit" : "Just this visit"}${s.added_at ? " · Added " + formatDateOnly(s.added_at) : ""}</span>
                </div>
              </div>`).join("")}
        </section>` : ""}

      ${cleanNotes ? `<section class="admin-focused__notes-block"><h3>Notes</h3><p>${escapeHtml(cleanNotes)}</p></section>` : ""}

      <section class="admin-focused__actions">
        <h3>Actions</h3>
        <div class="admin-focused__action-row">
          <button type="button" class="admin-pill admin-pill--action" data-cockpit-action="workbench-action" data-action-id="schedule" data-entity-type="task" data-entity-id="${escapeHtml(t.id)}">Schedule</button>
          <button type="button" class="admin-pill admin-pill--action" data-cockpit-action="workbench-action" data-action-id="complete_on_behalf" data-entity-type="task" data-entity-id="${escapeHtml(t.id)}">Mark complete</button>
          <button type="button" class="admin-pill" data-cockpit-action="workbench-action" data-action-id="snooze" data-entity-type="task" data-entity-id="${escapeHtml(t.id)}">Snooze 7d</button>
          ${renderOwnershipPill(t)}
        </div>
        <div class="admin-focused__action-row">
          <button type="button" class="admin-pill admin-pill--action admin-pill--secondary" data-focused-message-homeowner data-request-id="${escapeHtml(t.chez_request_id || "")}">✉ Message homeowner</button>
          <button type="button" class="admin-pill" data-focused-add-note>+ Add admin note</button>
        </div>
      </section>

      ${t.chez_request_id ? `
        <section class="admin-focused__notes-block">
          <h3>Linked case</h3>
          <button type="button" class="admin-pill" data-workbench-case-id="${escapeHtml(t.chez_request_id)}">Open case in cockpit →</button>
        </section>
      ` : ""}
    </article>
  `;
}

// Phase 85.7: System parity rebuild. Mirrors iOS SystemDetailView:
// brand identity row, equipment spec card, service cadence with the
// override origin (system frequency vs template default), components,
// service history, warranties, linked tasks, and a preferred vendor
// drill-in if one's set.
function renderFocusedSystemHtml(s, wb, rel) {
  const childSystems = (wb.home_systems || []).filter((x) => x.parent_system_id === s.id);
  const linkedTasks = (wb.tasks || []).filter((t) => t.system_id === s.id && !t.is_archived);
  // Service history can come from rel.services (focused load) OR wb.vehicle_service_records
  // (none for non-vehicle systems). Defer to rel.
  const services = rel.services || [];
  const warranties = rel.warranties || [];
  const ownedBadge = s.chez_owned ? `<span class="admin-pill admin-pill--owned">★ Chez owns</span>` : "";
  const preferredVendor = s.preferred_vendor_id ? (wb.contractors || []).find((c) => c.id === s.preferred_vendor_id) : null;
  // Computed: years since install + remaining lifespan estimate.
  const installDate = s.install_date ? new Date(s.install_date) : null;
  const ageYears = installDate ? Math.floor((Date.now() - installDate.getTime()) / (365.25 * 86400000)) : null;
  // Service cadence — show "Every N days" or rough cadence in years.
  const cadenceLabel = (() => {
    const days = s.service_interval_days;
    if (!days) return null;
    if (days >= 330) return `Every ${Math.round(days / 365)}y`;
    if (days >= 28) return `Every ${Math.round(days / 30)}mo`;
    if (days >= 6) return `Every ${Math.round(days / 7)}w`;
    return `Every ${days}d`;
  })();
  const cadenceSource = s.service_interval_source && s.service_interval_source !== "default" ? prettifyEnum(s.service_interval_source) : null;
  // Section visibility: avoid dedupe-by-name issue ("Sump Pump · Sump Pump").
  const headerTitle = (s.name && s.name !== s.category) ? s.name : s.category;
  return `
    <article class="admin-focused__entity">
      <header class="admin-focused__entity-head">
        <h2>${escapeHtml(headerTitle || "System")}</h2>
        <div class="admin-focused__entity-meta">
          ${ownedBadge}
          ${s.name && s.name !== s.category ? `<span class="admin-pill admin-pill--note">${escapeHtml(s.category)}</span>` : ""}
          ${s.subtype ? `<span class="admin-pill">${escapeHtml(prettifyEnum(s.subtype))}</span>` : ""}
          ${s.setup_state && s.setup_state !== "active" ? `<span class="admin-pill admin-pill--warning">${escapeHtml(prettifyEnum(s.setup_state))}</span>` : ""}
          ${cadenceLabel ? `<span class="admin-pill">${escapeHtml(cadenceLabel)}</span>` : ""}
        </div>
      </header>

      <section class="admin-focused__field-grid">
        <div><label>Manufacturer</label><strong>${escapeHtml(s.manufacturer || "Not on file")}</strong></div>
        <div><label>Model</label><strong>${escapeHtml(s.model_number || s.model || "Not on file")}</strong></div>
        <div><label>Serial</label><strong>${escapeHtml(s.serial_number || "Not on file")}</strong></div>
        <div><label>Installed</label><strong>${s.install_date ? formatDateOnly(s.install_date) + (ageYears !== null ? ` · ${ageYears}y old` : "") : "Not on file"}</strong></div>
        <div><label>Last service</label><strong>${s.last_service_date ? formatDateOnly(s.last_service_date) : "Not on file"}</strong></div>
        <div><label>Next service</label><strong>${s.next_maintenance_date ? formatDateOnly(s.next_maintenance_date) : "Not on file"}</strong></div>
        ${cadenceLabel ? `<div><label>Service cadence</label><strong>${escapeHtml(cadenceLabel)}${cadenceSource ? ` <span class="admin-muted">(${escapeHtml(cadenceSource)})</span>` : ""}</strong></div>` : ""}
        ${preferredVendor ? `<div><label>Preferred vendor</label><strong><button type="button" class="admin-link-inline" data-drill-link-type="contractor" data-drill-link-id="${escapeHtml(preferredVendor.id)}">${escapeHtml(preferredVendor.company_name)}</button></strong></div>` : ""}
      </section>

      ${s.notes ? `<section class="admin-focused__notes-block"><h3>Notes</h3><p>${escapeHtml(s.notes)}</p></section>` : ""}

      <section class="admin-focused__actions">
        <div class="admin-focused__action-row">
          <button type="button" class="admin-pill admin-pill--action" data-cockpit-action="workbench-action" data-action-id="log_service" data-entity-type="system" data-entity-id="${escapeHtml(s.id)}">Log service</button>
          <button type="button" class="admin-pill admin-pill--action" data-cockpit-action="workbench-action" data-action-id="schedule_maintenance" data-entity-type="system" data-entity-id="${escapeHtml(s.id)}">Schedule maintenance</button>
          ${renderOwnershipPill(s)}
          <button type="button" class="admin-pill admin-pill--secondary" data-focused-message-homeowner>✉ Message homeowner</button>
          <button type="button" class="admin-pill" data-focused-add-note>+ Add admin note</button>
        </div>
      </section>

      ${childSystems.length > 0 ? `
        <section class="admin-focused__list-block">
          <h3>Components · ${childSystems.length}</h3>
          ${childSystems.map((c) => `
            <div class="admin-households__entity-row is-clickable" data-drill-entity-type="system" data-drill-entity-id="${escapeHtml(c.id)}">
              <div class="admin-households__entity-main">
                <strong>${escapeHtml(c.name || c.category)}</strong>
                <span class="admin-muted">${escapeHtml(c.manufacturer || "")}${c.model_number ? " · " + escapeHtml(c.model_number) : ""}</span>
              </div>
              <span class="admin-households__entity-chevron" aria-hidden="true">›</span>
            </div>`).join("")}
        </section>` : ""}

      ${linkedTasks.length > 0 ? `
        <section class="admin-focused__list-block">
          <h3>Maintenance tasks · ${linkedTasks.length}</h3>
          ${linkedTasks.slice(0, 8).map((t) => `
            <div class="admin-households__entity-row is-clickable" data-drill-entity-type="task" data-drill-entity-id="${escapeHtml(t.id)}">
              <div class="admin-households__entity-main">
                <strong>${escapeHtml(t.title)}</strong>
                <span class="admin-muted">${escapeHtml(prettifyEnum(t.frequency) || "")}${t.next_due_date ? " · Due " + formatDateOnly(t.next_due_date) : ""}</span>
              </div>
              <span class="admin-households__entity-chevron" aria-hidden="true">›</span>
            </div>`).join("")}
        </section>` : ""}

      ${services.length > 0 ? `
        <section class="admin-focused__list-block">
          <h3>Service history · ${services.length}</h3>
          ${services.slice(0, 10).map((sv) => `
            <div class="admin-households__entity-row">
              <div class="admin-households__entity-main">
                <strong>${escapeHtml(sv.service_type || "Service")}${sv.cost ? " · $" + formatCompact(sv.cost) : ""}</strong>
                <span class="admin-muted">${sv.service_date ? formatDateOnly(sv.service_date) : ""}${sv.description ? " · " + escapeHtml(String(sv.description).slice(0, 80)) : ""}</span>
              </div>
            </div>`).join("")}
        </section>` : ""}

      ${warranties.length > 0 ? `
        <section class="admin-focused__list-block">
          <h3>Warranties · ${warranties.length}</h3>
          ${warranties.map((w) => `
            <div class="admin-households__entity-row">
              <div class="admin-households__entity-main">
                <strong>${escapeHtml(w.coverage_type || "Warranty")}</strong>
                <span class="admin-muted">${w.expires_at ? "Expires " + formatDateOnly(w.expires_at) : "No expiry on file"}${w.provider ? " · " + escapeHtml(w.provider) : ""}</span>
              </div>
            </div>`).join("")}
        </section>` : ""}
    </article>
  `;
}

// Phase 85.7: Routine parity rebuild. Mirrors iOS RoutineDetailView:
// brand-led header (vendor logo/name + service kind), schedule card
// (cadence + days + time + active months), vendor card with drill-in,
// cost summary, visit history (computed total + recent list), linked
// one-off tasks, notes.
function renderFocusedRoutineHtml(r, wb, rel) {
  const vendor = (wb.contractors || []).find((c) => c.id === r.vendor_id);
  const visits = rel.visits || [];
  // Linked one-off tasks (iOS shows these under "Linked tasks").
  const linkedTasks = (wb.tasks || []).filter((t) => t.routine_id === r.id && !t.is_archived);
  const ownedBadge = r.chez_owned ? `<span class="admin-pill admin-pill--owned">★ Chez owns</span>` : "";
  const cadenceLabel = (() => {
    const type = prettifyEnum(r.cadence_type);
    if (!type) return "—";
    if (r.cadence_interval_days && type !== "Weekly") return `${type} (${r.cadence_interval_days}d)`;
    return type;
  })();
  const dayLabels = ["Sun","Mon","Tue","Wed","Thu","Fri","Sat"];
  const dows = (Array.isArray(r.days_of_week) && r.days_of_week.length > 0)
    ? r.days_of_week.map((d) => dayLabels[((d - 1) % 7 + 7) % 7]).join(" · ")
    : null;
  // Cost rollup from visits.
  const totalSpent = visits.reduce((s, v) => s + (Number(v.actual_cost_cents) || 0), 0) / 100;
  const completedVisits = visits.filter((v) => v.visit_state === "completed" || v.status === "completed");
  return `
    <article class="admin-focused__entity">
      <header class="admin-focused__entity-head">
        <h2>${escapeHtml(r.label || prettifyEnum(r.routine_kind) || "Routine")}</h2>
        <div class="admin-focused__entity-meta">
          ${ownedBadge}
          <span class="admin-pill admin-pill--note">${escapeHtml(prettifyEnum(r.routine_kind))}</span>
          <span class="admin-pill">${escapeHtml(cadenceLabel)}</span>
          ${r.setup_state && r.setup_state !== "active" ? `<span class="admin-pill admin-pill--warning">${escapeHtml(prettifyEnum(r.setup_state))}</span>` : ""}
        </div>
      </header>

      <section class="admin-focused__field-grid">
        <div><label>Cadence</label><strong>${escapeHtml(cadenceLabel)}</strong></div>
        ${dows ? `<div><label>Days</label><strong>${escapeHtml(dows)}</strong></div>` : ""}
        <div><label>Time</label><strong>${escapeHtml(r.time_of_day || "Any time")}</strong></div>
        <div><label>Active months</label><strong>${escapeHtml(activeMonthsLabel(r.active_months))}</strong></div>
        <div><label>Cost / visit</label><strong>${r.cost_per_visit_cents ? "$" + formatCompact(r.cost_per_visit_cents / 100) : "Not set"}</strong></div>
        ${r.next_visit_date ? `<div><label>Next visit</label><strong>${formatDateOnly(r.next_visit_date)}</strong></div>` : ""}
      </section>

      ${vendor ? `
        <section class="admin-focused__list-block">
          <h3>Vendor</h3>
          <div class="admin-households__entity-row is-clickable" data-drill-entity-type="contractor" data-drill-entity-id="${escapeHtml(vendor.id)}">
            <div class="admin-households__entity-main">
              <strong>${escapeHtml(vendor.company_name)}</strong>
              <span class="admin-muted">${escapeHtml(vendor.category || "")}${vendor.phone ? " · " + formatPhoneNumber(vendor.phone) : ""}</span>
            </div>
            <span class="admin-households__entity-chevron" aria-hidden="true">›</span>
          </div>
        </section>` : `
        <section class="admin-focused__list-block">
          <h3>Vendor</h3>
          <p class="admin-muted">No vendor linked to this routine. Visits will need to be coordinated manually.</p>
        </section>`}

      ${r.notes ? `<section class="admin-focused__notes-block"><h3>Notes</h3><p>${escapeHtml(r.notes)}</p></section>` : ""}

      <section class="admin-focused__actions">
        <div class="admin-focused__action-row">
          <button type="button" class="admin-pill admin-pill--action" data-cockpit-action="workbench-action" data-action-id="schedule_visit" data-entity-type="routine" data-entity-id="${escapeHtml(r.id)}">Schedule next visit</button>
          <button type="button" class="admin-pill admin-pill--action" data-cockpit-action="workbench-action" data-action-id="log_visit" data-entity-type="routine" data-entity-id="${escapeHtml(r.id)}">Log a visit</button>
          ${renderOwnershipPill(r)}
          <button type="button" class="admin-pill admin-pill--secondary" data-focused-message-homeowner>✉ Message homeowner</button>
          <button type="button" class="admin-pill" data-focused-add-note>+ Add admin note</button>
        </div>
      </section>

      ${visits.length > 0 ? `
        <section class="admin-focused__list-block">
          <h3>Visit history · ${visits.length} ${completedVisits.length > 0 ? "· $" + formatCompact(totalSpent) + " total" : ""}</h3>
          ${visits.slice(0, 12).map((v) => `
            <div class="admin-households__entity-row">
              <div class="admin-households__entity-main">
                <strong>${v.scheduled_date ? formatDateOnly(v.scheduled_date) : "—"}${v.actual_cost_cents ? " · $" + formatCompact(v.actual_cost_cents / 100) : ""}</strong>
                <span class="admin-muted">${escapeHtml(prettifyEnum(v.visit_state || v.status) || "")}${v.notes ? " · " + escapeHtml(String(v.notes).slice(0, 80)) : ""}</span>
              </div>
            </div>`).join("")}
        </section>` : `
        <section class="admin-focused__list-block">
          <h3>Visit history</h3>
          <p class="admin-muted">No visits logged yet. Use "Log a visit" above to record completed work.</p>
        </section>`}

      ${linkedTasks.length > 0 ? `
        <section class="admin-focused__list-block">
          <h3>Linked tasks · ${linkedTasks.length}</h3>
          ${linkedTasks.slice(0, 6).map((t) => `
            <div class="admin-households__entity-row is-clickable" data-drill-entity-type="task" data-drill-entity-id="${escapeHtml(t.id)}">
              <div class="admin-households__entity-main">
                <strong>${escapeHtml(t.title)}</strong>
                <span class="admin-muted">${t.next_due_date ? "Due " + formatDateOnly(t.next_due_date) : "Unscheduled"}</span>
              </div>
              <span class="admin-households__entity-chevron" aria-hidden="true">›</span>
            </div>`).join("")}
        </section>` : ""}
    </article>
  `;
}

// Phase 85.7: Contractor (Vendor) parity rebuild. Mirrors iOS
// ContractorDetailView: contact card, source provenance, coverage
// (linked systems / routines / vehicles / tasks), engagement log.
function renderFocusedContractorHtml(c, wb, rel) {
  const linkedSystems = (wb.home_systems || []).filter((s) => s.preferred_vendor_id === c.id);
  const linkedRoutines = (wb.routines || []).filter((r) => r.vendor_id === c.id);
  const linkedTasks = (wb.tasks || []).filter((t) => t.assigned_contractor_id === c.id && !t.is_archived);
  const linkedVehicles = (wb.vehicles || []).filter((v) => v.preferred_mechanic_id === c.id);
  const engagements = rel.engagements || [];
  const ownedBadge = c.chez_owned ? `<span class="admin-pill admin-pill--owned">★ Chez owns</span>` : "";
  // Coverage rollup — how many entities does this vendor cover?
  const coverageCount = linkedSystems.length + linkedRoutines.length + linkedTasks.length + linkedVehicles.length;
  // Engagement summary: count by direction.
  const calls = engagements.filter((e) => e.channel === "call").length;
  const emails = engagements.filter((e) => e.channel === "email").length;
  const lastEngagement = engagements[0];
  return `
    <article class="admin-focused__entity">
      <header class="admin-focused__entity-head">
        <h2>${escapeHtml(c.company_name || "(unnamed vendor)")}</h2>
        <div class="admin-focused__entity-meta">
          ${ownedBadge}
          <span class="admin-pill admin-pill--note">${escapeHtml(c.category || "Vendor")}</span>
          ${c.chez_recommended_at ? `<span class="admin-pill">Sourced by Chez</span>` : ""}
          ${coverageCount > 0 ? `<span class="admin-pill">${coverageCount} linked</span>` : ""}
        </div>
      </header>
      <section class="admin-focused__field-grid">
        <div><label>Phone</label><strong>${c.phone ? `<a href="tel:${escapeHtml(c.phone)}" class="admin-link-inline">${escapeHtml(formatPhoneNumber(c.phone))}</a>` : "Not on file"}</strong></div>
        <div><label>Email</label><strong>${c.email ? `<a href="mailto:${escapeHtml(c.email)}" class="admin-link-inline">${escapeHtml(c.email)}</a>` : "Not on file"}</strong></div>
        <div><label>Website</label><strong>${c.website ? `<a href="${escapeHtml(c.website)}" target="_blank" rel="noopener" class="admin-link-inline">${escapeHtml(c.website)}</a>` : "Not on file"}</strong></div>
        <div><label>Source</label><strong>${escapeHtml(prettifyEnum(c.source) || "Manual entry")}</strong></div>
        ${c.contact_name ? `<div><label>Primary contact</label><strong>${escapeHtml(c.contact_name)}</strong></div>` : ""}
        ${lastEngagement ? `<div><label>Last engagement</label><strong>${escapeHtml(relativeTimeString(lastEngagement.created_at))} · ${escapeHtml(prettifyEnum(lastEngagement.channel))}</strong></div>` : ""}
      </section>
      <section class="admin-focused__actions">
        <div class="admin-focused__action-row">
          <button type="button" class="admin-pill admin-pill--action" data-cockpit-action="workbench-action" data-action-id="log_call" data-entity-type="contractor" data-entity-id="${escapeHtml(c.id)}">Log a call</button>
          <button type="button" class="admin-pill admin-pill--action" data-cockpit-action="workbench-action" data-action-id="send_message" data-entity-type="contractor" data-entity-id="${escapeHtml(c.id)}">Record message</button>
          ${renderOwnershipPill(c)}
          <button type="button" class="admin-pill admin-pill--secondary" data-focused-message-homeowner>✉ Message homeowner</button>
          <button type="button" class="admin-pill" data-focused-add-note>+ Add admin note</button>
        </div>
      </section>
      ${linkedSystems.length > 0 ? `
        <section class="admin-focused__list-block">
          <h3>Linked systems · ${linkedSystems.length}</h3>
          ${linkedSystems.map((s) => `<div class="admin-households__entity-row is-clickable" data-drill-entity-type="system" data-drill-entity-id="${escapeHtml(s.id)}"><div class="admin-households__entity-main"><strong>${escapeHtml(s.name || s.category)}</strong><span class="admin-muted">${escapeHtml(s.category)}</span></div><span class="admin-households__entity-chevron" aria-hidden="true">›</span></div>`).join("")}
        </section>` : ""}
      ${linkedRoutines.length > 0 ? `
        <section class="admin-focused__list-block">
          <h3>Linked routines · ${linkedRoutines.length}</h3>
          ${linkedRoutines.map((r) => `<div class="admin-households__entity-row is-clickable" data-drill-entity-type="routine" data-drill-entity-id="${escapeHtml(r.id)}"><div class="admin-households__entity-main"><strong>${escapeHtml(r.label || prettifyEnum(r.routine_kind))}</strong><span class="admin-muted">${escapeHtml(prettifyEnum(r.cadence_type))}</span></div><span class="admin-households__entity-chevron" aria-hidden="true">›</span></div>`).join("")}
        </section>` : ""}
      ${linkedVehicles.length > 0 ? `
        <section class="admin-focused__list-block">
          <h3>Mechanic for · ${linkedVehicles.length} ${linkedVehicles.length === 1 ? "vehicle" : "vehicles"}</h3>
          ${linkedVehicles.map((v) => `<div class="admin-households__entity-row is-clickable" data-drill-entity-type="vehicle" data-drill-entity-id="${escapeHtml(v.id)}"><div class="admin-households__entity-main"><strong>${escapeHtml([v.year, v.make, v.model].filter(Boolean).join(" "))}</strong><span class="admin-muted">${escapeHtml(v.license_plate || "")}</span></div><span class="admin-households__entity-chevron" aria-hidden="true">›</span></div>`).join("")}
        </section>` : ""}
      ${linkedTasks.length > 0 ? `
        <section class="admin-focused__list-block">
          <h3>Open tasks · ${linkedTasks.length}</h3>
          ${linkedTasks.slice(0, 8).map((t) => `<div class="admin-households__entity-row is-clickable" data-drill-entity-type="task" data-drill-entity-id="${escapeHtml(t.id)}"><div class="admin-households__entity-main"><strong>${escapeHtml(t.title)}</strong><span class="admin-muted">${t.next_due_date ? "Due " + formatDateOnly(t.next_due_date) : "Unscheduled"}</span></div><span class="admin-households__entity-chevron" aria-hidden="true">›</span></div>`).join("")}
        </section>` : ""}
      ${engagements.length > 0 ? `
        <section class="admin-focused__list-block">
          <h3>Engagement history · ${engagements.length}${calls + emails > 0 ? ` · ${calls} calls, ${emails} emails` : ""}</h3>
          ${engagements.slice(0, 10).map((e) => `<div class="admin-households__entity-row"><div class="admin-households__entity-main"><strong>${escapeHtml(prettifyEnum(e.channel))} · ${e.direction === "outbound" ? "Chez → Vendor" : "Vendor → Chez"}</strong><span class="admin-muted">${escapeHtml(relativeTimeString(e.created_at))}${e.subject ? " · " + escapeHtml(e.subject) : ""}${e.notes ? " · " + escapeHtml(String(e.notes).slice(0, 60)) : ""}</span></div></div>`).join("")}
        </section>` : `
        <section class="admin-focused__list-block">
          <h3>Engagement history</h3>
          <p class="admin-muted">No engagements logged yet. Use "Log a call" above to start the timeline.</p>
        </section>`}
    </article>
  `;
}

// Phase 85.7: Project parity rebuild. Mirrors iOS ProjectDetailView:
// timeline (start / target / actual), budget tracking, linked documents
// (filtered from workbench), description, action chips.
function renderFocusedProjectHtml(p, wb) {
  const ownedBadge = p.chez_owned ? `<span class="admin-pill admin-pill--owned">★ Chez owns</span>` : "";
  const linkedDocs = (wb.documents || []).filter((d) => d.project_id === p.id);
  // Status pill tone — completed projects feel different from active ones.
  const status = p.status || "planned";
  const statusTone = status === "completed" ? "active" : status === "active" ? "active" : "muted";
  return `
    <article class="admin-focused__entity">
      <header class="admin-focused__entity-head">
        <h2>${escapeHtml(p.name)}</h2>
        <div class="admin-focused__entity-meta">
          ${ownedBadge}
          <span class="admin-pill" data-tone="${statusTone}">${escapeHtml(prettifyEnum(status))}</span>
          ${p.project_type ? `<span class="admin-pill admin-pill--note">${escapeHtml(prettifyEnum(p.project_type))}</span>` : ""}
          ${p.entry_type === "historical" ? `<span class="admin-pill">Historical entry</span>` : ""}
        </div>
      </header>

      <section class="admin-focused__field-grid">
        <div><label>Estimated budget</label><strong>${p.estimated_budget ? "$" + formatCompact(p.estimated_budget) : "Not set"}</strong></div>
        ${p.total_spent ? `<div><label>Total spent</label><strong>$${formatCompact(p.total_spent)}</strong></div>` : ""}
        ${p.start_date ? `<div><label>Started</label><strong>${formatDateOnly(p.start_date)}</strong></div>` : ""}
        ${p.target_completion_date ? `<div><label>Target completion</label><strong>${formatDateOnly(p.target_completion_date)}</strong></div>` : ""}
        ${p.completed_at ? `<div><label>Completed</label><strong>${formatDateOnly(p.completed_at)}</strong></div>` : ""}
        ${p.active_quote_id ? `<div><label>Active quote</label><strong>${escapeHtml(String(p.active_quote_id).slice(0, 8))}</strong></div>` : ""}
      </section>

      ${p.description ? `<section class="admin-focused__notes-block"><h3>Description</h3><p>${escapeHtml(p.description)}</p></section>` : ""}

      <section class="admin-focused__actions">
        <div class="admin-focused__action-row">
          <button type="button" class="admin-pill admin-pill--action" data-cockpit-action="workbench-action" data-action-id="open_project_workbench" data-entity-type="project" data-entity-id="${escapeHtml(p.id)}">Open negotiation pane</button>
          ${renderOwnershipPill(p)}
          <button type="button" class="admin-pill admin-pill--secondary" data-focused-message-homeowner>✉ Message homeowner</button>
          <button type="button" class="admin-pill" data-focused-add-note>+ Add admin note</button>
        </div>
      </section>

      ${linkedDocs.length > 0 ? `
        <section class="admin-focused__list-block">
          <h3>Project documents · ${linkedDocs.length}</h3>
          ${linkedDocs.slice(0, 10).map((d) => `
            <div class="admin-households__entity-row is-clickable" data-drill-entity-type="document" data-drill-entity-id="${escapeHtml(d.id)}">
              <div class="admin-households__entity-main">
                <strong>${escapeHtml(d.filename || "Document")}</strong>
                <span class="admin-muted">${escapeHtml(d.category || "Unfiled")}${d.created_at ? " · Uploaded " + formatDateOnly(d.created_at) : ""}</span>
              </div>
              <span class="admin-households__entity-chevron" aria-hidden="true">›</span>
            </div>`).join("")}
        </section>` : ""}
    </article>
  `;
}

// Phase 85.6 Phase C: Document parity rebuild. Mirrors iOS
// DocumentDetailView section-by-section:
//   1. Header (filename + category pill + filing status)
//   2. Metadata grid (type, uploaded, expiration, file linked entities)
//   3. Notes (homeowner notes)
//   4. Linked-entity rows (system / project / vehicle this doc belongs to)
//   5. Actions row (Mark filed / Share / Ownership / Message)
//
// We don't render the actual PDF preview (security + load weight); the
// admin gets a "View original" button that hits the existing
// view-document Edge Function which streams the decrypted file.
function renderFocusedDocumentHtml(d, wb) {
  const ownedBadge = d.chez_owned ? `<span class="admin-pill admin-pill--owned">★ Chez owns</span>` : "";
  const filedPill = d.chez_filed_at
    ? `<span class="admin-pill">Filed ${relativeTimeString(d.chez_filed_at)}</span>`
    : `<span class="admin-pill admin-pill--warning">Needs filing</span>`;
  const linkedSystem = d.system_id ? (wb.home_systems || []).find((s) => s.id === d.system_id) : null;
  const linkedProject = d.project_id ? (wb.projects || []).find((p) => p.id === d.project_id) : null;
  const linkedVehicle = d.vehicle_id ? (wb.vehicles || []).find((v) => v.id === d.vehicle_id) : null;
  const expiringSoon = (() => {
    if (!d.expiration_date) return false;
    const diff = (new Date(d.expiration_date).getTime() - Date.now()) / 86400000;
    return diff >= 0 && diff <= 30;
  })();
  return `
    <article class="admin-focused__entity">
      <header class="admin-focused__entity-head">
        <h2>${escapeHtml(d.filename || "(no filename)")}</h2>
        <div class="admin-focused__entity-meta">
          ${ownedBadge}${filedPill}
          <span class="admin-pill admin-pill--note">${escapeHtml(d.category || "Document")}</span>
          ${expiringSoon ? `<span class="admin-pill admin-pill--warning">Expires soon</span>` : ""}
        </div>
      </header>

      <section class="admin-focused__field-grid">
        <div><label>Type</label><strong>${escapeHtml(d.mime_type || "Unknown")}</strong></div>
        <div><label>Uploaded</label><strong>${d.created_at ? formatDateOnly(d.created_at) : "Unknown"}</strong></div>
        <div><label>Expiration</label><strong>${d.expiration_date ? formatDateOnly(d.expiration_date) : "—"}</strong></div>
        <div><label>Filed</label><strong>${d.chez_filed_at ? formatDateOnly(d.chez_filed_at) : "Not yet"}</strong></div>
      </section>

      ${d.notes ? `<section class="admin-focused__notes-block"><h3>Notes</h3><p>${escapeHtml(d.notes)}</p></section>` : ""}

      ${(linkedSystem || linkedProject || linkedVehicle) ? `
        <section class="admin-focused__list-block">
          <h3>Linked to</h3>
          ${linkedSystem ? `
            <div class="admin-households__entity-row is-clickable" data-drill-entity-type="system" data-drill-entity-id="${escapeHtml(linkedSystem.id)}">
              <div class="admin-households__entity-main">
                <strong>System: ${escapeHtml(linkedSystem.name || linkedSystem.category)}</strong>
                <span class="admin-muted">${escapeHtml(linkedSystem.category)}</span>
              </div>
              <span class="admin-households__entity-chevron" aria-hidden="true">›</span>
            </div>` : ""}
          ${linkedProject ? `
            <div class="admin-households__entity-row is-clickable" data-drill-entity-type="project" data-drill-entity-id="${escapeHtml(linkedProject.id)}">
              <div class="admin-households__entity-main">
                <strong>Project: ${escapeHtml(linkedProject.name)}</strong>
                <span class="admin-muted">${escapeHtml(prettifyEnum(linkedProject.status) || "")}</span>
              </div>
              <span class="admin-households__entity-chevron" aria-hidden="true">›</span>
            </div>` : ""}
          ${linkedVehicle ? `
            <div class="admin-households__entity-row is-clickable" data-drill-entity-type="vehicle" data-drill-entity-id="${escapeHtml(linkedVehicle.id)}">
              <div class="admin-households__entity-main">
                <strong>Vehicle: ${escapeHtml([linkedVehicle.year, linkedVehicle.make, linkedVehicle.model].filter(Boolean).join(" "))}</strong>
                <span class="admin-muted">${escapeHtml(linkedVehicle.license_plate || "")}</span>
              </div>
              <span class="admin-households__entity-chevron" aria-hidden="true">›</span>
            </div>` : ""}
        </section>` : `
        <section class="admin-focused__list-block">
          <h3>Linked to</h3>
          <p class="admin-muted">This document isn't linked to a system, project, or vehicle yet.</p>
        </section>`}

      <section class="admin-focused__actions">
        <h3>Actions</h3>
        <div class="admin-focused__action-row">
          ${!d.chez_filed_at ? `<button type="button" class="admin-pill admin-pill--action" data-cockpit-action="workbench-action" data-action-id="mark_filed" data-entity-type="document" data-entity-id="${escapeHtml(d.id)}">Mark filed</button>` : ""}
          <button type="button" class="admin-pill admin-pill--action" data-cockpit-action="workbench-action" data-action-id="share_with_vendor" data-entity-type="document" data-entity-id="${escapeHtml(d.id)}">Share with vendor</button>
          ${renderOwnershipPill(d)}
          <button type="button" class="admin-pill admin-pill--secondary" data-focused-message-homeowner>✉ Message homeowner</button>
          <button type="button" class="admin-pill" data-focused-add-note>+ Add admin note</button>
        </div>
      </section>
    </article>
  `;
}

// Phase 85.7: Utility (Bill) parity rebuild. Mirrors iOS UtilityDetailSheet:
// provider identity, account/plan card, contact info, Chez audit timeline
// (history of audits with variance findings), linked documents.
function renderFocusedUtilityHtml(u, wb) {
  const ownedBadge = u.chez_owned ? `<span class="admin-pill admin-pill--owned">★ Chez owns</span>` : "";
  const audits = (wb.utility_bill_audits || []).filter((a) => a.utility_account_id === u.id);
  const lastAudit = audits[0];
  // Linked documents — bills/statements forwarded to this account. Heuristic:
  // documents with matching category like "Home Bill/Invoice" + matching
  // utility provider name in the filename or notes.
  const linkedDocs = (wb.documents || []).filter((d) => {
    if (d.category !== "Home Bill/Invoice") return false;
    const provider = (u.provider_name || "").toLowerCase();
    if (!provider) return false;
    const fname = (d.filename || "").toLowerCase();
    return fname.includes(provider.split(" ")[0]);
  });
  // Total Chez audit savings: sum of variance_cents where variance is favorable (homeowner overcharged).
  const totalVarianceCents = audits.reduce((s, a) => s + (Math.abs(Number(a.variance_cents)) || 0), 0);
  return `
    <article class="admin-focused__entity">
      <header class="admin-focused__entity-head">
        <h2>${escapeHtml(u.provider_name || u.account_name || "Utility")}</h2>
        <div class="admin-focused__entity-meta">
          ${ownedBadge}
          <span class="admin-pill admin-pill--note">${escapeHtml(prettifyEnum(u.utility_type || u.provider_type) || "Bill")}</span>
          ${audits.length > 0 ? `<span class="admin-pill">${audits.length} audit${audits.length === 1 ? "" : "s"}</span>` : ""}
          ${u.is_autopay ? `<span class="admin-pill">Auto-pay on</span>` : ""}
        </div>
      </header>

      <section class="admin-focused__field-grid">
        <div><label>Account #</label><strong>${escapeHtml(u.account_number || "Not on file")}</strong></div>
        <div><label>Plan</label><strong>${escapeHtml(u.plan_name || "Not on file")}</strong></div>
        <div><label>Monthly cost</label><strong>${u.monthly_cost ? "$" + formatCompact(u.monthly_cost) : "Not on file"}</strong></div>
        <div><label>Phone</label><strong>${u.phone ? `<a href="tel:${escapeHtml(u.phone)}" class="admin-link-inline">${escapeHtml(formatPhoneNumber(u.phone))}</a>` : "Not on file"}</strong></div>
        <div><label>Website</label><strong>${u.website ? `<a href="${escapeHtml(u.website)}" target="_blank" rel="noopener" class="admin-link-inline">${escapeHtml(u.website)}</a>` : "Not on file"}</strong></div>
        ${u.due_date ? `<div><label>Next due</label><strong>${formatDateOnly(u.due_date)}</strong></div>` : ""}
        ${lastAudit ? `<div><label>Last audit</label><strong>${formatDateOnly(lastAudit.created_at)}${lastAudit.variance_cents ? " · $" + formatCompact(Math.abs(Number(lastAudit.variance_cents)) / 100) + " variance" : ""}</strong></div>` : ""}
      </section>

      <section class="admin-focused__actions">
        <div class="admin-focused__action-row">
          <button type="button" class="admin-pill admin-pill--action" data-cockpit-action="workbench-action" data-action-id="audit_bill" data-entity-type="utility" data-entity-id="${escapeHtml(u.id)}">Audit bill</button>
          <button type="button" class="admin-pill admin-pill--action" data-cockpit-action="workbench-action" data-action-id="draft_negotiation" data-entity-type="utility" data-entity-id="${escapeHtml(u.id)}">Draft negotiation</button>
          ${renderOwnershipPill(u)}
          <button type="button" class="admin-pill admin-pill--secondary" data-focused-message-homeowner>✉ Message homeowner</button>
          <button type="button" class="admin-pill" data-focused-add-note>+ Add admin note</button>
        </div>
      </section>

      ${audits.length > 0 ? `
        <section class="admin-focused__list-block">
          <h3>Chez audit history · ${audits.length}${totalVarianceCents > 0 ? ` · $${formatCompact(totalVarianceCents / 100)} found` : ""}</h3>
          ${audits.slice(0, 10).map((a) => {
            const variance = Number(a.variance_cents) || 0;
            const periodLabel = a.bill_period_start ? formatDateOnly(a.bill_period_start) : "";
            return `
              <div class="admin-households__entity-row">
                <div class="admin-households__entity-main">
                  <strong>${escapeHtml(periodLabel || "Audit on " + formatDateOnly(a.created_at))}${a.bill_amount_cents ? " · $" + formatCompact(Number(a.bill_amount_cents) / 100) : ""}</strong>
                  <span class="admin-muted">${a.finding ? escapeHtml(String(a.finding).slice(0, 120)) : "No finding noted"}${variance ? ` · $${formatCompact(Math.abs(variance) / 100)} variance` : ""}</span>
                </div>
              </div>`;
          }).join("")}
        </section>` : `
        <section class="admin-focused__list-block">
          <h3>Chez audit history</h3>
          <p class="admin-muted">No audits yet. The "Audit bill" action above starts the first one.</p>
        </section>`}

      ${linkedDocs.length > 0 ? `
        <section class="admin-focused__list-block">
          <h3>Recent bills · ${linkedDocs.length}</h3>
          ${linkedDocs.slice(0, 10).map((d) => `
            <div class="admin-households__entity-row is-clickable" data-drill-entity-type="document" data-drill-entity-id="${escapeHtml(d.id)}">
              <div class="admin-households__entity-main">
                <strong>${escapeHtml(d.filename)}</strong>
                <span class="admin-muted">${d.created_at ? "Forwarded " + formatDateOnly(d.created_at) : ""}${d.chez_filed_at ? " · Filed" : ""}</span>
              </div>
              <span class="admin-households__entity-chevron" aria-hidden="true">›</span>
            </div>`).join("")}
        </section>` : ""}
    </article>
  `;
}

// Phase 85.6 Phase C: full parity rebuild for Vehicle.
// Mirrors iOS VehicleDetailView.swift section-by-section:
//   1. Brand hero (year/make/model + plate + mileage pill)
//   2. Mechanic card (linked contractor — drill to vendor panel)
//   3. Cost summary row (total spent / service count / last service)
//   4. Needs Attention (recalls + expiring docs)
//   5. Registration / Insurance / Ownership cards
//   6. Maintenance tasks (vehicle-linked, drill to task panel)
//   7. Service history (date + type + cost + mileage + contractor)
//   8. Documents (vehicle-linked, drill to doc panel)
//   9. Open + Resolved recalls
function renderFocusedVehicleHtml(v, wb, rel) {
  // Data sourcing — workbench fetch now ships every supporting list so
  // the panel doesn't have to chain DB calls.
  const allServices = (wb.vehicle_service_records || []).filter((s) => s.vehicle_id === v.id);
  const allRecalls = (wb.vehicle_recalls || []).filter((r) => r.vehicle_id === v.id);
  const openRecalls = allRecalls.filter((r) => !r.is_resolved);
  const resolvedRecalls = allRecalls.filter((r) => !!r.is_resolved);
  // Fall back to `rel.recalls` (loaded by hydrateFocusedEntityRelations) if
  // the workbench query is older than the relation fetch.
  const recallsFromRel = rel.recalls || [];
  const recallsAll = allRecalls.length > 0 ? allRecalls : recallsFromRel;
  const openRecallsFinal = recallsAll.filter((r) => !r.is_resolved);
  const resolvedRecallsFinal = recallsAll.filter((r) => !!r.is_resolved);
  const linkedTasks = (wb.tasks || []).filter((t) => t.vehicle_id === v.id && !t.is_archived);
  const linkedDocs = (wb.documents || []).filter((d) => d.vehicle_id === v.id);
  const mechanic = (wb.contractors || []).find((c) => c.id === v.preferred_mechanic_id);
  const ownedBadge = v.chez_owned ? `<span class="admin-pill admin-pill--owned">★ Chez owns</span>` : "";
  // Cost summary calculations
  const totalSpent = allServices.reduce((s, r) => s + (Number(r.cost) || 0), 0);
  const lastService = allServices[0];   // already ordered desc
  // Needs-attention badges (parity with iOS needsAttentionSection)
  const today = new Date();
  const within30Days = (iso) => {
    if (!iso) return false;
    const d = new Date(iso);
    const diff = (d.getTime() - today.getTime()) / 86400000;
    return diff >= 0 && diff <= 30;
  };
  const regExpiringSoon = within30Days(v.registration_expiry);
  const insExpiringSoon = within30Days(v.insurance_expiry);
  const overdueTasks = linkedTasks.filter((t) => {
    const due = t.scheduled_date || t.next_due_date;
    if (!due) return false;
    return new Date(due) < today;
  });
  const needsAttentionCount = openRecallsFinal.length
    + (regExpiringSoon ? 1 : 0)
    + (insExpiringSoon ? 1 : 0)
    + overdueTasks.length;
  return `
    <article class="admin-focused__entity">
      <header class="admin-focused__entity-head">
        <h2>${escapeHtml([v.year, v.make, v.model].filter(Boolean).join(" ") || "Vehicle")}</h2>
        <div class="admin-focused__entity-meta">
          ${ownedBadge}
          ${v.license_plate ? `<span class="admin-pill admin-pill--note">${escapeHtml(v.license_plate)}</span>` : ""}
          ${v.color ? `<span class="admin-pill">${escapeHtml(v.color)}</span>` : ""}
          ${v.current_mileage ? `<span class="admin-pill">${formatCompact(v.current_mileage)} mi</span>` : ""}
          ${openRecallsFinal.length > 0 ? `<span class="admin-pill admin-pill--warning">${openRecallsFinal.length} open recall${openRecallsFinal.length === 1 ? "" : "s"}</span>` : ""}
        </div>
      </header>

      <section class="admin-focused__field-grid">
        <div><label>VIN</label><strong>${escapeHtml(v.vin || "Not on file")}</strong></div>
        <div><label>Mileage</label><strong>${v.current_mileage ? formatCompact(v.current_mileage) + " mi" : "Not on file"}</strong></div>
        <div><label>Ownership</label><strong>${escapeHtml(prettifyEnum(v.ownership_type) || "Not on file")}</strong></div>
        <div><label>Purchased</label><strong>${v.purchase_date ? formatDateOnly(v.purchase_date) : "Not on file"}</strong></div>
        <div><label>Reg expires</label><strong>${v.registration_expiry ? formatDateOnly(v.registration_expiry) + (regExpiringSoon ? " ⚠️" : "") : "Not on file"}</strong></div>
        <div><label>Insurance expires</label><strong>${v.insurance_expiry ? formatDateOnly(v.insurance_expiry) + (insExpiringSoon ? " ⚠️" : "") : "Not on file"}</strong></div>
        ${v.insurance_carrier ? `<div><label>Insurance carrier</label><strong>${escapeHtml(v.insurance_carrier)}</strong></div>` : ""}
        ${v.insurance_policy_num ? `<div><label>Policy #</label><strong>${escapeHtml(v.insurance_policy_num)}</strong></div>` : ""}
      </section>

      <section class="admin-focused__actions">
        <h3>Actions</h3>
        <div class="admin-focused__action-row">
          <button type="button" class="admin-pill admin-pill--action" data-cockpit-action="workbench-action" data-action-id="schedule_service" data-entity-type="vehicle" data-entity-id="${escapeHtml(v.id)}">Schedule service</button>
          ${openRecallsFinal.length > 0
            ? `<button type="button" class="admin-pill admin-pill--action" data-cockpit-action="workbench-action" data-action-id="handle_recall" data-entity-type="vehicle" data-entity-id="${escapeHtml(v.id)}">Handle ${openRecallsFinal.length} recall${openRecallsFinal.length === 1 ? "" : "s"}</button>`
            : `<button type="button" class="admin-pill" disabled title="No open recalls on this vehicle.">Handle recall</button>`}
          ${renderOwnershipPill(v)}
          <button type="button" class="admin-pill admin-pill--secondary" data-focused-message-homeowner>✉ Message homeowner</button>
          <button type="button" class="admin-pill" data-focused-add-note>+ Add admin note</button>
        </div>
      </section>

      ${mechanic ? `
        <section class="admin-focused__list-block">
          <h3>Mechanic on file</h3>
          <div class="admin-households__entity-row is-clickable" data-drill-entity-type="contractor" data-drill-entity-id="${escapeHtml(mechanic.id)}">
            <div class="admin-households__entity-main">
              <strong>${escapeHtml(mechanic.company_name || "Linked mechanic")}</strong>
              <span class="admin-muted">${escapeHtml(mechanic.category || "Auto service")}${mechanic.phone ? " · " + formatPhoneNumber(mechanic.phone) : ""}</span>
            </div>
            <span class="admin-households__entity-chevron" aria-hidden="true">›</span>
          </div>
        </section>` : `
        <section class="admin-focused__list-block">
          <h3>Mechanic on file</h3>
          <p class="admin-muted">No mechanic linked. Homeowner can pick one in the iOS app, or Chez can propose one.</p>
        </section>`}

      ${allServices.length > 0 ? `
        <section class="admin-focused__list-block">
          <h3>Cost summary</h3>
          <div class="admin-focused__field-grid">
            <div><label>Total spent</label><strong>$${formatCompact(totalSpent)}</strong></div>
            <div><label>Services logged</label><strong>${allServices.length}</strong></div>
            <div><label>Last service</label><strong>${lastService?.service_date ? formatDateOnly(lastService.service_date) : "—"}</strong></div>
          </div>
        </section>` : ""}

      ${needsAttentionCount > 0 ? `
        <section class="admin-focused__list-block">
          <h3>Needs attention · ${needsAttentionCount}</h3>
          ${openRecallsFinal.map((r) => `
            <div class="admin-households__entity-row">
              <div class="admin-households__entity-main">
                <strong>⚠️ Recall: ${escapeHtml(r.component || r.summary || "Open recall")}</strong>
                <span class="admin-muted">${escapeHtml(r.campaign_number || "")}${r.consequence_summary ? " · " + escapeHtml(String(r.consequence_summary).slice(0, 100)) : ""}</span>
              </div>
            </div>`).join("")}
          ${regExpiringSoon ? `<div class="admin-households__entity-row"><div class="admin-households__entity-main"><strong>📋 Registration expiring</strong><span class="admin-muted">${formatDateOnly(v.registration_expiry)}</span></div></div>` : ""}
          ${insExpiringSoon ? `<div class="admin-households__entity-row"><div class="admin-households__entity-main"><strong>📋 Insurance expiring</strong><span class="admin-muted">${formatDateOnly(v.insurance_expiry)}</span></div></div>` : ""}
          ${overdueTasks.map((t) => `
            <div class="admin-households__entity-row is-clickable" data-drill-entity-type="task" data-drill-entity-id="${escapeHtml(t.id)}">
              <div class="admin-households__entity-main">
                <strong>🔧 Overdue: ${escapeHtml(t.title)}</strong>
                <span class="admin-muted">Was due ${formatDateOnly(t.scheduled_date || t.next_due_date)}</span>
              </div>
              <span class="admin-households__entity-chevron" aria-hidden="true">›</span>
            </div>`).join("")}
        </section>` : ""}

      ${linkedTasks.length > 0 ? `
        <section class="admin-focused__list-block">
          <h3>Vehicle tasks · ${linkedTasks.length}</h3>
          ${linkedTasks.slice(0, 8).map((t) => `
            <div class="admin-households__entity-row is-clickable" data-drill-entity-type="task" data-drill-entity-id="${escapeHtml(t.id)}">
              <div class="admin-households__entity-main">
                <strong>${escapeHtml(t.title)}</strong>
                <span class="admin-muted">${t.next_due_date ? "Next due " + formatDateOnly(t.next_due_date) : t.scheduled_date ? "Scheduled " + formatDateOnly(t.scheduled_date) : "Unscheduled"}</span>
              </div>
              <span class="admin-households__entity-chevron" aria-hidden="true">›</span>
            </div>`).join("")}
        </section>` : ""}

      ${allServices.length > 0 ? `
        <section class="admin-focused__list-block">
          <h3>Service history · ${allServices.length}</h3>
          ${allServices.slice(0, 12).map((s) => {
            const vendor = (wb.contractors || []).find((c) => c.id === s.contractor_id);
            const vendorName = vendor?.company_name || s.shop_name || "";
            return `
              <div class="admin-households__entity-row">
                <div class="admin-households__entity-main">
                  <strong>${escapeHtml(s.service_type || s.description || "Service")}</strong>
                  <span class="admin-muted">${s.service_date ? formatDateOnly(s.service_date) : ""}${s.mileage_at_service ? " · " + formatCompact(s.mileage_at_service) + " mi" : ""}${vendorName ? " · " + escapeHtml(vendorName) : ""}</span>
                </div>
                ${s.cost ? `<span class="admin-households__entity-meta">$${formatCompact(Number(s.cost))}</span>` : ""}
              </div>`;
          }).join("")}
        </section>` : `
        <section class="admin-focused__list-block">
          <h3>Service history</h3>
          <p class="admin-muted">No service records logged yet. The "Schedule service" action above creates the next entry; "Log service" on the system pulls from a workbench task.</p>
        </section>`}

      ${linkedDocs.length > 0 ? `
        <section class="admin-focused__list-block">
          <h3>Vehicle documents · ${linkedDocs.length}</h3>
          ${linkedDocs.slice(0, 10).map((d) => `
            <div class="admin-households__entity-row is-clickable" data-drill-entity-type="document" data-drill-entity-id="${escapeHtml(d.id)}">
              <div class="admin-households__entity-main">
                <strong>${escapeHtml(d.filename || "Document")}</strong>
                <span class="admin-muted">${escapeHtml(d.category || "Unfiled")}${d.expiration_date ? " · Expires " + formatDateOnly(d.expiration_date) : ""}</span>
              </div>
              <span class="admin-households__entity-chevron" aria-hidden="true">›</span>
            </div>`).join("")}
        </section>` : ""}

      ${resolvedRecallsFinal.length > 0 ? `
        <section class="admin-focused__list-block">
          <h3>Resolved recalls · ${resolvedRecallsFinal.length}</h3>
          ${resolvedRecallsFinal.slice(0, 6).map((r) => `
            <div class="admin-households__entity-row">
              <div class="admin-households__entity-main">
                <strong>${escapeHtml(r.component || r.summary || "Recall")}</strong>
                <span class="admin-muted">${escapeHtml(r.campaign_number || "")}${r.resolved_date ? " · Resolved " + formatDateOnly(r.resolved_date) : ""}</span>
              </div>
            </div>`).join("")}
        </section>` : ""}
    </article>
  `;
}

// Phase 85.5: focused panel for the household's pending handyman punch list.
// Synthetic "entity" — not a single DB row, but a household-level rollup
// of every active row in handyman_punch_items. Rendered when the operator
// clicks the "Handyman punch list · N items" row on Upcoming, or via any
// future entry point that wants to surface the punch list inline.
function renderFocusedHandymanPunchListHtml(entity, wb) {
  const items = entity?.items || wb.handyman_punch_items || [];
  const household = wb.household || {};
  const householdName = household.primary_name || household.display_name || "Household";
  return `
    <article class="admin-focused__entity">
      <header class="admin-focused__entity-head">
        <h2>Handyman punch list</h2>
        <div class="admin-focused__entity-meta">
          <span class="admin-pill admin-pill--note">${items.length} ${items.length === 1 ? "item" : "items"}</span>
        </div>
      </header>
      <p class="admin-muted">${escapeHtml(householdName)} has ${items.length} small ${items.length === 1 ? "task" : "tasks"} on the handyman backlog. Schedule one combined visit instead of one-offs.</p>
      <section class="admin-focused__actions">
        <h3>Actions</h3>
        <div class="admin-focused__action-row">
          <button type="button" class="admin-pill admin-pill--action" data-handyman-schedule-visit>Schedule handyman visit</button>
        </div>
      </section>
      ${items.length === 0 ? `
        <p class="admin-muted">No pending punch items right now.</p>
      ` : `
        <section class="admin-focused__list-block">
          <h3>Pending items</h3>
          ${items.map((p) => `
            <div class="admin-households__entity-row">
              <div class="admin-households__entity-main">
                <strong>${escapeHtml(p.title || "Untitled punch item")}</strong>
                <span class="admin-muted">${p.created_at ? "Added " + formatDateOnly(p.created_at) : ""}${p.source ? " · " + escapeHtml(p.source) : ""}</span>
                ${p.notes ? `<span class="admin-muted">${escapeHtml(p.notes)}</span>` : ""}
              </div>
              <div class="admin-households__entity-meta">
                <button type="button" class="admin-pill admin-pill--ghost" data-handyman-mark-filed data-punch-id="${escapeHtml(p.id)}">Mark filed</button>
              </div>
            </div>
          `).join("")}
        </section>
      `}
    </article>
  `;
}

// =============================================================================
// Phase 85 PR 5C — Message homeowner modal
// =============================================================================

function openMessageHomeownerModal({ requestId, entityType, entityId, householdId }) {
  const overlay = document.createElement("div");
  overlay.className = "admin-modal-overlay";
  const isReply = !!requestId;
  overlay.innerHTML = `
    <div class="admin-modal admin-modal--sm">
      <header class="admin-modal__head">
        <h2>${isReply ? "Message homeowner" : "Start a new conversation"}</h2>
        <button type="button" class="admin-modal__close" aria-label="Close">&times;</button>
      </header>
      <form class="admin-modal__body admin-modal__form" data-message-form>
        ${isReply ? "" : `
          <label class="admin-modal__field">
            <span>Summary <span class="admin-required">*</span></span>
            <input type="text" name="summary" required class="admin-input" placeholder="One-line summary visible in the homeowner's inbox" />
          </label>
        `}
        <label class="admin-modal__field">
          <span>Message <span class="admin-required">*</span></span>
          <textarea name="message" rows="5" required class="admin-input"></textarea>
        </label>
        <label class="admin-modal__field admin-modal__field--inline">
          <input type="checkbox" name="acknowledgement_required" />
          <span>Mark as needs-action (lands in Needs Attention inbox tab)</span>
        </label>
        <p class="admin-modal__error admin-error" data-error hidden></p>
        <div class="admin-modal__buttons">
          <button type="button" class="admin-pill" data-cancel>Cancel</button>
          <button type="submit" class="admin-pill admin-pill--action">Send</button>
        </div>
      </form>
    </div>
  `;
  document.body.appendChild(overlay);
  const close = () => overlay.remove();
  overlay.querySelector(".admin-modal__close").addEventListener("click", close);
  overlay.querySelector("[data-cancel]").addEventListener("click", close);
  overlay.addEventListener("click", (e) => { if (e.target === overlay) close(); });
  overlay.querySelector("[data-message-form]").addEventListener("submit", async (e) => {
    e.preventDefault();
    const submitBtn = overlay.querySelector('button[type="submit"]');
    const errorEl = overlay.querySelector("[data-error]");
    errorEl.hidden = true;
    const fd = new FormData(e.currentTarget);
    const message = String(fd.get("message") || "").trim();
    const ack = !!fd.get("acknowledgement_required");
    if (!message) return;
    submitBtn.disabled = true;
    submitBtn.textContent = "Sending…";
    try {
      if (isReply) {
        await callChezConcierge({
          action: "reply",
          request_id: requestId,
          message,
          acknowledgement_required: ack,
        });
      } else {
        const summary = String(fd.get("summary") || "").trim() || `Chez has an update on your ${entityType}`;
        await callChezConcierge({
          action: "admin_submit",
          household_id: householdId,
          category: "general",
          summary,
          initial_message: message,
          context: { entity_type: entityType, entity_id: entityId, source: "focused_message_modal" },
        });
      }
      close();
      alert("Message sent.");
    } catch (err) {
      errorEl.textContent = `Failed: ${err.message || err}`;
      errorEl.hidden = false;
      submitBtn.disabled = false;
      submitBtn.textContent = "Send";
    }
  });
  setTimeout(() => overlay.querySelector("textarea")?.focus(), 0);
}

