function openWorkbenchActionModal({ actionId, entityType, entityId, householdId }) {
  const def = WORKBENCH_ACTION_FIELD_SETS[actionId];
  if (!def) {
    return callChezConcierge({
      action: "workbench_action",
      household_id: householdId,
      entity_type: entityType,
      entity_id: entityId,
      action_type: actionId,
      payload: {},
    }).then(() => true).catch(() => false);
  }
  return new Promise((resolve) => {
    const overlay = document.createElement("div");
    overlay.className = "admin-modal-overlay";
    const todayIso = new Date().toISOString().slice(0, 10);
    // Phase 85 PR 5.1 — generate quick-select date pills for date
    // fields. (Today / Tomorrow / This Friday / Next Mon / Custom).
    // The pills set the value of the underlying <input type="date">.
    const dateQuickPills = (fieldKey) => {
      const today = new Date();
      const fmt = (d) => d.toISOString().slice(0, 10);
      const addDays = (d, n) => { const x = new Date(d); x.setDate(x.getDate() + n); return x; };
      const nextDow = (target) => {
        const d = new Date(today);
        const diff = (target - d.getDay() + 7) % 7 || 7;
        d.setDate(d.getDate() + diff);
        return d;
      };
      const friday = nextDow(5);
      const nextMonday = nextDow(1);
      const pills = [
        { label: "Today", date: fmt(today) },
        { label: "Tomorrow", date: fmt(addDays(today, 1)) },
        { label: "This Fri", date: fmt(friday) },
        { label: "Next Mon", date: fmt(nextMonday) },
        { label: "+1 week", date: fmt(addDays(today, 7)) },
      ];
      return `
        <div class="admin-modal__quickpills" data-quickpill-target="${escapeHtml(fieldKey)}">
          ${pills.map((p) => `
            <button type="button" class="admin-quickpill" data-quickpill-value="${escapeHtml(p.date)}">${escapeHtml(p.label)}</button>
          `).join("")}
        </div>
      `;
    };
    // Phase 85.5: pre-compute vendor options for contractor_picker fields
    // so admin operators see a real searchable list instead of a UUID
    // input. Workbench data is the source of truth — same shape across
    // both the focused panel and Upcoming entry points.
    const wb = state.households.workbench || {};
    const vendorOptions = (wb.contractors || [])
      .slice()
      .sort((a, b) => (a.company_name || "").localeCompare(b.company_name || ""))
      .map((c) => ({ value: c.id, label: c.company_name || c.contact_name || c.id }));
    const fieldsHtml = def.fields.map((f) => {
      const id = `wb-act-${f.key}`;
      const required = f.required ? "required" : "";
      const placeholder = f.placeholder ? ` placeholder="${escapeHtml(f.placeholder)}"` : "";
      let initialValue = "";
      if (f.defaultToToday) initialValue = todayIso;
      else if (f.defaultValue !== undefined) initialValue = String(f.defaultValue);
      const reqMark = f.required ? ' <span class="admin-required">*</span>' : "";
      if (f.type === "textarea") {
        return `
          <label class="admin-modal__field" for="${id}">
            <span>${escapeHtml(f.label)}${reqMark}</span>
            <textarea id="${id}" name="${escapeHtml(f.key)}" rows="3" ${required}${placeholder} class="admin-input">${escapeHtml(initialValue)}</textarea>
          </label>
        `;
      }
      if (f.type === "select") {
        return `
          <label class="admin-modal__field" for="${id}">
            <span>${escapeHtml(f.label)}${reqMark}</span>
            <select id="${id}" name="${escapeHtml(f.key)}" ${required} class="admin-input">
              ${f.options.map((o) => `<option value="${escapeHtml(o.value)}" ${o.value === initialValue ? "selected" : ""}>${escapeHtml(o.label)}</option>`).join("")}
            </select>
          </label>
        `;
      }
      // Phase 85.5: contractor_picker renders as a <select> populated
      // from the workbench's contractor list. Falls back to a free-text
      // UUID input if the workbench isn't loaded — should never happen
      // in practice since the modal is opened from the workbench.
      if (f.type === "contractor_picker") {
        if (vendorOptions.length === 0) {
          return `
            <label class="admin-modal__field" for="${id}">
              <span>${escapeHtml(f.label)}${reqMark}</span>
              <input type="text" id="${id}" name="${escapeHtml(f.key)}" value="" ${required}${placeholder} class="admin-input" placeholder="No vendors on file" />
            </label>
          `;
        }
        return `
          <label class="admin-modal__field" for="${id}">
            <span>${escapeHtml(f.label)}${reqMark}</span>
            <select id="${id}" name="${escapeHtml(f.key)}" ${required} class="admin-input">
              <option value="">— Pick a vendor —</option>
              ${vendorOptions.map((o) => `<option value="${escapeHtml(o.value)}">${escapeHtml(o.label)}</option>`).join("")}
            </select>
          </label>
        `;
      }
      // Phase 85.5: usd renders a $-prefixed dollar input. The form
      // submit handler below multiplies by 100 to land cents in the
      // payload so server-side code that expects cents keeps working.
      if (f.type === "usd") {
        return `
          <label class="admin-modal__field" for="${id}">
            <span>${escapeHtml(f.label)}${reqMark}</span>
            <div class="admin-input-prefix">
              <span class="admin-input-prefix__token">$</span>
              <input type="number" step="0.01" min="0" id="${id}" name="${escapeHtml(f.key)}" data-usd-input value="${escapeHtml(initialValue)}" ${required}${placeholder} class="admin-input" />
            </div>
          </label>
        `;
      }
      const inputType = f.type === "number" ? "number" : f.type === "date" ? "date" : "text";
      const quickPills = f.type === "date" ? dateQuickPills(f.key) : "";
      return `
        <label class="admin-modal__field" for="${id}">
          <span>${escapeHtml(f.label)}${reqMark}</span>
          <input type="${inputType}" id="${id}" name="${escapeHtml(f.key)}" value="${escapeHtml(initialValue)}" ${required}${placeholder} class="admin-input" />
          ${quickPills}
        </label>
      `;
    }).join("");
    overlay.innerHTML = `
      <div class="admin-modal admin-modal--sm">
        <header class="admin-modal__head">
          <h2>${escapeHtml(def.title)}</h2>
          <button type="button" class="admin-modal__close" aria-label="Close">&times;</button>
        </header>
        <form class="admin-modal__body admin-modal__form" data-workbench-action-form>
          ${def.intro ? `<p class="admin-modal__intro">${escapeHtml(def.intro)}</p>` : ""}
          ${fieldsHtml}
          <p class="admin-modal__error admin-error" data-error hidden></p>
          <div class="admin-modal__buttons">
            <button type="button" class="admin-pill" data-cancel>Cancel</button>
            <button type="submit" class="admin-pill admin-pill--action">${escapeHtml(def.submit)}</button>
          </div>
        </form>
      </div>
    `;
    document.body.appendChild(overlay);
    // Wire quick-select date pills.
    overlay.querySelectorAll("[data-quickpill-target]").forEach((group) => {
      const targetKey = group.dataset.quickpillTarget;
      const input = overlay.querySelector(`input[name="${CSS.escape(targetKey)}"]`);
      group.querySelectorAll("[data-quickpill-value]").forEach((btn) => {
        btn.addEventListener("click", () => {
          if (!input) return;
          input.value = btn.dataset.quickpillValue;
          group.querySelectorAll("[data-quickpill-value]").forEach((b) => b.classList.remove("is-active"));
          btn.classList.add("is-active");
        });
      });
      // Sync the active pill with the current input value on first paint.
      const matchActive = () => {
        const current = input?.value || "";
        group.querySelectorAll("[data-quickpill-value]").forEach((b) => {
          b.classList.toggle("is-active", b.dataset.quickpillValue === current);
        });
      };
      matchActive();
      input?.addEventListener("change", matchActive);
    });
    const close = (result) => { overlay.remove(); resolve(result); };
    overlay.querySelector(".admin-modal__close").addEventListener("click", () => close(false));
    overlay.querySelector("[data-cancel]").addEventListener("click", () => close(false));
    overlay.addEventListener("click", (e) => { if (e.target === overlay) close(false); });
    overlay.querySelector("[data-workbench-action-form]").addEventListener("submit", async (e) => {
      e.preventDefault();
      const submitBtn = overlay.querySelector('button[type="submit"]');
      const errorEl = overlay.querySelector("[data-error]");
      errorEl.hidden = true;
      const formData = new FormData(e.currentTarget);
      const payload = {};
      for (const f of def.fields) {
        const raw = formData.get(f.key);
        if (raw === null || raw === "") continue;
        if (f.type === "number") {
          const n = Number(raw);
          if (!Number.isFinite(n)) {
            errorEl.textContent = `${f.label} must be a number.`;
            errorEl.hidden = false;
            return;
          }
          payload[f.key] = n;
        } else if (f.type === "usd") {
          // Phase 85.5: dollar input → cents on submit. Server-side code
          // still receives the same `*_cents` integer payload key it
          // expected before, so no Edge Function changes needed.
          const dollars = Number(raw);
          if (!Number.isFinite(dollars) || dollars < 0) {
            errorEl.textContent = `${f.label} must be a positive amount.`;
            errorEl.hidden = false;
            return;
          }
          payload[f.key] = Math.round(dollars * 100);
        } else {
          payload[f.key] = String(raw).trim();
        }
      }
      submitBtn.disabled = true;
      submitBtn.textContent = "Saving…";
      try {
        await callChezConcierge({
          action: "workbench_action",
          household_id: householdId,
          entity_type: entityType,
          entity_id: entityId,
          action_type: actionId,
          payload,
        });
        close(true);
      } catch (err) {
        errorEl.textContent = `Failed: ${err.message || err}`;
        errorEl.hidden = false;
        submitBtn.disabled = false;
        submitBtn.textContent = def.submit;
      }
    });
    setTimeout(() => overlay.querySelector("input, textarea, select")?.focus(), 0);
  });
}

// Phase 85 PR 5.1 — friendly label per action_type. Beats the
// underscore-replace version that rendered "Complete On Behalf" in
// the Recent activity strip. Stays in sync with the action button
// labels everywhere else in the UI.
const WORKBENCH_ACTION_LABELS = {
  schedule_visit: "Scheduled visit",
  log_visit: "Logged visit",
  log_service: "Logged service",
  schedule_maintenance: "Scheduled maintenance",
  schedule: "Scheduled task",
  complete_on_behalf: "Marked task complete",
  snooze: "Snoozed task",
  log_call: "Logged vendor call",
  send_message: "Recorded vendor message",
  mark_filed: "Filed document",
  share_with_vendor: "Shared with vendor",
  audit_bill: "Audited bill",
  draft_negotiation: "Drafted negotiation",
  schedule_service: "Scheduled service",
  handle_recall: "Resolved recall",
  admin_note: "Added admin note",
};
function workbenchActionLabel(actionType) {
  return WORKBENCH_ACTION_LABELS[actionType] || actionType.replace(/_/g, " ");
}

function renderHouseholdWorkbenchHtml(wb, tab) {
  const household = wb.household ?? {};
  const homeownerName = primaryHomeownerLabel({ users: wb.users, family_members: wb.family_members, household: wb.household });
  const property = (wb.properties || [])[0] || null;

  // Phase 85 PR 5B — show ALL entities, not just chez_owned. Owned
  // status renders as a small inline badge. The owned-only filter
  // becomes a per-tab toggle chip, default off.
  const allRoutines = wb.routines || [];
  const allSystems = wb.home_systems || [];
  const allVendors = wb.contractors || [];
  const allTasks = wb.tasks || [];
  const allProjects = wb.projects || [];
  const allDocuments = wb.documents || [];
  const allUtilities = wb.utility_accounts || [];
  const allVehicles = wb.vehicles || [];
  const openCases = wb.open_cases || [];
  const reminders = wb.reminders || [];
  const recentActions = wb.workbench_actions || [];

  const ownedOnly = !!state.households.workbenchOwnedOnly;
  const query = (state.households.workbenchQuery || "").trim().toLowerCase();
  const matchOwned = (x) => !ownedOnly || x.chez_owned === true;
  const matchQuery = (...fields) => {
    if (!query) return true;
    return fields.some((f) => typeof f === "string" && f.toLowerCase().includes(query));
  };

  const tabs = [
    { id: "routines", label: "Routines", count: allRoutines.length, owned: allRoutines.filter((r) => r.chez_owned).length },
    { id: "systems", label: "Systems", count: allSystems.length, owned: allSystems.filter((s) => s.chez_owned).length },
    { id: "vendors", label: "Vendors", count: allVendors.length, owned: allVendors.filter((c) => c.chez_owned).length },
    { id: "tasks", label: "Tasks", count: allTasks.length, owned: allTasks.filter((t) => t.chez_owned).length },
    { id: "projects", label: "Projects", count: allProjects.length, owned: allProjects.filter((p) => p.chez_owned).length },
    { id: "documents", label: "Documents", count: allDocuments.length, owned: allDocuments.filter((d) => d.chez_owned).length },
    { id: "utilities", label: "Bills", count: allUtilities.length, owned: allUtilities.filter((u) => u.chez_owned).length },
    { id: "vehicles", label: "Vehicles", count: allVehicles.length, owned: allVehicles.filter((v) => v.chez_owned).length },
    { id: "cases", label: "Open cases", count: openCases.length, owned: 0 },
  ];

  const tabBody = (() => {
    switch (tab) {
      case "routines": {
        const rows = allRoutines.filter(matchOwned).filter((r) => matchQuery(r.label, r.routine_kind));
        return renderWorkbenchListHtml(rows, "No routines match.", (r) => {
          // Phase 85.5: prettify routine_kind / cadence_type so the row
          // shows "Other service" not "OTHER_SERVICE", "Weekly" not "WEEKLY".
          const niceKind = prettifyEnum(r.routine_kind);
          const niceCadence = prettifyEnum(r.cadence_type);
          return {
            title: r.label || niceKind || "(unnamed routine)",
            sub: `${niceCadence}${r.vendor_id ? " · vendor on file" : ""}`,
            meta: r.next_visit_date ? `Next ${formatDateOnly(r.next_visit_date)}` : "",
            isOwned: !!r.chez_owned,
            drillIn: { entityType: "routine", entityId: r.id },
            actions: [
              { id: "schedule_visit", label: "Schedule next visit", entityType: "routine", entityId: r.id },
              { id: "log_visit", label: "Log a visit", entityType: "routine", entityId: r.id },
            ],
          };
        });
      }
      case "systems": {
        const rows = allSystems.filter(matchOwned).filter((s) => matchQuery(s.name, s.category, s.manufacturer, s.model_number || s.model));
        return renderWorkbenchListHtml(rows, "No systems match.", (s) => {
          // Phase 85.5: dedupe "Sump Pump · Sump Pump" (audit Tier 4.23).
          // When the system has no distinct name, just use the category.
          const titleRaw = s.name && s.name !== s.category ? s.name : s.category;
          const subParts = [];
          if (s.name && s.name !== s.category && s.category) subParts.push(s.category);
          if (s.manufacturer) subParts.push(s.manufacturer);
          if (s.model_number || s.model) subParts.push(s.model_number || s.model);
          return {
            title: titleRaw,
            sub: subParts.join(" · "),
            meta: s.last_service_date ? `Last service ${formatDateOnly(s.last_service_date)}` : "",
            isOwned: !!s.chez_owned,
            drillIn: { entityType: "system", entityId: s.id },
            actions: [
              { id: "log_service", label: "Log service", entityType: "system", entityId: s.id },
              { id: "schedule_maintenance", label: "Schedule maintenance", entityType: "system", entityId: s.id },
            ],
          };
        });
      }
      case "vendors": {
        const rows = allVendors.filter(matchOwned).filter((c) => matchQuery(c.company_name, c.category, c.phone));
        return renderWorkbenchListHtml(rows, "No vendors match.", (c) => ({
          title: c.company_name,
          sub: `${c.category || ""}${c.phone ? " · " + c.phone : ""}`,
          meta: c.chez_recommended_at ? "Sourced by Chez" : "",
          isOwned: !!c.chez_owned,
          drillIn: { entityType: "contractor", entityId: c.id },
          actions: [
            { id: "log_call", label: "Log a call", entityType: "contractor", entityId: c.id },
            { id: "send_message", label: "Send message", entityType: "contractor", entityId: c.id },
          ],
        }));
      }
      case "tasks": {
        const rows = allTasks.filter(matchOwned).filter((t) => matchQuery(t.title, t.assignment_type, t.frequency));
        return renderWorkbenchListHtml(rows, "No tasks match.", (t) => ({
          title: t.title,
          sub: `${prettifyEnum(t.assignment_type) || "Task"}${t.frequency ? " · " + prettifyEnum(t.frequency) : ""}`,
          meta: t.next_due_date ? `Due ${formatDateOnly(t.next_due_date)}` : "",
          isOwned: !!t.chez_owned,
          drillIn: { entityType: "task", entityId: t.id },
          actions: [
            { id: "schedule", label: "Schedule", entityType: "task", entityId: t.id },
            { id: "complete_on_behalf", label: "Mark complete", entityType: "task", entityId: t.id },
            { id: "snooze", label: "Snooze 7d", entityType: "task", entityId: t.id },
          ],
        }));
      }
      case "projects": {
        const rows = allProjects.filter(matchOwned).filter((p) => matchQuery(p.name, p.status));
        const emptyCopy = allProjects.length === 0
          ? "No projects on file for this household yet."
          : ownedOnly && allProjects.length > 0
          ? "No Chez-owned projects yet. Toggle the filter chip above to see every project the homeowner has."
          : "No projects match the current filter or search.";
        return renderWorkbenchListHtml(rows, emptyCopy, (p) => ({
          title: p.name,
          sub: `${prettifyEnum(p.status)}${p.estimated_budget ? " · est. $" + formatCompact(p.estimated_budget) : ""}`,
          meta: "",
          isOwned: !!p.chez_owned,
          drillIn: { entityType: "project", entityId: p.id },
          actions: [
            { id: "open_project_workbench", label: "Open negotiation pane", entityType: "project", entityId: p.id },
          ],
        }));
      }
      case "documents": {
        const rows = allDocuments.filter(matchOwned).filter((d) => matchQuery(d.filename, d.category));
        return renderWorkbenchListHtml(rows, "No documents on file for this household yet. Forward an email to the household's Chez address to start a paper trail.", (d) => ({
          title: d.filename,
          sub: d.category || "Document",
          meta: d.expiration_date ? `Expires ${formatDateOnly(d.expiration_date)}` : "",
          isOwned: !!d.chez_owned,
          drillIn: { entityType: "document", entityId: d.id },
          actions: [
            { id: "mark_filed", label: "Mark filed", entityType: "document", entityId: d.id },
            { id: "share_with_vendor", label: "Share with vendor", entityType: "document", entityId: d.id },
          ],
        }));
      }
      case "utilities": {
        const rows = allUtilities.filter(matchOwned).filter((u) => matchQuery(u.provider_name, u.account_name, u.utility_type));
        return renderWorkbenchListHtml(rows, "No utility accounts match.", (u) => ({
          title: u.provider_name || u.account_name || "Utility",
          sub: prettifyEnum(u.utility_type || u.provider_type) || "",
          meta: u.monthly_cost ? `~$${u.monthly_cost}/mo` : "",
          isOwned: !!u.chez_owned,
          drillIn: { entityType: "utility", entityId: u.id },
          actions: [
            { id: "audit_bill", label: "Audit bill", entityType: "utility", entityId: u.id },
            { id: "draft_negotiation", label: "Draft negotiation email", entityType: "utility", entityId: u.id },
          ],
        }));
      }
      case "vehicles": {
        const rows = allVehicles.filter(matchOwned).filter((v) => matchQuery(v.make, v.model, v.license_plate, String(v.year || "")));
        return renderWorkbenchListHtml(rows, "No vehicles match.", (v) => ({
          title: [v.year, v.make, v.model].filter(Boolean).join(" "),
          sub: v.license_plate || "",
          meta: v.registration_expiry ? `Reg expires ${formatDateOnly(v.registration_expiry)}` : "",
          isOwned: !!v.chez_owned,
          drillIn: { entityType: "vehicle", entityId: v.id },
          actions: [
            { id: "schedule_service", label: "Schedule service", entityType: "vehicle", entityId: v.id },
            { id: "handle_recall", label: "Handle recall", entityType: "vehicle", entityId: v.id },
          ],
        }));
      }
      case "cases": return openCases.length === 0
        ? `<p class="admin-muted">No open cases for this household.</p>`
        : openCases.map((c) => `
          <button type="button" class="admin-audit__row" data-workbench-case-id="${escapeHtml(c.id)}">
            <div class="admin-audit__row-top">
              <strong>${escapeHtml(c.summary || "(no summary)")}</strong>
              <span class="admin-pill" data-tone="${c.status === "open" ? "amber" : "muted"}">${escapeHtml(prettifyEnum(c.status))}</span>
            </div>
            <p class="admin-audit__row-reason">${escapeHtml(CHEZ_CATEGORY_LABELS[c.category] || prettifyEnum(c.category))}${c.last_message_at ? " · last activity " + escapeHtml(relativeTimeString(c.last_message_at)) : ""}</p>
          </button>
        `).join("");
      default: return "";
    }
  })();

  return `
    <section class="admin-focused admin-households__workbench">
      <header class="admin-focused__head">
        <h2>${escapeHtml(homeownerName)}</h2>
        <div class="admin-focused__meta">
          <span class="admin-pill admin-pill--note">${escapeHtml(household.name || "Household")}</span>
          ${property ? `<span class="admin-muted">${escapeHtml(formatAddress(property))}</span>` : ""}
        </div>
      </header>

      <div class="admin-households__tabs">
        ${tabs.map((t) => `
          <button type="button" class="admin-households__tab ${tab === t.id ? "is-active" : ""}" data-workbench-tab="${escapeHtml(t.id)}">
            ${escapeHtml(t.label)}<span class="admin-households__tab-count">${t.count}${t.owned > 0 ? ` <span class="admin-households__tab-owned">★ ${t.owned}</span>` : ""}</span>
          </button>
        `).join("")}
      </div>

      ${tab !== "cases" ? `
        <div class="admin-households__toolbar">
          <input
            type="search"
            class="admin-households__search"
            placeholder="Search this tab…"
            value="${escapeHtml(state.households.workbenchQuery || "")}"
            data-workbench-search
          />
          <button type="button"
            class="admin-pill admin-pill--toggle ${ownedOnly ? "is-active" : ""}"
            data-workbench-owned-toggle
            title="${ownedOnly ? "Showing only Chez-owned. Click for all." : "Showing all entities. Click to filter Chez-owned only."}">
            ★ Chez owns ${ownedOnly ? "✓" : ""}
          </button>
          ${(() => {
            // Phase 85.7: Bulk propose-ownership button. Only renders when
            // the current tab has 2+ non-owned, non-pending entities to
            // propose. Single-entity proposals belong on the focused panel.
            const proposableCount = countProposableInTab(wb, tab);
            if (proposableCount < 2) return "";
            return `<button type="button" class="admin-pill admin-pill--action" data-workbench-bulk-propose data-tab="${escapeHtml(tab)}" title="Send one Approve/Decline card listing every non-owned ${tab === "vendors" ? "vendor" : tab} on this tab">
              Propose Chez ownership of ${proposableCount} ${tab === "vendors" ? "vendor" + (proposableCount === 1 ? "" : "s") : tab}
            </button>`;
          })()}
        </div>
      ` : ""}

      <div class="admin-households__panel">
        ${tabBody || `<p class="admin-muted">Nothing here yet.</p>`}
      </div>

      ${reminders.length > 0 ? `
        <div class="admin-households__section">
          <h4>Reminders · ${reminders.length}</h4>
          ${reminders.slice(0, 5).map((r) => `
            <div class="admin-households__reminder">
              <strong>${escapeHtml(r.title)}</strong>
              <span class="admin-muted">due ${escapeHtml(formatDateTimeShort(r.due_at))}</span>
            </div>
          `).join("")}
        </div>
      ` : ""}

      ${recentActions.length > 0 ? `
        <div class="admin-households__section">
          <h4>Recent workbench activity · ${recentActions.length}</h4>
          ${recentActions.slice(0, 5).map((a) => `
            <div class="admin-households__action-row">
              <strong>${escapeHtml(workbenchActionLabel(a.action_type))}</strong>
              <span class="admin-muted">${escapeHtml(a.entity_type)} · ${escapeHtml(relativeTimeString(a.created_at))}</span>
            </div>
          `).join("")}
        </div>
      ` : ""}
    </section>
  `;
}

function renderWorkbenchListHtml(items, emptyCopy, formatter) {
  if (items.length === 0) {
    return `<p class="admin-muted">${escapeHtml(emptyCopy)}</p>`;
  }
  // Phase 85 PR 5.1 — list rows are glance-only. Click drills into the
  // focused-detail pane on the right where actions live. The previous
  // per-row SCHEDULE / COMPLETE / SNOOZE button stack made the list
  // feel like a bingo card and didn't match the rest of the admin
  // portal (cockpit queue + catalog tabs all use clean rows + side
  // detail). The `actions` field on the formatter result is now ignored
  // here — kept on the formatter so the focused-detail panel can pull
  // the same set when it needs to render its action stack.
  return items.map((it) => {
    const f = formatter(it);
    const drillAttrs = f.drillIn
      ? ` data-drill-entity-type="${escapeHtml(f.drillIn.entityType)}" data-drill-entity-id="${escapeHtml(f.drillIn.entityId)}"`
      : "";
    const drillClass = f.drillIn ? " is-clickable" : "";
    const ownedBadge = f.isOwned
      ? `<span class="admin-households__owned-badge" title="Chez owns this">★</span>`
      : "";
    const chevron = f.drillIn
      ? `<span class="admin-households__entity-chevron" aria-hidden="true">›</span>`
      : "";
    return `
      <div class="admin-households__entity-row${drillClass}"${drillAttrs}>
        <div class="admin-households__entity-main">
          <strong>${ownedBadge}${escapeHtml(f.title || "(unnamed)")}</strong>
          ${f.sub ? `<span class="admin-muted">${escapeHtml(f.sub)}</span>` : ""}
        </div>
        ${f.meta ? `<span class="admin-households__entity-meta">${escapeHtml(f.meta)}</span>` : ""}
        ${chevron}
      </div>
    `;
  }).join("");
}

// ----- Upcoming feed view ----------------------------------------------------

async function renderUpcomingView() {
  el.search.value = state.search || "";
  el.stats.innerHTML = `<div class="admin-stat"><strong>—</strong><span>Loading…</span></div>`;
  el.list.innerHTML = `<p class="admin-audit__intro">Loading the upcoming feed…</p>`;

  const stale = Date.now() - state.upcoming.fetchedAt > 60_000;
  if (stale || state.upcoming.items.length === 0) {
    try {
      const result = await callChezConcierge({
        action: "fetch_upcoming",
        window_days: state.upcoming.windowDays,
      });
      state.upcoming.items = (result.items ?? []);
      state.upcoming.fetchedAt = Date.now();
      // Phase 85.5: refresh the sidebar Upcoming badge after items load.
      renderNav();
    } catch (e) {
      el.list.innerHTML = `<p class="admin-muted">Couldn't load upcoming: ${escapeHtml(String(e.message || e))}</p>`;
      return;
    }
  }

  const items = state.upcoming.items;
  const overdue = items.filter((i) => i.priority === "overdue").length;
  const today = items.filter((i) => i.priority === "today").length;
  const thisWeek = items.filter((i) => i.priority === "this_week").length;
  const chezOwnedCount = items.filter((i) => i.chez_owned).length;

  el.stats.innerHTML = `
    <div class="admin-stat"><strong>${overdue}</strong><span>Overdue</span></div>
    <div class="admin-stat"><strong>${today}</strong><span>Today</span></div>
    <div class="admin-stat"><strong>${thisWeek}</strong><span>This week</span></div>
    <div class="admin-stat"><strong>${chezOwnedCount}</strong><span>Chez owns</span></div>
  `;

  // Apply filters.
  const query = (state.search || "").toLowerCase().trim();
  let filtered = items;
  if (state.upcoming.typeFilter !== "all") {
    filtered = filtered.filter((i) => i.type === state.upcoming.typeFilter);
  }
  if (state.upcoming.priorityFilter !== "all") {
    filtered = filtered.filter((i) => i.priority === state.upcoming.priorityFilter);
  }
  if (state.upcoming.chezOwnedOnly) {
    filtered = filtered.filter((i) => i.chez_owned);
  }
  if (query) {
    filtered = filtered.filter((i) =>
      (i.title || "").toLowerCase().includes(query) ||
      (i.household_name || "").toLowerCase().includes(query) ||
      (i.sub || "").toLowerCase().includes(query)
    );
  }

  // Group by priority band for visual grouping.
  const bands = [
    { id: "overdue", label: "Overdue" },
    { id: "today", label: "Today" },
    { id: "this_week", label: "This week" },
    { id: "next_14_days", label: "Next 14 days" },
  ];

  // Phase 84.1 — added Tasks + Handyman type chips, plus the "Chez owns
  // only" master toggle that floats already-delegated work.
  const filterChips = `
    <div class="admin-upcoming__filters">
      ${[
        { id: "all", label: "All" },
        { id: "maintenance_task", label: "Tasks" },
        { id: "handyman_punch", label: "Handyman" },
        { id: "routine_visit", label: "Routine visits" },
        { id: "chez_visit", label: "Chez visits" },
        { id: "case_sla", label: "Cases at SLA" },
        { id: "reminder", label: "My reminders" },
        { id: "document_expiring", label: "Warranties" },
        { id: "vehicle_registration", label: "Vehicles" },
      ].map((f) => `
        <button type="button" class="admin-upcoming__filter ${state.upcoming.typeFilter === f.id ? "is-active" : ""}" data-upcoming-filter="${escapeHtml(f.id)}">
          ${escapeHtml(f.label)}
        </button>
      `).join("")}
      <button type="button" class="admin-upcoming__filter admin-upcoming__filter--chez ${state.upcoming.chezOwnedOnly ? "is-active" : ""}" data-upcoming-toggle-chez>
        ★ Chez owns only
      </button>
      <button type="button" class="admin-upcoming__add" data-upcoming-add-reminder>+ Add reminder</button>
    </div>
  `;

  el.list.innerHTML = `
    <div class="admin-audit admin-upcoming">
      <p class="admin-audit__intro">
        What's next, across every home you manage. Maintenance tasks coming due, handyman backlog, vendor visits, expirations, and follow-ups — chez-owned items float to the top.
      </p>
      ${filterChips}
      ${filtered.length === 0
        ? `<p class="admin-muted">Nothing matches that filter.</p>`
        : bands.map((b) => {
            const inBand = filtered.filter((i) => i.priority === b.id);
            if (inBand.length === 0) return "";
            return `
              <div class="admin-upcoming__band">
                <h4 class="admin-upcoming__band-label">${escapeHtml(b.label)} · ${inBand.length}</h4>
                ${inBand.map(renderUpcomingItemHtml).join("")}
              </div>
            `;
          }).join("")}
    </div>
  `;

  // Filter chip handlers.
  el.list.querySelectorAll("[data-upcoming-filter]").forEach((btn) => {
    btn.addEventListener("click", () => {
      state.upcoming.typeFilter = btn.dataset.upcomingFilter;
      renderUpcomingView();
    });
  });
  // Phase 84.1 — Chez-owned-only master toggle.
  el.list.querySelector("[data-upcoming-toggle-chez]")?.addEventListener("click", () => {
    state.upcoming.chezOwnedOnly = !state.upcoming.chezOwnedOnly;
    renderUpcomingView();
  });
  // Item click → deep-link.
  el.list.querySelectorAll("[data-upcoming-item-id]").forEach((btn) => {
    btn.addEventListener("click", async () => {
      const id = btn.dataset.upcomingItemId;
      const item = state.upcoming.items.find((i) => i.id === id);
      if (!item) return;
      // Reminder rows can be completed inline.
      if (item.type === "reminder") {
        const rid = item.id.replace(/^rm:/, "");
        if (confirm(`Complete reminder "${item.title}"?`)) {
          try {
            await callChezConcierge({ action: "complete_reminder", reminder_id: rid });
            state.upcoming.items = state.upcoming.items.filter((i) => i.id !== item.id);
            renderUpcomingView();
          } catch (e) {
            alert(`Couldn't complete: ${e.message || e}`);
          }
        }
        return;
      }
      // Case-bound items deep-link to the cockpit.
      if (item.type === "case_sla" || item.type === "chez_visit") {
        const requestId = item.deep_link?.match(/case=([0-9a-f-]+)/)?.[1];
        if (requestId) {
          state.view = "chez";
          state.selectedChezRequest = (state.chezRequests || []).find((r) => r.id === requestId);
          if (state.selectedChezRequest) {
            state.concierge.queueMode = "case";
            await loadChezMessages(requestId);
          }
          render();
        }
        return;
      }
      // Phase 85 PR 5.1 — Upcoming row click STAYS on the Upcoming view.
      // The focused-detail pane renders into the same right pane that
      // shows the "Click a row to drill in" empty state. Previously we
      // navigated to state.view = "households" which felt like a
      // context switch; Tom flagged it as wrong. Now: load the host
      // household's workbench data (so lookupFocusedEntity can resolve
      // the row), but don't switch views — render the focused detail
      // directly into the Upcoming surface's right pane.
      // handyman_punch is a per-household summary row (entity_id is the
      // household id), not a single entity; it falls through to the
      // households workbench since there's no single "task" to focus.
      const drillTypeByItem = {
        maintenance_task: { type: "task", idKey: "entity_id" },
        routine_visit: { type: "routine", idKey: "entity_id" },
        document_expiring: { type: "document", idKey: "entity_id" },
        vehicle_registration: { type: "vehicle", idKey: "entity_id" },
        vehicle_insurance: { type: "vehicle", idKey: "entity_id" },
      };
      const drill = drillTypeByItem[item.type];
      if (drill) {
        const entityId = item[drill.idKey];
        if (entityId) {
          // Load the host household quietly (without switching views)
          // so lookupFocusedEntity can find the row and the focused
          // detail can show the entity's relations.
          state.households.selectedId = item.household_id;
          await loadHouseholdWorkbench(item.household_id);
          // Tag the active row so the operator can see what's selected
          // alongside the right-pane detail.
          state.upcoming.selectedItemId = item.id;
          renderUpcomingView();
          openFocusedEntityDetail(drill.type, entityId);
        }
        return;
      }
      // Phase 85.5: handyman_punch is a household-level rollup, not a
      // single entity — render a synthetic focused panel that lists every
      // pending punch item for the household in the same right pane,
      // staying on Upcoming view. Each row gets a Mark filed action +
      // a Schedule handyman visit affordance.
      if (item.type === "handyman_punch") {
        state.households.selectedId = item.household_id;
        await loadHouseholdWorkbench(item.household_id);
        state.upcoming.selectedItemId = item.id;
        renderUpcomingView();
        openFocusedEntityDetail("handyman_punch_list", item.household_id);
        return;
      }
      // Unknown type — log it and don't navigate so we don't lose the
      // operator's Upcoming context.
      console.warn("[upcoming] unhandled item type", item.type, item);
      showAdminToast(`Drill-in for "${escapeHtml(item.type)}" isn't built yet — open the household manually.`, { kind: "info" });
    });
  });
  // Add-reminder button.
  el.list.querySelector("[data-upcoming-add-reminder]")?.addEventListener("click", () => {
    openAddReminderModal();
  });

  el.auditFocused?.classList.add("is-hidden");
  el.noteFocused?.classList.add("is-hidden");
  el.decisionFocused?.classList.add("is-hidden");
  el.emptyDetail?.classList.remove("is-hidden");
  el.detail?.classList.add("is-hidden");
  if (el.emptyDetail) {
    el.emptyDetail.querySelector("h3").textContent = "Click a row to drill in";
    el.emptyDetail.querySelector("p").textContent = "Cases + Chez-coordinated visits open the cockpit. Maintenance tasks, handyman buckets, routines, documents, and vehicles open the household workbench on the right tab. Reminders complete inline.";
  }
}

function renderUpcomingItemHtml(item) {
  const dueRel = relativeTimeString(item.due_at);
  // Phase 84.1 — added icons for the new types.
  const iconMap = {
    maintenance_task: "🔧",
    handyman_punch: "🔨",
    routine_visit: "📅",
    chez_visit: "📞",
    case_sla: "⏱",
    reminder: "🔔",
    document_expiring: "📄",
    vehicle_registration: "🚗",
    vehicle_insurance: "🛡",
  };
  const icon = iconMap[item.type] || "·";
  // Phase 84.1 — chez-owned badge so Tom can scan the queue and see at a
  // glance what's already a Chez commitment vs. a delegation opportunity.
  const chezBadge = item.chez_owned
    ? `<span class="admin-upcoming__row-chez">★ Chez owns</span>`
    : "";
  // Phase 85 PR 5.1 — highlight the row whose focused-detail is open
  // in the right pane. Mirror the Concierge cockpit's active-case
  // visual so the operator can scan the list and see what's loaded.
  const isActive = state.upcoming.selectedItemId === item.id;
  return `
    <button type="button" class="admin-audit__row admin-upcoming__row ${item.chez_owned ? "admin-upcoming__row--chez" : ""} ${isActive ? "is-active" : ""}" data-upcoming-item-id="${escapeHtml(item.id)}">
      <div class="admin-upcoming__row-icon">${icon}</div>
      <div class="admin-upcoming__row-main">
        <div class="admin-upcoming__row-title">
          ${escapeHtml(item.title)}
          ${chezBadge}
        </div>
        <div class="admin-upcoming__row-sub">
          ${escapeHtml(item.household_name)}
          ${item.sub ? ` · ${escapeHtml(item.sub)}` : ""}
        </div>
      </div>
      <div class="admin-upcoming__row-due">
        <strong>${escapeHtml(dueRel)}</strong>
        <span class="admin-muted">${escapeHtml(formatDateTimeShort(item.due_at))}</span>
      </div>
    </button>
  `;
}

// ----- Add-reminder modal ----------------------------------------------------

function openAddReminderModal() {
  document.querySelector("[data-chez-reminder-modal]")?.remove();
  // Build household picker from the cached list.
  const households = state.households.list.length > 0
    ? state.households.list
    : Array.from(new Map((state.chezRequests || []).map((r) => {
        const dossier = (state.chezDossiersByHousehold || {})[r.household_id];
        const name = dossier ? primaryHomeownerLabel(dossier) : `Household ${r.household_id.slice(0, 8)}`;
        return [r.household_id, { id: r.household_id, name }];
      })).values());

  const modal = document.createElement("div");
  modal.className = "admin-modal";
  modal.setAttribute("data-chez-reminder-modal", "");
  modal.innerHTML = `
    <div class="admin-modal__backdrop" data-modal-close></div>
    <div class="admin-modal__panel" style="max-width: 480px;">
      <header class="admin-modal__head">
        <div>
          <h2>Add a reminder</h2>
          <p class="admin-muted">Set a follow-up that doesn't fit an existing entity timeline. Lands in the Upcoming feed.</p>
        </div>
        <button type="button" class="admin-modal__close" data-modal-close aria-label="Close">×</button>
      </header>
      <div class="admin-modal__body">
        <label>
          <span>Household</span>
          <select name="household">
            <option value="">Pick a household</option>
            ${households.map((h) => `<option value="${escapeHtml(h.id)}">${escapeHtml(h.name)}</option>`).join("")}
          </select>
        </label>
        <label>
          <span>Title</span>
          <input type="text" name="title" placeholder="e.g. Call A&A about counter-offer" />
        </label>
        <label>
          <span>Due</span>
          <input type="datetime-local" name="due_at" />
        </label>
        <label>
          <span>Notes (optional)</span>
          <textarea name="notes" rows="2" placeholder="Any context that helps future-you remember why this matters."></textarea>
        </label>
      </div>
      <footer class="admin-modal__foot">
        <button type="button" class="admin-button admin-button--ghost" data-modal-close>Cancel</button>
        <button type="button" class="admin-button admin-button--primary" data-reminder-submit>Add reminder</button>
      </footer>
    </div>
  `;
  document.body.appendChild(modal);
  modal.querySelectorAll("[data-modal-close]").forEach((b) => b.addEventListener("click", () => modal.remove()));
  modal.querySelector("[data-reminder-submit]").addEventListener("click", async (e) => {
    const btn = e.currentTarget;
    const householdId = modal.querySelector("select[name='household']").value;
    const title = modal.querySelector("input[name='title']").value.trim();
    const dueAtLocal = modal.querySelector("input[name='due_at']").value;
    const notes = modal.querySelector("textarea[name='notes']").value.trim();
    if (!householdId || !title || !dueAtLocal) {
      alert("Fill in household, title, and due date.");
      return;
    }
    const dueIso = new Date(dueAtLocal).toISOString();
    btn.disabled = true; btn.textContent = "Adding…";
    try {
      await callChezConcierge({
        action: "create_reminder",
        household_id: householdId,
        due_at: dueIso,
        title,
        notes: notes || undefined,
      });
      // Force a refetch on next render.
      state.upcoming.fetchedAt = 0;
      modal.remove();
      renderUpcomingView();
    } catch (err) {
      alert(`Couldn't add: ${err.message || err}`);
      btn.disabled = false; btn.textContent = "Add reminder";
    }
  });
}
